const e=[{id:0,oaid:"W2064675550",doi:"10.1162/neco.1997.9.8.1735",title:"Long Short-Term Memory",authors:[{name:"Sepp Hochreiter",institutions:["Technical University of Munich"]},{name:"Jürgen Schmidhuber",institutions:["Dalle Molle Institute for Artificial Intelligence Research"]}],authorString:"Sepp Hochreiter; Jürgen Schmidhuber",institutions:["Dalle Molle Institute for Artificial Intelligence Research","Technical University of Munich"],countries:["CH","DE"],year:1997,journal:"Neural Computation",citations:99206,abstract:"Learning to store information over extended time intervals by recurrent backpropagation takes a very long time, mostly because of insufficient, decaying error backflow. We briefly review Hochreiter's (1991) analysis of this problem, then address it by introducing a novel, efficient, gradient-based method called long short-term memory (LSTM). Truncating the gradient where this does not do harm, LSTM can learn to bridge minimal time lags in excess of 1000 discrete-time steps by enforcing constant error flow through constant error carousels within special units. Multiplicative gate units learn to open and close access to the constant error flow. LSTM is local in space and time; its computational complexity per time step and weight is O(1). Our experiments with artificial data involve local, distributed, real-valued, and noisy pattern representations. In comparisons with real-time recurrent learning, back propagation through time, recurrent cascade correlation, Elman nets, and neural sequence chunking, LSTM leads to many more successful runs, and learns much faster. LSTM also solves complex, artificial long-time-lag tasks that have never been solved by previous recurrent network algorithms.",keywords:["Term","Short-term memory","Neuroscience","Cognition","Working memory"],concepts:["Term","Short-term memory"],pdf_url:null,is_oa:!1,n_refs:34,n_refs_in_core:1,degree:55,community:0,deg_w:307.5,betweenness:.0487,pagerank:.00783,eigenvector:.0522},{id:1,oaid:"W1522301498",doi:"10.48550/arxiv.1412.6980",title:"Adam: A Method for Stochastic Optimization",authors:[{name:"Diederik P. Kingma",institutions:["University of Amsterdam"]},{name:"Jimmy Ba",institutions:["University of Toronto"]}],authorString:"Diederik P. Kingma; Jimmy Ba",institutions:["University of Amsterdam","University of Toronto"],countries:["CA","NL"],year:2014,journal:"UvA-DARE (University of Amsterdam)",citations:84794,abstract:"We introduce Adam, an algorithm for first-order gradient-based optimization of stochastic objective functions, based on adaptive estimates of lower-order moments. The method is straightforward to implement, is computationally efficient, has little memory requirements, is invariant to diagonal rescaling of the gradients, and is well suited for problems that are large in terms of data and/or parameters. The method is also appropriate for non-stationary objectives and problems with very noisy and/or sparse gradients. The hyper-parameters have intuitive interpretations and typically require little tuning. Some connections to related algorithms, on which Adam was inspired, are discussed. We also analyze the theoretical convergence properties of the algorithm and provide a regret bound on the convergence rate that is comparable to the best known results under the online convex optimization framework. Empirical results demonstrate that Adam works well in practice and compares favorably to other stochastic optimization methods. Finally, we discuss AdaMax, a variant of Adam based on the infinity norm.",keywords:["Regret","Mathematical optimization","Diagonal","Convergence","Stochastic optimization","Rate of convergence","Optimization problem"],concepts:["Regret","Mathematical optimization","Diagonal","Convergence","Stochastic optimization","Rate of convergence","Optimization problem"],pdf_url:"https://handle.uba.uva.nl/personal/pure/en/publications/adam-a-method-for-stochastic-optimization(a20791d3-1aff-464a-8544-268383c33a75).html",is_oa:!0,n_refs:20,n_refs_in_core:1,degree:33,community:0,deg_w:185,betweenness:.0152,pagerank:.00521,eigenvector:.0141},{id:2,oaid:"W4385245566",doi:"10.4230/lipics.itp.2023.19",title:"Inline Hardware KV-Cache Compression for Long-Context Transformer Inference: An Architectural Case for a Memory-Path Compression Engine",authors:[{name:"Jakubův, Jan",institutions:["Czech Technical University in Prague"]},{name:"Chvalovský, Karel",institutions:["Czech Technical University in Prague"]},{name:"Goertzel, Zarathustra",institutions:["Czech Technical University in Prague"]},{name:"Kaliszyk, Cezary",institutions:["Universität Innsbruck","Food Research Institute Prague"]},{name:"Olšák, Mirek",institutions:["Institut des Hautes Études Scientifiques"]},{name:"Piotrowski, Bartosz",institutions:["Czech Technical University in Prague"]},{name:"Schulz, Stephan",institutions:["Baden-Wuerttemberg Cooperative State University"]},{name:"Suda, Martin",institutions:["Czech Technical University in Prague"]},{name:"Urban, Josef",institutions:["Czech Technical University in Prague"]}],authorString:"Jakubův, Jan; Chvalovský, Karel; Goertzel, Zarathustra; Kaliszyk, Cezary; Olšák, Mirek; Piotrowski, Bartosz; Schulz, Stephan; Suda, Martin; Urban, Josef",institutions:["Baden-Wuerttemberg Cooperative State University","Czech Technical University in Prague","Food Research Institute Prague","Institut des Hautes Études Scientifiques","Universität Innsbruck"],countries:["AT","CZ","DE","FR"],year:2023,journal:"DROPS (Schloss Dagstuhl – Leibniz Center for Informatics)",citations:77038,abstract:"As a present to Mizar on its 50th anniversary, we develop an AI/TP system that automatically proves about 60% of the Mizar theorems in the hammer setting. We also automatically prove 75% of the Mizar theorems when the automated provers are helped by using only the premises used in the human-written Mizar proofs. We describe the methods and large-scale experiments leading to these results. This includes in particular the E and Vampire provers, their ENIGMA and Deepire learning modifications, a number of learning-based premise selection methods, and the incremental loop that interleaves growing a corpus of millions of ATP proofs with training increasingly strong AI/TP systems on them. We also present a selection of Mizar problems that were proved automatically.",keywords:["Machine translation","Transformer","BLEU","Encoder","Parallelizable manifold","Parsing"],concepts:["Machine translation","Transformer","BLEU","Encoder","Parallelizable manifold","Parsing"],pdf_url:"https://drops.dagstuhl.de/storage/00lipics/lipics-vol268-itp2023/LIPIcs.ITP.2023.19/LIPIcs.ITP.2023.19.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:19,community:0,deg_w:81,betweenness:.0077,pagerank:.00273,eigenvector:.009},{id:3,oaid:"W2163605009",doi:"10.1145/3065386",title:"ImageNet classification with deep convolutional neural networks",authors:[{name:"Alex Krizhevsky",institutions:["Google (United States)","University of Toronto"]},{name:"Ilya Sutskever",institutions:["Google (United States)","University of Toronto"]},{name:"Geoffrey E. Hinton",institutions:["University of Toronto","OpenAI (United States)"]}],authorString:"Alex Krizhevsky; Ilya Sutskever; Geoffrey E. Hinton",institutions:["Google (United States)","OpenAI (United States)","University of Toronto"],countries:["CA","US"],year:2017,journal:"Communications of the ACM",citations:75716,abstract:'We trained a large, deep convolutional neural network to classify the 1.2 million high-resolution images in the ImageNet LSVRC-2010 contest into the 1000 different classes. On the test data, we achieved top-1 and top-5 error rates of 37.5% and 17.0%, respectively, which is considerably better than the previous state-of-the-art. The neural network, which has 60 million parameters and 650,000 neurons, consists of five convolutional layers, some of which are followed by max-pooling layers, and three fully connected layers with a final 1000-way softmax. To make training faster, we used non-saturating neurons and a very efficient GPU implementation of the convolution operation. To reduce overfitting in the fully connected layers we employed a recently developed regularization method called "dropout" that proved to be very effective. We also entered a variant of this model in the ILSVRC-2012 competition and achieved a winning top-5 test error rate of 15.3%, compared to 26.2% achieved by the second-best entry.',keywords:["Softmax function","Convolutional neural network","Pooling","Dropout","Convolution","Regularization"],concepts:["Softmax function","Convolutional neural network","Pooling","Dropout","Convolution","Regularization"],pdf_url:"http://dl.acm.org/ft_gateway.cfm?id=3065386&type=pdf",is_oa:!0,n_refs:26,n_refs_in_core:0,degree:82,community:0,deg_w:586,betweenness:.1108,pagerank:.01379,eigenvector:.0665},{id:4,oaid:"W2112796928",doi:"10.1109/5.726791",title:"Gradient-based learning applied to document recognition",authors:[{name:"Yann LeCun",institutions:["AT&T (United States)"]},{name:"Léon Bottou",institutions:["AT&T (United States)"]},{name:"Yoshua Bengio",institutions:["Université de Montréal"]},{name:"Patrick Haffner",institutions:["AT&T (United States)"]}],authorString:"Yann LeCun; Léon Bottou; Yoshua Bengio; Patrick Haffner",institutions:["AT&T (United States)","Université de Montréal"],countries:["CA","US"],year:1998,journal:"Proceedings of the IEEE",citations:58655,abstract:"Multilayer neural networks trained with the back-propagation algorithm constitute the best example of a successful gradient based learning technique. Given an appropriate network architecture, gradient-based learning algorithms can be used to synthesize a complex decision surface that can classify high-dimensional patterns, such as handwritten characters, with minimal preprocessing. This paper reviews various methods applied to handwritten character recognition and compares them on a standard handwritten digit recognition task. Convolutional neural networks, which are specifically designed to deal with the variability of 2D shapes, are shown to outperform all other techniques. Real-life document recognition systems are composed of multiple modules including field extraction, segmentation recognition, and language modeling. A new learning paradigm, called graph transformer networks (GTN), allows such multimodule systems to be trained globally using gradient-based methods so as to minimize an overall performance measure. Two systems for online handwriting recognition are described. Experiments demonstrate the advantage of global training, and the flexibility of graph transformer networks. A graph transformer network for reading a bank cheque is also described. It uses convolutional neural network character recognizers combined with global training techniques to provide record accuracy on business and personal cheques. It is deployed commercially and reads several million cheques per day.",keywords:["Convolutional neural network","Intelligent character recognition","Handwriting recognition","Transformer","Artificial neural network","Pattern recognition"],concepts:["Convolutional neural network","Intelligent character recognition","Handwriting recognition","Transformer","Artificial neural network","Pattern recognition"],pdf_url:"https://hal.science/hal-03926082/document",is_oa:!0,n_refs:135,n_refs_in_core:1,degree:69,community:0,deg_w:410.5,betweenness:.0629,pagerank:.01014,eigenvector:.0507},{id:5,oaid:"W2964121744",doi:"10.4230/lipics.cp.2021.42",title:"(untitled)",authors:[{name:"Mandi, Jayanta",institutions:[]},{name:"Canoy, Rocsildes",institutions:[]},{name:"Bucarey, Víctor",institutions:[]},{name:"Guns, Tias",institutions:[]}],authorString:"Mandi, Jayanta; Canoy, Rocsildes; Bucarey, Víctor; Guns, Tias",institutions:[],countries:[],year:2021,journal:"DROPS (Schloss Dagstuhl – Leibniz Center for Informatics)",citations:50400,abstract:"Designing complex, dynamic yet multi-functional materials and devices is challenging because the design spaces for these materials have numerous interdependent and often conflicting constraints. Taking inspiration from advances in artificial intelligence and their applications in material discovery, we propose a computational method for designing metamorphic DNA-co-polymerized hydrogel structures. The method consists of a coarse-grained simulation and a deep learning-guided optimization system for exploring the immense design space of these structures. Here, we develop a simple numeric simulation of DNA-co-polymerized hydrogel shape change and seek to find designs for structured hydrogels that can fold into the shapes of different Arabic numerals in different actuation states. We train a convolutional neural network to classify and score the geometric outputs of the coarse-grained simulation to provide autonomous feedback for design optimization. We then construct a genetic algorithm that generates and selects large batches of material designs that compete with one another to evolve and converge on optimal objective-matching designs. We show that we are able to explore the large design space and learn important parameters and traits. We identify vital relationships between the material scale size and the range of shape change that can be achieved by individual domains and we elucidate trade-offs between different design parameters. Finally, we discover material designs capable of transforming into multiple different digits in different actuation states.",keywords:["Regret","Mathematical optimization","Diagonal","Stochastic optimization","Convergence","Rate of convergence","Optimization problem"],concepts:["Regret","Mathematical optimization","Diagonal","Stochastic optimization","Convergence","Rate of convergence","Optimization problem"],pdf_url:"https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.CP.2021.42",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:27,community:0,deg_w:136,betweenness:.0097,pagerank:.00402,eigenvector:.0112},{id:6,oaid:"W2896457183",doi:"10.4230/lipics.cosit.2022.18",title:"AI-Assisted Pipeline for Dynamic Generation of Trustworthy Health Supplement Content at Scale",authors:[{name:"Kefallinos, Dionysios",institutions:["Google (United States)","National Technical University of Athens"]},{name:"Alexandris, Georgios",institutions:["Google (United States)","National Technical University of Athens"]},{name:"Maras, Alexis",institutions:["Google (United States)","National Technical University of Athens"]},{name:"Chaidos, Panagiotis",institutions:["Google (United States)","National Technical University of Athens"]},{name:"Gomony, Manil Dev",institutions:["Eindhoven University of Technology"]},{name:"Corporaal, Henk",institutions:["Eindhoven University of Technology"]},{name:"Soudris, Dimitrios",institutions:["National Technical University of Athens"]},{name:"Xydis, Sotirios",institutions:["National Technical University of Athens"]}],authorString:"Kefallinos, Dionysios; Alexandris, Georgios; Maras, Alexis; Chaidos, Panagiotis; Gomony, Manil Dev; Corporaal, Henk; Soudris, Dimitrios; Xydis, Sotirios",institutions:["Eindhoven University of Technology","Google (United States)","National Technical University of Athens"],countries:["GR","NL","US"],year:2018,journal:"DROPS (Schloss Dagstuhl – Leibniz Center for Informatics)",citations:45750,abstract:"Although geospatial question answering systems have received increasing attention in recent years, existing prototype systems struggle to properly answer qualitative spatial questions. In this work, we propose a unique framework for answering qualitative spatial questions, which comprises three main components: a geoparser that takes the input questions and extracts place semantic information from text, a reasoning system which is embedded with a crisp reasoner, and finally, answer extraction, which refines the solution space and generates final answers. We present an experimental design to evaluate our framework for point-based cardinal direction calculus (CDC) relations by developing an automated approach for generating three types of synthetic qualitative spatial questions. The initial evaluations of generated answers in our system are promising because a high proportion of answers were labelled correct.",keywords:["Transformer","Training","Electrical engineering","Geography","Voltage"],concepts:["Transformer","Training"],pdf_url:"https://drops.dagstuhl.de/entities/document/10.4230/OASIcs.LDK.2019.21",is_oa:!0,n_refs:55,n_refs_in_core:0,degree:24,community:0,deg_w:121,betweenness:.0116,pagerank:.00379,eigenvector:.0203},{id:7,oaid:"W2095705004",doi:null,title:"Dropout: a simple way to prevent neural networks from overfitting",authors:[{name:"Nitish Srivastava",institutions:["University of Toronto"]},{name:"Geoffrey E. Hinton",institutions:["University of Toronto"]},{name:"Alex Krizhevsky",institutions:["University of Toronto"]},{name:"Ilya Sutskever",institutions:["University of Toronto"]},{name:"Ruslan Salakhutdinov",institutions:["University of Toronto"]}],authorString:"Nitish Srivastava; Geoffrey E. Hinton; Alex Krizhevsky; Ilya Sutskever; Ruslan Salakhutdinov",institutions:["University of Toronto"],countries:["CA"],year:2014,journal:null,citations:34283,abstract:"Deep neural nets with a large number of parameters are very powerful machine learning systems. However, overfitting is a serious problem in such networks. Large networks are also slow to use, making it difficult to deal with overfitting by combining the predictions of many different large neural nets at test time. Dropout is a technique for addressing this problem. The key idea is to randomly drop units (along with their connections) from the neural network during training. This prevents units from co-adapting too much. During training, dropout samples from an exponential number of different “thinned ” networks. At test time, it is easy to approximate the effect of averaging the predictions of all these thinned networks by simply using a single unthinned network that has smaller weights. This significantly reduces overfitting and gives major improvements over other regularization methods. We show that dropout improves the performance of neural networks on supervised learning tasks in vision, speech recognition, document classification and computational biology, obtaining state-of-the-art results on many benchmark data sets.",keywords:["Overfitting","Dropout","Artificial neural network","Benchmark","Deep neural networks"],concepts:["Overfitting","Dropout","Artificial neural network","Benchmark","Deep neural networks"],pdf_url:null,is_oa:!1,n_refs:36,n_refs_in_core:1,degree:58,community:0,deg_w:391,betweenness:.0675,pagerank:.00969,eigenvector:.046},{id:8,oaid:"W1678356000",doi:"10.1214/aos/1013203451",title:"Greedy function approximation: A gradient boosting machine.",authors:[{name:"Jerome H. Friedman",institutions:["Stanford University"]}],authorString:"Jerome H. Friedman",institutions:["Stanford University"],countries:["US"],year:2001,journal:"The Annals of Statistics",citations:29372,abstract:"Function estimation/approximation is viewed from the perspective of numerical optimization in function space, rather than parameter space. A connection is made between stagewise additive expansions and steepest-descent minimization. A general gradient descent “boosting” paradigm is developed for additive expansions based on any fitting criterion.Specific algorithms are presented for least-squares, least absolute deviation, and Huber-M loss functions for regression, and multiclass logistic likelihood for classification. Special enhancements are derived for the particular case where the individual additive components are regression trees, and tools for interpreting such “TreeBoost” models are presented. Gradient boosting of regression trees produces competitive, highly robust, interpretable procedures for both regression and classification, especially appropriate for mining less than clean data. Connections between this approach and the boosting methods of Freund and Shapire and Friedman, Hastie and Tibshirani are discussed.",keywords:["Gradient boosting","Boosting","Gradient descent","Regression","Mathematical optimization","Minification","Logistic regression"],concepts:["Gradient boosting","Boosting","Gradient descent","Regression","Mathematical optimization","Minification","Logistic regression"],pdf_url:"https://projecteuclid.org/journals/annals-of-statistics/volume-29/issue-5/Greedy-function-approximation-A-gradient-boosting-machine/10.1214/aos/1013203451.pdf",is_oa:!0,n_refs:28,n_refs_in_core:0,degree:12,community:4,deg_w:55.5,betweenness:.0035,pagerank:.00204,eigenvector:.0132},{id:9,oaid:"W2099471712",doi:"10.3156/jsoft.29.5_177_2",title:"GAN（Generative Adversarial Nets）",authors:[{name:"柴田 淳司",institutions:["Université de Montréal"]}],authorString:"柴田 淳司",institutions:["Université de Montréal"],countries:["CA"],year:2017,journal:"Journal of Japan Society for Fuzzy Theory and Intelligent Informatics",citations:21802,abstract:"We propose a new framework for estimating generative models via an adversarial process, in which we simultaneously train two models: a generative model G that captures the data distribution, and a discriminative model D that estimates the probability that a sample came from the training data rather than G. The training procedure for G is to maximize the probability of D making a mistake. This framework corresponds to a minimax two-player game. In the space of arbitrary functions G and D, a unique solution exists, with G recovering the training data distribution and D equal to ½ everywhere. In the case where G and D are defined by multilayer perceptrons, the entire system can be trained with backpropagation. There is no need for any Markov chains or unrolled approximate inference networks during either training or generation of samples. Experiments demonstrate the potential of the framework through qualitative and quantitative evaluation of the generated samples.",keywords:["Adversarial system","Generative grammar"],concepts:["Adversarial system","Generative grammar"],pdf_url:"https://www.jstage.jst.go.jp/article/jsoft/29/5/29_177_2/_pdf",is_oa:!0,n_refs:34,n_refs_in_core:2,degree:48,community:0,deg_w:321.5,betweenness:.0499,pagerank:.00793,eigenvector:.0431},{id:10,oaid:"W2964350391",doi:"10.1609/aaai.v31i1.11231",title:"Inception-v4, Inception-ResNet and the Impact of Residual Connections on Learning",authors:[{name:"Christian Szegedy",institutions:["Google (United States)"]},{name:"Sergey Ioffe",institutions:["Google (United States)"]},{name:"Vincent Vanhoucke",institutions:["Google (United States)"]},{name:"Alexander A. Alemi",institutions:["Google (United States)"]}],authorString:"Christian Szegedy; Sergey Ioffe; Vincent Vanhoucke; Alexander A. Alemi",institutions:["Google (United States)"],countries:["US"],year:2017,journal:null,citations:12670,abstract:"Very deep convolutional networks have been central to the largest advances in image recognition performance in recent years. One example is the Inception architecture that has been shown to achieve very good performance at relatively low computational cost. Recently, the introduction of residual connections in conjunction with a more traditional architecture has yielded state-of-the-art performance in the 2015 ILSVRC challenge; its performance was similar to the latest generation Inception-v3 network. This raises the question: Are there any benefits to combining Inception architectures with residual connections? Here we give clear empirical evidence that training with residual connections accelerates the training of Inception networks significantly. There is also some evidence of residual Inception networks outperforming similarly expensive Inception networks without residual connections by a thin margin. We also present several new streamlined architectures for both residual and non-residual Inception networks. These variations improve the single-frame recognition performance on the ILSVRC 2012 classification task significantly. We further demonstrate how proper activation scaling stabilizes the training of very wide residual Inception networks. With an ensemble of three residual and one Inception-v4 networks, we achieve 3.08% top-5 error on the test set of the ImageNet classification (CLS) challenge.",keywords:["Residual","Residual neural network","Margin","Set","Test set","Network architecture"],concepts:["Residual","Residual neural network","Margin","Set","Test set","Network architecture"],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/11231/11090",is_oa:!0,n_refs:18,n_refs_in_core:1,degree:26,community:1,deg_w:192.5,betweenness:.0043,pagerank:.00489,eigenvector:.0181},{id:11,oaid:"W2954996726",doi:"10.1186/s40537-019-0197-0",title:"A survey on Image Data Augmentation for Deep Learning",authors:[{name:"Connor Shorten",institutions:["Florida Atlantic University"]},{name:"Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"]}],authorString:"Connor Shorten; Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"],countries:["US"],year:2019,journal:"Journal Of Big Data",citations:12619,abstract:"Deep convolutional neural networks have performed remarkably well on many Computer Vision tasks. However, these networks are heavily reliant on big data to avoid overfitting. Overfitting refers to the phenomenon when a network learns a function with very high variance such as to perfectly model the training data. Unfortunately, many application domains do not have access to big data, such as medical image analysis. This survey focuses on Data Augmentation, a data-space solution to the problem of limited data. Data Augmentation encompasses a suite of techniques that enhance the size and quality of training datasets such that better Deep Learning models can be built using them. The image augmentation algorithms discussed in this survey include geometric transformations, color space augmentations, kernel filters, mixing images, random erasing, feature space augmentation, adversarial training, generative adversarial networks, neural style transfer, and meta-learning. The application of augmentation methods based on GANs are heavily covered in this survey. In addition to augmentation techniques, this paper will briefly discuss other characteristics of Data Augmentation such as test-time augmentation, resolution impact, final dataset size, and curriculum learning. This survey will present existing methods for Data Augmentation, promising developments, and meta-level decisions for implementing Data Augmentation. Readers will understand how Data Augmentation can improve the performance of their models and expand limited datasets to take advantage of the capabilities of big data.",keywords:["Overfitting","Deep learning","Big data","Artificial neural network","Transfer of learning"],concepts:["Overfitting","Deep learning","Big data","Artificial neural network","Transfer of learning"],pdf_url:"https://journalofbigdata.springeropen.com/track/pdf/10.1186/s40537-019-0197-0",is_oa:!0,n_refs:119,n_refs_in_core:8,degree:34,community:1,deg_w:379,betweenness:.008,pagerank:.00915,eigenvector:.0321},{id:12,oaid:"W2109255472",doi:"10.1109/tpami.2015.2389824",title:"Spatial Pyramid Pooling in Deep Convolutional Networks for Visual Recognition",authors:[{name:"Kaiming He",institutions:["Microsoft (United States)","Microsoft Research Asia (China)"]},{name:"Xiangyu Zhang",institutions:["Xi'an Jiaotong University"]},{name:"Shaoqing Ren",institutions:["University of Science and Technology of China"]},{name:"Jian Sun",institutions:["Microsoft (United States)","Microsoft Research Asia (China)"]}],authorString:"Kaiming He; Xiangyu Zhang; Shaoqing Ren; Jian Sun",institutions:["Microsoft (United States)","Microsoft Research Asia (China)","University of Science and Technology of China","Xi'an Jiaotong University"],countries:["CN","US"],year:2015,journal:"IEEE Transactions on Pattern Analysis and Machine Intelligence",citations:11456,abstract:'Existing deep convolutional neural networks (CNNs) require a fixed-size (e.g., 224 × 224) input image. This requirement is "artificial" and may reduce the recognition accuracy for the images or sub-images of an arbitrary size/scale. In this work, we equip the networks with another pooling strategy, "spatial pyramid pooling", to eliminate the above requirement. The new network structure, called SPP-net, can generate a fixed-length representation regardless of image size/scale. Pyramid pooling is also robust to object deformations. With these advantages, SPP-net should in general improve all CNN-based image classification methods. On the ImageNet 2012 dataset, we demonstrate that SPP-net boosts the accuracy of a variety of CNN architectures despite their different designs. On the Pascal VOC 2007 and Caltech101 datasets, SPP-net achieves state-of-the-art classification results using a single full-image representation and no fine-tuning. The power of SPP-net is also significant in object detection. Using SPP-net, we compute the feature maps from the entire image only once, and then pool features in arbitrary regions (sub-images) to generate fixed-length representations for training the detectors. This method avoids repeatedly computing the convolutional features. In processing test images, our method is 24-102 × faster than the R-CNN method, while achieving better or comparable accuracy on Pascal VOC 2007. In ImageNet Large Scale Visual Recognition Challenge (ILSVRC) 2014, our methods rank #2 in object detection and #3 in image classification among all 38 teams. This manuscript also introduces the improvement made for this competition.',keywords:["Pooling","Pascal","Convolutional neural network","Pattern recognition","Pyramid","Contextual image classification"],concepts:["Pooling","Pascal","Convolutional neural network","Pattern recognition","Pyramid","Contextual image classification"],pdf_url:null,is_oa:!1,n_refs:70,n_refs_in_core:1,degree:22,community:1,deg_w:224.5,betweenness:.0044,pagerank:.00552,eigenvector:.0201},{id:13,oaid:"W2493916176",doi:"10.1162/tacl_a_00051",title:"Enriching Word Vectors with Subword Information",authors:[{name:"Piotr Bojanowski",institutions:["Meta (Israel)"]},{name:"Édouard Grave",institutions:["Meta (Israel)"]},{name:"Armand Joulin",institutions:["Meta (Israel)"]},{name:"Tomáš Mikolov",institutions:["Meta (Israel)"]}],authorString:"Piotr Bojanowski; Édouard Grave; Armand Joulin; Tomáš Mikolov",institutions:["Meta (Israel)"],countries:["IL"],year:2017,journal:"Transactions of the Association for Computational Linguistics",citations:9824,abstract:"Continuous word representations, trained on large unlabeled corpora are useful for many natural language processing tasks. Popular models that learn such representations ignore the morphology of words, by assigning a distinct vector to each word. This is a limitation, especially for languages with large vocabularies and many rare words. In this paper, we propose a new approach based on the skipgram model, where each word is represented as a bag of character n-grams. A vector representation is associated to each character n-gram; words being represented as the sum of these representations. Our method is fast, allowing to train models on large corpora quickly and allows us to compute word representations for words that did not appear in the training data. We evaluate our word representations on nine different languages, both on word similarity and analogy tasks. By comparing to recently proposed morphological word representations, we show that our vectors achieve state-of-the-art performance on these tasks.",keywords:["Word","Natural language processing","Character","Similarity","Analogy","Representation"],concepts:["Word","Natural language processing","Character","Similarity","Analogy","Representation"],pdf_url:"http://www.mitpressjournals.org/doi/pdf/10.1162/tacl_a_00051",is_oa:!0,n_refs:47,n_refs_in_core:1,degree:6,community:0,deg_w:29,betweenness:3e-4,pagerank:.00153,eigenvector:.0025},{id:14,oaid:"W2116341502",doi:"10.1109/tnn.2008.2005605",title:"The Graph Neural Network Model",authors:[{name:"Franco Scarselli",institutions:["University of Siena"]},{name:"M. Gori",institutions:["University of Siena"]},{name:"Ah Chung Tsoi",institutions:["Hong Kong Baptist University"]},{name:"Markus Hagenbuchner",institutions:["University of Wollongong"]},{name:"Gabriele Monfardini",institutions:["University of Siena"]}],authorString:"Franco Scarselli; M. Gori; Ah Chung Tsoi; Markus Hagenbuchner; Gabriele Monfardini",institutions:["Hong Kong Baptist University","University of Siena","University of Wollongong"],countries:["AU","HK","IT"],year:2008,journal:"IEEE Transactions on Neural Networks",citations:9444,abstract:"Many underlying relationships among data in several areas of science and engineering, e.g., computer vision, molecular chemistry, molecular biology, pattern recognition, and data mining, can be represented in terms of graphs. In this paper, we propose a new neural network model, called graph neural network (GNN) model, that extends existing neural network methods for processing the data represented in graph domains. This GNN model, which can directly process most of the practically useful types of graphs, e.g., acyclic, cyclic, directed, and undirected, implements a function tau(G,n) is an element of IR(m) that maps a graph G and one of its nodes n into an m-dimensional Euclidean space. A supervised learning algorithm is derived to estimate the parameters of the proposed GNN model. The computational cost of the proposed algorithm is also considered. Some experimental results are shown to validate the proposed learning algorithm, and to demonstrate its generalization capabilities.",keywords:["Artificial neural network","Graph","Theoretical computer science"],concepts:["Artificial neural network","Graph"],pdf_url:"https://figshare.com/articles/journal_contribution/The_graph_neural_network_model/27757629",is_oa:!0,n_refs:123,n_refs_in_core:0,degree:25,community:5,deg_w:147.5,betweenness:.0165,pagerank:.00378,eigenvector:.0644},{id:15,oaid:"W2907492528",doi:"10.1109/tnnls.2020.2978386",title:"A Comprehensive Survey on Graph Neural Networks",authors:[{name:"Zonghan Wu",institutions:["University of Technology Sydney"]},{name:"Shirui Pan",institutions:["Monash University"]},{name:"Fengwen Chen",institutions:["University of Technology Sydney"]},{name:"Guodong Long",institutions:["University of Technology Sydney"]},{name:"Chengqi Zhang",institutions:["University of Technology Sydney"]},{name:"Philip S. Yu",institutions:["University of Illinois Chicago"]}],authorString:"Zonghan Wu; Shirui Pan; Fengwen Chen; Guodong Long; Chengqi Zhang; Philip S. Yu",institutions:["Monash University","University of Illinois Chicago","University of Technology Sydney"],countries:["AU","US"],year:2020,journal:"IEEE Transactions on Neural Networks and Learning Systems",citations:9434,abstract:"Deep learning has revolutionized many machine learning tasks in recent years, ranging from image classification and video processing to speech recognition and natural language understanding. The data in these tasks are typically represented in the Euclidean space. However, there is an increasing number of applications, where data are generated from non-Euclidean domains and are represented as graphs with complex relationships and interdependency between objects. The complexity of graph data has imposed significant challenges on the existing machine learning algorithms. Recently, many studies on extending deep learning approaches for graph data have emerged. In this article, we provide a comprehensive overview of graph neural networks (GNNs) in data mining and machine learning fields. We propose a new taxonomy to divide the state-of-the-art GNNs into four categories, namely, recurrent GNNs, convolutional GNNs, graph autoencoders, and spatial-temporal GNNs. We further discuss the applications of GNNs across various domains and summarize the open-source codes, benchmark data sets, and model evaluation of GNNs. Finally, we propose potential research directions in this rapidly growing field.",keywords:["Deep learning","Graph","Convolutional neural network","Artificial neural network","Feature learning","Labeled data","Training set","Benchmark"],concepts:["Deep learning","Graph","Convolutional neural network","Artificial neural network","Feature learning"],pdf_url:"https://arxiv.org/pdf/1901.00596",is_oa:!0,n_refs:167,n_refs_in_core:6,degree:27,community:5,deg_w:426.5,betweenness:.0092,pagerank:.00883,eigenvector:.2427},{id:16,oaid:"W2508457857",doi:"10.1109/tip.2017.2662206",title:"Beyond a Gaussian Denoiser: Residual Learning of Deep CNN for Image Denoising",authors:[{name:"Kai Zhang",institutions:["Hong Kong Polytechnic University","Harbin Institute of Technology"]},{name:"Wangmeng Zuo",institutions:["Harbin Institute of Technology"]},{name:"Yunjin Chen",institutions:[]},{name:"Deyu Meng",institutions:["Xi'an Jiaotong University"]},{name:"Lei Zhang",institutions:["Hong Kong Polytechnic University"]}],authorString:"Kai Zhang; Wangmeng Zuo; Yunjin Chen; Deyu Meng; Lei Zhang",institutions:["Harbin Institute of Technology","Hong Kong Polytechnic University","Xi'an Jiaotong University"],countries:["CN","HK"],year:2017,journal:"IEEE Transactions on Image Processing",citations:8910,abstract:"The discriminative model learning for image denoising has been recently attracting considerable attentions due to its favorable denoising performance. In this paper, we take one step forward by investigating the construction of feed-forward denoising convolutional neural networks (DnCNNs) to embrace the progress in very deep architecture, learning algorithm, and regularization method into image denoising. Specifically, residual learning and batch normalization are utilized to speed up the training process as well as boost the denoising performance. Different from the existing discriminative denoising models which usually train a specific model for additive white Gaussian noise at a certain noise level, our DnCNN model is able to handle Gaussian denoising with unknown noise level (i.e., blind Gaussian denoising). With the residual learning strategy, DnCNN implicitly removes the latent clean image in the hidden layers. This property motivates us to train a single DnCNN model to tackle with several general image denoising tasks, such as Gaussian denoising, single image super-resolution, and JPEG image deblocking. Our extensive experiments demonstrate that our DnCNN model can not only exhibit high effectiveness in several general image denoising tasks, but also be efficiently implemented by benefiting from GPU computing.",keywords:["Residual","Image denoising","Noise reduction","Pattern recognition","Deep learning","Image"],concepts:["Residual","Image denoising","Noise reduction","Pattern recognition","Deep learning","Image"],pdf_url:"https://arxiv.org/pdf/1608.03981",is_oa:!0,n_refs:66,n_refs_in_core:3,degree:20,community:1,deg_w:170.5,betweenness:.0032,pagerank:.00473,eigenvector:.009},{id:17,oaid:"W2107878631",doi:"10.1109/72.279181",title:"Learning long-term dependencies with gradient descent is difficult",authors:[{name:"Yoshua Bengio",institutions:["AT&T (United States)","Queen's University","Université de Montréal"]},{name:"P. Simard",institutions:["AT&T (United States)"]},{name:"Paolo Frasconi",institutions:["University of Florence"]}],authorString:"Yoshua Bengio; P. Simard; Paolo Frasconi",institutions:["AT&T (United States)","Queen's University","University of Florence","Université de Montréal"],countries:["CA","IT","US"],year:1994,journal:"IEEE Transactions on Neural Networks",citations:8516,abstract:"Recurrent neural networks can be used to map input sequences to output sequences, such as for recognition, production or prediction problems. However, practical difficulties have been reported in training recurrent neural networks to perform tasks in which the temporal contingencies present in the input/output sequences span long intervals. We show why gradient based learning algorithms face an increasingly difficult problem as the duration of the dependencies to be captured increases. These results expose a trade-off between efficient learning by gradient descent and latching on information for long periods. Based on an understanding of this problem, alternatives to standard gradient descent are considered.",keywords:["Gradient descent","Term","Stochastic gradient descent","Artificial neural network","Recurrent neural network","Deep learning"],concepts:["Gradient descent","Term","Stochastic gradient descent","Artificial neural network","Recurrent neural network","Deep learning"],pdf_url:null,is_oa:!1,n_refs:26,n_refs_in_core:0,degree:11,community:0,deg_w:63.5,betweenness:.0016,pagerank:.00221,eigenvector:.0064},{id:18,oaid:"W3140854437",doi:"10.1186/s40537-021-00444-8",title:"Review of deep learning: concepts, CNN architectures, challenges, applications, future directions",authors:[{name:"Laith Alzubaidi",institutions:["Queensland University of Technology","University of Information Technology and Communications"]},{name:"Jinglan Zhang",institutions:["Queensland University of Technology"]},{name:"Amjad J. Humaidi",institutions:["University of Technology - Iraq"]},{name:"Ayad Q. Al-Dujaili",institutions:["Middle Technical University"]},{name:"Ye Duan",institutions:["University of Missouri"]},{name:"Omran Al-Shamma",institutions:["University of Information Technology and Communications"]},{name:"José Santamaría",institutions:["Universidad de Jaén"]},{name:"Mohammed A. Fadhel",institutions:["Thi Qar University","University of Sumer"]},{name:"Muthana Al‐Amidie",institutions:["University of Missouri"]},{name:"Laith Farhan",institutions:["Manchester Metropolitan University"]}],authorString:"Laith Alzubaidi; Jinglan Zhang; Amjad J. Humaidi; Ayad Q. Al-Dujaili; Ye Duan; Omran Al-Shamma; José Santamaría; Mohammed A. Fadhel; Muthana Al‐Amidie; Laith Farhan",institutions:["Manchester Metropolitan University","Middle Technical University","Queensland University of Technology","Thi Qar University","Universidad de Jaén","University of Information Technology and Communications","University of Missouri","University of Sumer","University of Technology - Iraq"],countries:["AU","ES","GB","IQ","US"],year:2021,journal:"Journal Of Big Data",citations:7669,abstract:"In the last few years, the deep learning (DL) computing paradigm has been deemed the Gold Standard in the machine learning (ML) community. Moreover, it has gradually become the most widely used computational approach in the field of ML, thus achieving outstanding results on several complex cognitive tasks, matching or even beating those provided by human performance. One of the benefits of DL is the ability to learn massive amounts of data. The DL field has grown fast in the last few years and it has been extensively used to successfully address a wide range of traditional applications. More importantly, DL has outperformed well-known ML techniques in many domains, e.g., cybersecurity, natural language processing, bioinformatics, robotics and control, and medical information processing, among many others. Despite it has been contributed several works reviewing the State-of-the-Art on DL, all of them only tackled one aspect of the DL, which leads to an overall lack of knowledge about it. Therefore, in this contribution, we propose using a more holistic approach in order to provide a more suitable starting point from which to develop a full understanding of DL. Specifically, this review attempts to provide a more comprehensive survey of the most important aspects of DL and including those enhancements recently added to the field. In particular, this paper outlines the importance of DL, presents the types of DL techniques and networks. It then presents convolutional neural networks (CNNs) which the most utilized DL network type and describes the development of CNNs architectures together with their main features, e.g., starting with the AlexNet network and closing with the High-Resolution network (HR.Net). Finally, we further present the challenges and suggested solutions to help researchers understand the existing research gaps. It is followed by a list of the major DL applications. Computational tools including FPGA, GPU, and CPU are summarized along with a description of their influence on DL. The paper ends with the evolution matrix, benchmark datasets, and summary and conclusion.",keywords:["Field","Deep learning","Convolutional neural network","Data science","Point"],concepts:["Field","Deep learning","Convolutional neural network","Data science","Point"],pdf_url:"https://journalofbigdata.springeropen.com/counter/pdf/10.1186/s40537-021-00444-8",is_oa:!0,n_refs:362,n_refs_in_core:17,degree:34,community:1,deg_w:471.5,betweenness:.0138,pagerank:.01084,eigenvector:.0525},{id:19,oaid:"W2979750740",doi:"10.1145/3326362",title:"Dynamic Graph CNN for Learning on Point Clouds",authors:[{name:"Yue Wang",institutions:["Massachusetts Institute of Technology"]},{name:"Yongbin Sun",institutions:["Massachusetts Institute of Technology"]},{name:"Ziwei Liu",institutions:["International Computer Science Institute","University of California, Berkeley"]},{name:"Sanjay E. Sarma",institutions:["Massachusetts Institute of Technology"]},{name:"Michael M. Bronstein",institutions:["Imperial College London","Università della Svizzera italiana"]},{name:"Justin Solomon",institutions:["Massachusetts Institute of Technology"]}],authorString:"Yue Wang; Yongbin Sun; Ziwei Liu; Sanjay E. Sarma; Michael M. Bronstein; Justin Solomon",institutions:["Imperial College London","International Computer Science Institute","Massachusetts Institute of Technology","University of California, Berkeley","Università della Svizzera italiana"],countries:["CH","GB","US"],year:2019,journal:"ACM Transactions on Graphics",citations:6805,abstract:"Point clouds provide a flexible geometric representation suitable for countless applications in computer graphics; they also comprise the raw output of most 3D data acquisition devices. While hand-designed features on point clouds have long been proposed in graphics and vision, however, the recent overwhelming success of convolutional neural networks (CNNs) for image analysis suggests the value of adapting insight from CNN to the point cloud world. Point clouds inherently lack topological information, so designing a model to recover topology can enrich the representation power of point clouds. To this end, we propose a new neural network module dubbed EdgeConv suitable for CNN-based high-level tasks on point clouds, including classification and segmentation. EdgeConv acts on graphs dynamically computed in each layer of the network. It is differentiable and can be plugged into existing architectures. Compared to existing modules operating in extrinsic space or treating each point independently, EdgeConv has several appealing properties: It incorporates local neighborhood information; it can be stacked applied to learn global shape properties; and in multi-layer systems affinity in feature space captures semantic characteristics over potentially long distances in the original embedding. We show the performance of our model on standard benchmarks, including ModelNet40, ShapeNetPart, and S3DIS.",keywords:["Point cloud","Representation","Convolutional neural network","Embedding","Computer graphics","Graph","Segmentation"],concepts:["Point cloud","Representation","Convolutional neural network","Embedding","Computer graphics","Graph","Segmentation"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3326362",is_oa:!0,n_refs:86,n_refs_in_core:3,degree:11,community:5,deg_w:97,betweenness:4e-4,pagerank:.00257,eigenvector:.0535},{id:20,oaid:"W1641498739",doi:"10.1109/tmi.2014.2377694",title:"The Multimodal Brain Tumor Image Segmentation Benchmark (BRATS)",authors:[{name:"Bjoern Menze",institutions:["Institut national de recherche en sciences et technologies du numérique","ETH Zurich","Technical University of Munich","Massachusetts Institute of Technology"]},{name:"András Jakab",institutions:["University of Debrecen","ETH Zurich"]},{name:"Stefan Bauer",institutions:["University of Bern","University Hospital of Bern"]},{name:"Jayashree Kalpathy–Cramer",institutions:["Harvard University"]},{name:"Keyvan Farahani",institutions:["National Institutes of Health"]},{name:"Justin Kirby",institutions:["National Institutes of Health"]},{name:"Yuliya Burren",institutions:["University Hospital of Bern"]},{name:"Nicole Porz",institutions:["University Hospital of Bern"]},{name:"Johannes Slotboom",institutions:["University Hospital of Bern"]},{name:"Roland Wiest",institutions:["University Hospital of Bern"]},{name:"Levente Lánczi",institutions:["University of Debrecen"]},{name:"Elizabeth R. Gerstner",institutions:["Harvard University","Massachusetts General Hospital"]},{name:"Marc‐An\uFEFFdré Weber",institutions:["Heidelberg University","University Hospital Heidelberg"]},{name:"Tal Arbel",institutions:["McGill University"]},{name:"Brian Avants",institutions:["University of Pennsylvania"]},{name:"Nicholas Ayache",institutions:["Institut national de recherche en sciences et technologies du numérique"]},{name:"Patricia Buendia",institutions:[]},{name:"D. Louis Collins",institutions:["McGill Genome Centre","McGill University"]},{name:"Nicolas Cordier",institutions:["Institut national de recherche en sciences et technologies du numérique"]},{name:"Jason J. Corso",institutions:["Buffalo State University"]},{name:"Antonio Criminisi",institutions:["Microsoft Research (United Kingdom)"]},{name:"Tilak Das",institutions:["Cambridge University Hospitals NHS Foundation Trust"]},{name:"Hervé Delingette",institutions:["Institut national de recherche en sciences et technologies du numérique"]},{name:"Çağatay Demiralp",institutions:["Stanford University"]},{name:"Christopher R. Durst",institutions:["University of Virginia"]},{name:"Michel Dojat",institutions:["Institut national de recherche en sciences et technologies du numérique","Inserm"]},{name:"Senan Doyle",institutions:["Institut national de recherche en sciences et technologies du numérique","Inserm"]},{name:"Joana Festa",institutions:["University of Minho"]},{name:"Florence Forbes",institutions:["Institut national de recherche en sciences et technologies du numérique","Inserm"]},{name:"Ezequiel Geremia",institutions:["Institut national de recherche en sciences et technologies du numérique"]},{name:"Ben Glocker",institutions:["Imperial College London"]},{name:"Polina Golland",institutions:["Massachusetts Institute of Technology"]},{name:"Xiaotao Guo",institutions:["Columbia University"]},{name:"Andaç Hamamcı",institutions:["Sabancı Üniversitesi"]},{name:"Khan M. Iftekharuddin",institutions:["Old Dominion University"]},{name:"Raj Jena",institutions:["Cambridge University Hospitals NHS Foundation Trust"]},{name:"Nigel John",institutions:["University of Miami"]},{name:"Ender Konukoğlu",institutions:["Harvard University","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Danial Lashkari",institutions:["Massachusetts Institute of Technology"]},{name:"José Mariz",institutions:["University of Minho"]},{name:"Raphael Meier",institutions:["University of Bern"]},{name:"Sérgio Pereira",institutions:["University of Minho"]},{name:"Doina Precup",institutions:["McGill University"]},{name:"Stephen J. Price",institutions:["Cambridge University Hospitals NHS Foundation Trust"]},{name:"Tammy Riklin Raviv",institutions:["Ben-Gurion University of the Negev","Brigham and Women's Hospital","Harvard University","Massachusetts Institute of Technology"]},{name:"Syed M. S. Reza",institutions:["Old Dominion University"]},{name:"Michael J. Ryan",institutions:[]},{name:"Duygu Sarıkaya",institutions:["Buffalo State University"]},{name:"Lawrence H. Schwartz",institutions:["Columbia University"]},{name:"Hoo-Chang Shin",institutions:["Ben-Gurion University of the Negev"]},{name:"Jamie Shotton",institutions:["Microsoft Research (United Kingdom)"]},{name:"Carlos A. Silva",institutions:["University of Minho"]},{name:"Nuno Sousa",institutions:["University of Minho"]},{name:"Nagesh K. Subbanna",institutions:["Heidelberg University","University Hospital Heidelberg"]},{name:"Gábor Székely",institutions:["ETH Zurich"]},{name:"Thomas J. Taylor",institutions:[]},{name:"Owen Thomas",institutions:["Cambridge University Hospitals NHS Foundation Trust"]},{name:"Nicholas J. Tustison",institutions:["University of Virginia"]},{name:"Gözde Ünal",institutions:["Sabancı Üniversitesi"]},{name:"Flor Vasseur",institutions:["Institut national de recherche en sciences et technologies du numérique","Inserm"]},{name:"Max Wintermark",institutions:["University of Virginia"]},{name:"Dong Hye Ye",institutions:["Purdue University West Lafayette"]},{name:"Liang Zhao",institutions:["Buffalo State University"]},{name:"Binsheng Zhao",institutions:["Columbia University"]},{name:"Darko Zikic",institutions:["Microsoft Research (United Kingdom)"]},{name:"Marcel Prastawa",institutions:["GE Global Research (United States)"]},{name:"Mauricio Reyes",institutions:["University of Bern"]},{name:"Koen Van Leemput",institutions:["Harvard University","Technical University of Denmark","Aalto University"]}],authorString:"Bjoern Menze; András Jakab; Stefan Bauer; Jayashree Kalpathy–Cramer; Keyvan Farahani; Justin Kirby; Yuliya Burren; Nicole Porz; Johannes Slotboom; Roland Wiest; Levente Lánczi; Elizabeth R. Gerstner et al.",institutions:["Aalto University","Athinoula A. Martinos Center for Biomedical Imaging","Ben-Gurion University of the Negev","Brigham and Women's Hospital","Buffalo State University","Cambridge University Hospitals NHS Foundation Trust","Columbia University","ETH Zurich","GE Global Research (United States)","Harvard University","Heidelberg University","Imperial College London","Inserm","Institut national de recherche en sciences et technologies du numérique","Massachusetts General Hospital","Massachusetts Institute of Technology","McGill Genome Centre","McGill University","Microsoft Research (United Kingdom)","National Institutes of Health","Old Dominion University","Purdue University West Lafayette","Sabancı Üniversitesi","Stanford University","Technical University of Denmark","Technical University of Munich","University Hospital Heidelberg","University Hospital of Bern","University of Bern","University of Debrecen","University of Miami","University of Minho","University of Pennsylvania","University of Virginia"],countries:["CA","CH","DE","DK","FI","FR","GB","HU","IL","PT","TR","US"],year:2014,journal:"IEEE Transactions on Medical Imaging",citations:6608,abstract:"In this paper we report the set-up and results of the Multimodal Brain Tumor Image Segmentation Benchmark (BRATS) organized in conjunction with the MICCAI 2012 and 2013 conferences. Twenty state-of-the-art tumor segmentation algorithms were applied to a set of 65 multi-contrast MR scans of low- and high-grade glioma patients-manually annotated by up to four raters-and to 65 comparable scans generated using tumor image simulation software. Quantitative evaluations revealed considerable disagreement between the human raters in segmenting various tumor sub-regions (Dice scores in the range 74%-85%), illustrating the difficulty of this task. We found that different algorithms worked best for different sub-regions (reaching performance comparable to human inter-rater variability), but that no single algorithm ranked in the top for all sub-regions simultaneously. Fusing several good algorithms using a hierarchical majority vote yielded segmentations that consistently ranked above all individual algorithms, indicating remaining opportunities for further methodological improvements. The BRATS image data and manual annotations continue to be publicly available through an online evaluation system as an ongoing benchmarking resource.",keywords:["Image segmentation","Benchmark","Computer vision","Pattern recognition","Image","Brain tumor"],concepts:["Image segmentation","Benchmark","Computer vision","Pattern recognition","Image","Brain tumor"],pdf_url:"https://ieeexplore.ieee.org/ielx7/42/7283692/06975210.pdf",is_oa:!0,n_refs:156,n_refs_in_core:1,degree:14,community:1,deg_w:86,betweenness:.0032,pagerank:.0027,eigenvector:.008},{id:21,oaid:"W2402144811",doi:"10.5555/3026877.3026899",title:"TensorFlow: a system for large-scale machine learning",authors:[{name:"Martı́n Abadi",institutions:["Google (United States)"]},{name:"Paul Barham",institutions:["Google (United States)"]},{name:"Jianmin Chen",institutions:["Google (United States)"]},{name:"Zhifeng Chen",institutions:["Google (United States)"]},{name:"Andy Davis",institutions:["Google (United States)"]},{name:"Jay B. Dean",institutions:["Google (United States)"]},{name:"Matthieu Devin",institutions:["Google (United States)"]},{name:"Sanjay Ghemawat",institutions:["Google (United States)"]},{name:"Geoffrey Irving",institutions:["Google (United States)"]},{name:"Michael Isard",institutions:["Google (United States)"]},{name:"Manjunath Kudlur",institutions:["Google (United States)"]},{name:"Josh Levenberg",institutions:["Google (United States)"]},{name:"Rajat Monga",institutions:["Google (United States)"]},{name:"Sherry Moore",institutions:["Google (United States)"]},{name:"Derek G. Murray",institutions:["Google (United States)"]},{name:"Benoit Steiner",institutions:["Google (United States)"]},{name:"Paul A. Tucker",institutions:["Google (United States)"]},{name:"Vijay Vasudevan",institutions:["Google (United States)"]},{name:"Pete Warden",institutions:["Google (United States)"]},{name:"Martin Wicke",institutions:["Google (United States)"]},{name:"Yuan Yu",institutions:["Google (United States)"]},{name:"Xiaoqiang Zheng",institutions:["Google (United States)"]}],authorString:"Martı́n Abadi; Paul Barham; Jianmin Chen; Zhifeng Chen; Andy Davis; Jay B. Dean; Matthieu Devin; Sanjay Ghemawat; Geoffrey Irving; Michael Isard; Manjunath Kudlur; Josh Levenberg et al.",institutions:["Google (United States)"],countries:["US"],year:2016,journal:"Operating Systems Design and Implementation",citations:6365,abstract:"TensorFlow is a machine learning system that operates at large scale and in heterogeneous environments. Tensor-Flow uses dataflow graphs to represent computation, shared state, and the operations that mutate that state. It maps the nodes of a dataflow graph across many machines in a cluster, and within a machine across multiple computational devices, including multicore CPUs, general-purpose GPUs, and custom-designed ASICs known as Tensor Processing Units (TPUs). This architecture gives flexibility to the application developer: whereas in previous parameter server designs the management of shared state is built into the system, TensorFlow enables developers to experiment with novel optimizations and training algorithms. TensorFlow supports a variety of applications, with a focus on training and inference on deep neural networks. Several Google services use TensorFlow in production, we have released it as an open-source project, and it has become widely used for machine learning research. In this paper, we describe the TensorFlow dataflow model and demonstrate the compelling performance that TensorFlow achieves for several real-world applications.",keywords:["Dataflow","Multi-core processor","Computer architecture","Deep learning","Scalability"],concepts:["Dataflow","Multi-core processor","Computer architecture","Deep learning","Scalability"],pdf_url:null,is_oa:!1,n_refs:55,n_refs_in_core:1,degree:19,community:0,deg_w:101.5,betweenness:.0043,pagerank:.00303,eigenvector:.01},{id:22,oaid:"W2395579298",doi:"10.1186/s40537-016-0043-6",title:"A survey of transfer learning",authors:[{name:"Karl R. Weiss",institutions:["Florida Atlantic University"]},{name:"Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"]},{name:"Dingding Wang",institutions:["Florida Atlantic University"]}],authorString:"Karl R. Weiss; Taghi M. Khoshgoftaar; Dingding Wang",institutions:["Florida Atlantic University"],countries:["US"],year:2016,journal:"Journal Of Big Data",citations:6207,abstract:"Machine learning and data mining techniques have been used in numerous real-world applications. An assumption of traditional machine learning methodologies is the training data and testing data are taken from the same domain, such that the input feature space and data distribution characteristics are the same. However, in some real-world machine learning scenarios, this assumption does not hold. There are cases where training data is expensive or difficult to collect. Therefore, there is a need to create high-performance learners trained with more easily obtained data from different domains. This methodology is referred to as transfer learning. This survey paper formally defines transfer learning, presents information on current solutions, and reviews applications applied to transfer learning. Lastly, there is information listed on software downloads for various transfer learning solutions and a discussion of possible future research work. The transfer learning solutions surveyed are independent of data size and can be applied to big data environments.",keywords:["Transfer of learning","Inductive transfer","Domain","Big data","Feature"],concepts:["Transfer of learning","Inductive transfer","Domain","Big data","Feature"],pdf_url:"https://journalofbigdata.springeropen.com/track/pdf/10.1186/s40537-016-0043-6",is_oa:!0,n_refs:143,n_refs_in_core:0,degree:15,community:1,deg_w:78.5,betweenness:.0016,pagerank:.00243,eigenvector:.0098},{id:23,oaid:"W2746553466",doi:"10.1609/aaai.v30i1.10295",title:"Deep Reinforcement Learning with Double Q-Learning",authors:[{name:"Hado van Hasselt",institutions:["Google (United States)","Google DeepMind (United Kingdom)"]},{name:"Arthur Guez",institutions:["Google (United States)","Google DeepMind (United Kingdom)"]},{name:"David Silver",institutions:["Google (United States)","Google DeepMind (United Kingdom)"]}],authorString:"Hado van Hasselt; Arthur Guez; David Silver",institutions:["Google (United States)","Google DeepMind (United Kingdom)"],countries:["GB","US"],year:2016,journal:null,citations:6099,abstract:"The popular Q-learning algorithm is known to overestimate action values under certain conditions. It was not previously known whether, in practice, such overestimations are common, whether they harm performance, and whether they can generally be prevented. In this paper, we answer all these questions affirmatively. In particular, we first show that the recent DQN algorithm, which combines Q-learning with a deep neural network, suffers from substantial overestimations in some games in the Atari 2600 domain. We then show that the idea behind the Double Q-learning algorithm, which was introduced in a tabular setting, can be generalized to work with large-scale function approximation. We propose a specific adaptation to the DQN algorithm and show that the resulting algorithm not only reduces the observed overestimations, as hypothesized, but that this also leads to much better performance on several games.",keywords:["Reinforcement learning","Q-learning","Action","Function","Artificial neural network","Harm"],concepts:["Reinforcement learning","Q-learning","Action","Function","Artificial neural network","Harm"],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/10295/10154",is_oa:!0,n_refs:22,n_refs_in_core:1,degree:5,community:0,deg_w:37.5,betweenness:0,pagerank:.00162,eigenvector:.0028},{id:24,oaid:"W2153791616",doi:"10.1017/s0140525x12000477",title:"Whatever next? Predictive brains, situated agents, and the future of cognitive science",authors:[{name:"Andy Clark",institutions:["University of Edinburgh"]}],authorString:"Andy Clark",institutions:["University of Edinburgh"],countries:["GB"],year:2013,journal:"Behavioral and Brain Sciences",citations:5957,abstract:'Brains, it has recently been argued, are essentially prediction machines. They are bundles of cells that support perception and action by constantly attempting to match incoming sensory inputs with top-down expectations or predictions. This is achieved using a hierarchical generative model that aims to minimize prediction error within a bidirectional cascade of cortical processing. Such accounts offer a unifying model of perception and action, illuminate the functional role of attention, and may neatly capture the special contribution of cortical processing to adaptive success. This target article critically examines this "hierarchical prediction machine" approach, concluding that it offers the best clue yet to the shape of a unified science of mind and action. Sections 1 and 2 lay out the key elements and implications of the approach. Section 3 explores a variety of pitfalls and challenges, spanning the evidential, the methodological, and the more properly conceptual. The paper ends (sections 4 and 5) by asking how such approaches might impact our more general vision of mind, experience, and agency.',keywords:["Situated","Cognitive science","Cognition","Cognitive psychology","Neuroscience"],concepts:["Situated","Cognitive science","Cognition","Cognitive psychology"],pdf_url:"https://www.cambridge.org/core/services/aop-cambridge-core/content/view/33542C736E17E3D1D44E8D03BE5F4CD9/S0140525X12000477a.pdf/div-class-title-whatever-next-predictive-brains-situated-agents-and-the-future-of-cognitive-science-div.pdf",is_oa:!0,n_refs:394,n_refs_in_core:1,degree:7,community:6,deg_w:73.5,betweenness:.03,pagerank:.00515,eigenvector:.0014},{id:25,oaid:"W2253429366",doi:"10.1109/tmi.2016.2528162",title:"Deep Convolutional Neural Networks for Computer-Aided Detection: CNN Architectures, Dataset Characteristics and Transfer Learning",authors:[{name:"Hoo-Chang Shin",institutions:[]},{name:"Holger R. Roth",institutions:[]},{name:"Mingchen Gao",institutions:[]},{name:"Le Lü",institutions:["National Institutes of Health Clinical Center"]},{name:"Ziyue Xu",institutions:[]},{name:"Isabella Nogues",institutions:[]},{name:"Jianhua Yao",institutions:["National Institutes of Health Clinical Center"]},{name:"Daniel J. Mollura",institutions:[]},{name:"Ronald M. Summers",institutions:["National Institutes of Health Clinical Center"]}],authorString:"Hoo-Chang Shin; Holger R. Roth; Mingchen Gao; Le Lü; Ziyue Xu; Isabella Nogues; Jianhua Yao; Daniel J. Mollura; Ronald M. Summers",institutions:["National Institutes of Health Clinical Center"],countries:["US"],year:2016,journal:"IEEE Transactions on Medical Imaging",citations:5820,abstract:"Remarkable progress has been made in image recognition, primarily due to the availability of large-scale annotated datasets and deep convolutional neural networks (CNNs). CNNs enable learning data-driven, highly representative, hierarchical image features from sufficient training data. However, obtaining datasets as comprehensively annotated as ImageNet in the medical imaging domain remains a challenge. There are currently three major techniques that successfully employ CNNs to medical image classification: training the CNN from scratch, using off-the-shelf pre-trained CNN features, and conducting unsupervised CNN pre-training with supervised fine-tuning. Another effective method is transfer learning, i.e., fine-tuning CNN models pre-trained from natural image dataset to medical image tasks. In this paper, we exploit three important, but previously understudied factors of employing deep convolutional neural networks to computer-aided detection problems. We first explore and evaluate different CNN architectures. The studied models contain 5 thousand to 160 million parameters, and vary in numbers of layers. We then evaluate the influence of dataset scale and spatial image context on performance. Finally, we examine when and why transfer learning from pre-trained ImageNet (via fine-tuning) can be useful. We study two specific computer-aided detection (CADe) problems, namely thoraco-abdominal lymph node (LN) detection and interstitial lung disease (ILD) classification. We achieve the state-of-the-art performance on the mediastinal LN detection, and report the first five-fold cross-validation classification results on predicting axial CT slices with ILD categories. Our extensive empirical evaluation, CNN model analysis and valuable insights can be extended to the design of high performance CAD systems for other medical imaging tasks.",keywords:["Convolutional neural network","Transfer of learning","Deep learning","Contextual image classification","Pattern recognition","Context"],concepts:["Convolutional neural network","Transfer of learning","Deep learning","Contextual image classification","Pattern recognition","Context"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/4890616",is_oa:!0,n_refs:104,n_refs_in_core:6,degree:28,community:1,deg_w:317.5,betweenness:.0093,pagerank:.00743,eigenvector:.0361},{id:26,oaid:"W3152893301",doi:"10.1016/j.aiopen.2021.01.001",title:"Graph neural networks: A review of methods and applications",authors:[{name:"Jie Zhou",institutions:["Tsinghua University"]},{name:"Ganqu Cui",institutions:["Tsinghua University"]},{name:"Shengding Hu",institutions:["Tsinghua University"]},{name:"Zhengyan Zhang",institutions:["Tsinghua University"]},{name:"Cheng Yang",institutions:["Beijing University of Posts and Telecommunications"]},{name:"Zhiyuan Liu",institutions:["Tsinghua University"]},{name:"Lifeng Wang",institutions:["Tencent (China)"]},{name:"Changcheng Li",institutions:["Tencent (China)"]},{name:"Maosong Sun",institutions:["Tsinghua University"]}],authorString:"Jie Zhou; Ganqu Cui; Shengding Hu; Zhengyan Zhang; Cheng Yang; Zhiyuan Liu; Lifeng Wang; Changcheng Li; Maosong Sun",institutions:["Beijing University of Posts and Telecommunications","Tencent (China)","Tsinghua University"],countries:["CN"],year:2020,journal:"AI Open",citations:5625,abstract:"Lots of learning tasks require dealing with graph data which contains rich relation information among elements. Modeling physics systems, learning molecular fingerprints, predicting protein interface, and classifying diseases demand a model to learn from graph inputs. In other domains such as learning from non-structural data like texts and images, reasoning on extracted structures (like the dependency trees of sentences and the scene graphs of images) is an important research topic which also needs graph reasoning models. Graph neural networks (GNNs) are neural models that capture the dependence of graphs via message passing between the nodes of graphs. In recent years, variants of GNNs such as graph convolutional network (GCN), graph attention network (GAT), graph recurrent network (GRN) have demonstrated ground-breaking performances on many deep learning tasks. In this survey, we propose a general design pipeline for GNN models and discuss the variants of each component, systematically categorize the applications, and propose four open problems for future research.",keywords:["Graph","Categorization","Deep learning","Graph database","Theoretical computer science","Convolutional neural network"],concepts:["Graph","Categorization","Deep learning","Graph database","Theoretical computer science","Convolutional neural network"],pdf_url:"https://doi.org/10.1016/j.aiopen.2021.01.001",is_oa:!0,n_refs:514,n_refs_in_core:9,degree:26,community:5,deg_w:515.5,betweenness:.0076,pagerank:.01051,eigenvector:.2756},{id:27,oaid:"W3168997536",doi:"10.1109/tnnls.2021.3084827",title:"A Survey of Convolutional Neural Networks: Analysis, Applications, and Prospects",authors:[{name:"Zewen Li",institutions:["Hohai University"]},{name:"Fan Liu",institutions:["Hohai University"]},{name:"Wenjie Yang",institutions:["Hohai University"]},{name:"Shouheng Peng",institutions:["Hohai University"]},{name:"Jun Zhou",institutions:["Griffith University"]}],authorString:"Zewen Li; Fan Liu; Wenjie Yang; Shouheng Peng; Jun Zhou",institutions:["Griffith University","Hohai University"],countries:["AU","CN"],year:2021,journal:"IEEE Transactions on Neural Networks and Learning Systems",citations:4924,abstract:"A convolutional neural network (CNN) is one of the most significant networks in the deep learning field. Since CNN made impressive achievements in many areas, including but not limited to computer vision and natural language processing, it attracted much attention from both industry and academia in the past few years. The existing reviews mainly focus on CNN's applications in different scenarios without considering CNN from a general perspective, and some novel ideas proposed recently are not covered. In this review, we aim to provide some novel ideas and prospects in this fast-growing field. Besides, not only 2-D convolution but also 1-D and multidimensional ones are involved. First, this review introduces the history of CNN. Second, we provide an overview of various convolutions. Third, some classic and advanced CNN models are introduced; especially those key points making them reach state-of-the-art results. Fourth, through experimental analysis, we draw some conclusions and provide several rules of thumb for functions and hyperparameter selection. Fifth, the applications of 1-D, 2-D, and multidimensional convolution are covered. Finally, some open issues and promising directions for CNN are discussed as guidelines for future work.",keywords:["Convolutional neural network","Data science"],concepts:["Convolutional neural network","Data science"],pdf_url:"http://hdl.handle.net/10072/405164",is_oa:!0,n_refs:263,n_refs_in_core:6,degree:21,community:1,deg_w:329,betweenness:.0037,pagerank:.00744,eigenvector:.0415},{id:28,oaid:"W2962772482",doi:"10.1145/3236009",title:"A survey of methods for explaining black box models",authors:[{name:"Riccardo Guidotti",institutions:["University of Pisa"]},{name:"Anna Monreale",institutions:["University of Pisa"]},{name:"Salvatore Ruggieri",institutions:["University of Pisa"]},{name:"Franco Turini",institutions:["University of Pisa"]},{name:"Fosca Giannotti",institutions:[`Istituto di Scienza e Tecnologie dell'Informazione "Alessandro Faedo"`]},{name:"Dino Pedreschi",institutions:["University of Pisa"]}],authorString:"Riccardo Guidotti; Anna Monreale; Salvatore Ruggieri; Franco Turini; Fosca Giannotti; Dino Pedreschi",institutions:[`Istituto di Scienza e Tecnologie dell'Informazione "Alessandro Faedo"`,"University of Pisa"],countries:["IT"],year:2019,journal:"ISTI Open Portal",citations:4812,abstract:"In recent years, many accurate decision support systems have been constructed as black boxes, that is as systems that hide their internal logic to the user. This lack of explanation constitutes both a practical and an ethical issue. The literature reports many approaches aimed at overcoming this crucial weakness, sometimes at the cost of sacrificing accuracy for interpretability. The applications in which black box decision systems can be used are various, and each approach is typically developed to provide a solution for a specific problem and, as a consequence, it explicitly or implicitly delineates its own definition of interpretability and explanation. The aim of this article is to provide a classification of the main problems addressed in the literature with respect to the notion of explanation and the type of black box system. Given a problem definition, a black box type, and a desired explanation, this survey should help the researcher to find the proposals more useful for his own work. The proposed classification of approaches to open black box models should also be useful for putting the many research open questions in perspective.",keywords:["Interpretability","Black box","Perspective","Data science","Management science"],concepts:["Interpretability","Black box","Perspective","Data science","Management science"],pdf_url:"https://openportal.isti.cnr.it/doc?id=people______::59c23a947c3ae79b5c331dedba7a295e",is_oa:!0,n_refs:82,n_refs_in_core:1,degree:19,community:4,deg_w:232,betweenness:7e-4,pagerank:.00484,eigenvector:.1068},{id:29,oaid:"W2473156356",doi:"10.3389/fpls.2016.01419",title:"Using Deep Learning for Image-Based Plant Disease Detection",authors:[{name:"Sharada P. Mohanty",institutions:["Electronic Product Services (Czechia)","École Polytechnique Fédérale de Lausanne"]},{name:"David Hughes",institutions:["Pennsylvania State University","Center for Disease Dynamics, Economics & Policy"]},{name:"Marcel Salathé",institutions:["Electronic Product Services (Czechia)","École Polytechnique Fédérale de Lausanne"]}],authorString:"Sharada P. Mohanty; David Hughes; Marcel Salathé",institutions:["Center for Disease Dynamics, Economics & Policy","Electronic Product Services (Czechia)","Pennsylvania State University","École Polytechnique Fédérale de Lausanne"],countries:["CH","CZ","US"],year:2016,journal:"Frontiers in Plant Science",citations:4692,abstract:"Crop diseases are a major threat to food security, but their rapid identification remains difficult in many parts of the world due to the lack of the necessary infrastructure. The combination of increasing global smartphone penetration and recent advances in computer vision made possible by deep learning has paved the way for smartphone-assisted disease diagnosis. Using a public dataset of 54,306 images of diseased and healthy plant leaves collected under controlled conditions, we train a deep convolutional neural network to identify 14 crop species and 26 diseases (or absence thereof). The trained model achieves an accuracy of 99.35% on a held-out test set, demonstrating the feasibility of this approach. Overall, the approach of training deep learning models on increasingly large and publicly available image datasets presents a clear path toward smartphone-assisted crop disease diagnosis on a massive global scale.",keywords:["Deep learning","Convolutional neural network","Plant disease","Test set","Transfer of learning"],concepts:["Deep learning","Convolutional neural network","Plant disease","Test set","Transfer of learning"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fpls.2016.01419/pdf",is_oa:!0,n_refs:39,n_refs_in_core:1,degree:25,community:3,deg_w:225,betweenness:.0106,pagerank:.0058,eigenvector:.0214},{id:30,oaid:"W2809254203",doi:"10.1007/s13244-018-0639-9",title:"Convolutional neural networks: an overview and application in radiology",authors:[{name:"Rikiya Yamashita",institutions:["Memorial Sloan Kettering Cancer Center","Kyoto University","Kyoto University Hospital"]},{name:"Mizuho Nishio",institutions:["Kyoto University","Kyoto University Hospital"]},{name:"Richard Kinh Gian",institutions:["Memorial Sloan Kettering Cancer Center"]},{name:"Kaori Togashi",institutions:["Kyoto University"]}],authorString:"Rikiya Yamashita; Mizuho Nishio; Richard Kinh Gian; Kaori Togashi",institutions:["Kyoto University","Kyoto University Hospital","Memorial Sloan Kettering Cancer Center"],countries:["JP","US"],year:2018,journal:"Insights into Imaging",citations:4632,abstract:"Convolutional neural network (CNN), a class of artificial neural networks that has become dominant in various computer vision tasks, is attracting interest across a variety of domains, including radiology. CNN is designed to automatically and adaptively learn spatial hierarchies of features through backpropagation by using multiple building blocks, such as convolution layers, pooling layers, and fully connected layers. This review article offers a perspective on the basic concepts of CNN and its application to various radiological tasks, and discusses its challenges and future directions in the field of radiology. Two challenges in applying CNN to radiological tasks, small dataset and overfitting, will also be covered in this article, as well as techniques to minimize them. Being familiar with the concepts and advantages, as well as limitations, of CNN is essential to leverage its potential in diagnostic radiology, with the goal of augmenting the performance of radiologists and improving patient care. KEY POINTS: • Convolutional neural network is a class of deep learning methods which has become dominant in various computer vision tasks and is attracting interest across a variety of domains, including radiology. • Convolutional neural network is composed of multiple building blocks, such as convolution layers, pooling layers, and fully connected layers, and is designed to automatically and adaptively learn spatial hierarchies of features through a backpropagation algorithm. • Familiarity with the concepts and advantages, as well as limitations, of convolutional neural network is essential to leverage its potential to improve radiologist performance and, eventually, patient care.",keywords:["Convolutional neural network","Leverage","Overfitting","Pooling","Deep learning"],concepts:["Convolutional neural network","Leverage","Overfitting","Pooling","Deep learning"],pdf_url:"https://insightsimaging.springeropen.com/track/pdf/10.1007/s13244-018-0639-9",is_oa:!0,n_refs:53,n_refs_in_core:1,degree:19,community:1,deg_w:161,betweenness:.0041,pagerank:.00414,eigenvector:.017},{id:31,oaid:"W2601081289",doi:"10.1088/1361-648x/aa680e",title:"The atomic simulation environment—a Python library for working with atoms",authors:[{name:"Ask Hjorth Larsen",institutions:["University of the Basque Country","Universitat de Barcelona"]},{name:"Jens Jørgen Mortensen",institutions:["Technical University of Denmark"]},{name:"Jakob Blomqvist",institutions:["Malmö University"]},{name:"Ivano E. Castelli",institutions:["University of Copenhagen"]},{name:"Rune Christensen",institutions:["Technical University of Denmark"]},{name:"Marcin Dułak",institutions:["Technical University of Denmark"]},{name:"Jesper Friis",institutions:["SINTEF"]},{name:"Michael N. Groves",institutions:["Aarhus University"]},{name:"Bjørk Hammer",institutions:["Aarhus University"]},{name:"Cory Hargus",institutions:["John Brown University","Brown University"]},{name:"Eric Hermes",institutions:["University of Wisconsin–Madison"]},{name:"Paul C. Jennings",institutions:["Technical University of Denmark"]},{name:"Peter Bjerre Jensen",institutions:["Technical University of Denmark"]},{name:"James R. Kermode",institutions:["University of Warwick"]},{name:"John R. Kitchin",institutions:["Carnegie Mellon University"]},{name:"Esben L. Kolsbjerg",institutions:["Aarhus University"]},{name:"Joseph Kubal",institutions:["Purdue University West Lafayette"]},{name:"Kristen Kaasbjerg",institutions:["Technical University of Denmark"]},{name:"Steen Lysgaard",institutions:["Technical University of Denmark"]},{name:"Jón Bergmann Maronsson",institutions:["EduInnovation"]},{name:"Tristan Maxson",institutions:["Purdue University West Lafayette"]},{name:"Thomas Olsen",institutions:["Technical University of Denmark"]},{name:"Lars Pastewka",institutions:["Karlsruhe Institute of Technology","Computational Physics (United States)"]},{name:"Andrew A. Peterson",institutions:["John Brown University","Brown University"]},{name:"C. Rostgaard",institutions:["Technical University of Denmark"]},{name:"Jakob Schiøtz",institutions:["Technical University of Denmark"]},{name:"Ole Schütt",institutions:["ETH Zurich"]},{name:"Mikkel Strange",institutions:["Technical University of Denmark"]},{name:"Kristian S. Thygesen",institutions:["Technical University of Denmark"]},{name:"Tejs Vegge",institutions:["Technical University of Denmark"]},{name:"Lasse B. Vilhelmsen",institutions:["Aarhus University"]},{name:"Michael Walter",institutions:["University of Freiburg"]},{name:"Zhenhua Zeng",institutions:["Purdue University West Lafayette"]},{name:"Karsten W. Jacobsen",institutions:["Technical University of Denmark"]}],authorString:"Ask Hjorth Larsen; Jens Jørgen Mortensen; Jakob Blomqvist; Ivano E. Castelli; Rune Christensen; Marcin Dułak; Jesper Friis; Michael N. Groves; Bjørk Hammer; Cory Hargus; Eric Hermes; Paul C. Jennings et al.",institutions:["Aarhus University","Brown University","Carnegie Mellon University","Computational Physics (United States)","ETH Zurich","EduInnovation","John Brown University","Karlsruhe Institute of Technology","Malmö University","Purdue University West Lafayette","SINTEF","Technical University of Denmark","Universitat de Barcelona","University of Copenhagen","University of Freiburg","University of Warwick","University of Wisconsin–Madison","University of the Basque Country"],countries:["CH","DE","DK","ES","GB","NO","SE","US"],year:2017,journal:"Journal of Physics Condensed Matter",citations:4628,abstract:"The atomic simulation environment (ASE) is a software package written in the Python programming language with the aim of setting up, steering, and analyzing atomistic simulations. In ASE, tasks are fully scripted in Python. The powerful syntax of Python combined with the NumPy array library make it possible to perform very complex simulation tasks. For example, a sequence of calculations may be performed with the use of a simple 'for-loop' construction. Calculations of energy, forces, stresses and other quantities are performed through interfaces to many external electronic structure codes or force fields using a uniform interface. On top of this calculator interface, ASE provides modules for performing many standard simulation tasks such as structure optimization, molecular dynamics, handling of constraints and performing nudged elastic band calculations.",keywords:["Python","Calculator","Computational science","Software","Molecular dynamics","Graphical user interface"],concepts:["Python","Calculator","Computational science","Software","Molecular dynamics","Graphical user interface"],pdf_url:"https://iopscience.iop.org/article/10.1088/1361-648X/aa680e/pdf",is_oa:!0,n_refs:148,n_refs_in_core:0,degree:9,community:2,deg_w:63,betweenness:0,pagerank:.00192,eigenvector:.0155},{id:32,oaid:"W1787224781",doi:"10.1371/journal.pone.0130140",title:"On Pixel-Wise Explanations for Non-Linear Classifier Decisions by Layer-Wise Relevance Propagation",authors:[{name:"Sebastian Bach",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Technische Universität Berlin"]},{name:"Alexander Binder",institutions:["Singapore University of Technology and Design","Technische Universität Berlin"]},{name:"Grégoire Montavon",institutions:["Technische Universität Berlin"]},{name:"Frederick Klauschen",institutions:["Charité - Universitätsmedizin Berlin"]},{name:"Klaus‐Robert Müller",institutions:["Korea University","Technische Universität Berlin"]},{name:"Wojciech Samek",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Technische Universität Berlin"]}],authorString:"Sebastian Bach; Alexander Binder; Grégoire Montavon; Frederick Klauschen; Klaus‐Robert Müller; Wojciech Samek",institutions:["Charité - Universitätsmedizin Berlin","Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Korea University","Singapore University of Technology and Design","Technische Universität Berlin"],countries:["DE","KR","SG"],year:2015,journal:"PLoS ONE",citations:4610,abstract:"Understanding and interpreting classification decisions of automated image classification systems is of high value in many applications, as it allows to verify the reasoning of the system and provides additional information to the human expert. Although machine learning methods are solving very successfully a plethora of tasks, they have in most cases the disadvantage of acting as a black box, not providing any information about what made them arrive at a particular decision. This work proposes a general solution to the problem of understanding classification decisions by pixel-wise decomposition of nonlinear classifiers. We introduce a methodology that allows to visualize the contributions of single pixels to predictions for kernel-based classifiers over Bag of Words features and for multilayered neural networks. These pixel contributions can be visualized as heatmaps and are provided to a human expert who can intuitively not only verify the validity of the classification decision, but also focus further analysis on regions of potential interest. We evaluate our method for classifiers trained on PASCAL VOC 2009 images, synthetic image data containing geometric shapes, the MNIST handwritten digits data set and for the pre-trained ImageNet model available as part of the Caffe open source package.",keywords:["MNIST database","Pixel","Pascal","Pattern recognition","Classifier"],concepts:["MNIST database","Pixel","Pascal","Pattern recognition","Classifier"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0130140&type=printable",is_oa:!0,n_refs:56,n_refs_in_core:1,degree:26,community:4,deg_w:178.5,betweenness:.011,pagerank:.00405,eigenvector:.0669},{id:33,oaid:"W3100789280",doi:"10.1109/msp.2017.2743240",title:"Deep Reinforcement Learning: A Brief Survey",authors:[{name:"Kai Arulkumaran",institutions:[]},{name:"Marc Peter Deisenroth",institutions:[]},{name:"Miles Brundage",institutions:["Arizona State University"]},{name:"Anil A. Bharath",institutions:["Institution of Engineering and Technology","Cortexica (United Kingdom)"]}],authorString:"Kai Arulkumaran; Marc Peter Deisenroth; Miles Brundage; Anil A. Bharath",institutions:["Arizona State University","Cortexica (United Kingdom)","Institution of Engineering and Technology"],countries:["GB","US"],year:2017,journal:"IEEE Signal Processing Magazine",citations:4336,abstract:"Deep reinforcement learning (DRL) is poised to revolutionize the field of artificial intelligence (AI) and represents a step toward building autonomous systems with a higher-level understanding of the visual world. Currently, deep learning is enabling reinforcement learning (RL) to scale to problems that were previously intractable, such as learning to play video games directly from pixels. DRL algorithms are also applied to robotics, allowing control policies for robots to be learned directly from camera inputs in the real world. In this survey, we begin with an introduction to the general field of RL, then progress to the main streams of value-based and policy-based methods. Our survey will cover central algorithms in deep RL, including the deep Q-network (DQN), trust region policy optimization (TRPO), and asynchronous advantage actor critic. In parallel, we highlight the unique advantages of deep neural networks, focusing on visual understanding via RL. To conclude, we describe several current areas of research within the field.",keywords:["Reinforcement learning","Deep learning","Field","Artificial neural network","Robotics","Asynchronous communication"],concepts:["Reinforcement learning","Deep learning","Field","Artificial neural network","Robotics","Asynchronous communication"],pdf_url:null,is_oa:!1,n_refs:252,n_refs_in_core:3,degree:26,community:0,deg_w:286,betweenness:.0111,pagerank:.00769,eigenvector:.0212},{id:34,oaid:"W2084341220",doi:"10.1214/ss/1009213726",title:"Statistical Modeling: The Two Cultures (with comments and a rejoinder by the author)",authors:[{name:"Leo Breiman",institutions:[]}],authorString:"Leo Breiman",institutions:[],countries:[],year:2001,journal:"Statistical Science",citations:4301,abstract:"There are two cultures in the use of statistical modeling to reach conclusions from data. One assumes that the data are generated by a given stochastic data model. The other uses algorithmic models and treats the data mechanism as unknown. The statistical community has been committed to the almost exclusive use of data models. This commitment has led to irrelevant theory, questionable conclusions, and has kept statisticians from working on a large range of interesting current problems. Algorithmic modeling, both in theory and practice, has developed rapidly in fields outside statistics. It can be used both on large complex data sets and as a more accurate and informative alternative to data modeling on smaller data sets. If our goal as a field is to use data to solve problems, then we need to move away from exclusive dependence on data models and adopt a more diverse set of tools.",keywords:["Data set","Field","Statistical model","Set","Range","Data science","Statistical theory"],concepts:["Data set","Field","Statistical model","Set","Range","Data science","Statistical theory"],pdf_url:"https://projecteuclid.org/journals/statistical-science/volume-16/issue-3/Statistical-Modeling--The-Two-Cultures-with-comments-and-a/10.1214/ss/1009213726.pdf",is_oa:!0,n_refs:27,n_refs_in_core:0,degree:8,community:4,deg_w:39.5,betweenness:4e-4,pagerank:.00156,eigenvector:.0113},{id:35,oaid:"W2952230511",doi:null,title:"Natural Language Processing (almost) from Scratch",authors:[{name:"Ronan Collobert",institutions:[]},{name:"Jason Weston",institutions:["Google (United States)"]},{name:"Léon Bottou",institutions:[]},{name:"Michael Karlen",institutions:[]},{name:"Koray Kavukcuoglu",institutions:["Supélec","University of Applied Sciences and Arts of Southern Switzerland","Shandong University of Political Science and Law"]},{name:"Pavel P. Kuksa",institutions:["Rutgers Sexual and Reproductive Health and Rights"]}],authorString:"Ronan Collobert; Jason Weston; Léon Bottou; Michael Karlen; Koray Kavukcuoglu; Pavel P. Kuksa",institutions:["Google (United States)","Rutgers Sexual and Reproductive Health and Rights","Shandong University of Political Science and Law","Supélec","University of Applied Sciences and Arts of Southern Switzerland"],countries:["CH","CN","FR","NL","US"],year:2011,journal:"Infoscience (Ecole Polytechnique Fédérale de Lausanne)",citations:3995,abstract:"Editor: We propose a unified neural network architecture and learning algorithm that can be applied to various natural language processing tasks including: part-of-speech tagging, chunking, named entity recognition, and semantic role labeling, achieving or exceeding state-of-theart performance in each on four benchmark tasks. Our goal was to design a flexible architecture that can learn representations useful for the tasks, thus avoiding excessive taskspecific feature engineering (and therefore disregarding a lot of prior knowledge). Instead of exploiting man-made input features carefully optimized for each task, our system learns internal representations on the basis of vast amounts of mostly unlabelled training data. This work is then used as a basis for building a freely available tagging system with excellent performance while requiring minimal computational resources. Keywords:",keywords:["Chunking","Scratch","Task","Natural language processing","Basis","Architecture"],concepts:["Chunking","Scratch","Task","Natural language processing","Basis","Architecture"],pdf_url:"https://infoscience.epfl.ch/record/192375/files/Collobert_JMLR_2493--2537.pdf",is_oa:!0,n_refs:56,n_refs_in_core:1,degree:10,community:0,deg_w:51,betweenness:4e-4,pagerank:.00191,eigenvector:.0047},{id:36,oaid:"W2301358467",doi:"10.1016/j.media.2016.10.004",title:"Efficient multi-scale 3D CNN with fully connected CRF for accurate brain lesion segmentation",authors:[{name:"Konstantinos Kamnitsas",institutions:["NIHR Imperial Biomedical Research Centre","Institute of Group Analysis","Imperial College London"]},{name:"Christian Ledig",institutions:["Institute of Group Analysis","Imperial College London"]},{name:"Virginia Newcombe",institutions:["University of Cambridge"]},{name:"Joanna Simpson",institutions:["University of Cambridge"]},{name:"Andrew D. Kane",institutions:["University of Cambridge"]},{name:"David Menon",institutions:["University of Cambridge"]},{name:"Daniel Rueckert",institutions:["Institute of Group Analysis","Imperial College London"]},{name:"Ben Glocker",institutions:["Institute of Group Analysis","Imperial College London"]}],authorString:"Konstantinos Kamnitsas; Christian Ledig; Virginia Newcombe; Joanna Simpson; Andrew D. Kane; David Menon; Daniel Rueckert; Ben Glocker",institutions:["Imperial College London","Institute of Group Analysis","NIHR Imperial Biomedical Research Centre","University of Cambridge"],countries:["GB"],year:2016,journal:"Medical Image Analysis",citations:3531,abstract:"We propose a dual pathway, 11-layers deep, three-dimensional Convolutional Neural Network for the challenging task of brain lesion segmentation. The devised architecture is the result of an in-depth analysis of the limitations of current networks proposed for similar applications. To overcome the computational burden of processing 3D medical scans, we have devised an efficient and effective dense training scheme which joins the processing of adjacent image patches into one pass through the network while automatically adapting to the inherent class imbalance present in the data. Further, we analyze the development of deeper, thus more discriminative 3D CNNs. In order to incorporate both local and larger contextual information, we employ a dual pathway architecture that processes the input images at multiple scales simultaneously. For post-processing of the network's soft segmentation, we use a 3D fully connected Conditional Random Field which effectively removes false positives. Our pipeline is extensively evaluated on three challenging tasks of lesion segmentation in multi-channel MRI patient data with traumatic brain injuries, brain tumours, and ischemic stroke. We improve on the state-of-the-art for all three applications, with top ranking performance on the public benchmarks BRATS 2015 and ISLES 2015. Our method is computationally efficient, which allows its adoption in a variety of research and clinical settings. The source code of our implementation is made publicly available.",keywords:["Conditional random field","Discriminative model","Segmentation","Pipeline","Convolutional neural network","Pattern recognition"],concepts:["Conditional random field","Discriminative model","Segmentation","Pipeline","Convolutional neural network","Pattern recognition"],pdf_url:"https://ars.els-cdn.com/content/image/1-s2.0-S1361841516301839-fx1_lrg.jpg",is_oa:!0,n_refs:119,n_refs_in_core:3,degree:23,community:1,deg_w:206,betweenness:.0043,pagerank:.00536,eigenvector:.0192},{id:37,oaid:"W2794284562",doi:"10.1155/2018/7068349",title:"Deep Learning for Computer Vision: A Brief Review",authors:[{name:"Athanasios Voulodimos",institutions:["National Technical University of Athens","Technological Educational Institute of Athens"]},{name:"Nikolaos Doulamis",institutions:["National Technical University of Athens"]},{name:"Anastasios Doulamis",institutions:["National Technical University of Athens"]},{name:"Eftychios Protopapadakis",institutions:["National Technical University of Athens"]}],authorString:"Athanasios Voulodimos; Nikolaos Doulamis; Anastasios Doulamis; Eftychios Protopapadakis",institutions:["National Technical University of Athens","Technological Educational Institute of Athens"],countries:["GR"],year:2018,journal:"Computational Intelligence and Neuroscience",citations:3327,abstract:"Over the last years deep learning methods have been shown to outperform previous state-of-the-art machine learning techniques in several fields, with computer vision being one of the most prominent cases. This review paper provides a brief overview of some of the most significant deep learning schemes used in computer vision problems, that is, Convolutional Neural Networks, Deep Boltzmann Machines and Deep Belief Networks, and Stacked Denoising Autoencoders. A brief account of their history, structure, advantages, and limitations is given, followed by a description of their applications in various computer vision tasks, such as object detection, face recognition, action and activity recognition, and human pose estimation. Finally, a brief overview is given of future directions in designing deep learning schemes for computer vision problems and the challenges involved therein.",keywords:["Deep learning","Boltzmann machine","Convolutional neural network","Restricted Boltzmann machine","Deep belief network"],concepts:["Deep learning","Boltzmann machine","Convolutional neural network","Restricted Boltzmann machine","Deep belief network"],pdf_url:"http://downloads.hindawi.com/journals/cin/2018/7068349.pdf",is_oa:!0,n_refs:58,n_refs_in_core:3,degree:15,community:3,deg_w:82.5,betweenness:.002,pagerank:.00259,eigenvector:.0059},{id:38,oaid:"W4210257598",doi:null,title:"A Comprehensive Survey on Graph Neural Networks",authors:[{name:"Wu, Z",institutions:["University of Technology Sydney"]},{name:"Pan, S",institutions:["Monash University"]},{name:"Chen, F",institutions:["University of Technology Sydney"]},{name:"Long, G",institutions:["University of Technology Sydney"]},{name:"Zhang, C",institutions:["University of Technology Sydney"]},{name:"Yu, PS",institutions:["University of Illinois Chicago"]}],authorString:"Wu, Z; Pan, S; Chen, F; Long, G; Zhang, C; Yu, PS",institutions:["Monash University","University of Illinois Chicago","University of Technology Sydney"],countries:["AU","US"],year:2020,journal:"UTS ePRESS (University of Technology Sydney)",citations:3314,abstract:"Deep learning has revolutionized many machine learning tasks in recent years, ranging from image classification and video processing to speech recognition and natural language understanding. The data in these tasks are typically represented in the Euclidean space. However, there is an increasing number of applications, where data are generated from non-Euclidean domains and are represented as graphs with complex relationships and interdependency between objects. The complexity of graph data has imposed significant challenges on the existing machine learning algorithms. Recently, many studies on extending deep learning approaches for graph data have emerged. In this article, we provide a comprehensive overview of graph neural networks (GNNs) in data mining and machine learning fields. We propose a new taxonomy to divide the state-of-the-art GNNs into four categories, namely, recurrent GNNs, convolutional GNNs, graph autoencoders, and spatial-temporal GNNs. We further discuss the applications of GNNs across various domains and summarize the open-source codes, benchmark data sets, and model evaluation of GNNs. Finally, we propose potential research directions in this rapidly growing field.",keywords:["Graph","Artificial neural network","Theoretical computer science"],concepts:["Graph","Artificial neural network"],pdf_url:"http://hdl.handle.net/10453/146542",is_oa:!0,n_refs:182,n_refs_in_core:7,degree:29,community:5,deg_w:512,betweenness:.0099,pagerank:.01047,eigenvector:.2581},{id:39,oaid:"W2153959628",doi:"10.1609/aimag.v29i3.2157",title:"Collective Classification in Network Data",authors:[{name:"Prithviraj Sen",institutions:["University of Maryland, College Park"]},{name:"Galileo Namata",institutions:["University of Maryland, College Park"]},{name:"Mustafa Bilgic",institutions:["University of Maryland, College Park"]},{name:"Lise Getoor",institutions:["University of Maryland, College Park"]},{name:"Brian Gallagher",institutions:["University of Maryland, College Park"]},{name:"Tina Eliassi‐Rad",institutions:["University of Maryland, College Park"]}],authorString:"Prithviraj Sen; Galileo Namata; Mustafa Bilgic; Lise Getoor; Brian Gallagher; Tina Eliassi‐Rad",institutions:["University of Maryland, College Park"],countries:["US"],year:2008,journal:"AI Magazine",citations:3306,abstract:"Many real‐world applications produce networked data such as the worldwide web (hypertext documents connected through hyperlinks), social networks (such as people connected by friendship links), communication networks (computers connected through communication links), and biological networks (such as protein interaction networks). A recent focus in machine‐learning research has been to extend traditional machine‐learning classification techniques to classify nodes in such networks. In this article, we provide a brief introduction to this area of research and how it has progressed during the past decade. We introduce four of the most widely used inference algorithms for classifying networked data and empirically compare them on both synthetic and real‐world data.",keywords:["Hyperlink","Hypertext","Inference","Focus","Friendship","Data science"],concepts:["Hyperlink","Hypertext","Inference","Focus","Friendship","Data science"],pdf_url:"https://ojs.aaai.org/index.php/aimagazine/article/download/2157/2022",is_oa:!0,n_refs:74,n_refs_in_core:0,degree:7,community:5,deg_w:33,betweenness:3e-4,pagerank:.00145,eigenvector:.0119},{id:40,oaid:"W1810943226",doi:"10.4230/lipics.fun.2016.3",title:"Generating Sequences With Recurrent Neural Networks",authors:[{name:"Graves, Alex",institutions:["University of Toronto"]}],authorString:"Graves, Alex",institutions:["University of Toronto"],countries:["CA"],year:2013,journal:"DROPS (Schloss Dagstuhl – Leibniz Center for Informatics)",citations:3102,abstract:"Global Navigation Satellite Systems (GNSS) are systems that continuously acquire data and provide position time series. Many monitoring applications are based on GNSS data and their efficiency depends on the capability in the time series analysis to characterize the signal content and/or to predict incoming coordinates. In this work we propose a suitable Network Architecture, based on Long Short Term Memory Recurrent Neural Networks, to solve two main tasks in GNSS time series analysis: denoising and prediction. We carry out an analysis on a synthetic time series, then we inspect two real different case studies and evaluate the results. We develop a non-deep network that removes almost the 50% of scattering from real GNSS time series and achieves a coordinate prediction with 1.1 millimeters of Mean Squared Error.",keywords:["Handwriting","Recurrent neural network","Variety","Artificial neural network","Sequence","Cursive","Point"],concepts:["Handwriting","Recurrent neural network","Variety","Artificial neural network","Sequence","Cursive","Point"],pdf_url:"https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.TIME.2019.10",is_oa:!0,n_refs:30,n_refs_in_core:2,degree:7,community:0,deg_w:43,betweenness:7e-4,pagerank:.00185,eigenvector:.0033},{id:41,oaid:"W2529996553",doi:"10.1021/acscentsci.7b00572",title:"Automatic Chemical Design Using a Data-Driven Continuous Representation of Molecules",authors:[{name:"Rafael Gómez-Bombarelli",institutions:[]},{name:"Jennifer N. Wei",institutions:["Harvard University"]},{name:"David Duvenaud",institutions:["University of New Brunswick","University of Toronto"]},{name:"José Miguel Hernández-Lobato",institutions:["University of Cambridge","Bridge University"]},{name:"Benjamín Sánchez-Lengeling",institutions:["Harvard University"]},{name:"Dennis Sheberla",institutions:["Harvard University"]},{name:"Jorge Aguilera-Iparraguirre",institutions:[]},{name:"Timothy D. Hirzel",institutions:[]},{name:"Ryan P. Adams",institutions:["Google (United States)","Princeton University"]},{name:"Alán Aspuru-Guzik",institutions:["Canadian Institute for Advanced Research","Harvard University"]}],authorString:"Rafael Gómez-Bombarelli; Jennifer N. Wei; David Duvenaud; José Miguel Hernández-Lobato; Benjamín Sánchez-Lengeling; Dennis Sheberla; Jorge Aguilera-Iparraguirre; Timothy D. Hirzel; Ryan P. Adams; Alán Aspuru-Guzik",institutions:["Bridge University","Canadian Institute for Advanced Research","Google (United States)","Harvard University","Princeton University","University of Cambridge","University of New Brunswick","University of Toronto"],countries:["CA","GB","SS","US"],year:2018,journal:"ACS Central Science",citations:3079,abstract:"We report a method to convert discrete representations of molecules to and from a multidimensional continuous representation. This model allows us to generate new molecules for efficient exploration and optimization through open-ended spaces of chemical compounds. A deep neural network was trained on hundreds of thousands of existing chemical structures to construct three coupled functions: an encoder, a decoder, and a predictor. The encoder converts the discrete representation of a molecule into a real-valued continuous vector, and the decoder converts these continuous vectors back to discrete molecular representations. The predictor estimates chemical properties from the latent continuous vector representation of the molecule. Continuous representations of molecules allow us to automatically generate novel chemical structures by performing simple operations in the latent space, such as decoding random vectors, perturbing known chemical structures, or interpolating between molecules. Continuous representations also allow the use of powerful gradient-based optimization to efficiently guide the search for optimized functional compounds. We demonstrate our method in the domain of drug-like molecules and also in a set of molecules with fewer that nine heavy atoms.",keywords:["Representation","Encoder","Set","Simple","Chemical space","Continuous modelling","Chemical process","Continuous optimization"],concepts:["Representation","Encoder","Set","Simple","Algorithm","Chemical space","Continuous modelling"],pdf_url:"https://pubs.acs.org/doi/pdf/10.1021/acscentsci.7b00572?ref=article_openPDF",is_oa:!0,n_refs:44,n_refs_in_core:0,degree:28,community:2,deg_w:192,betweenness:.0091,pagerank:.00482,eigenvector:.0424},{id:42,oaid:"W2610332124",doi:"10.1093/bib/bbx044",title:"Deep learning for healthcare: review, opportunities and challenges",authors:[{name:"Riccardo Miotto",institutions:["Icahn School of Medicine at Mount Sinai"]},{name:"Fei Wang",institutions:["Cornell University"]},{name:"Shuang Wang",institutions:["University of California San Diego"]},{name:"Xiaoqian Jiang",institutions:["University of California San Diego"]},{name:"Joel T. Dudley",institutions:["Icahn School of Medicine at Mount Sinai"]}],authorString:"Riccardo Miotto; Fei Wang; Shuang Wang; Xiaoqian Jiang; Joel T. Dudley",institutions:["Cornell University","Icahn School of Medicine at Mount Sinai","University of California San Diego"],countries:["US"],year:2017,journal:"Briefings in Bioinformatics",citations:3042,abstract:"Gaining knowledge and actionable insights from complex, high-dimensional and heterogeneous biomedical data remains a key challenge in transforming health care. Various types of data have been emerging in modern biomedical research, including electronic health records, imaging, -omics, sensor data and text, which are complex, heterogeneous, poorly annotated and generally unstructured. Traditional data mining and statistical learning approaches typically need to first perform feature engineering to obtain effective and more robust features from those data, and then build prediction or clustering models on top of them. There are lots of challenges on both steps in a scenario of complicated data and lacking of sufficient domain knowledge. The latest advances in deep learning technologies provide new effective paradigms to obtain end-to-end learning models from complex data. In this article, we review the recent literature on applying deep learning technologies to advance the health care domain. Based on the analyzed work, we suggest that deep learning approaches could be the vehicle for translating big biomedical data into improved human health. However, we also note limitations and needs for improved methods development and applications, especially in terms of ease-of-understanding for domain experts and citizen scientists. We discuss such challenges and suggest developing holistic and meaningful interpretable architectures to bridge deep learning models and human interpretability.",keywords:["Interpretability","Deep learning","Data science","Big data","Domain","Domain knowledge"],concepts:["Interpretability","Deep learning","Data science","Big data","Domain","Domain knowledge"],pdf_url:"https://academic.oup.com/bib/article-pdf/19/6/1236/27119191/bbx044.pdf",is_oa:!0,n_refs:133,n_refs_in_core:6,degree:23,community:0,deg_w:259.5,betweenness:.0037,pagerank:.0062,eigenvector:.0316},{id:43,oaid:"W2594183968",doi:"10.1039/c7sc02664a",title:"MoleculeNet: a benchmark for molecular machine learning",authors:[{name:"Zhenqin Wu",institutions:["Stanford Medicine","Stanford University"]},{name:"Bharath Ramsundar",institutions:["Stanford Medicine","Stanford University"]},{name:"Evan N. Feinberg",institutions:["Stanford Medicine"]},{name:"Joseph Gomes",institutions:["Stanford Medicine","Stanford University"]},{name:"Caleb Geniesse",institutions:["Stanford Medicine"]},{name:"Aneesh Pappu",institutions:["Stanford Medicine","Stanford University"]},{name:"Karl Leswing",institutions:["Schrodinger (United States)"]},{name:"Vijay S. Pande",institutions:["Stanford Medicine","Stanford University"]}],authorString:"Zhenqin Wu; Bharath Ramsundar; Evan N. Feinberg; Joseph Gomes; Caleb Geniesse; Aneesh Pappu; Karl Leswing; Vijay S. Pande",institutions:["Schrodinger (United States)","Stanford Medicine","Stanford University"],countries:["US"],year:2017,journal:"Chemical Science",citations:3024,abstract:"Molecular machine learning has been maturing rapidly over the last few years. Improved methods and the presence of larger datasets have enabled machine learning algorithms to make increasingly accurate predictions about molecular properties. However, algorithmic progress has been limited due to the lack of a standard benchmark to compare the efficacy of proposed methods; most new algorithms are benchmarked on different datasets making it challenging to gauge the quality of proposed methods. This work introduces MoleculeNet, a large scale benchmark for molecular machine learning. MoleculeNet curates multiple public datasets, establishes metrics for evaluation, and offers high quality open-source implementations of multiple previously proposed molecular featurization and learning algorithms (released as part of the DeepChem open source library). MoleculeNet benchmarks demonstrate that learnable representations are powerful tools for molecular machine learning and broadly offer the best performance. However, this result comes with caveats. Learnable representations still struggle to deal with complex tasks under data scarcity and highly imbalanced classification. For quantum mechanical and biophysical datasets, the use of physics-aware featurizations can be more important than choice of particular learning algorithm.",keywords:["Benchmark","Scale","Geography"],concepts:["Benchmark","Scale"],pdf_url:"https://pubs.rsc.org/en/content/articlepdf/2018/sc/c7sc02664a",is_oa:!0,n_refs:64,n_refs_in_core:1,degree:25,community:2,deg_w:231.5,betweenness:.0049,pagerank:.00542,eigenvector:.0616},{id:44,oaid:"W2500751094",doi:"10.1109/tgrs.2016.2584107",title:"Deep Feature Extraction and Classification of Hyperspectral Images Based on Convolutional Neural Networks",authors:[{name:"Yushi Chen",institutions:["Harbin Institute of Technology"]},{name:"Hanlu Jiang",institutions:["Harbin Institute of Technology"]},{name:"Chunyang Li",institutions:["Harbin Institute of Technology"]},{name:"Xiuping Jia",institutions:["University of Canberra","UNSW Sydney"]},{name:"Pedram Ghamisi",institutions:["Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)"]}],authorString:"Yushi Chen; Hanlu Jiang; Chunyang Li; Xiuping Jia; Pedram Ghamisi",institutions:["Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)","Harbin Institute of Technology","UNSW Sydney","University of Canberra"],countries:["AU","CN","DE"],year:2016,journal:"IEEE Transactions on Geoscience and Remote Sensing",citations:2925,abstract:"Due to the advantages of deep learning, in this paper, a regularized deep feature extraction (FE) method is presented for hyperspectral image (HSI) classification using a convolutional neural network (CNN). The proposed approach employs several convolutional and pooling layers to extract deep features from HSIs, which are nonlinear, discriminant, and invariant. These features are useful for image classification and target detection. Furthermore, in order to address the common issue of imbalance between high dimensionality and limited availability of training samples for the classification of HSI, a few strategies such as L2 regularization and dropout are investigated to avoid overfitting in class data modeling. More importantly, we propose a 3-D CNN-based FE model with combined regularization to extract effective spectral-spatial features of hyperspectral imagery. Finally, in order to further improve the performance, a virtual sample enhanced method is proposed. The proposed approaches are carried out on three widely used hyperspectral data sets: Indian Pines, University of Pavia, and Kennedy Space Center. The obtained results reveal that the proposed models with sparse constraints provide competitive results to state-of-the-art methods. In addition, the proposed deep FE opens a new window for further research.",keywords:["Hyperspectral imaging","Convolutional neural network","Feature extraction","Pattern recognition","Contextual image classification","Feature"],concepts:["Hyperspectral imaging","Convolutional neural network","Feature extraction","Pattern recognition","Contextual image classification","Feature"],pdf_url:null,is_oa:!1,n_refs:60,n_refs_in_core:2,degree:27,community:3,deg_w:278.5,betweenness:.0052,pagerank:.00681,eigenvector:.017},{id:45,oaid:"W2936503027",doi:"10.1186/s40537-019-0192-5",title:"Survey on deep learning with class imbalance",authors:[{name:"Justin Johnson",institutions:["Florida Atlantic University"]},{name:"Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"]}],authorString:"Justin Johnson; Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"],countries:["US"],year:2019,journal:"Journal Of Big Data",citations:2878,abstract:"The purpose of this study is to examine existing deep learning techniques for addressing class imbalanced data. Effective classification with imbalanced data is an important area of research, as high class imbalance is naturally inherent in many real-world applications, e.g., fraud detection and cancer detection. Moreover, highly imbalanced data poses added difficulty, as most learners will exhibit bias towards the majority class, and in extreme cases, may ignore the minority class altogether. Class imbalance has been studied thoroughly over the last two decades using traditional machine learning models, i.e. non-deep learning. Despite recent advances in deep learning, along with its increasing popularity, very little empirical work in the area of deep learning with class imbalance exists. Having achieved record-breaking performance results in several complex domains, investigating the use of deep neural networks for problems containing high levels of class imbalance is of great interest. Available studies regarding class imbalance and deep learning are surveyed in order to better understand the efficacy of deep learning when applied to class imbalanced data. This survey discusses the implementation details and experimental results for each study, and offers additional insight into their strengths and weaknesses. Several areas of focus include: data complexity, architectures tested, performance interpretation, ease of use, big data application, and generalization to other domains. We have found that research in this area is very limited, that most existing work focuses on computer vision tasks with convolutional neural networks, and that the effects of big data are rarely considered. Several traditional methods for class imbalance, e.g. data sampling and cost-sensitive learning, prove to be applicable in deep learning, while more advanced methods that exploit neural network feature learning abilities show promising results. The survey concludes with a discussion that highlights various gaps in deep learning from class imbalanced data for the purpose of guiding future research.",keywords:["Deep learning","Class","Popularity","Big data","Convolutional neural network"],concepts:["Deep learning","Class","Popularity","Big data","Convolutional neural network"],pdf_url:"https://journalofbigdata.springeropen.com/track/pdf/10.1186/s40537-019-0192-5",is_oa:!0,n_refs:123,n_refs_in_core:2,degree:20,community:1,deg_w:219.5,betweenness:.0025,pagerank:.00557,eigenvector:.0221},{id:46,oaid:"W2988916019",doi:"10.1007/s11263-019-01247-4",title:"Deep Learning for Generic Object Detection: A Survey",authors:[{name:"Li Liu",institutions:["National University of Defense Technology","University of Oulu"]},{name:"Wanli Ouyang",institutions:["The University of Sydney"]},{name:"Xiaogang Wang",institutions:["Chinese University of Hong Kong"]},{name:"Paul Fieguth",institutions:["University of Waterloo"]},{name:"Jie Chen",institutions:["University of Oulu"]},{name:"Xinwang Liu",institutions:["National University of Defense Technology"]},{name:"Matti Pietikäinen",institutions:["University of Oulu"]}],authorString:"Li Liu; Wanli Ouyang; Xiaogang Wang; Paul Fieguth; Jie Chen; Xinwang Liu; Matti Pietikäinen",institutions:["Chinese University of Hong Kong","National University of Defense Technology","The University of Sydney","University of Oulu","University of Waterloo"],countries:["AU","CA","CN","FI","HK"],year:2019,journal:"International Journal of Computer Vision",citations:2798,abstract:"Abstract Object detection, one of the most fundamental and challenging problems in computer vision, seeks to locate object instances from a large number of predefined categories in natural images. Deep learning techniques have emerged as a powerful strategy for learning feature representations directly from data and have led to remarkable breakthroughs in the field of generic object detection. Given this period of rapid evolution, the goal of this paper is to provide a comprehensive survey of the recent achievements in this field brought about by deep learning techniques. More than 300 research contributions are included in this survey, covering many aspects of generic object detection: detection frameworks, object feature representation, object proposal generation, context modeling, training strategies, and evaluation metrics. We finish the survey by identifying promising directions for future research.",keywords:["Object detection","Deep learning","Field","Representation","Object","Context"],concepts:["Object detection","Deep learning","Field","Representation","Object","Context"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s11263-019-01247-4.pdf",is_oa:!0,n_refs:390,n_refs_in_core:5,degree:20,community:1,deg_w:388.5,betweenness:.0019,pagerank:.00858,eigenvector:.0499},{id:47,oaid:"W2657631929",doi:"10.1016/j.dsp.2017.10.011",title:"Methods for interpreting and understanding deep neural networks",authors:[{name:"Grégoire Montavon",institutions:["Technische Universität Berlin"]},{name:"Wojciech Samek",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute"]},{name:"Klaus‐Robert Müller",institutions:["Korea University","Max Planck Institute for Informatics","Technische Universität Berlin"]}],authorString:"Grégoire Montavon; Wojciech Samek; Klaus‐Robert Müller",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Korea University","Max Planck Institute for Informatics","Technische Universität Berlin"],countries:["DE","KR"],year:2017,journal:"Digital Signal Processing",citations:2731,abstract:"This paper provides an entry point to the problem of interpreting a deep neural network model and explaining its predictions. It is based on a tutorial given at ICASSP 2017. As a tutorial paper, the set of methods covered here is not exhaustive, but sufficiently representative to discuss a number of questions in interpretability, technical challenges, and possible applications. The second part of the tutorial focuses on the recently proposed layer-wise relevance propagation (LRP) technique, for which we provide theory, recommendations, and tricks, to make most efficient use of it on real data.",keywords:["Artificial neural network","Deep neural networks"],concepts:["Artificial neural network","Deep neural networks"],pdf_url:"https://doi.org/10.1016/j.dsp.2017.10.011",is_oa:!0,n_refs:122,n_refs_in_core:5,degree:32,community:4,deg_w:389.5,betweenness:.0169,pagerank:.0079,eigenvector:.1451},{id:48,oaid:"W2022508996",doi:"10.1109/tpami.2012.231",title:"Learning Hierarchical Features for Scene Labeling",authors:[{name:"Clément Farabet",institutions:["Courant Institute of Mathematical Sciences","Laboratoire d'Informatique Gaspard-Monge","Université Gustave Eiffel"]},{name:"Camille Couprie",institutions:["Courant Institute of Mathematical Sciences","New York University"]},{name:"Laurent Najman",institutions:["Laboratoire d'Informatique Gaspard-Monge","Université Gustave Eiffel"]},{name:"Yann LeCun",institutions:["Courant Institute of Mathematical Sciences","New York University"]}],authorString:"Clément Farabet; Camille Couprie; Laurent Najman; Yann LeCun",institutions:["Courant Institute of Mathematical Sciences","Laboratoire d'Informatique Gaspard-Monge","New York University","Université Gustave Eiffel"],countries:["FR","US"],year:2012,journal:"IEEE Transactions on Pattern Analysis and Machine Intelligence",citations:2720,abstract:"Scene labeling consists of labeling each pixel in an image with the category of the object it belongs to. We propose a method that uses a multiscale convolutional network trained from raw pixels to extract dense feature vectors that encode regions of multiple sizes centered on each pixel. The method alleviates the need for engineered features, and produces a powerful representation that captures texture, shape, and contextual information. We report results using multiple postprocessing methods to produce the final labeling. Among those, we propose a technique to automatically retrieve, from a pool of segmentation components, an optimal set of components that best explain the scene; these components are arbitrary, for example, they can be taken from a segmentation tree or from any family of oversegmentations. The system yields record accuracies on the SIFT Flow dataset (33 classes) and the Barcelona dataset (170 classes) and near-record accuracy on Stanford background dataset (eight classes), while being an order of magnitude faster than competing approaches, producing a $(320\\times 240)$ image labeling in less than a second, including feature extraction.",keywords:["Pattern recognition","Pixel","Segmentation","Feature extraction","Convolutional neural network","Image segmentation"],concepts:["Pattern recognition","Pixel","Segmentation","Feature extraction","Convolutional neural network","Image segmentation"],pdf_url:"https://hal.science/hal-00742077v1/file/farabet-pami-13.pdf",is_oa:!0,n_refs:64,n_refs_in_core:1,degree:11,community:0,deg_w:61,betweenness:.0018,pagerank:.00214,eigenvector:.006},{id:49,oaid:"W2766856748",doi:"10.1103/physrevlett.120.145301",title:"Crystal Graph Convolutional Neural Networks for an Accurate and Interpretable Prediction of Material Properties",authors:[{name:"Tian Xie",institutions:["Massachusetts Institute of Technology"]},{name:"Jeffrey C. Grossman",institutions:["Massachusetts Institute of Technology"]}],authorString:"Tian Xie; Jeffrey C. Grossman",institutions:["Massachusetts Institute of Technology"],countries:["US"],year:2018,journal:"Physical Review Letters",citations:2700,abstract:"The use of machine learning methods for accelerating the design of crystalline materials usually requires manually constructed feature vectors or complex transformation of atom coordinates to input the crystal structure, which either constrains the model to certain crystal types or makes it difficult to provide chemical insights. Here, we develop a crystal graph convolutional neural networks framework to directly learn material properties from the connection of atoms in the crystal, providing a universal and interpretable representation of crystalline materials. Our method provides a highly accurate prediction of density functional theory calculated properties for eight different properties of crystals with various structure types and compositions after being trained with 10^{4} data points. Further, our framework is interpretable because one can extract the contributions from local chemical environments to global properties. Using an example of perovskites, we show how this information can be utilized to discover empirical rules for materials design.",keywords:["Convolutional neural network","Crystal","Representation","Graph","Crystal structure","Graph rewriting","Artificial neural network"],concepts:["Convolutional neural network","Crystal","Representation","Graph","Crystal structure","Graph rewriting","Artificial neural network"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.120.145301",is_oa:!0,n_refs:36,n_refs_in_core:1,degree:20,community:2,deg_w:166.5,betweenness:.0039,pagerank:.00374,eigenvector:.0653},{id:50,oaid:"W2965658867",doi:"10.1609/aaai.v33i01.33014780",title:"Regularized Evolution for Image Classifier Architecture Search",authors:[{name:"Esteban Real",institutions:["Google (United States)"]},{name:"Alok Aggarwal",institutions:["Google (United States)"]},{name:"Yanping Huang",institutions:["Google (United States)"]},{name:"Quoc V. Le",institutions:["Google (United States)"]}],authorString:"Esteban Real; Alok Aggarwal; Yanping Huang; Quoc V. Le",institutions:["Google (United States)"],countries:["US"],year:2019,journal:null,citations:2675,abstract:"The effort devoted to hand-crafting neural network image classifiers has motivated the use of architecture search to discover them automatically. Although evolutionary algorithms have been repeatedly applied to neural network topologies, the image classifiers thus discovered have remained inferior to human-crafted ones. Here, we evolve an image classifier— AmoebaNet-A—that surpasses hand-designs for the first time. To do this, we modify the tournament selection evolutionary algorithm by introducing an age property to favor the younger genotypes. Matching size, AmoebaNet-A has comparable accuracy to current state-of-the-art ImageNet models discovered with more complex architecture-search methods. Scaled to larger size, AmoebaNet-A sets a new state-of-theart 83.9% top-1 / 96.6% top-5 ImageNet accuracy. In a controlled comparison against a well known reinforcement learning algorithm, we give evidence that evolution can obtain results faster with the same hardware, especially at the earlier stages of the search. This is relevant when fewer compute resources are available. Evolution is, thus, a simple method to effectively discover high-quality architectures.",keywords:["Classifier","Tournament selection","Evolutionary algorithm","Architecture","Artificial neural network"],concepts:["Classifier","Tournament selection","Evolutionary algorithm","Architecture","Artificial neural network"],pdf_url:null,is_oa:!1,n_refs:49,n_refs_in_core:4,degree:14,community:1,deg_w:75,betweenness:.0025,pagerank:.00251,eigenvector:.0051},{id:51,oaid:"W2118023920",doi:"10.1186/s40537-014-0007-7",title:"Deep learning applications and challenges in big data analytics",authors:[{name:"Maryam M. Najafabadi",institutions:["Florida Atlantic University"]},{name:"Flavio Villanustre",institutions:[]},{name:"Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"]},{name:"Naeem Seliya",institutions:["Florida Atlantic University"]},{name:"Randall Wald",institutions:["Florida Atlantic University"]},{name:"Edin Muharemagic",institutions:["Lexicon Pharmaceuticals (United States)"]}],authorString:"Maryam M. Najafabadi; Flavio Villanustre; Taghi M. Khoshgoftaar; Naeem Seliya; Randall Wald; Edin Muharemagic",institutions:["Florida Atlantic University","Lexicon Pharmaceuticals (United States)"],countries:["US"],year:2015,journal:"Journal Of Big Data",citations:2594,abstract:"Abstract Big Data Analytics and Deep Learning are two high-focus of data science. Big Data has become important as many organizations both public and private have been collecting massive amounts of domain-specific information, which can contain useful information about problems such as national intelligence, cyber security, fraud detection, marketing, and medical informatics. Companies such as Google and Microsoft are analyzing large volumes of data for business analysis and decisions, impacting existing and future technology. Deep Learning algorithms extract high-level, complex abstractions as data representations through a hierarchical learning process. Complex abstractions are learnt at a given level based on relatively simpler abstractions formulated in the preceding level in the hierarchy. A key benefit of Deep Learning is the analysis and learning of massive amounts of unsupervised data, making it a valuable tool for Big Data Analytics where raw data is largely unlabeled and un-categorized. In the present study, we explore how Deep Learning can be utilized for addressing some important problems in Big Data Analytics, including extracting complex patterns from massive volumes of data, semantic indexing, data tagging, fast information retrieval, and simplifying discriminative tasks. We also investigate some aspects of Deep Learning research that need further exploration to incorporate specific challenges introduced by Big Data Analytics, including streaming data, high-dimensional data, scalability of models, and distributed computing. We conclude by presenting insights into relevant future works by posing some questions, including defining data sampling criteria, domain adaptation modeling, defining criteria for obtaining useful data abstractions, improving semantic indexing, semi-supervised learning, and active learning.",keywords:["Big data","Data science","Deep learning","Raw data","Analytics","Scalability","Business intelligence"],concepts:["Big data","Data science","Deep learning","Raw data","Analytics","Scalability","Business intelligence"],pdf_url:"https://journalofbigdata.springeropen.com/counter/pdf/10.1186/s40537-014-0007-7",is_oa:!0,n_refs:70,n_refs_in_core:1,degree:21,community:0,deg_w:175,betweenness:.0088,pagerank:.00469,eigenvector:.017},{id:52,oaid:"W2984353870",doi:"10.1007/s10994-019-05855-6",title:"A survey on semi-supervised learning",authors:[{name:"Jesper E. van Engelen",institutions:["Leiden University"]},{name:"Holger H. Hoos",institutions:["Leiden University","University of British Columbia"]}],authorString:"Jesper E. van Engelen; Holger H. Hoos",institutions:["Leiden University","University of British Columbia"],countries:["CA","NL"],year:2019,journal:"Machine Learning",citations:2588,abstract:"Abstract Semi-supervised learning is the branch of machine learning concerned with using labelled as well as unlabelled data to perform certain learning tasks. Conceptually situated between supervised and unsupervised learning, it permits harnessing the large amounts of unlabelled data available in many use cases in combination with typically smaller sets of labelled data. In recent years, research in this area has followed the general trends observed in machine learning, with much attention directed at neural network-based models and generative learning. The literature on the topic has also expanded in volume and scope, now encompassing a broad spectrum of theory, algorithms and applications. However, no recent surveys exist to collect and organize this knowledge, impeding the ability of researchers and engineers alike to utilize it. Filling this void, we present an up-to-date overview of semi-supervised learning methods, covering earlier work as well as more recent advances. We focus primarily on semi-supervised classification, where the large majority of semi-supervised learning research takes place. Our survey aims to provide researchers and practitioners new to the field as well as more advanced readers with a solid understanding of the main approaches and algorithms developed over the past two decades, with an emphasis on the most prominent and currently relevant work. Furthermore, we propose a new taxonomy of semi-supervised classification algorithms, which sheds light on the different conceptual and methodological approaches for incorporating unlabelled data into the training process. Lastly, we show how the fundamental assumptions underlying most semi-supervised learning algorithms are closely connected to each other, and how they relate to the well-known semi-supervised clustering assumption.",keywords:["Supervised learning","Unsupervised learning","Scope","Semi-supervised learning","Artificial neural network"],concepts:["Supervised learning","Unsupervised learning","Scope","Semi-supervised learning","Artificial neural network"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10994-019-05855-6.pdf",is_oa:!0,n_refs:264,n_refs_in_core:5,degree:22,community:5,deg_w:172,betweenness:.0066,pagerank:.0045,eigenvector:.0417},{id:53,oaid:"W2574952845",doi:"10.1109/tip.2017.2713099",title:"Deep Convolutional Neural Network for Inverse Problems in Imaging",authors:[{name:"Kyong Hwan Jin",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Michael T. McCann",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Emmanuel Froustey",institutions:["Dassault Aviation (France)","École Polytechnique Fédérale de Lausanne"]},{name:"Michaël Unser",institutions:["École Polytechnique Fédérale de Lausanne"]}],authorString:"Kyong Hwan Jin; Michael T. McCann; Emmanuel Froustey; Michaël Unser",institutions:["Dassault Aviation (France)","École Polytechnique Fédérale de Lausanne"],countries:["CH","FR"],year:2017,journal:"IEEE Transactions on Image Processing",citations:2542,abstract:"In this paper, we propose a novel deep convolutional neural network (CNN)-based algorithm for solving ill-posed inverse problems. Regularized iterative algorithms have emerged as the standard approach to ill-posed inverse problems in the past few decades. These methods produce excellent results, but can be challenging to deploy in practice due to factors including the high computational cost of the forward and adjoint operators and the difficulty of hyperparameter selection. The starting point of this paper is the observation that unrolled iterative methods have the form of a CNN (filtering followed by pointwise nonlinearity) when the normal operator (H*H, where H* is the adjoint of the forward imaging operator, H) of the forward model is a convolution. Based on this observation, we propose using direct inversion followed by a CNN to solve normal-convolutional inverse problems. The direct inversion encapsulates the physical model of the system, but leads to artifacts when the problem is ill posed; the CNN combines multiresolution decomposition and residual learning in order to learn to remove these artifacts while preserving image structure. We demonstrate the performance of the proposed network in sparse-view reconstruction (down to 50 views) on parallel beam X-ray computed tomography in synthetic phantoms as well as in real experimental sinograms. The proposed network outperforms total variation-regularized iterative reconstruction for the more realistic phantoms and requires less than a second to reconstruct a 512 × 512 image on the GPU.",keywords:["Convolutional neural network","Inverse problem","Pattern recognition","Artificial neural network","Medical imaging","Image processing"],concepts:["Convolutional neural network","Inverse problem","Pattern recognition","Artificial neural network","Medical imaging","Image processing"],pdf_url:"https://arxiv.org/pdf/1611.03679",is_oa:!0,n_refs:84,n_refs_in_core:2,degree:19,community:1,deg_w:145,betweenness:.0044,pagerank:.00424,eigenvector:.0091},{id:54,oaid:"W2948978827",doi:"10.1561/2200000056",title:"An Introduction to Variational Autoencoders",authors:[{name:"Diederik P. Kingma",institutions:["Google (United States)"]},{name:"Max Welling",institutions:["Qualcomm (United Kingdom)","Qualcomm (United States)","University of Amsterdam"]}],authorString:"Diederik P. Kingma; Max Welling",institutions:["Google (United States)","Qualcomm (United Kingdom)","Qualcomm (United States)","University of Amsterdam"],countries:["GB","NL","US"],year:2019,journal:"Foundations and Trends® in Machine Learning",citations:2538,abstract:"Variational autoencoders provide a principled framework for learning deep latent-variable models and corresponding inference models. In this work, we provide an introduction to variational autoencoders and some important extensions.",keywords:["Latent variable","Inference","Deep learning","Autoencoder","Variable"],concepts:["Latent variable","Inference","Deep learning","Autoencoder","Variable"],pdf_url:"https://arxiv.org/pdf/1906.02691",is_oa:!0,n_refs:196,n_refs_in_core:5,degree:22,community:0,deg_w:187.5,betweenness:.0041,pagerank:.0048,eigenvector:.0276},{id:55,oaid:"W2968923792",doi:"10.1038/s41524-019-0221-0",title:"Recent advances and applications of machine learning in solid-state materials science",authors:[{name:"Jonathan Schmidt",institutions:["Martin Luther University Halle-Wittenberg"]},{name:"Mário R. G. Marques",institutions:["Martin Luther University Halle-Wittenberg"]},{name:"Silvana Botti",institutions:["Friedrich Schiller University Jena"]},{name:"Miguel A. L. Marques",institutions:["Martin Luther University Halle-Wittenberg"]}],authorString:"Jonathan Schmidt; Mário R. G. Marques; Silvana Botti; Miguel A. L. Marques",institutions:["Friedrich Schiller University Jena","Martin Luther University Halle-Wittenberg"],countries:["DE"],year:2019,journal:"npj Computational Materials",citations:2432,abstract:"Abstract One of the most exciting tools that have entered the material science toolbox in recent years is machine learning. This collection of statistical methods has already proved to be capable of considerably speeding up both fundamental and applied research. At present, we are witnessing an explosion of works that develop and apply machine learning to solid-state systems. We provide a comprehensive overview and analysis of the most recent research in this topic. As a starting point, we introduce machine learning principles, algorithms, descriptors, and databases in materials science. We continue with the description of different machine learning approaches for the discovery of stable materials and the prediction of their crystal structure. Then we discuss research in numerous quantitative structure–property relationships and various approaches for the replacement of first-principle methods by machine learning. We review how active learning and surrogate-based optimization can be applied to improve the rational design process and related examples of applications. Two major questions are always the interpretability of and the physical understanding gained from machine learning models. We consider therefore the different facets of interpretability and their importance in materials science. Finally, we propose solutions and future research paths for various challenges in computational materials science.",keywords:["Interpretability","Toolbox","Process","Property","Point"],concepts:["Interpretability","Toolbox","Process","Property","Point"],pdf_url:"https://www.nature.com/articles/s41524-019-0221-0.pdf",is_oa:!0,n_refs:518,n_refs_in_core:17,degree:34,community:2,deg_w:660,betweenness:.0274,pagerank:.01295,eigenvector:.2063},{id:56,oaid:"W4288039037",doi:"10.1007/s10915-022-01939-z",title:"Scientific Machine Learning Through Physics–Informed Neural Networks: Where we are and What’s Next",authors:[{name:"Salvatore Cuomo",institutions:["University of Naples Federico II"]},{name:"Vincenzo Schiano Di Cola",institutions:["University of Naples Federico II"]},{name:"Fabio Giampaolo",institutions:["University of Naples Federico II"]},{name:"Gianluigi Rozza",institutions:["Scuola Internazionale Superiore di Studi Avanzati"]},{name:"Maziar Raissi",institutions:["University of Colorado Boulder"]},{name:"Francesco Piccialli",institutions:["University of Naples Federico II"]}],authorString:"Salvatore Cuomo; Vincenzo Schiano Di Cola; Fabio Giampaolo; Gianluigi Rozza; Maziar Raissi; Francesco Piccialli",institutions:["Scuola Internazionale Superiore di Studi Avanzati","University of Colorado Boulder","University of Naples Federico II"],countries:["IT","US"],year:2022,journal:"Journal of Scientific Computing",citations:2416,abstract:"Abstract Physics-Informed Neural Networks (PINN) are neural networks (NNs) that encode model equations, like Partial Differential Equations (PDE), as a component of the neural network itself. PINNs are nowadays used to solve PDEs, fractional equations, integral-differential equations, and stochastic PDEs. This novel methodology has arisen as a multi-task learning framework in which a NN must fit observed data while reducing a PDE residual. This article provides a comprehensive review of the literature on PINNs: while the primary goal of the study was to characterize these networks and their related advantages and disadvantages. The review also attempts to incorporate publications on a broader range of collocation-based physics informed neural networks, which stars form the vanilla PINN, as well as many other variants, such as physics-constrained neural networks (PCNN), variational hp-VPINN, and conservative PINN (CPINN). The study indicates that most research has focused on customizing the PINN through different activation functions, gradient optimization techniques, neural network structures, and loss function structures. Despite the wide range of applications for which PINNs have been used, by demonstrating their ability to be more feasible in some contexts than classical numerical techniques like Finite Element Method (FEM), advancements are still possible, most notably theoretical issues that remain unresolved.",keywords:["Artificial neural network","Collocation","Partial differential equation","Function","Finite element method","Range"],concepts:["Artificial neural network","Collocation","Partial differential equation","Function","Finite element method","Range"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10915-022-01939-z.pdf",is_oa:!0,n_refs:185,n_refs_in_core:5,degree:8,community:1,deg_w:68,betweenness:6e-4,pagerank:.00233,eigenvector:.0074},{id:57,oaid:"W2566079294",doi:"10.1145/3446776",title:"Understanding deep learning (still) requires rethinking generalization",authors:[{name:"Chiyuan Zhang",institutions:["Google (United States)"]},{name:"Samy Bengio",institutions:["Google (United States)"]},{name:"Moritz Hardt",institutions:["University of California, Berkeley"]},{name:"Benjamin Recht",institutions:["University of California, Berkeley"]},{name:"Oriol Vinyals",institutions:["Google DeepMind (United Kingdom)"]}],authorString:"Chiyuan Zhang; Samy Bengio; Moritz Hardt; Benjamin Recht; Oriol Vinyals",institutions:["Google (United States)","Google DeepMind (United Kingdom)","University of California, Berkeley"],countries:["GB","US"],year:2021,journal:"Communications of the ACM",citations:2300,abstract:"Despite their massive size, successful deep artificial neural networks can exhibit a remarkably small gap between training and test performance. Conventional wisdom attributes small generalization error either to properties of the model family or to the regularization techniques used during training. Through extensive systematic experiments, we show how these traditional approaches fail to explain why large neural networks generalize well in practice. Specifically, our experiments establish that state-of-the-art convolutional networks for image classification trained with stochastic gradient methods easily fit a random labeling of the training data. This phenomenon is qualitatively unaffected by explicit regularization and occurs even if we replace the true images by completely unstructured random noise. We corroborate these experimental findings with a theoretical construction showing that simple depth two neural networks already have perfect finite sample expressivity as soon as the number of parameters exceeds the number of data points as it usually does in practice. We interpret our experimental findings by comparison with traditional models. We supplement this republication with a new section at the end summarizing recent progresses in the field since the original version of this paper.",keywords:["Regularization","Generalization","Artificial neural network","Deep neural networks","Deep learning","Early stopping"],concepts:["Regularization","Generalization","Artificial neural network","Deep neural networks","Deep learning","Early stopping"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3446776",is_oa:!0,n_refs:53,n_refs_in_core:1,degree:6,community:0,deg_w:31,betweenness:3e-4,pagerank:.0015,eigenvector:.0026},{id:58,oaid:"W2958089299",doi:"10.1109/tnnls.2020.3027314",title:"A Survey on Explainable Artificial Intelligence (XAI): Toward Medical XAI",authors:[{name:"Erico Tjoa",institutions:["Nanyang Technological University","Alibaba Group (China)"]},{name:"Cuntai Guan",institutions:["Nanyang Technological University"]}],authorString:"Erico Tjoa; Cuntai Guan",institutions:["Alibaba Group (China)","Nanyang Technological University"],countries:["CN","SG"],year:2020,journal:"IEEE Transactions on Neural Networks and Learning Systems",citations:2252,abstract:'Recently, artificial intelligence and machine learning in general have demonstrated remarkable performances in many tasks, from image processing to natural language processing, especially with the advent of deep learning (DL). Along with research progress, they have encroached upon many different fields and disciplines. Some of them require high level of accountability and thus transparency, for example, the medical sector. Explanations for machine decisions and predictions are thus needed to justify their reliability. This requires greater interpretability, which often means we need to understand the mechanism underlying the algorithms. Unfortunately, the blackbox nature of the DL is still unresolved, and many machine decisions are still poorly understood. We provide a review on interpretabilities suggested by different research works and categorize them. The different categories show different dimensions in interpretability research, from approaches that provide "obviously" interpretable information to the studies of complex patterns. By applying the same categorization to interpretability in medical research, it is hoped that: 1) clinicians and practitioners can subsequently approach these methods with caution; 2) insight into interpretability will be born with more considerations for medical practices; and 3) initiatives to push forward data-based, mathematically grounded, and technically grounded medical education are encouraged.',keywords:["Croatian","Linguistics","Philosophy"],concepts:["Croatian"],pdf_url:"https://ieeexplore.ieee.org/ielx7/5962385/9591206/09233366.pdf",is_oa:!0,n_refs:247,n_refs_in_core:6,degree:25,community:4,deg_w:436.5,betweenness:.0057,pagerank:.00855,eigenvector:.1907},{id:59,oaid:"W2742127985",doi:"10.1103/physrevlett.120.143001",title:"Deep Potential Molecular Dynamics: A Scalable Model with the Accuracy of Quantum Mechanics",authors:[{name:"Linfeng Zhang",institutions:["Princeton University"]},{name:"Jiequn Han",institutions:["Princeton University"]},{name:"Han Wang",institutions:["Numerical Method (China)","Institute of Applied Physics and Computational Mathematics"]},{name:"Roberto Car",institutions:["Princeton University"]},{name:"E Weinan",institutions:["Princeton University","Peking University","Beijing Institute of Big Data Research"]}],authorString:"Linfeng Zhang; Jiequn Han; Han Wang; Roberto Car; E Weinan",institutions:["Beijing Institute of Big Data Research","Institute of Applied Physics and Computational Mathematics","Numerical Method (China)","Peking University","Princeton University"],countries:["CN","US"],year:2018,journal:"Physical Review Letters",citations:2237,abstract:"We introduce a scheme for molecular simulations, the deep potential molecular dynamics (DPMD) method, based on a many-body potential and interatomic forces generated by a carefully crafted deep neural network trained with ab initio data. The neural network model preserves all the natural symmetries in the problem. It is first-principles based in the sense that there are no ad hoc components aside from the network model. We show that the proposed scheme provides an efficient and accurate protocol in a variety of systems, including bulk materials and molecules. In all these cases, DPMD gives results that are essentially indistinguishable from the original data, at a cost that scales linearly with system size.",keywords:["Molecular dynamics","Quantum dynamics","Statistical physics","Dynamics","Quantum","Quantum mechanics","Classical mechanics"],concepts:["Molecular dynamics","Quantum dynamics","Statistical physics","Dynamics","Quantum","Quantum mechanics","Classical mechanics"],pdf_url:"https://arxiv.org/pdf/1707.09571",is_oa:!0,n_refs:43,n_refs_in_core:2,degree:13,community:2,deg_w:154,betweenness:2e-4,pagerank:.00362,eigenvector:.0459},{id:60,oaid:"W2921406441",doi:"10.1109/tmi.2019.2903562",title:"CE-Net: Context Encoder Network for 2D Medical Image Segmentation",authors:[{name:"Zaiwang Gu",institutions:["Chinese Academy of Sciences"]},{name:"Jun Cheng",institutions:["Chinese Academy of Sciences"]},{name:"Huazhu Fu",institutions:["Inception Institute of Artificial Intelligence"]},{name:"Kang Zhou",institutions:["ShanghaiTech University"]},{name:"Huaying Hao",institutions:["Chinese Academy of Sciences"]},{name:"Yitian Zhao",institutions:["Chinese Academy of Sciences"]},{name:"Tianyang Zhang",institutions:["Chinese Academy of Sciences"]},{name:"Shenghua Gao",institutions:["ShanghaiTech University"]},{name:"Jiang Liu",institutions:["Southern University of Science and Technology"]}],authorString:"Zaiwang Gu; Jun Cheng; Huazhu Fu; Kang Zhou; Huaying Hao; Yitian Zhao; Tianyang Zhang; Shenghua Gao; Jiang Liu",institutions:["Chinese Academy of Sciences","Inception Institute of Artificial Intelligence","ShanghaiTech University","Southern University of Science and Technology"],countries:["AE","CN"],year:2019,journal:"IEEE Transactions on Medical Imaging",citations:2229,abstract:"Medical image segmentation is an important step in medical image analysis. With the rapid development of a convolutional neural network in image processing, deep learning has been used for medical image segmentation, such as optic disc segmentation, blood vessel detection, lung segmentation, cell segmentation, and so on. Previously, U-net based approaches have been proposed. However, the consecutive pooling and strided convolutional operations led to the loss of some spatial information. In this paper, we propose a context encoder network (CE-Net) to capture more high-level information and preserve spatial information for 2D medical image segmentation. CE-Net mainly contains three major components: a feature encoder module, a context extractor, and a feature decoder module. We use the pretrained ResNet block as the fixed feature extractor. The context extractor module is formed by a newly proposed dense atrous convolution block and a residual multi-kernel pooling block. We applied the proposed CE-Net to different 2D medical image segmentation tasks. Comprehensive results show that the proposed method outperforms the original U-Net method and other state-of-the-art methods for optic disc segmentation, vessel detection, lung segmentation, cell contour segmentation, and retinal optical coherence tomography layer segmentation.",keywords:["Image segmentation","Feature","Pattern recognition","Context","Convolutional neural network","Encoder","Segmentation","Feature extraction"],concepts:["Image segmentation","Feature","Computer vision","Pattern recognition","Context","Convolutional neural network"],pdf_url:"https://arxiv.org/pdf/1903.02740",is_oa:!0,n_refs:75,n_refs_in_core:3,degree:10,community:1,deg_w:70.5,betweenness:5e-4,pagerank:.00234,eigenvector:.0057},{id:61,oaid:"W2950865323",doi:"10.1109/jproc.2019.2918951",title:"Edge Intelligence: Paving the Last Mile of Artificial Intelligence With Edge Computing",authors:[{name:"Zhi Zhou",institutions:["Sun Yat-sen University"]},{name:"Xu Chen",institutions:["Sun Yat-sen University"]},{name:"En Li",institutions:["Sun Yat-sen University"]},{name:"Liekang Zeng",institutions:["Sun Yat-sen University"]},{name:"Ke Luo",institutions:["Sun Yat-sen University"]},{name:"Junshan Zhang",institutions:["Arizona State University"]}],authorString:"Zhi Zhou; Xu Chen; En Li; Liekang Zeng; Ke Luo; Junshan Zhang",institutions:["Arizona State University","Sun Yat-sen University"],countries:["CN","US"],year:2019,journal:"Proceedings of the IEEE",citations:2220,abstract:"With the breakthroughs in deep learning, the recent years have witnessed a booming of artificial intelligence (AI) applications and services, spanning from personal assistant to recommendation systems to video/audio surveillance. More recently, with the proliferation of mobile computing and Internet of Things (IoT), billions of mobile and IoT devices are connected to the Internet, generating zillions bytes of data at the network edge. Driving by this trend, there is an urgent need to push the AI frontiers to the network edge so as to fully unleash the potential of the edge big data. To meet this demand, edge computing, an emerging paradigm that pushes computing tasks and services from the network core to the network edge, has been widely recognized as a promising solution. The resulted new interdiscipline, edge AI or edge intelligence (EI), is beginning to receive a tremendous amount of interest. However, research on EI is still in its infancy stage, and a dedicated venue for exchanging the recent advances of EI is highly desired by both the computer system and AI communities. To this end, we conduct a comprehensive survey of the recent research efforts on EI. Specifically, we first review the background and motivation for AI running at the network edge. We then provide an overview of the overarching architectures, frameworks, and emerging key technologies for deep learning model toward training/inference at the network edge. Finally, we discuss future research opportunities on EI. We believe that this survey will elicit escalating attentions, stimulate fruitful discussions, and inspire further research ideas on EI.",keywords:["Edge computing","Edge device","Enhanced Data Rates for GSM Evolution","Data science","Deep learning","Applications of artificial intelligence","Big data"],concepts:["Edge computing","Edge device","Enhanced Data Rates for GSM Evolution","Data science","Deep learning","Applications of artificial intelligence","Big data"],pdf_url:"https://ieeexplore.ieee.org/ielx7/5/8789751/08736011.pdf",is_oa:!0,n_refs:168,n_refs_in_core:4,degree:20,community:0,deg_w:246.5,betweenness:.0028,pagerank:.00599,eigenvector:.0233},{id:62,oaid:"W2778051509",doi:"10.1063/1.5019779",title:"SchNet – A deep learning architecture for molecules and materials",authors:[{name:"Kristof T. Schütt",institutions:["Technische Universität Berlin"]},{name:"Huziel E. Sauceda",institutions:["Fritz Haber Institute of the Max Planck Society"]},{name:"Pieter-Jan Kindermans",institutions:["Technische Universität Berlin"]},{name:"Alexandre Tkatchenko",institutions:["University of Luxembourg"]},{name:"K. Müller",institutions:["Korea University","Max Planck Institute for Informatics","Technische Universität Berlin"]}],authorString:"Kristof T. Schütt; Huziel E. Sauceda; Pieter-Jan Kindermans; Alexandre Tkatchenko; K. Müller",institutions:["Fritz Haber Institute of the Max Planck Society","Korea University","Max Planck Institute for Informatics","Technische Universität Berlin","University of Luxembourg"],countries:["DE","KR","LU"],year:2018,journal:"The Journal of Chemical Physics",citations:2217,abstract:"Deep learning has led to a paradigm shift in artificial intelligence, including web, text, and image search, speech recognition, as well as bioinformatics, with growing impact in chemical physics. Machine learning, in general, and deep learning, in particular, are ideally suitable for representing quantum-mechanical interactions, enabling us to model nonlinear potential-energy surfaces or enhancing the exploration of chemical compound space. Here we present the deep learning architecture SchNet that is specifically designed to model atomistic systems by making use of continuous-filter convolutional layers. We demonstrate the capabilities of SchNet by accurately predicting a range of properties across chemical space for molecules and materials, where our model learns chemically plausible embeddings of atom types across the periodic table. Finally, we employ SchNet to predict potential-energy surfaces and energy-conserving force fields for molecular dynamics simulations of small molecules and perform an exemplary study on the quantum-mechanical properties of C20-fullerene that would have been infeasible with regular ab initio molecular dynamics.",keywords:["Deep learning","Chemical space","Ab initio","Molecular dynamics","Architecture","Space"],concepts:["Deep learning","Chemical space","Ab initio","Molecular dynamics","Architecture","Space"],pdf_url:"https://aip.scitation.org/doi/pdf/10.1063/1.5019779",is_oa:!0,n_refs:62,n_refs_in_core:4,degree:30,community:2,deg_w:389,betweenness:.004,pagerank:.00786,eigenvector:.1228},{id:63,oaid:"W2889985731",doi:"10.3390/info11020125",title:"Albumentations: Fast and Flexible Image Augmentations",authors:[{name:"Alexander Buslaev",institutions:[]},{name:"Vladimir I. Iglovikov",institutions:[]},{name:"Eugene Khvedchenya",institutions:["Odesa I. I. Mechnikov National University"]},{name:"Alex Parinov",institutions:[]},{name:"Mikhail Druzhinin",institutions:[]},{name:"Alexandr A. Kalinin",institutions:["University of Michigan","Shenzhen Research Institute of Big Data"]}],authorString:"Alexander Buslaev; Vladimir I. Iglovikov; Eugene Khvedchenya; Alex Parinov; Mikhail Druzhinin; Alexandr A. Kalinin",institutions:["Odesa I. I. Mechnikov National University","Shenzhen Research Institute of Big Data","University of Michigan"],countries:["CN","UA","US"],year:2020,journal:"Information",citations:2177,abstract:"Data augmentation is a commonly used technique for increasing both the size and the diversity of labeled training sets by leveraging input transformations that preserve corresponding output labels. In computer vision, image augmentations have become a common implicit regularization technique to combat overfitting in deep learning models and are ubiquitously used to improve performance. While most deep learning frameworks implement basic image transformations, the list is typically limited to some variations of flipping, rotating, scaling, and cropping. Moreover, image processing speed varies in existing image augmentation libraries. We present Albumentations, a fast and flexible open source library for image augmentation with many various image transform operations available that is also an easy-to-use wrapper around other augmentation libraries. We discuss the design principles that drove the implementation of Albumentations and give an overview of the key features and distinct capabilities. Finally, we provide examples of image augmentations for different computer vision tasks and demonstrate that Albumentations is faster than other commonly used image augmentation tools on most image transform operations.",keywords:["Overfitting","Image","Image processing","Key","Regularization","Deep learning","Image manipulation"],concepts:["Overfitting","Computer vision","Image","Image processing","Key","Regularization"],pdf_url:"https://www.mdpi.com/2078-2489/11/2/125/pdf?version=1582551862",is_oa:!0,n_refs:56,n_refs_in_core:4,degree:19,community:1,deg_w:97.5,betweenness:.0031,pagerank:.00299,eigenvector:.0062},{id:64,oaid:"W2964010366",doi:"10.1038/s41598-018-24271-9",title:"Recurrent Neural Networks for Multivariate Time Series with Missing Values",authors:[{name:"Zhengping Che",institutions:["University of Southern California"]},{name:"Sanjay Purushotham",institutions:["University of Southern California"]},{name:"Kyunghyun Cho",institutions:["New York University"]},{name:"David Sontag",institutions:["Massachusetts Institute of Technology"]},{name:"Yan Liu",institutions:["University of Southern California"]}],authorString:"Zhengping Che; Sanjay Purushotham; Kyunghyun Cho; David Sontag; Yan Liu",institutions:["Massachusetts Institute of Technology","New York University","University of Southern California"],countries:["US"],year:2018,journal:"Scientific Reports",citations:2168,abstract:"Multivariate time series data in practical applications, such as health care, geoscience, and biology, are characterized by a variety of missing values. In time series prediction and other related tasks, it has been noted that missing values and their missing patterns are often correlated with the target labels, a.k.a., informative missingness. There is very limited work on exploiting the missing patterns for effective imputation and improving prediction performance. In this paper, we develop novel deep learning models, namely GRU-D, as one of the early attempts. GRU-D is based on Gated Recurrent Unit (GRU), a state-of-the-art recurrent neural network. It takes two representations of missing patterns, i.e., masking and time interval, and effectively incorporates them into a deep model architecture so that it not only captures the long-term temporal dependencies in time series, but also utilizes the missing patterns to achieve better prediction results. Experiments of time series classification tasks on real-world clinical datasets (MIMIC-III, PhysioNet) and synthetic datasets demonstrate that our models achieve state-of-the-art performance and provide useful insights for better understanding and utilization of missing values in time series analysis.",keywords:["Missing data","Imputation","Multivariate statistics","Time series","Series","Data mining"],concepts:["Missing data","Imputation","Multivariate statistics","Time series","Series","Data mining"],pdf_url:"https://www.nature.com/articles/s41598-018-24271-9.pdf",is_oa:!0,n_refs:51,n_refs_in_core:4,degree:13,community:0,deg_w:51.5,betweenness:.0016,pagerank:.00203,eigenvector:.0048},{id:65,oaid:"W2188365844",doi:null,title:"Learning structured output representation using deep conditional generative models",authors:[{name:"Kihyuk Sohn",institutions:["University of Michigan"]},{name:"Xinchen Yan",institutions:["University of Michigan"]},{name:"Honglak Lee",institutions:["University of Michigan"]}],authorString:"Kihyuk Sohn; Xinchen Yan; Honglak Lee",institutions:["University of Michigan"],countries:["US"],year:2015,journal:null,citations:2142,abstract:"Supervised deep learning has been successfully applied to many recognition problems. Although it can approximate a complex many-to-one function well when a large amount of training data is provided, it is still challenging to model complex structured output representations that effectively perform probabilistic inference and make diverse predictions. In this work, we develop a deep conditional generative model for structured output prediction using Gaussian latent variables. The model is trained efficiently in the framework of stochastic gradient variational Bayes, and allows for fast prediction using stochastic feed-forward inference. In addition, we provide novel strategies to build robust structured prediction algorithms, such as input noise-injection and multi-scale prediction objective at training. In experiments, we demonstrate the effectiveness of our proposed algorithm in comparison to the deterministic deep neural network counterparts in generating diverse but realistic structured output predictions using stochastic inference. Furthermore, the proposed training methods are complimentary, which leads to strong pixel-level object segmentation and semantic labeling performance on Caltech-UCSD Birds 200 and the subset of Labeled Faces in the Wild dataset.",keywords:["Structured prediction","Inference","Deep learning","Bayes' theorem","Representation"],concepts:["Structured prediction","Inference","Deep learning","Bayes' theorem","Representation"],pdf_url:null,is_oa:!1,n_refs:40,n_refs_in_core:6,degree:21,community:0,deg_w:117.5,betweenness:.0033,pagerank:.00343,eigenvector:.0098},{id:66,oaid:"W2910705748",doi:"10.1073/pnas.1900654116",title:"Definitions, methods, and applications in interpretable machine learning",authors:[{name:"William J. Murdoch",institutions:["University of California, Berkeley"]},{name:"Chandan Singh",institutions:["University of California, Berkeley"]},{name:"Karl Kumbier",institutions:["University of California, Berkeley"]},{name:"Reza Abbasi-Asl",institutions:["Allen Institute for Brain Science","University of California, San Francisco","Allen Institute","University of California, Berkeley"]},{name:"Bin Yu",institutions:["University of California, Berkeley"]}],authorString:"William J. Murdoch; Chandan Singh; Karl Kumbier; Reza Abbasi-Asl; Bin Yu",institutions:["Allen Institute","Allen Institute for Brain Science","University of California, Berkeley","University of California, San Francisco"],countries:["US"],year:2019,journal:"Proceedings of the National Academy of Sciences",citations:2106,abstract:"Machine-learning models have demonstrated great success in learning complex patterns that enable them to make predictions about unobserved data. In addition to using models for prediction, the ability to interpret what a model has learned is receiving an increasing amount of attention. However, this increased focus has led to considerable confusion about the notion of interpretability. In particular, it is unclear how the wide array of proposed interpretation methods are related and what common concepts can be used to evaluate them. We aim to address these concerns by defining interpretability in the context of machine learning and introducing the predictive, descriptive, relevant (PDR) framework for discussing interpretations. The PDR framework provides 3 overarching desiderata for evaluation: predictive accuracy, descriptive accuracy, and relevancy, with relevancy judged relative to a human audience. Moreover, to help manage the deluge of interpretation methods, we introduce a categorization of existing techniques into model-based and post hoc categories, with subgroups including sparsity, modularity, and simulatability. To demonstrate how practitioners can use the PDR framework to evaluate and understand interpretations, we provide numerous real-world examples. These examples highlight the often underappreciated role played by human audiences in discussions of interpretability. Finally, based on our framework, we discuss limitations of existing methods and directions for future work. We hope that this work will provide a common vocabulary that will make it easier for both practitioners and researchers to discuss and choose from the full range of interpretation methods.",keywords:["Interpretability","Categorization","Context","Interpretation","Modularity"],concepts:["Interpretability","Categorization","Context","Interpretation","Modularity"],pdf_url:"https://www.pnas.org/content/pnas/116/44/22071.full.pdf",is_oa:!0,n_refs:137,n_refs_in_core:3,degree:23,community:4,deg_w:265,betweenness:.0039,pagerank:.00559,eigenvector:.1212},{id:67,oaid:"W3046375318",doi:"10.1145/3458754",title:"Domain-Specific Language Model Pretraining for Biomedical Natural Language Processing",authors:[{name:"裕二 池谷",institutions:["Microsoft (United States)"]},{name:"Robert Tinn",institutions:["Microsoft (United States)"]},{name:"Hao Cheng",institutions:["Microsoft (United States)"]},{name:"Michael Lucas",institutions:["Microsoft (United States)"]},{name:"Naoto Usuyama",institutions:["Microsoft (United States)"]},{name:"Xiaodong Liu",institutions:["Microsoft (United States)"]},{name:"Tristan Naumann",institutions:["Microsoft (United States)"]},{name:"Jianfeng Gao",institutions:["Microsoft (United States)"]},{name:"Hoifung Poon",institutions:["Microsoft (United States)"]}],authorString:"裕二 池谷; Robert Tinn; Hao Cheng; Michael Lucas; Naoto Usuyama; Xiaodong Liu; Tristan Naumann; Jianfeng Gao; Hoifung Poon",institutions:["Microsoft (United States)"],countries:["US"],year:2021,journal:"ACM Transactions on Computing for Healthcare",citations:2073,abstract:"Pretraining large neural language models, such as BERT, has led to impressive gains on many natural language processing (NLP) tasks. However, most pretraining efforts focus on general domain corpora, such as newswire and Web. A prevailing assumption is that even domain-specific pretraining can benefit by starting from general-domain language models. In this article, we challenge this assumption by showing that for domains with abundant unlabeled text, such as biomedicine, pretraining language models from scratch results in substantial gains over continual pretraining of general-domain language models. To facilitate this investigation, we compile a comprehensive biomedical NLP benchmark from publicly available datasets. Our experiments show that domain-specific pretraining serves as a solid foundation for a wide range of biomedical NLP tasks, leading to new state-of-the-art results across the board. Further, in conducting a thorough evaluation of modeling choices, both for pretraining and task-specific fine-tuning, we discover that some common practices are unnecessary with BERT models, such as using complex tagging schemes in named entity recognition. To help accelerate research in biomedical NLP, we have released our state-of-the-art pretrained and task-specific models for the community, and created a leaderboard featuring our BLURB benchmark (short for Biomedical Language Understanding &amp; Reasoning Benchmark) at https://aka.ms/BLURB .",keywords:["Benchmark","Domain","Natural language processing","Language model","Task","Biomedicine"],concepts:["Benchmark","Domain","Natural language processing","Language model","Task","Biomedicine"],pdf_url:"https://arxiv.org/pdf/2007.15779",is_oa:!0,n_refs:68,n_refs_in_core:5,degree:12,community:0,deg_w:65,betweenness:9e-4,pagerank:.00254,eigenvector:.003},{id:68,oaid:"W2541404351",doi:"10.1039/c6sc05720a",title:"ANI-1: an extensible neural network potential with DFT accuracy at force field computational cost",authors:[{name:"Justin S. Smith",institutions:["University of Florida","Gainesville Obstetrics & Gynecology"]},{name:"Olexandr Isayev",institutions:["University of North Carolina at Chapel Hill","Communities In Schools of Orange County","Institute of Medicinal Plant Development"]},{name:"Adrián E. Roitberg",institutions:["University of Florida","Gainesville Obstetrics & Gynecology"]}],authorString:"Justin S. Smith; Olexandr Isayev; Adrián E. Roitberg",institutions:["Communities In Schools of Orange County","Gainesville Obstetrics & Gynecology","Institute of Medicinal Plant Development","University of Florida","University of North Carolina at Chapel Hill"],countries:["CN","US"],year:2017,journal:"Chemical Science",citations:2037,abstract:"Deep learning is revolutionizing many areas of science and technology, especially image, text, and speech recognition. In this paper, we demonstrate how a deep neural network (NN) trained on quantum mechanical (QM) DFT calculations can learn an accurate and transferable potential for organic molecules. We introduce ANAKIN-ME (Accurate NeurAl networK engINe for Molecular Energies) or ANI for short. ANI is a new method designed with the intent of developing transferable neural network potentials that utilize a highly-modified version of the Behler and Parrinello symmetry functions to build single-atom atomic environment vectors (AEV) as a molecular representation. AEVs provide the ability to train neural networks to data that spans both configurational and conformational space, a feat not previously accomplished on this scale. We utilized ANI to build a potential called ANI-1, which was trained on a subset of the GDB databases with up to 8 heavy atoms in order to predict total energies for organic molecules containing four atom types: H, C, N, and O. To obtain an accelerated but physically relevant sampling of molecular potential surfaces, we also proposed a Normal Mode Sampling (NMS) method for generating molecular conformations. Through a series of case studies, we show that ANI-1 is chemically accurate compared to reference DFT calculations on much larger molecular systems (up to 54 atoms) than those included in the training data set.",keywords:["Artificial neural network","Force field","Extensibility","Set","Molecule","Quantum","Field"],concepts:["Artificial neural network","Force field","Extensibility","Set","Molecule","Quantum","Field"],pdf_url:"https://pubs.rsc.org/en/content/articlepdf/2017/sc/c6sc05720a",is_oa:!0,n_refs:47,n_refs_in_core:1,degree:25,community:2,deg_w:200.5,betweenness:.0056,pagerank:.00453,eigenvector:.0539},{id:69,oaid:"W2470368200",doi:"10.1155/2016/3289801",title:"Deep Neural Networks Based Recognition of Plant Diseases by Leaf Image Classification",authors:[{name:"Srdjan Sladojević",institutions:["University of Novi Sad"]},{name:"Marko Arsenović",institutions:["University of Novi Sad"]},{name:"Andraš Anderla",institutions:["University of Novi Sad"]},{name:"Dubravko Ćulibrk",institutions:["University of Trento"]},{name:"Darko Stefanović",institutions:["University of Novi Sad"]}],authorString:"Srdjan Sladojević; Marko Arsenović; Andraš Anderla; Dubravko Ćulibrk; Darko Stefanović",institutions:["University of Novi Sad","University of Trento"],countries:["IT","RS"],year:2016,journal:"Computational Intelligence and Neuroscience",citations:1951,abstract:"The latest generation of convolutional neural networks (CNNs) has achieved impressive results in the field of image classification. This paper is concerned with a new approach to the development of plant disease recognition model, based on leaf image classification, by the use of deep convolutional networks. Novel way of training and the methodology used facilitate a quick and easy system implementation in practice. The developed model is able to recognize 13 different types of plant diseases out of healthy leaves, with the ability to distinguish plant leaves from their surroundings. According to our knowledge, this method for plant disease recognition has been proposed for the first time. All essential steps required for implementing this disease recognition model are fully described throughout the paper, starting from gathering images in order to create a database, assessed by agricultural experts. Caffe, a deep learning framework developed by Berkley Vision and Learning Centre, was used to perform the deep CNN training. The experimental results on the developed model achieved precision between 91% and 98%, for separate class tests, on average 96.3%.",keywords:["Convolutional neural network","Deep learning","Plant disease","Pattern recognition","Field"],concepts:["Convolutional neural network","Deep learning","Plant disease","Pattern recognition","Field"],pdf_url:"https://downloads.hindawi.com/journals/cin/2016/3289801.pdf",is_oa:!0,n_refs:45,n_refs_in_core:2,degree:15,community:3,deg_w:95,betweenness:.003,pagerank:.00307,eigenvector:.0033},{id:70,oaid:"W4919037",doi:"10.1016/s0074-7696(08)60205-3",title:"Regularization of Neural Networks using DropConnect",authors:[{name:"Li Wan",institutions:["Courant Institute of Mathematical Sciences"]},{name:"Matthew D. Zeiler",institutions:["Courant Institute of Mathematical Sciences"]},{name:"Sixin Zhang",institutions:["Université Toulouse III - Paul Sabatier","Université Toulouse-I-Capitole","Institut de Recherche en Informatique de Toulouse","Université Toulouse - Jean Jaurès","Institut Polytechnique de Bordeaux"]},{name:"Yann Lecun",institutions:["Courant Institute of Mathematical Sciences"]},{name:"Rob Fergus",institutions:["Courant Institute of Mathematical Sciences"]}],authorString:"Li Wan; Matthew D. Zeiler; Sixin Zhang; Yann Lecun; Rob Fergus",institutions:["Courant Institute of Mathematical Sciences","Institut Polytechnique de Bordeaux","Institut de Recherche en Informatique de Toulouse","Université Toulouse - Jean Jaurès","Université Toulouse III - Paul Sabatier","Université Toulouse-I-Capitole"],countries:["FR","US"],year:2013,journal:"International review of cytology",citations:1925,abstract:"We introduce DropConnect, a generalization of Dropout (Hinton et al., 2012), for regular-izing large fully-connected layers within neu-ral networks. When training with Dropout, a randomly selected subset of activations are set to zero within each layer. DropCon-nect instead sets a randomly selected sub-set of weights within the network to zero. Each unit thus receives input from a ran-dom subset of units in the previous layer. We derive a bound on the generalization per-formance of both Dropout and DropCon-nect. We then evaluate DropConnect on a range of datasets, comparing to Dropout, and show state-of-the-art results on several image recognition benchmarks by aggregating mul-tiple DropConnect-trained models. 1.",keywords:["Dropout","Regularization","Artificial neural network","Generalization","Set","Layer"],concepts:["Dropout","Regularization","Artificial neural network","Generalization","Set","Layer"],pdf_url:null,is_oa:!1,n_refs:13,n_refs_in_core:1,degree:12,community:0,deg_w:55.5,betweenness:.0014,pagerank:.00201,eigenvector:.0054},{id:71,oaid:"W3096947210",doi:"10.1109/access.2021.3086020",title:"U-Net and Its Variants for Medical Image Segmentation: A Review of Theory and Applications",authors:[{name:"Nahian Siddique",institutions:["Purdue University Northwest"]},{name:"Sidike Paheding",institutions:["Michigan Technological University"]},{name:"Colin Elkin",institutions:["Purdue University Northwest"]},{name:"Vijay Devabhaktuni",institutions:["Purdue University Northwest"]}],authorString:"Nahian Siddique; Sidike Paheding; Colin Elkin; Vijay Devabhaktuni",institutions:["Michigan Technological University","Purdue University Northwest"],countries:["US"],year:2021,journal:"IEEE Access",citations:1908,abstract:"U-net is an image segmentation technique developed primarily for image segmentation tasks. These traits provide U-net with a high utility within the medical imaging community and have resulted in extensive adoption of U-net as the primary tool for segmentation tasks in medical imaging. The success of U-net is evident in its widespread use in nearly all major image modalities, from CT scans and MRI to X-rays and microscopy. Furthermore, while U-net is largely a segmentation tool, there have been instances of the use of U-net in other applications. Given that U-net's potential is still increasing, this narrative literature review examines the numerous developments and breakthroughs in the U-net architecture and provides observations on recent trends. We also discuss the many innovations that have advanced in deep learning and discuss how these tools facilitate U-net. In addition, we review the different image modalities and application areas that have been enhanced by U-net.",keywords:["Image segmentation","Segmentation","Net","Modalities","Medical imaging","Image"],concepts:["Image segmentation","Segmentation","Net","Modalities","Medical imaging","Image"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/9312710/09446143.pdf",is_oa:!0,n_refs:485,n_refs_in_core:5,degree:19,community:1,deg_w:147,betweenness:.0047,pagerank:.0041,eigenvector:.0153},{id:72,oaid:"W1521436688",doi:"10.1155/2015/258619",title:"Deep Convolutional Neural Networks for Hyperspectral Image Classification",authors:[{name:"Wei Hu",institutions:["Beijing University of Chemical Technology"]},{name:"Yangyu Huang",institutions:["Beijing University of Chemical Technology"]},{name:"Li Wei",institutions:["Beijing University of Chemical Technology"]},{name:"Fan Zhang",institutions:["Beijing University of Chemical Technology"]},{name:"Heng-Chao Li",institutions:["University of Colorado Boulder","Southwest Jiaotong University"]}],authorString:"Wei Hu; Yangyu Huang; Li Wei; Fan Zhang; Heng-Chao Li",institutions:["Beijing University of Chemical Technology","Southwest Jiaotong University","University of Colorado Boulder"],countries:["CN","US"],year:2015,journal:"Journal of Sensors",citations:1889,abstract:"Recently, convolutional neural networks have demonstrated excellent performance on various visual tasks, including the classification of common two-dimensional images. In this paper, deep convolutional neural networks are employed to classify hyperspectral images directly in spectral domain. More specifically, the architecture of the proposed classifier contains five layers with weights which are the input layer, the convolutional layer, the max pooling layer, the full connection layer, and the output layer. These five layers are implemented on each spectral signature to discriminate against others. Experimental results based on several hyperspectral image data sets demonstrate that the proposed method can achieve better classification performance than some traditional methods, such as support vector machines and the conventional deep learning-based methods.",keywords:["Hyperspectral imaging","Convolutional neural network","Pattern recognition","Classifier","Pooling","Deep learning"],concepts:["Hyperspectral imaging","Convolutional neural network","Pattern recognition","Classifier","Pooling","Deep learning"],pdf_url:"https://downloads.hindawi.com/journals/js/2015/258619.pdf",is_oa:!0,n_refs:33,n_refs_in_core:5,degree:23,community:3,deg_w:170.5,betweenness:.0031,pagerank:.00461,eigenvector:.0102},{id:73,oaid:"W2764276316",doi:"10.1109/tgrs.2017.2755542",title:"Spectral–Spatial Residual Network for Hyperspectral Image Classification: A 3-D Deep Learning Framework",authors:[{name:"Zilong Zhong",institutions:["University of Waterloo"]},{name:"Jonathan Li",institutions:["University of Waterloo","Xiamen University"]},{name:"Zhiming Luo",institutions:["Université de Sherbrooke","Xiamen University"]},{name:"Michael A. Chapman",institutions:["Toronto Metropolitan University"]}],authorString:"Zilong Zhong; Jonathan Li; Zhiming Luo; Michael A. Chapman",institutions:["Toronto Metropolitan University","University of Waterloo","Université de Sherbrooke","Xiamen University"],countries:["CA","CN"],year:2017,journal:"IEEE Transactions on Geoscience and Remote Sensing",citations:1874,abstract:"In this paper, we designed an end-to-end spectral-spatial residual network (SSRN) that takes raw 3-D cubes as input data without feature engineering for hyperspectral image classification. In this network, the spectral and spatial residual blocks consecutively learn discriminative features from abundant spectral signatures and spatial contexts in hyperspectral imagery (HSI). The proposed SSRN is a supervised deep learning framework that alleviates the declining-accuracy phenomenon of other deep learning models. Specifically, the residual blocks connect every other 3-D convolutional layer through identity mapping, which facilitates the backpropagation of gradients. Furthermore, we impose batch normalization on every convolutional layer to regularize the learning process and improve the classification performance of trained models. Quantitative and qualitative results demonstrate that the SSRN achieved the state-of-the-art HSI classification accuracy in agricultural, rural-urban, and urban data sets: Indian Pines, Kennedy Space Center, and University of Pavia.",keywords:["Hyperspectral imaging","Discriminative model","Normalization","Residual","Pattern recognition","Deep learning"],concepts:["Hyperspectral imaging","Discriminative model","Normalization","Residual","Pattern recognition","Deep learning"],pdf_url:null,is_oa:!1,n_refs:34,n_refs_in_core:3,degree:22,community:3,deg_w:177,betweenness:.0033,pagerank:.00465,eigenvector:.013},{id:74,oaid:"W2942231644",doi:"10.1109/access.2019.2912200",title:"Review of Deep Learning Algorithms and Architectures",authors:[{name:"Ajay Shrestha",institutions:["University of Bridgeport"]},{name:"Ausif Mahmood",institutions:["University of Bridgeport"]}],authorString:"Ajay Shrestha; Ausif Mahmood",institutions:["University of Bridgeport"],countries:["US"],year:2019,journal:"IEEE Access",citations:1848,abstract:"Deep learning (DL) is playing an increasingly important role in our lives. It has already made a huge impact in areas, such as cancer diagnosis, precision medicine, self-driving cars, predictive forecasting, and speech recognition. The painstakingly handcrafted feature extractors used in traditional learning, classification, and pattern recognition systems are not scalable for large-sized data sets. In many cases, depending on the problem complexity, DL can also overcome the limitations of earlier shallow networks that prevented efficient training and abstractions of hierarchical representations of multi-dimensional training data. Deep neural network (DNN) uses multiple (deep) layers of units with highly optimized algorithms and architectures. This paper reviews several optimization methods to improve the accuracy of the training and to reduce training time. We delve into the math behind training algorithms used in recent deep networks. We describe current shortcomings, enhancements, and implementations. The review also covers different types of deep architectures, such as deep convolution networks, deep residual networks, recurrent neural networks, reinforcement learning, variational autoencoders, and others.",keywords:["Deep learning","Scalability","Deep neural networks","Artificial neural network","Implementation"],concepts:["Deep learning","Scalability","Deep neural networks","Artificial neural network","Implementation"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/8600701/08694781.pdf",is_oa:!0,n_refs:109,n_refs_in_core:9,degree:30,community:0,deg_w:259,betweenness:.0096,pagerank:.00654,eigenvector:.0268},{id:75,oaid:"W2584483805",doi:"10.1109/tmi.2017.2715284",title:"Low-Dose CT With a Residual Encoder-Decoder Convolutional Neural Network",authors:[{name:"Hu Chen",institutions:["Sichuan University","Chengdu University"]},{name:"Yi Zhang",institutions:["Sichuan University","Chengdu University"]},{name:"Mannudeep K. Kalra",institutions:["Massachusetts General Hospital"]},{name:"Feng Lin",institutions:["Sichuan University","Chengdu University"]},{name:"Yang Chen",institutions:["Southeast University"]},{name:"Peixi Liao",institutions:["The Sixth People's Hospital of Shenyang"]},{name:"Jiliu Zhou",institutions:["Sichuan University","Chengdu University"]},{name:"Ge Wang",institutions:["Rensselaer Polytechnic Institute"]}],authorString:"Hu Chen; Yi Zhang; Mannudeep K. Kalra; Feng Lin; Yang Chen; Peixi Liao; Jiliu Zhou; Ge Wang",institutions:["Chengdu University","Massachusetts General Hospital","Rensselaer Polytechnic Institute","Sichuan University","Southeast University","The Sixth People's Hospital of Shenyang"],countries:["CN","US"],year:2017,journal:"IEEE Transactions on Medical Imaging",citations:1844,abstract:"Given the potential risk of X-ray radiation to the patient, low-dose CT has attracted a considerable interest in the medical imaging field. Currently, the main stream low-dose CT methods include vendor-specific sinogram domain filtration and iterative reconstruction algorithms, but they need to access raw data, whose formats are not transparent to most users. Due to the difficulty of modeling the statistical characteristics in the image domain, the existing methods for directly processing reconstructed images cannot eliminate image noise very well while keeping structural details. Inspired by the idea of deep learning, here we combine the autoencoder, deconvolution network, and shortcut connections into the residual encoder-decoder convolutional neural network (RED-CNN) for low-dose CT imaging. After patch-based training, the proposed RED-CNN achieves a competitive performance relative to the-state-of-art methods in both simulated and clinical cases. Especially, our method has been favorably evaluated in terms of noise suppression, structural preservation, and lesion detection.",keywords:["Convolutional neural network","Residual","Encoder","Convolutional code","Decoding methods","Computer vision"],concepts:["Convolutional neural network","Residual","Encoder","Convolutional code","Decoding methods","Computer vision"],pdf_url:"https://arxiv.org/pdf/1702.00288",is_oa:!0,n_refs:67,n_refs_in_core:2,degree:13,community:1,deg_w:115,betweenness:.0018,pagerank:.00361,eigenvector:.0051},{id:76,oaid:"W2985331920",doi:"10.1186/s40649-019-0069-y",title:"Graph convolutional networks: a comprehensive review",authors:[{name:"Si Zhang",institutions:["University of Illinois Urbana-Champaign"]},{name:"Hanghang Tong",institutions:["University of Illinois Urbana-Champaign"]},{name:"Jiejun Xu",institutions:["HRL Laboratories (United States)"]},{name:"Ross Maciejewski",institutions:["Arizona State University"]}],authorString:"Si Zhang; Hanghang Tong; Jiejun Xu; Ross Maciejewski",institutions:["Arizona State University","HRL Laboratories (United States)","University of Illinois Urbana-Champaign"],countries:["US"],year:2019,journal:"Computational Social Networks",citations:1830,abstract:"Graphs naturally appear in numerous application domains, ranging from social analysis, bioinformatics to computer vision. The unique capability of graphs enables capturing the structural relations among data, and thus allows to harvest more insights compared to analyzing data in isolation. However, it is often very challenging to solve the learning problems on graphs, because (1) many types of data are not originally structured as graphs, such as images and text data, and (2) for graph-structured data, the underlying connectivity patterns are often complex and diverse. On the other hand, the representation learning has achieved great successes in many areas. Thereby, a potential solution is to learn the representation of graphs in a low-dimensional Euclidean space, such that the graph properties can be preserved. Although tremendous efforts have been made to address the graph representation learning problem, many of them still suffer from their shallow learning mechanisms. Deep learning models on graphs (e.g., graph neural networks) have recently emerged in machine learning and other related areas, and demonstrated the superior performance in various problems. In this survey, despite numerous types of graph neural networks, we conduct a comprehensive review specifically on the emerging field of graph convolutional networks, which is one of the most prominent graph deep learning models. First, we group the existing graph convolutional network models into two categories based on the types of convolutions and highlight some graph convolutional network models in details. Then, we categorize different graph convolutional networks according to the areas of their applications. Finally, we present several open challenges in this area and discuss potential directions for future research.",keywords:["Graph","Theoretical computer science"],concepts:["Graph"],pdf_url:"https://computationalsocialnetworks.springeropen.com/track/pdf/10.1186/s40649-019-0069-y",is_oa:!0,n_refs:133,n_refs_in_core:7,degree:26,community:5,deg_w:327,betweenness:.0117,pagerank:.00702,eigenvector:.169},{id:77,oaid:"W4386142022",doi:"10.1007/s12559-023-10179-8",title:"Interpreting Black-Box Models: A Review on Explainable Artificial Intelligence",authors:[{name:"Vikas Hassija",institutions:["KIIT University"]},{name:"Vinay Chamola",institutions:["Birla Institute of Technology and Science, Pilani"]},{name:"Atmesh Mahapatra",institutions:["Birla Institute of Technology and Science, Pilani"]},{name:"Abhinandan Singal",institutions:["Jaypee Institute of Information Technology"]},{name:"Divyansh Goel",institutions:["Jaypee Institute of Information Technology"]},{name:"Kaizhu Huang",institutions:["Duke Kunshan University"]},{name:"Simone Scardapane",institutions:["Sapienza University of Rome"]},{name:"Indro Spinelli",institutions:["Istituto Nazionale di Fisica Nucleare, Sezione di Roma I"]},{name:"Mufti Mahmud",institutions:["Nottingham Trent University"]},{name:"Amir Hussain",institutions:["Edinburgh Napier University"]}],authorString:"Vikas Hassija; Vinay Chamola; Atmesh Mahapatra; Abhinandan Singal; Divyansh Goel; Kaizhu Huang; Simone Scardapane; Indro Spinelli; Mufti Mahmud; Amir Hussain",institutions:["Birla Institute of Technology and Science, Pilani","Duke Kunshan University","Edinburgh Napier University","Istituto Nazionale di Fisica Nucleare, Sezione di Roma I","Jaypee Institute of Information Technology","KIIT University","Nottingham Trent University","Sapienza University of Rome"],countries:["CN","GB","IN","IT"],year:2023,journal:"Cognitive Computation",citations:1825,abstract:"Abstract Recent years have seen a tremendous growth in Artificial Intelligence (AI)-based methodological development in a broad range of domains. In this rapidly evolving field, large number of methods are being reported using machine learning (ML) and Deep Learning (DL) models. Majority of these models are inherently complex and lacks explanations of the decision making process causing these models to be termed as 'Black-Box'. One of the major bottlenecks to adopt such models in mission-critical application domains, such as banking, e-commerce, healthcare, and public services and safety, is the difficulty in interpreting them. Due to the rapid proleferation of these AI models, explaining their learning and decision making process are getting harder which require transparency and easy predictability. Aiming to collate the current state-of-the-art in interpreting the black-box models, this study provides a comprehensive analysis of the explainable AI (XAI) models. To reduce false negative and false positive outcomes of these back-box models, finding flaws in them is still difficult and inefficient. In this paper, the development of XAI is reviewed meticulously through careful selection and analysis of the current state-of-the-art of XAI research. It also provides a comprehensive and in-depth evaluation of the XAI frameworks and their efficacy to serve as a starting point of XAI for applied and theoretical researchers. Towards the end, it highlights emerging and critical issues pertaining to XAI research to showcase major, model-specific trends for better explanation, enhanced transparency, and improved prediction accuracy.",keywords:["Transparency","Black box","Process","Predictability","Field","Data science"],concepts:["Transparency","Black box","Process","Predictability","Field","Data science"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s12559-023-10179-8.pdf",is_oa:!0,n_refs:135,n_refs_in_core:6,degree:18,community:4,deg_w:165,betweenness:.0042,pagerank:.00382,eigenvector:.0684},{id:78,oaid:"W2966357564",doi:"10.1021/acs.jcim.9b00237",title:"Analyzing Learned Molecular Representations for Property Prediction",authors:[{name:"Kevin Yang",institutions:[]},{name:"Kyle Swanson",institutions:[]},{name:"Wengong Jin",institutions:[]},{name:"Connor W. Coley",institutions:["IIT@MIT"]},{name:"Philipp Eiden",institutions:["BASF (Germany)"]},{name:"Hua Gao",institutions:["Amgen (United States)"]},{name:"Angel Guzmán-Pérez",institutions:["Amgen (United States)"]},{name:"Timothy Hopper",institutions:["Amgen (United States)"]},{name:"Brian Kelley",institutions:["Novartis (United States)"]},{name:"Miriam Mathea",institutions:["BASF (Germany)"]},{name:"Andrew Palmer",institutions:["BASF (Germany)"]},{name:"Volker Settels",institutions:["BASF (Germany)"]},{name:"Tommi Jaakkola",institutions:[]},{name:"Klavs F. Jensen",institutions:["IIT@MIT"]},{name:"Regina Barzilay",institutions:[]}],authorString:"Kevin Yang; Kyle Swanson; Wengong Jin; Connor W. Coley; Philipp Eiden; Hua Gao; Angel Guzmán-Pérez; Timothy Hopper; Brian Kelley; Miriam Mathea; Andrew Palmer; Volker Settels et al.",institutions:["Amgen (United States)","BASF (Germany)","IIT@MIT","Novartis (United States)"],countries:["DE","US"],year:2019,journal:"Journal of Chemical Information and Modeling",citations:1820,abstract:"Advancements in neural machinery have led to a wide range of algorithmic solutions for molecular property prediction. Two classes of models in particular have yielded promising results: neural networks applied to computed molecular fingerprints or expert-crafted descriptors and graph convolutional neural networks that construct a learned molecular representation by operating on the graph structure of the molecule. However, recent literature has yet to clearly determine which of these two methods is superior when generalizing to new chemical space. Furthermore, prior research has rarely examined these new models in industry research settings in comparison to existing employed models. In this paper, we benchmark models extensively on 19 public and 16 proprietary industrial data sets spanning a wide variety of chemical end points. In addition, we introduce a graph convolutional model that consistently matches or outperforms models using fixed molecular descriptors as well as previous graph neural architectures on both public and proprietary data sets. Our empirical findings indicate that while approaches based on these representations have yet to reach the level of experimental reproducibility, our proposed model nevertheless offers significant improvements over models currently used in industrial workflows.",keywords:["Graph","Molecular graph","Benchmark","Chemical space","Convolutional neural network","Workflow"],concepts:["Graph","Molecular graph","Benchmark","Chemical space","Convolutional neural network","Workflow"],pdf_url:"https://doi.org/10.1021/acs.jcim.9b00237",is_oa:!0,n_refs:54,n_refs_in_core:7,degree:23,community:2,deg_w:200.5,betweenness:.003,pagerank:.0048,eigenvector:.0527},{id:79,oaid:"W2052685640",doi:"10.1016/j.tics.2013.09.007",title:"Interoceptive inference, emotion, and the embodied self",authors:[{name:"Anil K. Seth",institutions:["University of Sussex"]}],authorString:"Anil K. Seth",institutions:["University of Sussex"],countries:["GB"],year:2013,journal:"Trends in Cognitive Sciences",citations:1813,abstract:"The concept of the brain as a prediction machine has enjoyed a resurgence in the context of the Bayesian brain and predictive coding approaches within cognitive science. To date, this perspective has been applied primarily to exteroceptive perception (e.g., vision, audition), and action. Here, I describe a predictive, inferential perspective on interoception: 'interoceptive inference' conceives of subjective feeling states (emotions) as arising from actively-inferred generative (predictive) models of the causes of interoceptive afferents. The model generalizes 'appraisal' theories that view emotions as emerging from cognitive evaluations of physiological changes, and it sheds new light on the neurocognitive mechanisms that underlie the experience of body ownership and conscious selfhood in health and in neuropsychiatric illness.",keywords:["Interoception","Embodied cognition","Neurocognitive","Predictive coding","Inference","Cognition","Cognitive psychology"],concepts:["Interoception","Embodied cognition","Neurocognitive","Predictive coding","Inference","Cognition","Cognitive psychology"],pdf_url:"http://www.cell.com/article/S1364661313002118/pdf",is_oa:!0,n_refs:95,n_refs_in_core:2,degree:3,community:6,deg_w:58,betweenness:0,pagerank:.00453,eigenvector:1e-4},{id:80,oaid:"W2964303497",doi:"10.3390/electronics8080832",title:"Machine Learning Interpretability: A Survey on Methods and Metrics",authors:[{name:"Diogo V. Carvalho",institutions:["Universidade do Porto"]},{name:"Eduardo M. Pereira",institutions:[]},{name:"Jaime S. Cardoso",institutions:["Universidade do Porto","INESC TEC"]}],authorString:"Diogo V. Carvalho; Eduardo M. Pereira; Jaime S. Cardoso",institutions:["INESC TEC","Universidade do Porto"],countries:["PT"],year:2019,journal:"Electronics",citations:1781,abstract:"Machine learning systems are becoming increasingly ubiquitous. These systems’s adoption has been expanding, accelerating the shift towards a more algorithmic society, meaning that algorithmically informed decisions have greater potential for significant social impact. However, most of these accurate decision support systems remain complex black boxes, meaning their internal logic and inner workings are hidden to the user and even experts cannot fully understand the rationale behind their predictions. Moreover, new regulations and highly regulated domains have made the audit and verifiability of decisions mandatory, increasing the demand for the ability to question, understand, and trust machine learning systems, for which interpretability is indispensable. The research community has recognized this interpretability problem and focused on developing both interpretable models and explanation methods over the past few years. However, the emergence of these methods shows there is no consensus on how to assess the explanation quality. Which are the most suitable metrics to assess the quality of an explanation? The aim of this article is to provide a review of the current state of the research field on machine learning interpretability while focusing on the societal impact and on the developed methods and metrics. Furthermore, a complete literature review is presented in order to identify future directions of work on this field.",keywords:["Interpretability","Meaning","Field","Audit","Quality","Data science"],concepts:["Interpretability","Meaning","Field","Audit","Quality","Data science"],pdf_url:"https://www.mdpi.com/2079-9292/8/8/832/pdf?version=1564134847",is_oa:!0,n_refs:113,n_refs_in_core:3,degree:19,community:4,deg_w:241,betweenness:9e-4,pagerank:.0051,eigenvector:.1115},{id:81,oaid:"W2927351257",doi:"10.1002/widm.1312",title:"Causability and explainability of artificial intelligence in medicine",authors:[{name:"Andreas Holzinger",institutions:["Medical University of Graz"]},{name:"Georg Langs",institutions:["Medical University of Vienna"]},{name:"Helmut Denk",institutions:["Medical University of Graz"]},{name:"Kurt Zatloukal",institutions:["Medical University of Graz"]},{name:"Heimo Müller",institutions:["Medical University of Graz"]}],authorString:"Andreas Holzinger; Georg Langs; Helmut Denk; Kurt Zatloukal; Heimo Müller",institutions:["Medical University of Graz","Medical University of Vienna"],countries:["AT"],year:2019,journal:"Wiley Interdisciplinary Reviews Data Mining and Knowledge Discovery",citations:1780,abstract:"Explainable artificial intelligence (AI) is attracting much interest in medicine. Technically, the problem of explainability is as old as AI itself and classic AI represented comprehensible retraceable approaches. However, their weakness was in dealing with uncertainties of the real world. Through the introduction of probabilistic learning, applications became increasingly successful, but increasingly opaque. Explainable AI deals with the implementation of transparency and traceability of statistical black‐box machine learning methods, particularly deep learning (DL). We argue that there is a need to go beyond explainable AI. To reach a level of explainable medicine we need causability. In the same way that usability encompasses measurements for the quality of use, causability encompasses measurements for the quality of explanations. In this article, we provide some necessary definitions to discriminate between explainability and causability as well as a use‐case of DL interpretation and of human explanation in histopathology. The main contribution of this article is the notion of causability, which is differentiated from explainability in that causability is a property of a person, while explainability is a property of a system This article is categorized under: Fundamental Concepts of Data and Knowledge &gt; Human Centricity and User Interaction",keywords:["Transparency","Usability","Probabilistic logic","Property","Quality","Traceability"],concepts:["Transparency","Usability","Probabilistic logic","Property","Quality","Traceability"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/widm.1312",is_oa:!0,n_refs:88,n_refs_in_core:4,degree:25,community:4,deg_w:179.5,betweenness:.0073,pagerank:.00412,eigenvector:.0581},{id:82,oaid:"W2464725281",doi:"10.1038/npjcompumats.2016.28",title:"A general-purpose machine learning framework for predicting properties of inorganic materials",authors:[{name:"Logan Ward",institutions:["Northwestern University"]},{name:"Ankit Agrawal",institutions:["Northwestern University"]},{name:"Alok Choudhary",institutions:["Northwestern University"]},{name:"Christopher Wolverton",institutions:["Northwestern University"]}],authorString:"Logan Ward; Ankit Agrawal; Alok Choudhary; Christopher Wolverton",institutions:["Northwestern University"],countries:["US"],year:2016,journal:"npj Computational Materials",citations:1728,abstract:"Abstract A very active area of materials research is to devise methods that use machine learning to automatically extract predictive models from existing materials data. While prior examples have demonstrated successful models for some applications, many more applications exist where machine learning can make a strong impact. To enable faster development of machine-learning-based models for such applications, we have created a framework capable of being applied to a broad range of materials data. Our method works by using a chemically diverse list of attributes, which we demonstrate are suitable for describing a wide variety of properties, and a novel method for partitioning the data set into groups of similar materials to boost the predictive accuracy. In this manuscript, we demonstrate how this new method can be used to predict diverse properties of crystalline and amorphous materials, such as band gap energy and glass-forming ability.",keywords:["Variety","Set","Range"],concepts:["Variety","Set","Range"],pdf_url:"https://www.nature.com/articles/npjcompumats201628.pdf",is_oa:!0,n_refs:74,n_refs_in_core:0,degree:13,community:2,deg_w:147,betweenness:0,pagerank:.00334,eigenvector:.0586},{id:83,oaid:"W4225405705",doi:"10.1038/s41467-022-29939-5",title:"E(3)-equivariant graph neural networks for data-efficient and accurate interatomic potentials",authors:[{name:"Simon Batzner",institutions:["Harvard University"]},{name:"Albert Musaelian",institutions:["Harvard University"]},{name:"Lixin Sun",institutions:["Harvard University"]},{name:"Mario Geiger",institutions:["École Polytechnique Fédérale de Lausanne","Massachusetts Institute of Technology"]},{name:"Jonathan P. Mailoa",institutions:["Robert Bosch (United States)"]},{name:"Mordechai Kornbluth",institutions:["Robert Bosch (United States)"]},{name:"Nicola Molinari",institutions:["Harvard University"]},{name:"Tess Smidt",institutions:["Lawrence Berkeley National Laboratory","Research Applications (United States)","Massachusetts Institute of Technology"]},{name:"Boris Kozinsky",institutions:["Harvard University","Robert Bosch (United States)","Robert Bosch (Slovenia)"]}],authorString:"Simon Batzner; Albert Musaelian; Lixin Sun; Mario Geiger; Jonathan P. Mailoa; Mordechai Kornbluth; Nicola Molinari; Tess Smidt; Boris Kozinsky",institutions:["Harvard University","Lawrence Berkeley National Laboratory","Massachusetts Institute of Technology","Research Applications (United States)","Robert Bosch (Slovenia)","Robert Bosch (United States)","École Polytechnique Fédérale de Lausanne"],countries:["CH","SI","US"],year:2022,journal:"Nature Communications",citations:1720,abstract:"This work presents Neural Equivariant Interatomic Potentials (NequIP), an E(3)-equivariant neural network approach for learning interatomic potentials from ab-initio calculations for molecular dynamics simulations. While most contemporary symmetry-aware models use invariant convolutions and only act on scalars, NequIP employs E(3)-equivariant convolutions for interactions of geometric tensors, resulting in a more information-rich and faithful representation of atomic environments. The method achieves state-of-the-art accuracy on a challenging and diverse set of molecules and materials while exhibiting remarkable data efficiency. NequIP outperforms existing models with up to three orders of magnitude fewer training data, challenging the widely held belief that deep neural networks require massive training sets. The high data efficiency of the method allows for the construction of accurate potentials using high-order quantum chemical level of theory as reference and enables high-fidelity molecular dynamics simulations over long time scales.",keywords:["Equivariant map","Invariant","Artificial neural network","Representation","Ab initio","Set","Theoretical computer science"],concepts:["Equivariant map","Invariant","Artificial neural network","Representation","Ab initio","Set","Theoretical computer science"],pdf_url:"https://www.nature.com/articles/s41467-022-29939-5.pdf",is_oa:!0,n_refs:72,n_refs_in_core:6,degree:17,community:2,deg_w:193,betweenness:5e-4,pagerank:.00433,eigenvector:.0483},{id:84,oaid:"W2964161785",doi:null,title:"End-to-end training of deep visuomotor policies",authors:[{name:"Sergey Levine",institutions:["University of California, Berkeley"]},{name:"Chelsea Finn",institutions:["University of California, Berkeley"]},{name:"Trevor Darrell",institutions:["University of California, Berkeley"]},{name:"Pieter Abbeel",institutions:["University of California, Berkeley"]}],authorString:"Sergey Levine; Chelsea Finn; Trevor Darrell; Pieter Abbeel",institutions:["University of California, Berkeley"],countries:["US"],year:2016,journal:"Journal of Machine Learning Research",citations:1715,abstract:"Policy search methods can allow robots to learn control policies for a wide range of tasks, but practical applications of policy search often require hand-engineered components for perception, state estimation, and low-level control. In this paper, we aim to answer the following question: does training the perception and control systems jointly end-to-end provide better performance than training each component separately? To this end, we develop a method that can be used to learn policies that map raw image observations directly to torques at the robot's motors. The policies are represented by deep convolutional neural networks (CNNs) with 92,000 parameters, and are trained using a guided policy search method, which transforms policy search into supervised learning, with supervision provided by a simple trajectory-centric reinforcement learning method. We evaluate our method on a range of real-world manipulation tasks that require close coordination between vision and control, such as screwing a cap onto a bottle, and present simulated comparisons to a range of prior policy search methods.",keywords:["Convolutional neural network","Reinforcement learning","End-to-end principle","Trajectory","Robot","Perception"],concepts:["Convolutional neural network","Reinforcement learning","End-to-end principle","Trajectory","Robot","Perception"],pdf_url:null,is_oa:!1,n_refs:86,n_refs_in_core:2,degree:19,community:0,deg_w:114,betweenness:.0054,pagerank:.00335,eigenvector:.0102},{id:85,oaid:"W3094948551",doi:"10.1186/s40537-020-00369-8",title:"CatBoost for big data: an interdisciplinary review",authors:[{name:"John Hancock",institutions:["Florida Atlantic University"]},{name:"Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"]}],authorString:"John Hancock; Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"],countries:["US"],year:2020,journal:"Journal Of Big Data",citations:1705,abstract:"Gradient Boosted Decision Trees (GBDT's) are a powerful tool for classification and regression tasks in Big Data. Researchers should be familiar with the strengths and weaknesses of current implementations of GBDT's in order to use them effectively and make successful contributions. CatBoost is a member of the family of GBDT machine learning ensemble techniques. Since its debut in late 2018, researchers have successfully used CatBoost for machine learning studies involving Big Data. We take this opportunity to review recent research on CatBoost as it relates to Big Data, and learn best practices from studies that cast CatBoost in a positive light, as well as studies where CatBoost does not outshine other techniques, since we can learn lessons from both types of scenarios. Furthermore, as a Decision Tree based algorithm, CatBoost is well-suited to machine learning tasks involving categorical, heterogeneous data. Recent work across multiple disciplines illustrates CatBoost's effectiveness and shortcomings in classification and regression tasks. Another important issue we expose in literature on CatBoost is its sensitivity to hyper-parameters and the importance of hyper-parameter tuning. One contribution we make is to take an interdisciplinary approach to cover studies related to CatBoost in a single work. This provides researchers an in-depth understanding to help clarify proper application of CatBoost in solving problems. To the best of our knowledge, this is the first survey that studies all works related to CatBoost in a single publication.",keywords:["Decision tree","Categorical variable","Big data","Data science","Data mining"],concepts:["Decision tree","Categorical variable","Big data","Data science"],pdf_url:"https://journalofbigdata.springeropen.com/counter/pdf/10.1186/s40537-020-00369-8",is_oa:!0,n_refs:116,n_refs_in_core:4,degree:8,community:1,deg_w:37.5,betweenness:8e-4,pagerank:.00158,eigenvector:.0047},{id:86,oaid:"W3176923149",doi:"10.1186/s40537-021-00492-0",title:"Text Data Augmentation for Deep Learning",authors:[{name:"Connor Shorten",institutions:["Florida Atlantic University"]},{name:"Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"]},{name:"Borko Furht",institutions:["Florida Atlantic University"]}],authorString:"Connor Shorten; Taghi M. Khoshgoftaar; Borko Furht",institutions:["Florida Atlantic University"],countries:["US"],year:2021,journal:"Journal Of Big Data",citations:1685,abstract:"Natural Language Processing (NLP) is one of the most captivating applications of Deep Learning. In this survey, we consider how the Data Augmentation training strategy can aid in its development. We begin with the major motifs of Data Augmentation summarized into strengthening local decision boundaries, brute force training, causality and counterfactual examples, and the distinction between meaning and form. We follow these motifs with a concrete list of augmentation frameworks that have been developed for text data. Deep Learning generally struggles with the measurement of generalization and characterization of overfitting. We highlight studies that cover how augmentations can construct test sets for generalization. NLP is at an early stage in applying Data Augmentation compared to Computer Vision. We highlight the key differences and promising ideas that have yet to be tested in NLP. For the sake of practical implementation, we describe tools that facilitate Data Augmentation such as the use of consistency regularization, controllers, and offline and online augmentation pipelines, to preview a few. Finally, we discuss interesting topics around Data Augmentation in NLP such as task-specific augmentations, the use of prior knowledge in self-supervised learning versus Data Augmentation, intersections with transfer and multi-task learning, and ideas for AI-GAs (AI-Generating Algorithms). We hope this paper inspires further research interest in Text Data Augmentation.",keywords:["Computational Science and Engineering","Deep learning","Data science"],concepts:["Computational Science and Engineering","Deep learning","Data science"],pdf_url:"https://journalofbigdata.springeropen.com/track/pdf/10.1186/s40537-021-00492-0",is_oa:!0,n_refs:129,n_refs_in_core:7,degree:16,community:1,deg_w:127,betweenness:9e-4,pagerank:.00359,eigenvector:.0084},{id:87,oaid:"W3047443805",doi:"10.1109/tgrs.2020.3015157",title:"Graph Convolutional Networks for Hyperspectral Image Classification",authors:[{name:"Danfeng Hong",institutions:["Institut polytechnique de Grenoble","Centre National de la Recherche Scientifique","GIPSA-Lab","Université Grenoble Alpes"]},{name:"Lianru Gao",institutions:["Chinese Academy of Sciences","Aerospace Information Research Institute"]},{name:"Jing Yao",institutions:["Xi'an Jiaotong University"]},{name:"Bing Zhang",institutions:["Chinese Academy of Sciences","Aerospace Information Research Institute","University of Chinese Academy of Sciences"]},{name:"Antonio Plaza",institutions:["Universidad de Extremadura"]},{name:"Jocelyn Chanussot",institutions:["Institut polytechnique de Grenoble","Centre National de la Recherche Scientifique","Chinese Academy of Sciences","GIPSA-Lab","Aerospace Information Research Institute","Université Grenoble Alpes"]}],authorString:"Danfeng Hong; Lianru Gao; Jing Yao; Bing Zhang; Antonio Plaza; Jocelyn Chanussot",institutions:["Aerospace Information Research Institute","Centre National de la Recherche Scientifique","Chinese Academy of Sciences","GIPSA-Lab","Institut polytechnique de Grenoble","Universidad de Extremadura","University of Chinese Academy of Sciences","Université Grenoble Alpes","Xi'an Jiaotong University"],countries:["CN","ES","FR"],year:2020,journal:"IEEE Transactions on Geoscience and Remote Sensing",citations:1652,abstract:"Convolutional neural networks (CNNs) have been attracting increasing attention in hyperspectral (HS) image classification due to their ability to capture spatial-spectral feature representations. Nevertheless, their ability in modeling relations between the samples remains limited. Beyond the limitations of grid sampling, graph convolutional networks (GCNs) have been recently proposed and successfully applied in irregular (or nongrid) data representation and analysis. In this article, we thoroughly investigate CNNs and GCNs (qualitatively and quantitatively) in terms of HS image classification. Due to the construction of the adjacency matrix on all the data, traditional GCNs usually suffer from a huge computational cost, particularly in large-scale remote sensing (RS) problems. To this end, we develop a new minibatch GCN (called miniGCN hereinafter), which allows to train large-scale GCNs in a minibatch fashion. More significantly, our miniGCN is capable of inferring out-of-sample data without retraining networks and improving classification performance. Furthermore, as CNNs and GCNs can extract different types of HS features, an intuitive solution to break the performance bottleneck of a single model is to fuse them. Since miniGCNs can perform batchwise network training (enabling the combination of CNNs and GCNs), we explore three fusion strategies: additive fusion, elementwise multiplicative fusion, and concatenation fusion to measure the obtained performance gain. Extensive experiments, conducted on three HS data sets, demonstrate the advantages of miniGCNs over GCNs and the superiority of the tested fusion strategies with regard to the single CNN or GCN models. The codes of this work will be available at https://github.com/danfenghong/IEEE_TGRS_GCN for the sake of reproducibility.",keywords:["Hyperspectral imaging","Bottleneck","Pattern recognition","Convolutional neural network","Adjacency matrix","Graph"],concepts:["Hyperspectral imaging","Bottleneck","Pattern recognition","Convolutional neural network","Adjacency matrix","Graph"],pdf_url:"https://arxiv.org/pdf/2008.02457",is_oa:!0,n_refs:65,n_refs_in_core:3,degree:17,community:3,deg_w:117.5,betweenness:.0024,pagerank:.00346,eigenvector:.0048},{id:88,oaid:"W2743780012",doi:"10.1109/tmi.2018.2827462",title:"Low-Dose CT Image Denoising Using a Generative Adversarial Network With Wasserstein Distance and Perceptual Loss",authors:[{name:"Qingsong Yang",institutions:["Rensselaer Polytechnic Institute"]},{name:"Pingkun Yan",institutions:["Rensselaer Polytechnic Institute"]},{name:"Yanbo Zhang",institutions:["University of Massachusetts Lowell","Sichuan University","Chengdu University"]},{name:"Hengyong Yu",institutions:["University of Massachusetts Lowell"]},{name:"Yongyi Shi",institutions:["Xi'an Jiaotong University"]},{name:"Xuanqin Mou",institutions:["Xi'an Jiaotong University"]},{name:"Mannudeep K. Kalra",institutions:["Harvard University"]},{name:"Yi Zhang",institutions:["University of Massachusetts Lowell","Sichuan University","Chengdu University"]},{name:"Ling Sun",institutions:["Sichuan University","West China Hospital of Sichuan University"]},{name:"Ge Wang",institutions:["Rensselaer Polytechnic Institute"]}],authorString:"Qingsong Yang; Pingkun Yan; Yanbo Zhang; Hengyong Yu; Yongyi Shi; Xuanqin Mou; Mannudeep K. Kalra; Yi Zhang; Ling Sun; Ge Wang",institutions:["Chengdu University","Harvard University","Rensselaer Polytechnic Institute","Sichuan University","University of Massachusetts Lowell","West China Hospital of Sichuan University","Xi'an Jiaotong University"],countries:["CN","US"],year:2018,journal:"IEEE Transactions on Medical Imaging",citations:1631,abstract:"The continuous development and extensive use of computed tomography (CT) in medical practice has raised a public concern over the associated radiation dose to the patient. Reducing the radiation dose may lead to increased noise and artifacts, which can adversely affect the radiologists' judgment and confidence. Hence, advanced image reconstruction from low-dose CT data is needed to improve the diagnostic performance, which is a challenging problem due to its ill-posed nature. Over the past years, various low-dose CT methods have produced impressive results. However, most of the algorithms developed for this application, including the recently popularized deep learning techniques, aim for minimizing the mean-squared error (MSE) between a denoised CT image and the ground truth under generic penalties. Although the peak signal-to-noise ratio is improved, MSE- or weighted-MSE-based methods can compromise the visibility of important structural details after aggressive denoising. This paper introduces a new CT image denoising method based on the generative adversarial network (GAN) with Wasserstein distance and perceptual similarity. The Wasserstein distance is a key concept of the optimal transport theory and promises to improve the performance of GAN. The perceptual loss suppresses noise by comparing the perceptual features of a denoised output against those of the ground truth in an established feature space, while the GAN focuses more on migrating the data noise distribution from strong to weak statistically. Therefore, our proposed method transfers our knowledge of visual perception to the image denoising task and is capable of not only reducing the image noise level but also trying to keep the critical information at the same time. Promising results have been obtained in our experiments with clinical CT images.",keywords:["Image denoising","Computer vision","Adversarial system","Noise reduction","Image","Generative adversarial network"],concepts:["Image denoising","Computer vision","Adversarial system","Noise reduction","Image","Generative adversarial network"],pdf_url:"https://arxiv.org/pdf/1708.00961",is_oa:!0,n_refs:59,n_refs_in_core:4,degree:13,community:1,deg_w:98,betweenness:.0015,pagerank:.00314,eigenvector:.0052},{id:89,oaid:"W2947263797",doi:"10.1007/s10278-019-00227-x",title:"Deep Learning Techniques for Medical Image Segmentation: Achievements and Challenges",authors:[{name:"Mohammad Hesam Hesamian",institutions:["University of Technology Sydney"]},{name:"Wenjing Jia",institutions:["University of Technology Sydney"]},{name:"Xiangjian He",institutions:["University of Technology Sydney"]},{name:"Paul Kennedy",institutions:["University of Technology Sydney"]}],authorString:"Mohammad Hesam Hesamian; Wenjing Jia; Xiangjian He; Paul Kennedy",institutions:["University of Technology Sydney"],countries:["AU"],year:2019,journal:"Journal of Digital Imaging",citations:1625,abstract:"Deep learning-based image segmentation is by now firmly established as a robust tool in image segmentation. It has been widely used to separate homogeneous areas as the first and critical component of diagnosis and treatment pipeline. In this article, we present a critical appraisal of popular methods that have employed deep-learning techniques for medical image segmentation. Moreover, we summarize the most common challenges incurred and suggest possible solutions.",keywords:["Deep learning","Segmentation","Pipeline","Image segmentation","Homogeneous","Segmentation-based object categorization"],concepts:["Deep learning","Segmentation","Pipeline","Image segmentation","Homogeneous","Segmentation-based object categorization"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10278-019-00227-x.pdf",is_oa:!0,n_refs:106,n_refs_in_core:4,degree:20,community:1,deg_w:205.5,betweenness:.0034,pagerank:.00509,eigenvector:.024},{id:90,oaid:"W2919358988",doi:"10.3390/electronics8030292",title:"A State-of-the-Art Survey on Deep Learning Theory and Architectures",authors:[{name:"Md Zahangir Alom",institutions:["University of Dayton"]},{name:"Tarek M. Taha",institutions:["University of Dayton"]},{name:"Chris Yakopcic",institutions:["University of Dayton"]},{name:"Stefan Westberg",institutions:["University of Dayton"]},{name:"Paheding Sidike",institutions:["Saint Louis University"]},{name:"Mst Shamima Nasrin",institutions:["University of Dayton"]},{name:"Mahmudul Hasan",institutions:["Comcast (United States)"]},{name:"Brian C. Van Essen",institutions:["Lawrence Livermore National Laboratory"]},{name:"Abdul Ahad S. Awwal",institutions:["Lawrence Livermore National Laboratory"]},{name:"Vijayan K. Asari",institutions:["University of Dayton"]}],authorString:"Md Zahangir Alom; Tarek M. Taha; Chris Yakopcic; Stefan Westberg; Paheding Sidike; Mst Shamima Nasrin; Mahmudul Hasan; Brian C. Van Essen; Abdul Ahad S. Awwal; Vijayan K. Asari",institutions:["Comcast (United States)","Lawrence Livermore National Laboratory","Saint Louis University","University of Dayton"],countries:["US"],year:2019,journal:"Electronics",citations:1605,abstract:"In recent years, deep learning has garnered tremendous success in a variety of application domains. This new field of machine learning has been growing rapidly and has been applied to most traditional application domains, as well as some new areas that present more opportunities. Different methods have been proposed based on different categories of learning, including supervised, semi-supervised, and un-supervised learning. Experimental results show state-of-the-art performance using deep learning when compared to traditional machine learning approaches in the fields of image processing, computer vision, speech recognition, machine translation, art, medical imaging, medical information processing, robotics and control, bioinformatics, natural language processing, cybersecurity, and many others. This survey presents a brief survey on the advances that have occurred in the area of Deep Learning (DL), starting with the Deep Neural Network (DNN). The survey goes on to cover Convolutional Neural Network (CNN), Recurrent Neural Network (RNN), including Long Short-Term Memory (LSTM) and Gated Recurrent Units (GRU), Auto-Encoder (AE), Deep Belief Network (DBN), Generative Adversarial Network (GAN), and Deep Reinforcement Learning (DRL). Additionally, we have discussed recent developments, such as advanced variant DL techniques based on these DL approaches. This work considers most of the papers published after 2012 from when the history of deep learning began. Furthermore, DL approaches that have been explored and evaluated in different application domains are also included in this survey. We also included recently developed frameworks, SDKs, and benchmark datasets that are used for implementing and evaluating deep learning approaches. There are some surveys that have been published on DL using neural networks and a survey on Reinforcement Learning (RL). However, those papers have not discussed individual advanced techniques for training large-scale deep learning models and the recently developed method of generative models.",keywords:["Deep learning","Deep belief network","Reinforcement learning","Recurrent neural network","Convolutional neural network"],concepts:["Deep learning","Deep belief network","Reinforcement learning","Recurrent neural network","Convolutional neural network"],pdf_url:"https://www.mdpi.com/2079-9292/8/3/292/pdf?version=1552274432",is_oa:!0,n_refs:247,n_refs_in_core:9,degree:28,community:0,deg_w:453,betweenness:.0074,pagerank:.01008,eigenvector:.0635},{id:91,oaid:"W4366262984",doi:"10.1016/j.inffus.2023.101805",title:"Explainable Artificial Intelligence (XAI): What we know and what is left to attain Trustworthy Artificial Intelligence",authors:[{name:"Sajid Ali",institutions:["Sungkyunkwan University"]},{name:"Tamer Abuhmed",institutions:["Sungkyunkwan University"]},{name:"Shaker El–Sappagh",institutions:["Suez University","Benha University","Galala University","Sungkyunkwan University"]},{name:"Khan Muhammad",institutions:["Sungkyunkwan University"]},{name:"José M. Alonso",institutions:["Universidade de Santiago de Compostela","Center for Research in Molecular Medicine and Chronic Diseases"]},{name:"Roberto Confalonieri",institutions:["University of Padua"]},{name:"Riccardo Guidotti",institutions:["University of Pisa"]},{name:"Javier Del Ser",institutions:["University of the Basque Country","Association of Electronic and Information Technologies"]},{name:"Natalia Díaz-Rodríguez",institutions:["Universidad de Granada","Instituto Andaluz de Ciencias de la Tierra"]},{name:"Francisco Herrera",institutions:["Universidad de Granada","Instituto Andaluz de Ciencias de la Tierra"]}],authorString:"Sajid Ali; Tamer Abuhmed; Shaker El–Sappagh; Khan Muhammad; José M. Alonso; Roberto Confalonieri; Riccardo Guidotti; Javier Del Ser; Natalia Díaz-Rodríguez; Francisco Herrera",institutions:["Association of Electronic and Information Technologies","Benha University","Center for Research in Molecular Medicine and Chronic Diseases","Galala University","Instituto Andaluz de Ciencias de la Tierra","Suez University","Sungkyunkwan University","Universidad de Granada","Universidade de Santiago de Compostela","University of Padua","University of Pisa","University of the Basque Country"],countries:["EG","ES","IT","KR"],year:2023,journal:"Information Fusion",citations:1573,abstract:"Artificial intelligence (AI) is currently being utilized in a wide range of sophisticated applications, but the outcomes of many AI models are challenging to comprehend and trust due to their black-box nature. Usually, it is essential to understand the reasoning behind an AI model’s decision-making. Thus, the need for eXplainable AI (XAI) methods for improving trust in AI models has arisen. XAI has become a popular research subject within the AI field in recent years. Existing survey papers have tackled the concepts of XAI, its general terms, and post-hoc explainability methods but there have not been any reviews that have looked at the assessment methods, available tools, XAI datasets, and other related aspects. Therefore, in this comprehensive study, we provide readers with an overview of the current research and trends in this rapidly emerging area with a case study example. The study starts by explaining the background of XAI, common definitions, and summarizing recently proposed techniques in XAI for supervised machine learning. The review divides XAI techniques into four axes using a hierarchical categorization system: (i) data explainability, (ii) model explainability, (iii) post-hoc explainability, and (iv) assessment of explanations. We also introduce available evaluation metrics as well as open-source packages and datasets with future research directions. Then, the significance of explainability in terms of legal demands, user viewpoints, and application orientation is outlined, termed as XAI concerns. This paper advocates for tailoring explanation content to specific user types. An examination of XAI techniques and evaluation was conducted by looking at 410 critical articles, published between January 2016 and October 2022, in reputed journals and using a wide range of research databases as a source of information. The article is aimed at XAI researchers who are interested in making their AI models more trustworthy, as well as towards researchers from other disciplines who are looking for effective XAI methods to complete tasks with confidence while communicating meaning from data.",keywords:["Trustworthiness","Computer security"],concepts:["Trustworthiness"],pdf_url:"https://doi.org/10.1016/j.inffus.2023.101805",is_oa:!0,n_refs:529,n_refs_in_core:10,degree:23,community:4,deg_w:478.5,betweenness:.0031,pagerank:.0093,eigenvector:.2039},{id:92,oaid:"W2502949459",doi:"10.15252/msb.20156651",title:"Deep learning for computational biology",authors:[{name:"Christof Angermueller",institutions:["European Bioinformatics Institute","Wellcome Trust"]},{name:"Tanel Pärnamaa",institutions:["Wellcome Sanger Institute","University of Tartu"]},{name:"Leopold Parts",institutions:["Wellcome Sanger Institute","University of Tartu"]},{name:"Oliver Stegle",institutions:["European Bioinformatics Institute","Wellcome Trust"]}],authorString:"Christof Angermueller; Tanel Pärnamaa; Leopold Parts; Oliver Stegle",institutions:["European Bioinformatics Institute","University of Tartu","Wellcome Sanger Institute","Wellcome Trust"],countries:["EE","GB"],year:2016,journal:"Molecular Systems Biology",citations:1548,abstract:"Technological advances in genomics and imaging have led to an explosion of molecular and cellular profiling data from large numbers of samples. This rapid increase in biological data dimension and acquisition rate is challenging conventional analysis strategies. Modern machine learning methods, such as deep learning, promise to leverage very large data sets for finding hidden structure within them, and for making accurate predictions. In this review, we discuss applications of this new breed of analysis approaches in regulatory genomics and cellular imaging. We provide background of what deep learning is, and the settings in which it can be successfully applied to derive biological insights. In addition to presenting specific applications and providing tips for practical use, we also highlight possible pitfalls and limitations to guide computational biologists when and how to make the most use of this new technology.",keywords:["Computational biology","Systems biology"],concepts:["Computational biology","Systems biology"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.15252/msb.20156651",is_oa:!0,n_refs:143,n_refs_in_core:5,degree:24,community:0,deg_w:342.5,betweenness:.0061,pagerank:.0074,eigenvector:.0672},{id:93,oaid:"W2125663122",doi:"10.1364/josaa.20.001434",title:"Hierarchical Bayesian inference in the visual cortex",authors:[{name:"Tai Sing Lee",institutions:["Center for the Neural Basis of Cognition"]},{name:"David B. Mumford",institutions:["Brown University"]}],authorString:"Tai Sing Lee; David B. Mumford",institutions:["Brown University","Center for the Neural Basis of Cognition"],countries:["US"],year:2003,journal:"Journal of the Optical Society of America A",citations:1547,abstract:"Traditional views of visual processing suggest that early visual neurons in areas V1 and V2 are static spatiotemporal filters that extract local features from a visual scene. The extracted information is then channeled through a feedforward chain of modules in successively higher visual areas for further analysis. Recent electrophysiological recordings from early visual neurons in awake behaving monkeys reveal that there are many levels of complexity in the information processing of the early visual cortex, as seen in the long-latency responses of its neurons. These new findings suggest that activity in the early visual cortex is tightly coupled and highly interactive with the rest of the visual system. They lead us to propose a new theoretical setting based on the mathematical framework of hierarchical Bayesian inference for reasoning about the visual system. In this framework, the recurrent feedforward/feedback loops in the cortex serve to integrate top-down contextual priors and bottom-up observations so as to implement concurrent probabilistic inference along the visual hierarchy. We suggest that the algorithms of particle filtering and Bayesian-belief propagation might model these interactive cortical computations. We review some recent neurophysiological evidences that support the plausibility of these ideas.",keywords:["Visual cortex","Bayesian inference","Visual processing","Feed forward","Probabilistic logic","Inference"],concepts:["Visual cortex","Bayesian inference","Visual processing","Feed forward","Probabilistic logic","Inference"],pdf_url:"https://opg.optica.org/viewmedia.cfm?uri=josaa-20-7-1434&seq=0",is_oa:!0,n_refs:71,n_refs_in_core:0,degree:3,community:6,deg_w:29.5,betweenness:0,pagerank:.00261,eigenvector:1e-4},{id:94,oaid:"W2753403518",doi:"10.3390/s17092022",title:"A Robust Deep-Learning-Based Detector for Real-Time Tomato Plant Diseases and Pests Recognition",authors:[{name:"Alvaro Fuentes",institutions:["Jeonbuk National University"]},{name:"Sook Yoon",institutions:["Mokpo National University"]},{name:"Sang Ryong Kim",institutions:["National Institute of Agricultural Science and Technology"]},{name:"Dong Jun Park",institutions:["Jeonbuk National University"]}],authorString:"Alvaro Fuentes; Sook Yoon; Sang Ryong Kim; Dong Jun Park",institutions:["Jeonbuk National University","Mokpo National University","National Institute of Agricultural Science and Technology"],countries:["KR"],year:2017,journal:"Sensors",citations:1538,abstract:`Plant Diseases and Pests are a major challenge in the agriculture sector. An accurate and a faster detection of diseases and pests in plants could help to develop an early treatment technique while substantially reducing economic losses. Recent developments in Deep Neural Networks have allowed researchers to drastically improve the accuracy of object detection and recognition systems. In this paper, we present a deep-learning-based approach to detect diseases and pests in tomato plants using images captured in-place by camera devices with various resolutions. Our goal is to find the more suitable deep-learning architecture for our task. Therefore, we consider three main families of detectors: Faster Region-based Convolutional Neural Network (Faster R-CNN), Region-based Fully Convolutional Network (R-FCN), and Single Shot Multibox Detector (SSD), which for the purpose of this work are called "deep learning meta-architectures". We combine each of these meta-architectures with "deep feature extractors" such as VGG net and Residual Network (ResNet). We demonstrate the performance of deep meta-architectures and feature extractors, and additionally propose a method for local and global class annotation and data augmentation to increase the accuracy and reduce the number of false positives during training. We train and test our systems end-to-end on our large Tomato Diseases and Pests Dataset, which contains challenging images with diseases and pests, including several inter- and extra-class variations, such as infection status and location in the plant. Experimental results show that our proposed system can effectively recognize nine different types of diseases and pests, with the ability to deal with complex scenarios from a plant's surrounding area.`,keywords:["Detector","Deep learning","Telecommunications"],concepts:["Detector","Deep learning"],pdf_url:"https://www.mdpi.com/1424-8220/17/9/2022/pdf?version=1504687369",is_oa:!0,n_refs:43,n_refs_in_core:3,degree:14,community:3,deg_w:133,betweenness:9e-4,pagerank:.00398,eigenvector:.0035},{id:95,oaid:"W3011667710",doi:"10.1109/tkde.2020.2981333",title:"Deep Learning on Graphs: A Survey",authors:[{name:"Ziwei Zhang",institutions:["Tsinghua University"]},{name:"Peng Cui",institutions:["Tsinghua University"]},{name:"Wenwu Zhu",institutions:["Tsinghua University"]}],authorString:"Ziwei Zhang; Peng Cui; Wenwu Zhu",institutions:["Tsinghua University"],countries:["CN"],year:2020,journal:"IEEE Transactions on Knowledge and Data Engineering",citations:1528,abstract:"Deep learning has been shown to be successful in a number of domains, ranging from acoustics, images, to natural language processing. However, applying deep learning to the ubiquitous graph data is non-trivial because of the unique characteristics of graphs. Recently, substantial research efforts have been devoted to applying deep learning methods to graphs, resulting in beneficial advances in graph analysis techniques. In this survey, we comprehensively review the different types of deep learning methods on graphs. We divide the existing methods into five categories based on their model architectures and training strategies: graph recurrent neural networks, graph convolutional networks, graph autoencoders, graph reinforcement learning, and graph adversarial methods. We then provide a comprehensive overview of these methods in a systematic manner mainly by following their development history. We also analyze the differences and compositions of different methods. Finally, we briefly outline the applications in which they have been used and discuss potential future research directions.",keywords:["Deep learning","Graph","Theoretical computer science","Data science"],concepts:["Deep learning","Graph","Theoretical computer science","Data science"],pdf_url:null,is_oa:!1,n_refs:183,n_refs_in_core:9,degree:25,community:5,deg_w:411.5,betweenness:.0091,pagerank:.00864,eigenvector:.2218},{id:96,oaid:"W2527189750",doi:"10.1038/ncomms13890",title:"Quantum-chemical insights from deep tensor neural networks",authors:[{name:"Kristof T. Schütt",institutions:["Technische Universität Berlin"]},{name:"Farhad Arbabzadah",institutions:["Technische Universität Berlin"]},{name:"Stefan Chmiela",institutions:["Technische Universität Berlin"]},{name:"K. Müller",institutions:["Korea University","Technische Universität Berlin"]},{name:"Alexandre Tkatchenko",institutions:["University of Luxembourg","Fritz Haber Institute of the Max Planck Society"]}],authorString:"Kristof T. Schütt; Farhad Arbabzadah; Stefan Chmiela; K. Müller; Alexandre Tkatchenko",institutions:["Fritz Haber Institute of the Max Planck Society","Korea University","Technische Universität Berlin","University of Luxembourg"],countries:["DE","KR","LU"],year:2017,journal:"Nature Communications",citations:1498,abstract:"Abstract Learning from data has led to paradigm shifts in a multitude of disciplines, including web, text and image search, speech recognition, as well as bioinformatics. Can machine learning enable similar breakthroughs in understanding quantum many-body systems? Here we develop an efficient deep learning approach that enables spatially and chemically resolved insights into quantum-mechanical observables of molecular systems. We unify concepts from many-body Hamiltonians with purpose-designed deep tensor neural networks, which leads to size-extensive and uniformly accurate (1 kcal mol −1 ) predictions in compositional and configurational chemical space for molecules of intermediate size. As an example of chemical relevance, the model reveals a classification of aromatic rings with respect to their stability. Further applications of our model for predicting atomic energies and local chemical potentials in molecules, reliable isomer energies, and molecules with peculiar electronic structure demonstrate the potential of machine learning for revealing insights into complex quantum-chemical systems.",keywords:["Chemical space","Observable","Quantum","Quantum chemical","Tensor","Artificial neural network","Molecule"],concepts:["Chemical space","Observable","Quantum","Quantum chemical","Tensor","Artificial neural network","Molecule"],pdf_url:"https://www.nature.com/articles/ncomms13890.pdf",is_oa:!0,n_refs:57,n_refs_in_core:2,degree:40,community:2,deg_w:370.5,betweenness:.0273,pagerank:.00764,eigenvector:.1214},{id:97,oaid:"W2777186991",doi:"10.1109/access.2017.2788044",title:"Deep Learning Applications in Medical Image Analysis",authors:[{name:"Justin Ker",institutions:["National Neuroscience Institute"]},{name:"Lipo Wang",institutions:["Nanyang Technological University"]},{name:"Jai Prashanth Rao",institutions:["National Neuroscience Institute"]},{name:"C. C. Tchoyoson Lim",institutions:["National Neuroscience Institute"]}],authorString:"Justin Ker; Lipo Wang; Jai Prashanth Rao; C. C. Tchoyoson Lim",institutions:["Nanyang Technological University","National Neuroscience Institute"],countries:["SG"],year:2017,journal:"IEEE Access",citations:1484,abstract:"The tremendous success of machine learning algorithms at image recognition tasks in recent years intersects with a time of dramatically increased use of electronic medical records and diagnostic imaging. This review introduces the machine learning algorithms as applied to medical image analysis, focusing on convolutional neural networks, and emphasizing clinical aspects of the field. The advantage of machine learning in an era of medical big data is that significant hierarchal relationships within the data can be discovered algorithmically without laborious hand-crafting of features. We cover key research areas and applications of medical image classification, localization, detection, segmentation, and registration. We conclude by discussing research obstacles, emerging trends, and possible future directions.",keywords:["Convolutional neural network","Deep learning","Medical imaging","Field","Image segmentation","Segmentation"],concepts:["Convolutional neural network","Deep learning","Medical imaging","Field","Image segmentation","Segmentation"],pdf_url:"https://doi.org/10.1109/access.2017.2788044",is_oa:!0,n_refs:151,n_refs_in_core:6,degree:22,community:1,deg_w:339,betweenness:.003,pagerank:.00765,eigenvector:.0424},{id:98,oaid:"W2962814013",doi:"10.1109/comst.2020.2970550",title:"Convergence of Edge Computing and Deep Learning: A Comprehensive Survey",authors:[{name:"Xiaofei Wang",institutions:["Tianjin University"]},{name:"Yiwen Han",institutions:["Tianjin University"]},{name:"Victor C. M. Leung",institutions:["University of British Columbia","Shenzhen University"]},{name:"Dusit Niyato",institutions:["Nanyang Technological University"]},{name:"Xueqiang Yan",institutions:["Huawei Technologies (China)"]},{name:"Xu Chen",institutions:["Sun Yat-sen University"]}],authorString:"Xiaofei Wang; Yiwen Han; Victor C. M. Leung; Dusit Niyato; Xueqiang Yan; Xu Chen",institutions:["Huawei Technologies (China)","Nanyang Technological University","Shenzhen University","Sun Yat-sen University","Tianjin University","University of British Columbia"],countries:["CA","CN","SG"],year:2020,journal:"IEEE Communications Surveys & Tutorials",citations:1456,abstract:"Ubiquitous sensors and smart devices from factories and communities are generating massive amounts of data, and ever-increasing computing power is driving the core of computation and services from the cloud to the edge of the network. As an important enabler broadly changing people's lives, from face recognition to ambitious smart factories and cities, developments of artificial intelligence (especially deep learning, DL) based applications and services are thriving. However, due to efficiency and latency issues, the current cloud computing service architecture hinders the vision of “providing artificial intelligence for every person and every organization at everywhere”. Thus, unleashing DL services using resources at the network edge near the data sources has emerged as a desirable solution. Therefore, edge intelligence, aiming to facilitate the deployment of DL services by edge computing, has received significant attention. In addition, DL, as the representative technique of artificial intelligence, can be integrated into edge computing frameworks to build intelligent edge for dynamic, adaptive edge maintenance and management. With regard to mutually beneficial edge intelligence and intelligent edge, this paper introduces and discusses: 1) the application scenarios of both; 2) the practical implementation methods and enabling technologies, namely DL training and inference in the customized edge computing framework; 3) challenges and future trends of more pervasive and fine-grained intelligence. We believe that by consolidating information scattered across the communication, networking, and DL areas, this survey can help readers to understand the connections between enabling technologies while promoting further discussions on the fusion of edge intelligence and intelligent edge, i.e., Edge DL.",keywords:["Edge computing","Cloud computing","Edge device","Enhanced Data Rates for GSM Evolution","Applications of artificial intelligence","Data science"],concepts:["Edge computing","Cloud computing","Edge device","Enhanced Data Rates for GSM Evolution","Applications of artificial intelligence","Data science"],pdf_url:"https://arxiv.org/pdf/1907.08349",is_oa:!0,n_refs:336,n_refs_in_core:6,degree:20,community:0,deg_w:252,betweenness:.0041,pagerank:.00627,eigenvector:.0284},{id:99,oaid:"W2949095042",doi:"10.1021/acs.chemmater.9b01294",title:"Graph Networks as a Universal Machine Learning Framework for Molecules and Crystals",authors:[{name:"Chi Chen",institutions:["University of California San Diego"]},{name:"Weike Ye",institutions:["University of California San Diego"]},{name:"Yunxing Zuo",institutions:["University of California San Diego"]},{name:"Zheng Chen",institutions:["University of California San Diego"]},{name:"Shyue Ping Ong",institutions:["University of California San Diego"]}],authorString:"Chi Chen; Weike Ye; Yunxing Zuo; Zheng Chen; Shyue Ping Ong",institutions:["University of California San Diego"],countries:["US"],year:2019,journal:"Chemistry of Materials",citations:1446,abstract:"Graph networks are a new machine learning (ML) paradigm that supports both relational reasoning and combinatorial generalization. Here, we develop universal MatErials Graph Network (MEGNet) models for accurate property prediction in both molecules and crystals. We demonstrate that the MEGNet models outperform prior ML models such as the SchNet in 11 out of 13 properties of the QM9 molecule data set. Similarly, we show that MEGNet models trained on ∼60 000 crystals in the Materials Project substantially outperform prior ML models in the prediction of the formation energies, band gaps, and elastic moduli of crystals, achieving better than density functional theory accuracy over a much larger data set. We present two new strategies to address data limitations common in materials science and chemistry. First, we demonstrate a physically intuitive approach to unify four separate molecular MEGNet models for the internal energy at 0 K and room temperature, enthalpy, and Gibbs free energy into a single free energy MEGNet model by incorporating the temperature, pressure, and entropy as global state inputs. Second, we show that the learned element embeddings in MEGNet models encode periodic chemical trends and can be transfer-learned from a property model trained on a larger data set (formation energies) to improve property models with smaller amounts of data (band gaps and elastic moduli).",keywords:["Generalization","Moduli","Graph","Enthalpy","Molecule","Property","Gibbs free energy"],concepts:["Generalization","Moduli","Graph","Enthalpy","Molecule","Property","Gibbs free energy"],pdf_url:"https://arxiv.org/pdf/1812.05055",is_oa:!0,n_refs:73,n_refs_in_core:6,degree:26,community:2,deg_w:339,betweenness:.0058,pagerank:.00688,eigenvector:.1296},{id:100,oaid:"W2610148085",doi:"10.1186/s13321-017-0235-x",title:"Molecular de-novo design through deep reinforcement learning",authors:[{name:"Marcus Olivecrona",institutions:["AstraZeneca (Japan)","AstraZeneca (Sweden)","AstraZeneca (United States)"]},{name:"Thomas Blaschke",institutions:["AstraZeneca (Sweden)"]},{name:"Ola Engkvist",institutions:["AstraZeneca (Sweden)"]},{name:"Hongming Chen",institutions:["AstraZeneca (Sweden)"]}],authorString:"Marcus Olivecrona; Thomas Blaschke; Ola Engkvist; Hongming Chen",institutions:["AstraZeneca (Japan)","AstraZeneca (Sweden)","AstraZeneca (United States)"],countries:["JP","SE","US"],year:2017,journal:"Journal of Cheminformatics",citations:1438,abstract:"This work introduces a method to tune a sequence-based generative model for molecular de novo design that through augmented episodic likelihood can learn to generate structures with certain specified desirable properties. We demonstrate how this model can execute a range of tasks such as generating analogues to a query structure and generating compounds predicted to be active against a biological target. As a proof of principle, the model is first trained to generate molecules that do not contain sulphur. As a second example, the model is trained to generate analogues to the drug Celecoxib, a technique that could be used for scaffold hopping or library expansion starting from a single molecule. Finally, when tuning the model towards generating compounds predicted to be active against the dopamine receptor type 2, the model generates structures of which more than 95% are predicted to be active, including experimentally confirmed actives that have not been included in either the generative model nor the activity prediction model. Graphical abstract .",keywords:["Reinforcement learning","Deep learning"],concepts:["Reinforcement learning","Deep learning"],pdf_url:"https://jcheminf.biomedcentral.com/track/pdf/10.1186/s13321-017-0235-x",is_oa:!0,n_refs:46,n_refs_in_core:5,degree:17,community:2,deg_w:119.5,betweenness:.0037,pagerank:.0035,eigenvector:.0147},{id:101,oaid:"W2786016794",doi:"10.1093/bioinformatics/bty294",title:"Modeling polypharmacy side effects with graph convolutional networks",authors:[{name:"Marinka Žitnik",institutions:["Stanford University"]},{name:"Monica Agrawal",institutions:["Stanford University"]},{name:"Jure Leskovec",institutions:["Chan Zuckerberg Initiative (United States)","Stanford University"]}],authorString:"Marinka Žitnik; Monica Agrawal; Jure Leskovec",institutions:["Chan Zuckerberg Initiative (United States)","Stanford University"],countries:["US"],year:2018,journal:"Bioinformatics",citations:1426,abstract:"Motivation: The use of drug combinations, termed polypharmacy, is common to treat patients with complex diseases or co-existing conditions. However, a major consequence of polypharmacy is a much higher risk of adverse side effects for the patient. Polypharmacy side effects emerge because of drug-drug interactions, in which activity of one drug may change, favorably or unfavorably, if taken with another drug. The knowledge of drug interactions is often limited because these complex relationships are rare, and are usually not observed in relatively small clinical testing. Discovering polypharmacy side effects thus remains an important challenge with significant implications for patient mortality and morbidity. Results: Here, we present Decagon, an approach for modeling polypharmacy side effects. The approach constructs a multimodal graph of protein-protein interactions, drug-protein target interactions and the polypharmacy side effects, which are represented as drug-drug interactions, where each side effect is an edge of a different type. Decagon is developed specifically to handle such multimodal graphs with a large number of edge types. Our approach develops a new graph convolutional neural network for multirelational link prediction in multimodal networks. Unlike approaches limited to predicting simple drug-drug interaction values, Decagon can predict the exact side effect, if any, through which a given drug combination manifests clinically. Decagon accurately predicts polypharmacy side effects, outperforming baselines by up to 69%. We find that it automatically learns representations of side effects indicative of co-occurrence of polypharmacy in patients. Furthermore, Decagon models particularly well polypharmacy side effects that have a strong molecular basis, while on predominantly non-molecular side effects, it achieves good performance because of effective sharing of model parameters across edge types. Decagon opens up opportunities to use large pharmacogenomic and patient population data to flag and prioritize polypharmacy side effects for follow-up analysis via formal pharmacological studies. Availability and implementation: Source code and preprocessed datasets are at: http://snap.stanford.edu/decagon.",keywords:["Polypharmacy","Graph","Theoretical computer science","Pharmacology"],concepts:["Polypharmacy","Graph","Theoretical computer science"],pdf_url:"https://academic.oup.com/bioinformatics/article-pdf/34/13/i457/25098429/bty294.pdf",is_oa:!0,n_refs:68,n_refs_in_core:2,degree:13,community:5,deg_w:75.5,betweenness:.0021,pagerank:.00233,eigenvector:.0291},{id:102,oaid:"W2892341857",doi:"10.1145/3234150",title:"A Survey on Deep Learning",authors:[{name:"Samira Pouyanfar",institutions:["Florida International University"]},{name:"Saad Sadiq",institutions:["University of Miami"]},{name:"Yilin Yan",institutions:["University of Miami"]},{name:"Haiman Tian",institutions:["Florida International University"]},{name:"Yudong Tao",institutions:["University of Miami"]},{name:"Maria Presa Reyes",institutions:["Florida International University"]},{name:"Mei‐Ling Shyu",institutions:["University of Miami"]},{name:"Shu‐Ching Chen",institutions:["Florida International University"]},{name:"S. S. Iyengar",institutions:["Florida International University"]}],authorString:"Samira Pouyanfar; Saad Sadiq; Yilin Yan; Haiman Tian; Yudong Tao; Maria Presa Reyes; Mei‐Ling Shyu; Shu‐Ching Chen; S. S. Iyengar",institutions:["Florida International University","University of Miami"],countries:["US"],year:2018,journal:"ACM Computing Surveys",citations:1380,abstract:"The field of machine learning is witnessing its golden era as deep learning slowly becomes the leader in this domain. Deep learning uses multiple layers to represent the abstractions of data to build computational models. Some key enabler deep learning algorithms such as generative adversarial networks, convolutional neural networks, and model transfers have completely changed our perception of information processing. However, there exists an aperture of understanding behind this tremendously fast-paced domain, because it was never previously represented from a multiscope perspective. The lack of core understanding renders these powerful methods as black-box machines that inhibit development at a fundamental level. Moreover, deep learning has repeatedly been perceived as a silver bullet to all stumbling blocks in machine learning, which is far from the truth. This article presents a comprehensive review of historical and recent state-of-the-art approaches in visual, audio, and text processing; social network analysis; and natural language processing, followed by the in-depth analysis on pivoting and groundbreaking advances in deep learning applications. It was also undertaken to review the issues faced in deep learning such as unsupervised learning, black-box models, and online learning and to illustrate how these challenges can be transformed into prolific future research avenues.",keywords:["Deep learning","Convolutional neural network","Field","Deep belief network","Unsupervised learning"],concepts:["Deep learning","Convolutional neural network","Field","Deep belief network","Unsupervised learning"],pdf_url:null,is_oa:!1,n_refs:185,n_refs_in_core:5,degree:25,community:0,deg_w:354.5,betweenness:.0029,pagerank:.00814,eigenvector:.0423},{id:103,oaid:"W4240485910",doi:"10.1109/tgrs.2016.2636241",title:"Deep Recurrent Neural Networks for Hyperspectral Image Classification",authors:[{name:"Lichao Mou",institutions:["Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)","Technical University of Munich"]},{name:"Pedram Ghamisi",institutions:["Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)","Technical University of Munich"]},{name:"Xiao Xiang Zhu",institutions:["Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)","Technical University of Munich"]}],authorString:"Lichao Mou; Pedram Ghamisi; Xiao Xiang Zhu",institutions:["Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)","Technical University of Munich"],countries:["DE"],year:2017,journal:"IEEE Transactions on Geoscience and Remote Sensing",citations:1360,abstract:"In recent years, vector-based machine learning algorithms, such as random forests, support vector machines, and 1-D convolutional neural networks, have shown promising results in hyperspectral image classification. Such methodologies, nevertheless, can lead to information loss in representing hyperspectral pixels, which intrinsically have a sequence-based data structure. A recurrent neural network (RNN), an important branch of the deep learning family, is mainly designed to handle sequential data. Can sequence-based RNN be an effective method of hyperspectral image classification? In this paper, we propose a novel RNN model that can effectively analyze hyperspectral pixels as sequential data and then determine information categories via network reasoning. As far as we know, this is the first time that an RNN framework has been proposed for hyperspectral image classification. Specifically, our RNN makes use of a newly proposed activation function, parametric rectified tanh (PRetanh), for hyperspectral sequential data analysis instead of the popular tanh or rectified linear unit. The proposed activation function makes it possible to use fairly high learning rates without the risk of divergence during the training procedure. Moreover, a modified gated recurrent unit, which uses PRetanh for hidden representation, is adopted to construct the recurrent layer in our network to efficiently process hyperspectral data and reduce the total number of parameters. Experimental results on three airborne hyperspectral images suggest competitive performance in the proposed mode. In addition, the proposed network architecture opens a new window for future research, showcasing the huge potential of deep recurrent networks for hyperspectral data analysis.",keywords:["Hyperspectral imaging","Recurrent neural network","Pattern recognition","Deep learning","Convolutional neural network","Support vector machine"],concepts:["Hyperspectral imaging","Recurrent neural network","Pattern recognition","Deep learning","Convolutional neural network","Support vector machine"],pdf_url:null,is_oa:!1,n_refs:52,n_refs_in_core:7,degree:22,community:3,deg_w:163.5,betweenness:.0053,pagerank:.00446,eigenvector:.0096},{id:104,oaid:"W3132191748",doi:"10.1109/jproc.2021.3060483",title:"Explaining Deep Neural Networks and Beyond: A Review of Methods and Applications",authors:[{name:"Wojciech Samek",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute"]},{name:"Grégoire Montavon",institutions:["Berlin Institute for the Foundations of Learning and Data"]},{name:"Sebastian Lapuschkin",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute"]},{name:"Christopher J. Anders",institutions:["Berlin Institute for the Foundations of Learning and Data"]},{name:"Klaus‐Robert Müller",institutions:["Korea University","Berlin Institute for the Foundations of Learning and Data"]}],authorString:"Wojciech Samek; Grégoire Montavon; Sebastian Lapuschkin; Christopher J. Anders; Klaus‐Robert Müller",institutions:["Berlin Institute for the Foundations of Learning and Data","Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Korea University"],countries:["DE","KR"],year:2021,journal:"Proceedings of the IEEE",citations:1348,abstract:"With the broader and highly successful usage of machine learning (ML) in industry and the sciences, there has been a growing demand for explainable artificial intelligence (XAI). Interpretability and explanation methods for gaining a better understanding of the problem-solving abilities and strategies of nonlinear ML, in particular, deep neural networks, are, therefore, receiving increased attention. In this work, we aim to: 1) provide a timely overview of this active emerging field, with a focus on “post hoc” explanations, and explain its theoretical foundations; 2) put interpretability algorithms to a test both from a theory and comparative evaluation perspective using extensive simulations; 3) outline best practice aspects, i.e., how to best include interpretation methods into the standard usage of ML; and 4) demonstrate successful usage of XAI in a representative selection of application scenarios. Finally, we discuss challenges and possible future directions of this exciting foundational field of ML.",keywords:["Interpretability","Field","Perspective","Artificial neural network","Interpretation"],concepts:["Interpretability","Field","Perspective","Artificial neural network","Interpretation"],pdf_url:"https://ieeexplore.ieee.org/ielx7/5/9369414/09369420.pdf",is_oa:!0,n_refs:320,n_refs_in_core:11,degree:26,community:4,deg_w:541,betweenness:.0107,pagerank:.01043,eigenvector:.2311},{id:105,oaid:"W3100366369",doi:"10.1561/2200000071",title:"An Introduction to Deep Reinforcement Learning",authors:[{name:"Vincent François-Lavet",institutions:["McGill University"]},{name:"Peter Henderson",institutions:["McGill University"]},{name:"Riashat Islam",institutions:["McGill University"]},{name:"Marc G. Bellemare",institutions:["Google (United States)"]},{name:"Joëlle Pineau",institutions:["Meta (Israel)","McGill University"]}],authorString:"Vincent François-Lavet; Peter Henderson; Riashat Islam; Marc G. Bellemare; Joëlle Pineau",institutions:["Google (United States)","McGill University","Meta (Israel)"],countries:["CA","IL","US"],year:2018,journal:"Foundations and Trends® in Machine Learning",citations:1268,abstract:"Deep reinforcement learning is the combination of reinforcement learning (RL) and deep learning. This field of research has been able to solve a wide range of complex decision making tasks that were previously out of reach for a machine. Thus, deep RL opens up many new applications in domains such as healthcare, robotics, smart grids, finance, and many more. This manuscript provides an introduction to deep reinforcement learning models, algorithms and techniques. Particular focus is on the aspects related to generalization and how deep RL can be used for practical applications. We assume the reader is familiar with basic machine learning concepts.",keywords:["Reinforcement learning","Deep learning","Generalization","Field","Robotics"],concepts:["Reinforcement learning","Deep learning","Generalization","Field","Robotics"],pdf_url:"https://arxiv.org/pdf/1811.12560",is_oa:!0,n_refs:104,n_refs_in_core:2,degree:9,community:0,deg_w:59.5,betweenness:5e-4,pagerank:.00213,eigenvector:.0038},{id:106,oaid:"W1984020445",doi:"10.1109/access.2014.2325029",title:"Big Data Deep Learning: Challenges and Perspectives",authors:[{name:"Xuewen Chen",institutions:["Wayne State University"]},{name:"Xiaotong Lin",institutions:["Oakland University","University of Rochester"]}],authorString:"Xuewen Chen; Xiaotong Lin",institutions:["Oakland University","University of Rochester","Wayne State University"],countries:["US"],year:2014,journal:"IEEE Access",citations:1260,abstract:"Deep learning is currently an extremely active research area in machine learning and pattern recognition society. It has gained huge successes in a broad area of applications such as speech recognition, computer vision, and natural language processing. With the sheer size of data available today, big data brings big opportunities and transformative potential for various sectors; on the other hand, it also presents unprecedented challenges to harnessing data and information. As the data keeps getting bigger, deep learning is coming to play a key role in providing big data predictive analytics solutions. In this paper, we provide a brief overview of deep learning, and highlight current research efforts and the challenges to big data, as well as the future trends.",keywords:["Big data","Transformative learning","Deep learning","Data science","Learning analytics","Key"],concepts:["Big data","Transformative learning","Deep learning","Data science","Learning analytics","Key"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/6705689/06817512.pdf",is_oa:!0,n_refs:131,n_refs_in_core:4,degree:22,community:0,deg_w:215,betweenness:.0022,pagerank:.00558,eigenvector:.0187},{id:107,oaid:"W2908261578",doi:"10.1109/tcyb.2020.2977374",title:"Deep Reinforcement Learning for Multiagent Systems: A Review of Challenges, Solutions, and Applications",authors:[{name:"Thanh Thi Nguyen",institutions:["Deakin University"]},{name:"Ngoc Duy Nguyen",institutions:["Deakin University"]},{name:"Saeid Nahavandi",institutions:["Deakin University"]}],authorString:"Thanh Thi Nguyen; Ngoc Duy Nguyen; Saeid Nahavandi",institutions:["Deakin University"],countries:["AU"],year:2020,journal:"IEEE Transactions on Cybernetics",citations:1240,abstract:"Reinforcement learning (RL) algorithms have been around for decades and employed to solve various sequential decision-making problems. These algorithms, however, have faced great challenges when dealing with high-dimensional environments. The recent development of deep learning has enabled RL methods to drive optimal policies for sophisticated and capable agents, which can perform efficiently in these challenging environments. This article addresses an important aspect of deep RL related to situations that require multiple agents to communicate and cooperate to solve complex tasks. A survey of different approaches to problems related to multiagent deep RL (MADRL) is presented, including nonstationarity, partial observability, continuous state and action spaces, multiagent training schemes, and multiagent transfer learning. The merits and demerits of the reviewed methods will be analyzed and discussed with their corresponding applications explored. It is envisaged that this review provides insights about various MADRL methods and can lead to the future development of more robust and highly useful multiagent learning methods for solving real-world problems.",keywords:["Reinforcement learning","Observability","Deep learning","Transfer of learning","Action","State"],concepts:["Reinforcement learning","Observability","Deep learning","Transfer of learning","Action","State"],pdf_url:"https://arxiv.org/pdf/1812.11794",is_oa:!0,n_refs:205,n_refs_in_core:4,degree:13,community:0,deg_w:144,betweenness:.0021,pagerank:.00423,eigenvector:.0089},{id:108,oaid:"W2098676252",doi:"10.3390/rs71114680",title:"Transferring Deep Convolutional Neural Networks for the Scene Classification of High-Resolution Remote Sensing Imagery",authors:[{name:"Fan Hu",institutions:["Wuhan University","State Key Laboratory of Information Engineering in Surveying Mapping and Remote Sensing"]},{name:"Gui-Song Xia",institutions:["State Key Laboratory of Information Engineering in Surveying Mapping and Remote Sensing"]},{name:"Jingwen Hu",institutions:["Wuhan University","State Key Laboratory of Information Engineering in Surveying Mapping and Remote Sensing"]},{name:"Liangpei Zhang",institutions:["State Key Laboratory of Information Engineering in Surveying Mapping and Remote Sensing"]}],authorString:"Fan Hu; Gui-Song Xia; Jingwen Hu; Liangpei Zhang",institutions:["State Key Laboratory of Information Engineering in Surveying Mapping and Remote Sensing","Wuhan University"],countries:["CN"],year:2015,journal:"Remote Sensing",citations:1211,abstract:"Learning efficient image representations is at the core of the scene classification task of remote sensing imagery. The existing methods for solving the scene classification task, based on either feature coding approaches with low-level hand-engineered features or unsupervised feature learning, can only generate mid-level image features with limited representative ability, which essentially prevents them from achieving better performance. Recently, the deep convolutional neural networks (CNNs), which are hierarchical architectures trained on large-scale datasets, have shown astounding performance in object recognition and detection. However, it is still not clear how to use these deep convolutional neural networks for high-resolution remote sensing (HRRS) scene classification. In this paper, we investigate how to transfer features from these successfully pre-trained CNNs for HRRS scene classification. We propose two scenarios for generating image features via extracting CNN features from different layers. In the first scenario, the activation vectors extracted from fully-connected layers are regarded as the final image features; in the second scenario, we extract dense features from the last convolutional layer at multiple scales and then encode the dense features into global image features through commonly used feature coding approaches. Extensive experiments on two public scene classification datasets demonstrate that the image features obtained by the two proposed scenarios, even with a simple linear classifier, can result in remarkable performance and improve the state-of-the-art by a significant margin. The results reveal that the features from pre-trained CNNs generalize well to HRRS datasets and are more expressive than the low- and mid-level features. Moreover, we tentatively combine features extracted from different CNN models for better performance.",keywords:["Convolutional neural network","Pattern recognition","Classifier","Contextual image classification","Deep learning","Transfer of learning"],concepts:["Convolutional neural network","Pattern recognition","Classifier","Contextual image classification","Deep learning","Transfer of learning"],pdf_url:"https://www.mdpi.com/2072-4292/7/11/14680/pdf?version=1446720431",is_oa:!0,n_refs:63,n_refs_in_core:2,degree:21,community:3,deg_w:228,betweenness:.0023,pagerank:.00554,eigenvector:.0203},{id:109,oaid:"W2148461049",doi:"10.5591/978-1-57735-516-8/ijcai11-210",title:"Flexible, high performance convolutional neural networks for image classification",authors:[{name:"Dan Cireşan",institutions:["University of Applied Sciences and Arts of Southern Switzerland","Dalle Molle Institute for Artificial Intelligence Research"]},{name:"Ueli Meier",institutions:["University of Applied Sciences and Arts of Southern Switzerland","Dalle Molle Institute for Artificial Intelligence Research"]},{name:"Jonathan Masci",institutions:["University of Applied Sciences and Arts of Southern Switzerland","Dalle Molle Institute for Artificial Intelligence Research"]},{name:"Luca Maria Gambardella",institutions:["University of Applied Sciences and Arts of Southern Switzerland","Dalle Molle Institute for Artificial Intelligence Research"]},{name:"Jürgen Schmidhuber",institutions:["University of Applied Sciences and Arts of Southern Switzerland","Dalle Molle Institute for Artificial Intelligence Research"]}],authorString:"Dan Cireşan; Ueli Meier; Jonathan Masci; Luca Maria Gambardella; Jürgen Schmidhuber",institutions:["Dalle Molle Institute for Artificial Intelligence Research","University of Applied Sciences and Arts of Southern Switzerland"],countries:["CH"],year:2011,journal:null,citations:1208,abstract:"We present a fast, fully parameterizable GPU implementation of Convolutional Neural Network variants. Our feature extractors are neither carefully designed nor pre-wired, but rather learned in a supervised way. Our deep hierarchical architectures achieve the best published results on benchmarks for object classification (NORB, CIFAR10) and handwritten digit recognition (MNIST), with error rates of 2.53%, 19.51%, 0.35%, respectively. Deep nets trained by simple back-propagation perform better than more shallow ones. Learning is surprisingly rapid. NORB is completely trained within five epochs. Test error rates on MNIST drop to 2.42%, 0.97 % and 0.48 % after 1, 3 and 17 epochs, respectively.",keywords:["MNIST database","Convolutional neural network","Pattern recognition","Feature","Deep learning","Contextual image classification"],concepts:["MNIST database","Convolutional neural network","Pattern recognition","Feature","Deep learning","Contextual image classification"],pdf_url:null,is_oa:!1,n_refs:28,n_refs_in_core:1,degree:13,community:0,deg_w:69,betweenness:.001,pagerank:.00237,eigenvector:.0054},{id:110,oaid:"W2621028221",doi:"10.1007/s10278-017-9983-4",title:"Deep Learning for Brain MRI Segmentation: State of the Art and Future Directions",authors:[{name:"Zeynettin Akkus",institutions:["Mayo Clinic"]},{name:"Alfiia Galimzianova",institutions:["Stanford University"]},{name:"Assaf Hoogi",institutions:["Stanford University"]},{name:"Daniel L. Rubin",institutions:["Stanford University"]},{name:"Bradley J. Erickson",institutions:["Mayo Clinic"]}],authorString:"Zeynettin Akkus; Alfiia Galimzianova; Assaf Hoogi; Daniel L. Rubin; Bradley J. Erickson",institutions:["Mayo Clinic","Stanford University"],countries:["US"],year:2017,journal:"Journal of Digital Imaging",citations:1121,abstract:"Quantitative analysis of brain MRI is routine for many neurological diseases and conditions and relies on accurate segmentation of structures of interest. Deep learning-based segmentation approaches for brain MRI are gaining interest due to their self-learning and generalization ability over large amounts of data. As the deep learning architectures are becoming more mature, they gradually outperform previous state-of-the-art classical machine learning algorithms. This review aims to provide an overview of current deep learning-based segmentation approaches for quantitative brain MRI. First we review the current deep learning architectures used for segmentation of anatomical brain structures and brain lesions. Next, the performance, speed, and properties of deep learning approaches are summarized and discussed. Finally, we provide a critical assessment of the current state and identify likely future developments and trends.",keywords:["Deep learning","Segmentation","Deep neural networks","Generalization","Neuroimaging"],concepts:["Deep learning","Segmentation","Deep neural networks","Generalization","Neuroimaging"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10278-017-9983-4.pdf",is_oa:!0,n_refs:69,n_refs_in_core:4,degree:19,community:1,deg_w:152,betweenness:.004,pagerank:.00401,eigenvector:.0174},{id:111,oaid:"W2778924750",doi:"10.1109/tmi.2017.2785879",title:"DAGAN: Deep De-Aliasing Generative Adversarial Networks for Fast Compressed Sensing MRI Reconstruction",authors:[{name:"Guang Yang",institutions:["Lung Institute"]},{name:"Simiao Yu",institutions:["NIHR Imperial Biomedical Research Centre","Imperial College London"]},{name:"Hao Dong",institutions:["NIHR Imperial Biomedical Research Centre","Imperial College London"]},{name:"Greg Slabaugh",institutions:["City, University of London"]},{name:"Pier Luigi Dragotti",institutions:["Imperial College London"]},{name:"Xujiong Ye",institutions:["University of Lincoln"]},{name:"Fangde Liu",institutions:["NIHR Imperial Biomedical Research Centre","Imperial College London"]},{name:"Simon Arridge",institutions:["University College London"]},{name:"Jennifer Keegan",institutions:["Lung Institute"]},{name:"Yike Guo",institutions:["NIHR Imperial Biomedical Research Centre","Imperial College London"]},{name:"David Firmin",institutions:["Lung Institute"]}],authorString:"Guang Yang; Simiao Yu; Hao Dong; Greg Slabaugh; Pier Luigi Dragotti; Xujiong Ye; Fangde Liu; Simon Arridge; Jennifer Keegan; Yike Guo; David Firmin",institutions:["City, University of London","Imperial College London","Lung Institute","NIHR Imperial Biomedical Research Centre","University College London","University of Lincoln"],countries:["GB","US"],year:2017,journal:"IEEE Transactions on Medical Imaging",citations:1117,abstract:"Compressed sensing magnetic resonance imaging (CS-MRI) enables fast acquisition, which is highly desirable for numerous clinical applications. This can not only reduce the scanning cost and ease patient burden, but also potentially reduce motion artefacts and the effect of contrast washout, thus yielding better image quality. Different from parallel imaging-based fast MRI, which utilizes multiple coils to simultaneously receive MR signals, CS-MRI breaks the Nyquist-Shannon sampling barrier to reconstruct MRI images with much less required raw data. This paper provides a deep learning-based strategy for reconstruction of CS-MRI, and bridges a substantial gap between conventional non-learning methods working only on data from a single image, and prior knowledge from large training data sets. In particular, a novel conditional Generative Adversarial Networks-based model (DAGAN)-based model is proposed to reconstruct CS-MRI. In our DAGAN architecture, we have designed a refinement learning method to stabilize our U-Net based generator, which provides an end-to-end network to reduce aliasing artefacts. To better preserve texture and edges in the reconstruction, we have coupled the adversarial loss with an innovative content loss. In addition, we incorporate frequency-domain information to enforce similarity in both the image and frequency domains. We have performed comprehensive comparison studies with both conventional CS-MRI reconstruction methods and newly investigated deep learning approaches. Compared with these methods, our DAGAN method provides superior reconstruction with preserved perceptual image details. Furthermore, each image is reconstructed in about 5 ms, which is suitable for real-time processing.",keywords:["Aliasing","Compressed sensing","Iterative reconstruction","Deep learning","Computer vision","Image quality"],concepts:["Aliasing","Compressed sensing","Iterative reconstruction","Deep learning","Computer vision","Image quality"],pdf_url:"https://doi.org/10.1109/tmi.2017.2785879",is_oa:!0,n_refs:94,n_refs_in_core:3,degree:20,community:1,deg_w:148,betweenness:.0035,pagerank:.00441,eigenvector:.0059},{id:112,oaid:"W3208687975",doi:"10.1038/s41524-022-00734-6",title:"Recent advances and applications of deep learning methods in materials science",authors:[{name:"Kamal Choudhary",institutions:["National Institute of Standards and Technology","Theiss Research","National Labor College"]},{name:"Brian DeCost",institutions:["National Institute of Standards and Technology","Material Measurement Laboratory"]},{name:"Chi Chen",institutions:["University of California San Diego"]},{name:"Anubhav Jain",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Francesca Tavazza",institutions:["National Institute of Standards and Technology"]},{name:"Ryan Cohn",institutions:["Carnegie Mellon University"]},{name:"Cheol Woo Park",institutions:["Northwestern University"]},{name:"Alok Choudhary",institutions:["Northwestern University"]},{name:"Ankit Agrawal",institutions:["Northwestern University"]},{name:"Simon J. L. Billinge",institutions:["Institute of Applied Mathematics","Columbia University"]},{name:"Elizabeth A. Holm",institutions:["Carnegie Mellon University"]},{name:"Shyue Ping Ong",institutions:["University of California San Diego"]},{name:"Chris Wolverton",institutions:["Northwestern University"]}],authorString:"Kamal Choudhary; Brian DeCost; Chi Chen; Anubhav Jain; Francesca Tavazza; Ryan Cohn; Cheol Woo Park; Alok Choudhary; Ankit Agrawal; Simon J. L. Billinge; Elizabeth A. Holm; Shyue Ping Ong et al.",institutions:["Carnegie Mellon University","Columbia University","Institute of Applied Mathematics","Lawrence Berkeley National Laboratory","Material Measurement Laboratory","National Institute of Standards and Technology","National Labor College","Northwestern University","Theiss Research","University of California San Diego"],countries:["RU","US"],year:2022,journal:"npj Computational Materials",citations:1080,abstract:"Abstract Deep learning (DL) is one of the fastest-growing topics in materials data science, with rapidly emerging applications spanning atomistic, image-based, spectral, and textual data modalities. DL allows analysis of unstructured data and automated identification of features. The recent development of large materials databases has fueled the application of DL methods in atomistic prediction in particular. In contrast, advances in image and spectral data have largely leveraged synthetic data enabled by high-quality forward models as well as by generative unsupervised DL methods. In this article, we present a high-level overview of deep learning methods followed by a detailed discussion of recent developments of deep learning in atomistic simulation, materials imaging, spectral analysis, and natural language processing. For each modality we discuss applications involving both theoretical and experimental data, typical modeling approaches with their strengths and limitations, and relevant publicly available software and datasets. We conclude the review with a discussion of recent cross-cutting work related to uncertainty quantification in this field and a brief perspective on limitations, challenges, and potential growth areas for DL methods in materials science.",keywords:["Deep learning","Data science","Field","Identification","Generative grammar","Perspective"],concepts:["Deep learning","Data science","Field","Identification","Generative grammar","Perspective"],pdf_url:"https://www.nature.com/articles/s41524-022-00734-6.pdf",is_oa:!0,n_refs:455,n_refs_in_core:17,degree:31,community:2,deg_w:497,betweenness:.0113,pagerank:.00991,eigenvector:.1758},{id:113,oaid:"W2923693308",doi:"10.1021/acs.jctc.9b00181",title:"PhysNet: A Neural Network for Predicting Energies, Forces, Dipole Moments, and Partial Charges",authors:[{name:"Oliver T. Unke",institutions:["University of Basel"]},{name:"Markus Meuwly",institutions:["University of Basel"]}],authorString:"Oliver T. Unke; Markus Meuwly",institutions:["University of Basel"],countries:["CH"],year:2019,journal:"Journal of Chemical Theory and Computation",citations:1076,abstract:"In recent years, machine learning (ML) methods have become increasingly popular in computational chemistry. After being trained on appropriate ab initio reference data, these methods allow for accurately predicting the properties of chemical systems, circumventing the need for explicitly solving the electronic Schrödinger equation. Because of their computational efficiency and scalability to large data sets, deep neural networks (DNNs) are a particularly promising ML algorithm for chemical applications. This work introduces PhysNet, a DNN architecture designed for predicting energies, forces, and dipole moments of chemical systems. PhysNet achieves state-of-the-art performance on the QM9, MD17, and ISO17 benchmarks. Further, two new data sets are generated in order to probe the performance of ML models for describing chemical reactions, long-range interactions, and condensed phase systems. It is shown that explicitly including electrostatics in energy predictions is crucial for a qualitatively correct description of the asymptotic regions of a potential energy surface (PES). PhysNet models trained on a systematically constructed set of small peptide fragments (at most eight heavy atoms) are able to generalize to considerably larger proteins like deca-alanine (Ala10): The optimized geometry of helical Ala10 predicted by PhysNet is virtually identical to ab initio results (RMSD = 0.21 Å). By running unbiased molecular dynamics (MD) simulations of Ala10 on the PhysNet-PES in gas phase, it is found that instead of a helical structure, Ala10 folds into a “wreath-shaped” configuration, which is more stable than the helical form by 0.46 kcal mol–1 according to the reference ab initio calculations.",keywords:["Dipole","Ab initio","Artificial neural network","Electrostatics","Scalability","Statistical physics"],concepts:["Dipole","Ab initio","Artificial neural network","Electrostatics","Scalability","Statistical physics"],pdf_url:"https://arxiv.org/pdf/1902.08408",is_oa:!0,n_refs:129,n_refs_in_core:5,degree:25,community:2,deg_w:299.5,betweenness:.0055,pagerank:.00636,eigenvector:.0925},{id:114,oaid:"W2189911347",doi:"10.3389/fenvs.2015.00080",title:"DeepTox: Toxicity Prediction using Deep Learning",authors:[{name:"Andreas Mayr",institutions:["Johannes Kepler University of Linz","RISC Software (Austria)"]},{name:"Günter Klambauer",institutions:["Johannes Kepler University of Linz"]},{name:"Thomas Unterthiner",institutions:["Johannes Kepler University of Linz","RISC Software (Austria)"]},{name:"Sepp Hochreiter",institutions:["Johannes Kepler University of Linz"]}],authorString:"Andreas Mayr; Günter Klambauer; Thomas Unterthiner; Sepp Hochreiter",institutions:["Johannes Kepler University of Linz","RISC Software (Austria)"],countries:["AT"],year:2016,journal:"Frontiers in Environmental Science",citations:1059,abstract:"The Tox21 Data Challenge has been the largest effort of the scientific community to compare computational methods for toxicity prediction. This challenge comprised 12,000 environmental chemicals and drugs which were measured for 12 different toxic effects by specifically designed assays. We participated in this challenge to assess the performance of Deep Learning in computational toxicity prediction. Deep Learning has already revolutionized image processing, speech recognition, and language understanding but has not yet been applied to computational toxicity. Deep Learning is founded on novel algorithms and architectures for artificial neural networks together with the recent availability of very fast computers and massive datasets. It discovers multiple levels of distributed representations of the input, with higher levels representing more abstract concepts. We hypothesized that the construction of a hierarchy of chemical features gives Deep Learning the edge over other toxicity prediction methods. Furthermore, Deep Learning naturally enables multi-task learning, that is, learning of all toxic effects in one neural network and thereby learning of highly informative chemical features.In order to utilize Deep Learning for toxicity prediction, we have developed the DeepTox pipeline. First, DeepTox normalizes the chemical representations of the compounds. Then it computes a large number of chemical descriptors that are used as input to machine learning methods. In its next step, DeepTox trains models, evaluates them, and combines the best of them to ensembles. Finally, DeepTox predicts the toxicity of new compounds. In the Tox21 Data Challenge, DeepTox had the highest performance of all computational methods winning the grand challenge, the nuclear receptor panel, the stress response panel, and six single assays (teams ``Bioinf@JKU''). We found that Deep Learning excelled in toxicity prediction and outperformed many other computational approaches like naive Bayes, support vector machines, and random forests.",keywords:["Deep learning","Chemical toxicity","Artificial neural network","Computational model","Pipeline"],concepts:["Deep learning","Chemical toxicity","Artificial neural network","Computational model","Pipeline"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fenvs.2015.00080/pdf",is_oa:!0,n_refs:107,n_refs_in_core:2,degree:21,community:2,deg_w:150.5,betweenness:.0079,pagerank:.00399,eigenvector:.018},{id:115,oaid:"W2744692634",doi:"10.1109/jbhi.2017.2731873",title:"Automated Breast Ultrasound Lesions Detection Using Convolutional Neural Networks",authors:[{name:"Moi Hoon Yap",institutions:["Manchester Metropolitan University"]},{name:"Gérard Pons",institutions:["Universitat Oberta de Catalunya"]},{name:"Robert Martí",institutions:["Universitat de Girona"]},{name:"Sergi Ganau",institutions:["Corporació Sanitària Parc Taulí"]},{name:"Melcior Sentís",institutions:["Corporació Sanitària Parc Taulí"]},{name:"Reyer Zwiggelaar",institutions:["Aberystwyth University"]},{name:"Adrian K. Davison",institutions:["Manchester Academic Health Science Centre","University of Manchester"]},{name:"Robert Martí",institutions:["Universitat de Girona"]}],authorString:"Moi Hoon Yap; Gérard Pons; Robert Martí; Sergi Ganau; Melcior Sentís; Reyer Zwiggelaar; Adrian K. Davison; Robert Martí",institutions:["Aberystwyth University","Corporació Sanitària Parc Taulí","Manchester Academic Health Science Centre","Manchester Metropolitan University","Universitat Oberta de Catalunya","Universitat de Girona","University of Manchester"],countries:["ES","GB"],year:2017,journal:"IEEE Journal of Biomedical and Health Informatics",citations:1034,abstract:"Breast lesion detection using ultrasound imaging is considered an important step of computer-aided diagnosis systems. Over the past decade, researchers have demonstrated the possibilities to automate the initial lesion detection. However, the lack of a common dataset impedes research when comparing the performance of such algorithms. This paper proposes the use of deep learning approaches for breast ultrasound lesion detection and investigates three different methods: a Patch-based LeNet, a U-Net, and a transfer learning approach with a pretrained FCN-AlexNet. Their performance is compared against four state-of-the-art lesion detection algorithms (i.e., Radial Gradient Index, Multifractal Filtering, Rule-based Region Ranking, and Deformable Part Models). In addition, this paper compares and contrasts two conventional ultrasound image datasets acquired from two different ultrasound systems. Dataset A comprises 306 (60 malignant and 246 benign) images and Dataset B comprises 163 (53 malignant and 110 benign) images. To overcome the lack of public datasets in this domain, Dataset B will be made available for research purposes. The results demonstrate an overall improvement by the deep learning approaches when assessed on both datasets in terms of True Positive Fraction, False Positives per image, and F-measure.",keywords:["Convolutional neural network","Deep learning","False positive paradox","Transfer of learning","Pattern recognition","Breast ultrasound"],concepts:["Convolutional neural network","Deep learning","False positive paradox","Transfer of learning","Pattern recognition","Breast ultrasound"],pdf_url:"https://research.manchester.ac.uk/en/publications/2a313e92-e0c1-438e-875b-0cef27e6f535",is_oa:!0,n_refs:52,n_refs_in_core:5,degree:20,community:0,deg_w:123.5,betweenness:.0025,pagerank:.00354,eigenvector:.0088},{id:116,oaid:"W2972418846",doi:"10.1002/inf2.12028",title:"Machine learning in materials science",authors:[{name:"Jing Wei",institutions:["Beijing University of Posts and Telecommunications"]},{name:"Xuan Chu",institutions:["Beijing University of Posts and Telecommunications"]},{name:"Xiangyu Sun",institutions:["Beijing University of Posts and Telecommunications"]},{name:"Kun Xu",institutions:["Beijing University of Posts and Telecommunications"]},{name:"Hui‐Xiong Deng",institutions:["Institute of Semiconductors","University of Chinese Academy of Sciences"]},{name:"Ji-Gen Chen",institutions:["Taizhou University"]},{name:"Zhongming Wei",institutions:["Institute of Semiconductors","Beijing Academy of Quantum Information Sciences","University of Chinese Academy of Sciences"]},{name:"Ming Lei",institutions:["Beijing University of Posts and Telecommunications"]}],authorString:"Jing Wei; Xuan Chu; Xiangyu Sun; Kun Xu; Hui‐Xiong Deng; Ji-Gen Chen; Zhongming Wei; Ming Lei",institutions:["Beijing Academy of Quantum Information Sciences","Beijing University of Posts and Telecommunications","Institute of Semiconductors","Taizhou University","University of Chinese Academy of Sciences"],countries:["CN"],year:2019,journal:"InfoMat",citations:1018,abstract:"Abstract Traditional methods of discovering new materials, such as the empirical trial and error method and the density functional theory (DFT)‐based method, are unable to keep pace with the development of materials science today due to their long development cycles, low efficiency, and high costs. Accordingly, due to its low computational cost and short development cycle, machine learning is coupled with powerful data processing and high prediction performance and is being widely used in material detection, material analysis, and material design. In this article, we discuss the basic operational procedures in analyzing material properties via machine learning, summarize recent applications of machine learning algorithms to several mature fields in materials science, and discuss the improvements that are required for wide‐ranging application.",keywords:["Pace","Development","Ranging","Industrial engineering"],concepts:["Pace","Development","Ranging","Industrial engineering"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/inf2.12028",is_oa:!0,n_refs:153,n_refs_in_core:8,degree:23,community:2,deg_w:303.5,betweenness:.0042,pagerank:.0064,eigenvector:.0989},{id:117,oaid:"W2921802966",doi:"10.1038/s41467-019-08987-4",title:"Unmasking Clever Hans predictors and assessing what machines really learn",authors:[{name:"Sebastian Lapuschkin",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute"]},{name:"Stephan Wäldchen",institutions:["Technische Universität Berlin"]},{name:"Alexander Binder",institutions:["Singapore University of Technology and Design"]},{name:"Grégoire Montavon",institutions:["Technische Universität Berlin"]},{name:"Wojciech Samek",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute"]},{name:"Klaus-Robert Müller",institutions:["Korea University","Max Planck Institute for Informatics","Technische Universität Berlin"]}],authorString:"Sebastian Lapuschkin; Stephan Wäldchen; Alexander Binder; Grégoire Montavon; Wojciech Samek; Klaus-Robert Müller",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Korea University","Max Planck Institute for Informatics","Singapore University of Technology and Design","Technische Universität Berlin"],countries:["DE","KR","SG"],year:2019,journal:"Nature Communications",citations:1005,abstract:"Current learning machines have successfully solved hard application problems, reaching high accuracy and displaying seemingly intelligent behavior. Here we apply recent techniques for explaining decisions of state-of-the-art learning machines and analyze various tasks from computer vision and arcade games. This showcases a spectrum of problem-solving behaviors ranging from naive and short-sighted, to well-informed and strategic. We observe that standard performance evaluation metrics can be oblivious to distinguishing these diverse problem solving behaviors. Furthermore, we propose our semi-automated Spectral Relevance Analysis that provides a practically effective way of characterizing and validating the behavior of nonlinear learning machines. This helps to assess whether a learned model indeed delivers reliably for the problem that it was conceived for. Furthermore, our work intends to add a voice of caution to the ongoing excitement about machine intelligence and pledges to evaluate and judge some of these recent successes in a more nuanced manner.",keywords:["Relevance","Work","Ranging","Human intelligence","Variety"],concepts:["Relevance","Data science","Human–computer interaction","Work","Ranging"],pdf_url:"https://www.nature.com/articles/s41467-019-08987-4.pdf",is_oa:!0,n_refs:41,n_refs_in_core:3,degree:23,community:4,deg_w:189,betweenness:.0067,pagerank:.00417,eigenvector:.0781},{id:118,oaid:"W2513853720",doi:"10.3389/fnins.2016.00508",title:"Training Deep Spiking Neural Networks Using Backpropagation",authors:[{name:"Jun Haeng Lee",institutions:["SIB Swiss Institute of Bioinformatics","University of Zurich","Samsung (South Korea)","ETH Zurich"]},{name:"Tobi Delbrück",institutions:["SIB Swiss Institute of Bioinformatics","University of Zurich","ETH Zurich"]},{name:"Michael Pfeiffer",institutions:["SIB Swiss Institute of Bioinformatics","University of Zurich","ETH Zurich"]}],authorString:"Jun Haeng Lee; Tobi Delbrück; Michael Pfeiffer",institutions:["ETH Zurich","SIB Swiss Institute of Bioinformatics","Samsung (South Korea)","University of Zurich"],countries:["CH","KR"],year:2016,journal:"Frontiers in Neuroscience",citations:992,abstract:"Deep spiking neural networks (SNNs) hold the potential for improving the latency and energy efficiency of deep neural networks through data-driven event-based computation. However, training such networks is difficult due to the non-differentiable nature of spike events. In this paper, we introduce a novel technique, which treats the membrane potentials of spiking neurons as differentiable signals, where discontinuities at spike times are considered as noise. This enables an error backpropagation mechanism for deep SNNs that follows the same principles as in conventional deep networks, but works directly on spike signals and membrane potentials. Compared with previous methods relying on indirect training and conversion, our technique has the potential to capture the statistics of spikes more precisely. We evaluate the proposed framework on artificially generated events from the original MNIST handwritten digit benchmark, and also on the N-MNIST benchmark recorded with an event-based dynamic vision sensor, in which the proposed method reduces the error rate by a factor of more than three compared to the best previous SNN, and also achieves a higher accuracy than a conventional convolutional neural network (CNN) trained and tested on the same data. We demonstrate in the context of the MNIST task that thanks to their event-driven operation, deep SNNs (both fully connected and convolutional) trained with our method achieve accuracy equivalent with conventional neural networks. In the N-MNIST example, equivalent accuracy is achieved with about five times fewer computational operations.",keywords:["MNIST database","Spiking neural network","Backpropagation","Benchmark","Convolutional neural network","Deep learning"],concepts:["MNIST database","Spiking neural network","Backpropagation","Benchmark","Convolutional neural network","Deep learning"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnins.2016.00508/pdf",is_oa:!0,n_refs:57,n_refs_in_core:4,degree:20,community:0,deg_w:140,betweenness:.0028,pagerank:.00408,eigenvector:.0104},{id:119,oaid:"W4366091323",doi:"10.1007/s10462-023-10466-8",title:"Deep learning modelling techniques: current progress, applications, advantages, and challenges",authors:[{name:"Shams Forruque Ahmed",institutions:["Asian University for Women"]},{name:"Md. Sakib Bin Alam",institutions:["Asian Institute of Technology"]},{name:"Maruf Hassan",institutions:["Asian University for Women"]},{name:"Mahtabin Rodela Rozbu",institutions:["Carnegie Mellon University"]},{name:"Taoseef Ishtiak",institutions:["Carleton University"]},{name:"Nazifa Rafa",institutions:["University of Cambridge"]},{name:"M. Mofijur",institutions:["University of Technology Sydney","Prince Mohammad bin Fahd University"]},{name:"A. B. M. Shawkat Ali",institutions:["University of Fiji","Central Queensland University"]},{name:"Amir H. Gandomi",institutions:["Obuda University","University of Technology Sydney"]}],authorString:"Shams Forruque Ahmed; Md. Sakib Bin Alam; Maruf Hassan; Mahtabin Rodela Rozbu; Taoseef Ishtiak; Nazifa Rafa; M. Mofijur; A. B. M. Shawkat Ali; Amir H. Gandomi",institutions:["Asian Institute of Technology","Asian University for Women","Carleton University","Carnegie Mellon University","Central Queensland University","Obuda University","Prince Mohammad bin Fahd University","University of Cambridge","University of Fiji","University of Technology Sydney"],countries:["AU","BD","CA","FJ","GB","HU","SA","TH","US"],year:2023,journal:"Artificial Intelligence Review",citations:991,abstract:"Abstract Deep learning (DL) is revolutionizing evidence-based decision-making techniques that can be applied across various sectors. Specifically, it possesses the ability to utilize two or more levels of non-linear feature transformation of the given data via representation learning in order to overcome limitations posed by large datasets. As a multidisciplinary field that is still in its nascent phase, articles that survey DL architectures encompassing the full scope of the field are rather limited. Thus, this paper comprehensively reviews the state-of-art DL modelling techniques and provides insights into their advantages and challenges. It was found that many of the models exhibit a highly domain-specific efficiency and could be trained by two or more methods. However, training DL models can be very time-consuming, expensive, and requires huge samples for better accuracy. Since DL is also susceptible to deception and misclassification and tends to get stuck on local minima, improved optimization of parameters is required to create more robust models. Regardless, DL has already been leading to groundbreaking results in the healthcare, education, security, commercial, industrial, as well as government sectors. Some models, like the convolutional neural network (CNN), generative adversarial networks (GAN), recurrent neural network (RNN), recursive neural networks, and autoencoders, are frequently used, while the potential of other models remains widely unexplored. Pertinently, hybrid conventional DL architectures have the capacity to overcome the challenges experienced by conventional models. Considering that capsule architectures may dominate future DL models, this work aimed to compile information for stakeholders involved in the development and use of DL models in the contemporary world.",keywords:["Deep learning","Field","Convolutional neural network","Benchmark","Feature learning"],concepts:["Deep learning","Field","Convolutional neural network","Benchmark","Feature learning"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10462-023-10466-8.pdf",is_oa:!0,n_refs:258,n_refs_in_core:10,degree:24,community:0,deg_w:158,betweenness:.0113,pagerank:.00426,eigenvector:.0167},{id:120,oaid:"W2945526235",doi:"10.1109/access.2020.2976199",title:"Explainable Machine Learning for Scientific Insights and Discoveries",authors:[{name:"Ribana Roscher",institutions:["University of Bonn"]},{name:"Bastian Bohn",institutions:["University of Bonn"]},{name:"Marco F. Duarte",institutions:["University of Massachusetts Amherst"]},{name:"Jochen Garcke",institutions:["University of Bonn","Fraunhofer Institute for Algorithms and Scientific Computing"]}],authorString:"Ribana Roscher; Bastian Bohn; Marco F. Duarte; Jochen Garcke",institutions:["Fraunhofer Institute for Algorithms and Scientific Computing","University of Bonn","University of Massachusetts Amherst"],countries:["DE","US"],year:2020,journal:"IEEE Access",citations:986,abstract:"Machine learning methods have been remarkably successful for a wide range of application areas in the extraction of essential information from data. An exciting and relatively recent development is the uptake of machine learning in the natural sciences, where the major goal is to obtain novel scientific insights and discoveries from observational or simulated data. A prerequisite for obtaining a scientific outcome is domain knowledge, which is needed to gain explainability, but also to enhance scientific consistency. In this article, we review explainable machine learning in view of applications in the natural sciences and discuss three core elements that we identified as relevant in this context: transparency, interpretability, and explainability. With respect to these core elements, we provide a survey of recent scientific works that incorporate machine learning and the way that explainable machine learning is used in combination with domain knowledge from the application areas.",keywords:["Interpretability","Transparency","Context","Consistency","Domain"],concepts:["Interpretability","Transparency","Context","Consistency","Domain"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/8948470/09007737.pdf",is_oa:!0,n_refs:181,n_refs_in_core:7,degree:23,community:4,deg_w:195,betweenness:.0068,pagerank:.00425,eigenvector:.0879},{id:121,oaid:"W3155966371",doi:"10.1109/access.2021.3069646",title:"Plant Disease Detection and Classification by Deep Learning—A Review",authors:[{name:"Lili Li",institutions:["Shanxi Agricultural University"]},{name:"Shujuan Zhang",institutions:["Shanxi Agricultural University"]},{name:"Bin Wang",institutions:["Shanxi Agricultural University"]}],authorString:"Lili Li; Shujuan Zhang; Bin Wang",institutions:["Shanxi Agricultural University"],countries:["CN"],year:2021,journal:"IEEE Access",citations:970,abstract:"Deep learning is a branch of artificial intelligence. In recent years, with the advantages of automatic learning and feature extraction, it has been widely concerned by academic and industrial circles. It has been widely used in image and video processing, voice processing, and natural language processing. At the same time, it has also become a research hotspot in the field of agricultural plant protection, such as plant disease recognition and pest range assessment, etc. The application of deep learning in plant disease recognition can avoid the disadvantages caused by artificial selection of disease spot features, make plant disease feature extraction more objective, and improve the research efficiency and technology transformation speed. This review provides the research progress of deep learning technology in the field of crop leaf disease identification in recent years. In this paper, we present the current trends and challenges for the detection of plant leaf disease using deep learning and advanced imaging techniques. We hope that this work will be a valuable resource for researchers who study the detection of plant diseases and insect pests. At the same time, we also discussed some of the current challenges and problems that need to be resolved.",keywords:["Deep learning","Plant disease","Feature extraction","Biotechnology"],concepts:["Deep learning","Plant disease","Feature extraction"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/9312710/09399342.pdf",is_oa:!0,n_refs:118,n_refs_in_core:7,degree:21,community:3,deg_w:220.5,betweenness:.0048,pagerank:.00575,eigenvector:.0092},{id:122,oaid:"W3101981467",doi:"10.1613/jair.1.12228",title:"A Survey on the Explainability of Supervised Machine Learning",authors:[{name:"Nadia Burkart",institutions:["Fraunhofer Institute of Optronics, System Technologies and Image Exploitation"]},{name:"Marco F. Huber",institutions:["University of Stuttgart","Fraunhofer Institute for Manufacturing Engineering and Automation"]}],authorString:"Nadia Burkart; Marco F. Huber",institutions:["Fraunhofer Institute for Manufacturing Engineering and Automation","Fraunhofer Institute of Optronics, System Technologies and Image Exploitation","University of Stuttgart"],countries:["DE"],year:2021,journal:"Journal of Artificial Intelligence Research",citations:966,abstract:"Predictions obtained by, e.g., artificial neural networks have a high accuracy but humans often perceive the models as black boxes. Insights about the decision making are mostly opaque for humans. Particularly understanding the decision making in highly sensitive areas such as healthcare or finance, is of paramount importance. The decision-making behind the black boxes requires it to be more transparent, accountable, and understandable for humans. This survey paper provides essential definitions, an overview of the different principles and methodologies of explainable Supervised Machine Learning (SML). We conduct a state-of-the-art survey that reviews past and recent explainable SML approaches and classifies them according to the introduced definitions. Finally, we illustrate principles by means of an explanatory case study and discuss important future directions.",keywords:["Supervised learning","Artificial neural network"],concepts:["Supervised learning"],pdf_url:"https://jair.org/index.php/jair/article/download/12228/26647",is_oa:!0,n_refs:323,n_refs_in_core:5,degree:21,community:4,deg_w:401,betweenness:.0011,pagerank:.00781,eigenvector:.1808},{id:123,oaid:"W3130071898",doi:"10.1186/s13007-021-00722-9",title:"Plant diseases and pests detection based on deep learning: a review",authors:[{name:"Jun Liu",institutions:["Weifang University of Science and Technology"]},{name:"Xuewei Wang",institutions:["Weifang University of Science and Technology","Weifang University"]}],authorString:"Jun Liu; Xuewei Wang",institutions:["Weifang University","Weifang University of Science and Technology"],countries:["CN"],year:2021,journal:"Plant Methods",citations:958,abstract:"Plant diseases and pests are important factors determining the yield and quality of plants. Plant diseases and pests identification can be carried out by means of digital image processing. In recent years, deep learning has made breakthroughs in the field of digital image processing, far superior to traditional methods. How to use deep learning technology to study plant diseases and pests identification has become a research issue of great concern to researchers. This review provides a definition of plant diseases and pests detection problem, puts forward a comparison with traditional plant diseases and pests detection methods. According to the difference of network structure, this study outlines the research on plant diseases and pests detection based on deep learning in recent years from three aspects of classification network, detection network and segmentation network, and the advantages and disadvantages of each method are summarized. Common datasets are introduced, and the performance of existing studies is compared. On this basis, this study discusses possible challenges in practical applications of plant diseases and pests detection based on deep learning. In addition, possible solutions and research ideas are proposed for the challenges, and several suggestions are given. Finally, this study gives the analysis and prospect of the future trend of plant diseases and pests detection based on deep learning.",keywords:["Deep learning","Identification","Field","Quality","Segmentation"],concepts:["Deep learning","Identification","Field","Quality","Segmentation"],pdf_url:"https://plantmethods.biomedcentral.com/track/pdf/10.1186/s13007-021-00722-9",is_oa:!0,n_refs:106,n_refs_in_core:6,degree:21,community:3,deg_w:230.5,betweenness:.0063,pagerank:.00603,eigenvector:.0104},{id:124,oaid:"W2530226740",doi:"10.1098/rstb.2016.0007",title:"Active interoceptive inference and the emotional brain",authors:[{name:"Anil K. Seth",institutions:["University of Sussex"]},{name:"Karl Friston",institutions:["Wellcome Centre for Human Neuroimaging","University College London"]}],authorString:"Anil K. Seth; Karl Friston",institutions:["University College London","University of Sussex","Wellcome Centre for Human Neuroimaging"],countries:["GB"],year:2016,journal:"Philosophical Transactions of the Royal Society B Biological Sciences",citations:938,abstract:"We review a recent shift in conceptions of interoception and its relationship to hierarchical inference in the brain. The notion of interoceptive inference means that bodily states are regulated by autonomic reflexes that are enslaved by descending predictions from deep generative models of our internal and external milieu. This re-conceptualization illuminates several issues in cognitive and clinical neuroscience with implications for experiences of selfhood and emotion. We first contextualize interoception in terms of active (Bayesian) inference in the brain, highlighting its enactivist (embodied) aspects. We then consider the key role of uncertainty or precision and how this might translate into neuromodulation. We next examine the implications for understanding the functional anatomy of the emotional brain, surveying recent observations on agranular cortex. Finally, we turn to theoretical issues, namely, the role of interoception in shaping a sense of embodied self and feelings. We will draw links between physiological homoeostasis and allostasis, early cybernetic ideas of predictive control and hierarchical generative models in predictive processing. The explanatory scope of interoceptive inference ranges from explanations for autism and depression, through to consciousness. We offer a brief survey of these exciting developments.This article is part of the themed issue 'Interoception beyond homeostasis: affect, cognition and mental health'.",keywords:["Interoception","Embodied cognition","Cognitive science","Inference","Cognitive psychology","Cognition","Conceptualization"],concepts:["Interoception","Embodied cognition","Cognitive science","Inference","Cognitive psychology","Cognition","Conceptualization"],pdf_url:"https://royalsocietypublishing.org/doi/pdf/10.1098/rstb.2016.0007",is_oa:!0,n_refs:107,n_refs_in_core:3,degree:3,community:6,deg_w:53,betweenness:0,pagerank:.00421,eigenvector:1e-4},{id:125,oaid:"W3023042104",doi:"10.1039/d0cs00098a",title:"QSAR without borders",authors:[{name:"Eugene Muratov",institutions:["University of North Carolina at Chapel Hill","Universidade Federal da Paraíba","Communities In Schools of Orange County"]},{name:"Jürgen Bajorath",institutions:["University of Bonn"]},{name:"Robert P. Sheridan",institutions:["Merck & Co., Inc., Rahway, NJ, USA (United States)"]},{name:"Igor V. Tetko",institutions:["Helmholtz Zentrum München","Institute of Structural and Molecular Biology"]},{name:"Dmitry Filimonov",institutions:["Institute of Biomedical Chemistry"]},{name:"Vladimir Poroikov",institutions:["Institute of Biomedical Chemistry"]},{name:"Tudor I. Oprea",institutions:["University of New Mexico","Novo Nordisk Foundation","New Mexico Cancer Center","University of Gothenburg"]},{name:"Igor I. Baskin",institutions:["Lomonosov Moscow State University","Université de Strasbourg"]},{name:"Alexandre Varnek",institutions:["Université de Strasbourg"]},{name:"Adrián E. Roitberg",institutions:["University of Florida","Gainesville Obstetrics & Gynecology"]},{name:"Olexandr Isayev",institutions:["University of North Carolina at Chapel Hill","Communities In Schools of Orange County"]},{name:"Stefano Curtalolo",institutions:["Duke University","Durham Technical Community College"]},{name:"Denis Fourches",institutions:["North Carolina State University"]},{name:"Yoram Cohen",institutions:["University of California, Los Angeles","Los Angeles City College","University of California System","Sustainability Institute"]},{name:"Alán Aspuru‐Guzik",institutions:["Toronto Public Health","University of Toronto"]},{name:"David A. Winkler",institutions:["University of Nottingham","La Trobe University","Australian Regenerative Medicine Institute","Institute for Molecular Science","CSIRO Manufacturing","Monash University"]},{name:"Dimitris K. Agrafiotis",institutions:["Novartis (Switzerland)","Novartis Institutes for BioMedical Research"]},{name:"Artem Cherkasov",institutions:["University of British Columbia","Vancouver Biotech (Canada)","The Prostate Centre"]},{name:"Alexander Tropsha",institutions:["University of North Carolina at Chapel Hill","Communities In Schools of Orange County"]}],authorString:"Eugene Muratov; Jürgen Bajorath; Robert P. Sheridan; Igor V. Tetko; Dmitry Filimonov; Vladimir Poroikov; Tudor I. Oprea; Igor I. Baskin; Alexandre Varnek; Adrián E. Roitberg; Olexandr Isayev; Stefano Curtalolo et al.",institutions:["Australian Regenerative Medicine Institute","CSIRO Manufacturing","Communities In Schools of Orange County","Duke University","Durham Technical Community College","Gainesville Obstetrics & Gynecology","Helmholtz Zentrum München","Institute for Molecular Science","Institute of Biomedical Chemistry","Institute of Structural and Molecular Biology","La Trobe University","Lomonosov Moscow State University","Los Angeles City College","Merck & Co., Inc., Rahway, NJ, USA (United States)","Monash University","New Mexico Cancer Center","North Carolina State University","Novartis (Switzerland)","Novartis Institutes for BioMedical Research","Novo Nordisk Foundation","Sustainability Institute","The Prostate Centre","Toronto Public Health","Universidade Federal da Paraíba","University of Bonn","University of British Columbia","University of California System","University of California, Los Angeles","University of Florida","University of Gothenburg","University of New Mexico","University of North Carolina at Chapel Hill","University of Nottingham","University of Toronto","Université de Strasbourg","Vancouver Biotech (Canada)"],countries:["AU","BR","CA","CH","DE","DK","FR","GB","JP","RU","SE","US","ZA"],year:2020,journal:"Chemical Society Reviews",citations:864,abstract:"Prediction of chemical bioactivity and physical properties has been one of the most important applications of statistical and more recently, machine learning and artificial intelligence methods in chemical sciences. This field of research, broadly known as quantitative structure-activity relationships (QSAR) modeling, has developed many important algorithms and has found a broad range of applications in physical organic and medicinal chemistry in the past 55+ years. This Perspective summarizes recent technological advances in QSAR modeling but it also highlights the applicability of algorithms, modeling methods, and validation practices developed in QSAR to a wide range of research areas outside of traditional QSAR boundaries including synthesis planning, nanotechnology, materials science, biomaterials, and clinical informatics. As modern research methods generate rapidly increasing amounts of data, the knowledge of robust data-driven modelling methods professed within the QSAR field can become essential for scientists working both within and outside of chemical research. We hope that this contribution highlighting the generalizable components of QSAR modeling will serve to address this challenge.",keywords:["Quantitative structure–activity relationship"],concepts:["Quantitative structure–activity relationship"],pdf_url:"https://pubs.rsc.org/en/content/articlepdf/2020/cs/d0cs00098a",is_oa:!0,n_refs:345,n_refs_in_core:6,degree:20,community:2,deg_w:267,betweenness:.0014,pagerank:.00569,eigenvector:.0876},{id:126,oaid:"W3137125108",doi:"10.1214/21-ss133",title:"Interpretable machine learning: Fundamental principles and 10 grand challenges",authors:[{name:"Cynthia Rudin",institutions:[]},{name:"Chaofan Chen",institutions:[]},{name:"Zhi Chen",institutions:[]},{name:"Haiyang Huang",institutions:[]},{name:"Lesia Semenova",institutions:[]},{name:"Chudi Zhong",institutions:[]}],authorString:"Cynthia Rudin; Chaofan Chen; Zhi Chen; Haiyang Huang; Lesia Semenova; Chudi Zhong",institutions:[],countries:[],year:2022,journal:"Statistics Surveys",citations:863,abstract:"Interpretability in machine learning (ML) is crucial for high stakes decisions and troubleshooting. In this work, we provide fundamental principles for interpretable ML, and dispel common misunderstandings that dilute the importance of this crucial topic. We also identify 10 technical challenge areas in interpretable machine learning and provide history and background on each problem. Some of these problems are classically important, and some are recent problems that have arisen in the last few years. These problems are: (1) Optimizing sparse logical models such as decision trees; (2) Optimization of scoring systems; (3) Placing constraints into generalized additive models to encourage sparsity and better interpretability; (4) Modern case-based reasoning, including neural networks and matching for causal inference; (5) Complete supervised disentanglement of neural networks; (6) Complete or even partial unsupervised disentanglement of neural networks; (7) Dimensionality reduction for data visualization; (8) Machine learning models that can incorporate physics and other generative or causal constraints; (9) Characterization of the “Rashomon set” of good models; and (10) Interpretable reinforcement learning. This survey is suitable as a starting point for statisticians and computer scientists interested in working in interpretable machine learning.",keywords:["Interpretability","Artificial neural network","Troubleshooting","Inference","Dimensionality reduction"],concepts:["Interpretability","Artificial neural network","Troubleshooting","Inference","Dimensionality reduction"],pdf_url:"https://projecteuclid.org/journals/statistics-surveys/volume-16/issue-none/Interpretable-machine-learning-Fundamental-principles-and-10-grand-challenges/10.1214/21-SS133.pdf",is_oa:!0,n_refs:374,n_refs_in_core:4,degree:21,community:4,deg_w:236.5,betweenness:.0078,pagerank:.0054,eigenvector:.0854},{id:127,oaid:"W2982381523",doi:"10.3390/plants8110468",title:"Plant Disease Detection and Classification by Deep Learning",authors:[{name:"Muhammad Hammad Saleem",institutions:["Massey University"]},{name:"Johan Potgieter",institutions:["Massey University"]},{name:"Khalid Mahmood Arif",institutions:["Massey University"]}],authorString:"Muhammad Hammad Saleem; Johan Potgieter; Khalid Mahmood Arif",institutions:["Massey University"],countries:["NZ"],year:2019,journal:"Plants",citations:845,abstract:"Plant diseases affect the growth of their respective species, therefore their early identification is very important. Many Machine Learning (ML) models have been employed for the detection and classification of plant diseases but, after the advancements in a subset of ML, that is, Deep Learning (DL), this area of research appears to have great potential in terms of increased accuracy. Many developed/modified DL architectures are implemented along with several visualization techniques to detect and classify the symptoms of plant diseases. Moreover, several performance metrics are used for the evaluation of these architectures/techniques. This review provides a comprehensive explanation of DL models used to visualize various plant diseases. In addition, some research gaps are identified from which to obtain greater transparency for detecting diseases in plants, even before their symptoms appear clearly.",keywords:["Deep learning","Transparency","Identification","Visualization","Plant disease"],concepts:["Deep learning","Transparency","Identification","Visualization","Plant disease"],pdf_url:"https://www.mdpi.com/2223-7747/8/11/468/pdf?version=1574044728",is_oa:!0,n_refs:119,n_refs_in_core:11,degree:26,community:3,deg_w:301.5,betweenness:.0051,pagerank:.00757,eigenvector:.0128},{id:128,oaid:"W3043426275",doi:"10.1109/mci.2022.3155327",title:"Hands-On Bayesian Neural Networks—A Tutorial for Deep Learning Users",authors:[{name:"Laurent Valentin Jospin",institutions:["The University of Western Australia"]},{name:"Hamid Laga",institutions:["Murdoch University"]},{name:"Farid Boussaïd",institutions:["The University of Western Australia"]},{name:"Wray Buntine",institutions:["Murdoch University"]},{name:"Mohammed Bennamoun",institutions:["The University of Western Australia"]}],authorString:"Laurent Valentin Jospin; Hamid Laga; Farid Boussaïd; Wray Buntine; Mohammed Bennamoun",institutions:["Murdoch University","The University of Western Australia"],countries:["AU"],year:2022,journal:"IEEE Computational Intelligence Magazine",citations:841,abstract:'Modern deep learning methods constitute incredibly powerful tools to tackle a myriad of challenging problems. However, since deep learning methods operate as black boxes, the uncertainty associated with their predictions is often challenging to quantify. Bayesian statistics offer a formalism to understand and quantify the uncertainty associated with deep neural network predictions. This tutorial provides deep learning practitioners with an overview of the relevant literature and a complete toolset to design, implement, train, use and evaluate Bayesian neural networks, <italic xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">i</i> . <italic xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">e</i> ., stochastic artificial neural networks trained using Bayesian methods.',keywords:["Deep learning","Artificial neural network","Deep neural networks","Bayesian probability","Bayesian network"],concepts:["Deep learning","Artificial neural network","Deep neural networks","Bayesian probability","Bayesian network"],pdf_url:"https://arxiv.org/pdf/2007.06823",is_oa:!0,n_refs:208,n_refs_in_core:8,degree:22,community:0,deg_w:124,betweenness:.0058,pagerank:.00372,eigenvector:.0117},{id:129,oaid:"W3089028909",doi:"10.1109/jproc.2021.3052449",title:"A Unifying Review of Deep and Shallow Anomaly Detection",authors:[{name:"Lukas Ruff",institutions:["Technische Universität Berlin"]},{name:"Jacob R. Kauffmann",institutions:["Technische Universität Berlin"]},{name:"Robert A. Vandermeulen",institutions:["Technische Universität Berlin"]},{name:"Gregoire Montavon",institutions:["Technische Universität Berlin"]},{name:"Wojciech Samek",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute"]},{name:"Marius Kloft",institutions:["University of Kaiserslautern"]},{name:"Thomas G. Dietterich",institutions:["Oregon State University"]},{name:"Klaus-Robert Muller",institutions:["Korea University","Max Planck Institute for Informatics","Brain (Germany)","Technische Universität Berlin"]}],authorString:"Lukas Ruff; Jacob R. Kauffmann; Robert A. Vandermeulen; Gregoire Montavon; Wojciech Samek; Marius Kloft; Thomas G. Dietterich; Klaus-Robert Muller",institutions:["Brain (Germany)","Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Korea University","Max Planck Institute for Informatics","Oregon State University","Technische Universität Berlin","University of Kaiserslautern"],countries:["DE","KR","US"],year:2021,journal:"Proceedings of the IEEE",citations:834,abstract:"Deep learning approaches to anomaly detection (AD) have recently improved the state of the art in detection performance on complex data sets, such as large collections of images or text. These results have sparked a renewed interest in the AD problem and led to the introduction of a great variety of new methods. With the emergence of numerous such methods, including approaches based on generative models, one-class classification, and reconstruction, there is a growing need to bring methods of this field into a systematic and unified perspective. In this review, we aim to identify the common underlying principles and the assumptions that are often made implicitly by various methods. In particular, we draw connections between classic “shallow” and novel deep approaches and show how this relation might cross-fertilize or extend both directions. We further provide an empirical assessment of major existing methods that are enriched by the use of recent explainability techniques and present specific worked-through examples together with practical advice. Finally, we outline critical open challenges and identify specific paths for future research in AD.",keywords:["Variety","Deep learning","Field","Generative grammar","Anomaly detection","Relation"],concepts:["Variety","Deep learning","Field","Generative grammar","Anomaly detection","Relation"],pdf_url:"https://ieeexplore.ieee.org/ielx7/5/9420072/09347460.pdf",is_oa:!0,n_refs:530,n_refs_in_core:6,degree:21,community:0,deg_w:246,betweenness:.0072,pagerank:.00554,eigenvector:.0867},{id:130,oaid:"W4365504037",doi:"10.1186/s40537-023-00727-2",title:"A survey on deep learning tools dealing with data scarcity: definitions, challenges, solutions, tips, and applications",authors:[{name:"Laith Alzubaidi",institutions:["Queensland University of Technology"]},{name:"Jinshuai Bai",institutions:["Queensland University of Technology"]},{name:"Aiman Al-Sabaawi",institutions:["Queensland University of Technology"]},{name:"José Santamaría",institutions:["Universidad de Jaén"]},{name:"A. S. Albahri",institutions:["Sultan Idris Education University"]},{name:"Bashar Sami Nayyef Al-dabbagh",institutions:["Universidad Carlos III de Madrid"]},{name:"Mohammed A. Fadhel",institutions:["Thi Qar University","University of Sumer"]},{name:"Mohamed Manoufali",institutions:["The University of Queensland"]},{name:"Jinglan Zhang",institutions:["Queensland University of Technology"]},{name:"Ali H. Al‐Timemy",institutions:["University of Baghdad"]},{name:"Ye Duan",institutions:["University of Missouri"]},{name:"Amjed Abdullah",institutions:["University of Missouri"]},{name:"Laith Farhan",institutions:["Manchester Metropolitan University"]},{name:"Yi Lu",institutions:["Queensland University of Technology"]},{name:"Ashish Gupta",institutions:["Queensland University of Technology"]},{name:"Felix Albu",institutions:["Valahia University of Targoviste"]},{name:"Amin Abbosh",institutions:["The University of Queensland"]},{name:"Yuantong Gu",institutions:["Queensland University of Technology"]}],authorString:"Laith Alzubaidi; Jinshuai Bai; Aiman Al-Sabaawi; José Santamaría; A. S. Albahri; Bashar Sami Nayyef Al-dabbagh; Mohammed A. Fadhel; Mohamed Manoufali; Jinglan Zhang; Ali H. Al‐Timemy; Ye Duan; Amjed Abdullah et al.",institutions:["Manchester Metropolitan University","Queensland University of Technology","Sultan Idris Education University","The University of Queensland","Thi Qar University","Universidad Carlos III de Madrid","Universidad de Jaén","University of Baghdad","University of Missouri","University of Sumer","Valahia University of Targoviste"],countries:["AU","ES","GB","IQ","MY","RO","US"],year:2023,journal:"Journal Of Big Data",citations:818,abstract:"Abstract Data scarcity is a major challenge when training deep learning (DL) models. DL demands a large amount of data to achieve exceptional performance. Unfortunately, many applications have small or inadequate data to train DL frameworks. Usually, manual labeling is needed to provide labeled data, which typically involves human annotators with a vast background of knowledge. This annotation process is costly, time-consuming, and error-prone. Usually, every DL framework is fed by a significant amount of labeled data to automatically learn representations. Ultimately, a larger amount of data would generate a better DL model and its performance is also application dependent. This issue is the main barrier for many applications dismissing the use of DL. Having sufficient data is the first step toward any successful and trustworthy DL application. This paper presents a holistic survey on state-of-the-art techniques to deal with training DL models to overcome three challenges including small, imbalanced datasets, and lack of generalization. This survey starts by listing the learning techniques. Next, the types of DL architectures are introduced. After that, state-of-the-art solutions to address the issue of lack of training data are listed, such as Transfer Learning (TL), Self-Supervised Learning (SSL), Generative Adversarial Networks (GANs), Model Architecture (MA), Physics-Informed Neural Network (PINN), and Deep Synthetic Minority Oversampling Technique (DeepSMOTE). Then, these solutions were followed by some related tips about data acquisition needed prior to training purposes, as well as recommendations for ensuring the trustworthiness of the training dataset. The survey ends with a list of applications that suffer from data scarcity, several alternatives are proposed in order to generate more data in each application including Electromagnetic Imaging (EMI), Civil Structural Health Monitoring, Medical imaging, Meteorology, Wireless Communications, Fluid Mechanics, Microelectromechanical system, and Cybersecurity. To the best of the authors’ knowledge, this is the first review that offers a comprehensive overview on strategies to tackle data scarcity in DL.",keywords:["Deep learning","Generalization","Scarcity","Process","Data science"],concepts:["Deep learning","Generalization","Scarcity","Process","Data science"],pdf_url:"https://journalofbigdata.springeropen.com/counter/pdf/10.1186/s40537-023-00727-2",is_oa:!0,n_refs:561,n_refs_in_core:7,degree:14,community:1,deg_w:98,betweenness:.0036,pagerank:.00306,eigenvector:.0087},{id:131,oaid:"W4309028162",doi:"10.1016/j.array.2022.100258",title:"Data augmentation: A comprehensive survey of modern approaches",authors:[{name:"Alhassan Mumuni",institutions:["Cape Coast Technical University"]},{name:"Fuseini Mumuni",institutions:["University of Mines and Technology"]}],authorString:"Alhassan Mumuni; Fuseini Mumuni",institutions:["Cape Coast Technical University","University of Mines and Technology"],countries:["GH"],year:2022,journal:"Array",citations:817,abstract:"To ensure good performance, modern machine learning models typically require large amounts of quality annotated data. Meanwhile, the data collection and annotation processes are usually performed manually, and consume a lot of time and resources. The quality and representativeness of curated data for a given task is usually dictated by the natural availability of clean data in the particular domain as well as the level of expertise of developers involved. In many real-world application settings it is often not feasible to obtain sufficient training data. Currently, data augmentation is the most effective way of alleviating this problem. The main goal of data augmentation is to increase the volume, quality and diversity of training data. This paper presents an extensive and thorough review of data augmentation methods applicable in computer vision domains. The focus is on more recent and advanced data augmentation techniques. The surveyed methods include deeply learned augmentation strategies as well as feature-level and meta-learning-based data augmentation techniques. Data synthesis approaches based on realistic 3D graphics modeling, neural rendering, and generative adversarial networks are also covered. Different from previous surveys, we cover a more extensive array of modern techniques and applications. We also compare the performance of several state-of-the-art augmentation methods and present a rigorous discussion of the effectiveness of various techniques in different scenarios of use based on performance results on different datasets and tasks.",keywords:["Data quality","Representativeness heuristic","Rendering","Data science","Computer graphics"],concepts:["Data quality","Representativeness heuristic","Rendering","Data science","Computer graphics"],pdf_url:"https://doi.org/10.1016/j.array.2022.100258",is_oa:!0,n_refs:324,n_refs_in_core:8,degree:22,community:1,deg_w:206,betweenness:.0038,pagerank:.00546,eigenvector:.0144},{id:132,oaid:"W2976720228",doi:"10.1016/j.cpc.2019.106949",title:"DScribe: Library of descriptors for machine learning in materials science",authors:[{name:"Lauri Himanen",institutions:["Aalto University"]},{name:"Marc O. J. Jäger",institutions:["Aalto University"]},{name:"Eiaki V. Morooka",institutions:["Aalto University"]},{name:"Filippo Federici Canova",institutions:["Nanolayers","Aalto University"]},{name:"Yashasvi S. Ranawat",institutions:["Aalto University"]},{name:"David Gao",institutions:["Norwegian University of Science and Technology","Nanolayers"]},{name:"Patrick Rinke",institutions:["Technical University of Munich","Aalto University"]},{name:"Adam S. Foster",institutions:["Kanazawa University","Johannes Gutenberg University Mainz","Life Science Institute","Aalto University"]}],authorString:"Lauri Himanen; Marc O. J. Jäger; Eiaki V. Morooka; Filippo Federici Canova; Yashasvi S. Ranawat; David Gao; Patrick Rinke; Adam S. Foster",institutions:["Aalto University","Johannes Gutenberg University Mainz","Kanazawa University","Life Science Institute","Nanolayers","Norwegian University of Science and Technology","Technical University of Munich"],countries:["DE","FI","GB","JP","NO"],year:2019,journal:"Computer Physics Communications",citations:816,abstract:"DScribe is a software package for machine learning that provides popular feature transformations (“descriptors”) for atomistic materials simulations. DScribe accelerates the application of machine learning for atomistic property prediction by providing user-friendly, off-the-shelf descriptor implementations. The package currently contains implementations for Coulomb matrix, Ewald sum matrix, sine matrix, Many-body Tensor Representation (MBTR), Atom-centered Symmetry Function (ACSF) and Smooth Overlap of Atomic Positions (SOAP). Usage of the package is illustrated for two different applications: formation energy prediction for solids and ionic charge prediction for atoms in organic molecules. The package is freely available under the open-source Apache License 2.0. Program Title: DScribe Program Files doi: http://dx.doi.org/10.17632/vzrs8n8pk6.1 Licensing provisions: Apache-2.0 Programming language: Python/C/C++ Supplementary material: Supplementary Information as PDF Nature of problem: The application of machine learning for materials science is hindered by the lack of consistent software implementations for feature transformations. These feature transformations, also called descriptors, are a key step in building machine learning models for property prediction in materials science. Solution method: We have developed a library for creating common descriptors used in machine learning applied to materials science. We provide an implementation the following descriptors: Coulomb matrix, Ewald sum matrix, sine matrix, Many-body Tensor Representation (MBTR), Atom-centered Symmetry Functions (ACSF) and Smooth Overlap of Atomic Positions (SOAP). The library has a python interface with computationally intensive routines written in C or C++. The source code, tutorials and documentation are provided online. A continuous integration mechanism is set up to automatically run a series of regression tests and check code coverage when the codebase is updated.",keywords:["Matrix","Computational science","Matrix multiplication","Tensor","Software","Feature","Implementation"],concepts:["Matrix","Computational science","Matrix multiplication","Tensor","Software","Feature","Implementation"],pdf_url:"https://www.sciencedirect.com/science/article/pii/S0010465519303042?via%3Dihub",is_oa:!0,n_refs:82,n_refs_in_core:6,degree:23,community:2,deg_w:343.5,betweenness:9e-4,pagerank:.00697,eigenvector:.1176},{id:133,oaid:"W4297964528",doi:"10.1109/tnnls.2022.3207346",title:"Deep Reinforcement Learning: A Survey",authors:[{name:"Xu Wang",institutions:["Xidian University"]},{name:"Sen Wang",institutions:["Xidian University"]},{name:"Xingxing Liang",institutions:["National University of Defense Technology"]},{name:"Dawei Zhao",institutions:["National University of Defense Technology"]},{name:"Jincai Huang",institutions:["National University of Defense Technology"]},{name:"Xin Xu",institutions:["National University of Defense Technology"]},{name:"Bin Dai",institutions:["National University of Defense Technology"]},{name:"Qiguang Miao",institutions:["Xidian University"]}],authorString:"Xu Wang; Sen Wang; Xingxing Liang; Dawei Zhao; Jincai Huang; Xin Xu; Bin Dai; Qiguang Miao",institutions:["National University of Defense Technology","Xidian University"],countries:["CN"],year:2022,journal:"IEEE Transactions on Neural Networks and Learning Systems",citations:809,abstract:"Deep reinforcement learning (DRL) integrates the feature representation ability of deep learning with the decision-making ability of reinforcement learning so that it can achieve powerful end-to-end learning control capabilities. In the past decade, DRL has made substantial advances in many tasks that require perceiving high-dimensional input and making optimal or near-optimal decisions. However, there are still many challenging problems in the theory and applications of DRL, especially in learning control tasks with limited samples, sparse rewards, and multiple agents. Researchers have proposed various solutions and new theories to solve these problems and promote the development of DRL. In addition, deep learning has stimulated the further development of many subfields of reinforcement learning, such as hierarchical reinforcement learning (HRL), multiagent reinforcement learning, and imitation learning. This article gives a comprehensive overview of the fundamental theories, key algorithms, and primary research domains of DRL. In addition to value-based and policy-based DRL algorithms, the advances in maximum entropy-based DRL are summarized. The future research topics of DRL are also analyzed and discussed.",keywords:["Reinforcement learning","Imitation"],concepts:["Reinforcement learning","Imitation"],pdf_url:null,is_oa:!1,n_refs:148,n_refs_in_core:6,degree:20,community:0,deg_w:146,betweenness:.0075,pagerank:.00427,eigenvector:.0215},{id:134,oaid:"W2776705292",doi:"10.3390/sym10010011",title:"Identification of Apple Leaf Diseases Based on Deep Convolutional Neural Networks",authors:[{name:"Bin Liu",institutions:["Northwest A&F University"]},{name:"Yun Zhang",institutions:["Northwest A&F University"]},{name:"Dongjian He",institutions:["Northwest A&F University"]},{name:"Yuxiang Li",institutions:["Henan University of Science and Technology"]}],authorString:"Bin Liu; Yun Zhang; Dongjian He; Yuxiang Li",institutions:["Henan University of Science and Technology","Northwest A&F University"],countries:["CN"],year:2017,journal:"Symmetry",citations:791,abstract:"Mosaic, Rust, Brown spot, and Alternaria leaf spot are the four common types of apple leaf diseases. Early diagnosis and accurate identification of apple leaf diseases can control the spread of infection and ensure the healthy development of the apple industry. The existing research uses complex image preprocessing and cannot guarantee high recognition rates for apple leaf diseases. This paper proposes an accurate identifying approach for apple leaf diseases based on deep convolutional neural networks. It includes generating sufficient pathological images and designing a novel architecture of a deep convolutional neural network based on AlexNet to detect apple leaf diseases. Using a dataset of 13,689 images of diseased apple leaves, the proposed deep convolutional neural network model is trained to identify the four common apple leaf diseases. Under the hold-out test set, the experimental results show that the proposed disease identification approach based on the convolutional neural network achieves an overall accuracy of 97.62%, the model parameters are reduced by 51,206,928 compared with those in the standard AlexNet model, and the accuracy of the proposed model with generated pathological images obtains an improvement of 10.83%. This research indicates that the proposed deep learning model provides a better solution in disease control for apple leaf diseases with high accuracy and a faster convergence rate, and that the image generation technique proposed in this paper can enhance the robustness of the convolutional neural network model.",keywords:["Convolutional neural network","Deep learning","Preprocessor","Robustness","Pattern recognition","Identification"],concepts:["Convolutional neural network","Deep learning","Preprocessor","Robustness","Pattern recognition","Identification"],pdf_url:"https://www.mdpi.com/2073-8994/10/1/11/pdf?version=1514560591",is_oa:!0,n_refs:25,n_refs_in_core:5,degree:11,community:3,deg_w:90.5,betweenness:.0011,pagerank:.00293,eigenvector:.0034},{id:135,oaid:"W4206693420",doi:"10.1049/ipr2.12419",title:"Medical image segmentation using deep learning: A survey",authors:[{name:"Risheng Wang",institutions:["Shaanxi University of Science and Technology"]},{name:"Tao Lei",institutions:["Shaanxi University of Science and Technology"]},{name:"Ruixia Cui",institutions:["First Affiliated Hospital of Xi'an Jiaotong University","Xi'an Jiaotong University"]},{name:"Bingtao Zhang",institutions:["Lanzhou Jiaotong University"]},{name:"Hongying Meng",institutions:["Brunel University of London"]},{name:"Asoke K. Nandi",institutions:["Brunel University of London"]}],authorString:"Risheng Wang; Tao Lei; Ruixia Cui; Bingtao Zhang; Hongying Meng; Asoke K. Nandi",institutions:["Brunel University of London","First Affiliated Hospital of Xi'an Jiaotong University","Lanzhou Jiaotong University","Shaanxi University of Science and Technology","Xi'an Jiaotong University"],countries:["CN","GB"],year:2022,journal:"IET Image Processing",citations:789,abstract:"Abstract Deep learning has been widely used for medical image segmentation and a large number of papers has been presented recording the success of deep learning in the field. A comprehensive thematic survey on medical image segmentation using deep learning techniques is presented. This paper makes two original contributions. Firstly, compared to traditional surveys that directly divide literatures of deep learning on medical image segmentation into many groups and introduce literatures in detail for each group, we classify currently popular literatures according to a multi‐level structure from coarse to fine. Secondly, this paper focuses on supervised and weakly supervised learning approaches, without including unsupervised approaches since they have been introduced in many old surveys and they are not popular currently. For supervised learning approaches, we analyse literatures in three aspects: the selection of backbone networks, the design of network blocks, and the improvement of loss functions. For weakly supervised learning approaches, we investigate literature according to data augmentation, transfer learning, and interactive segmentation, separately. Compared to existing surveys, this survey classifies the literatures very differently from before and is more convenient for readers to understand the relevant rationale and will guide them to think of appropriate improvements in medical image segmentation based on deep learning approaches.",keywords:["Image segmentation","Segmentation","Computer vision","Deep learning","Image","Scale-space segmentation"],concepts:["Image segmentation","Segmentation","Computer vision","Deep learning","Image","Scale-space segmentation"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1049/ipr2.12419",is_oa:!0,n_refs:206,n_refs_in_core:8,degree:22,community:1,deg_w:212,betweenness:.0053,pagerank:.00539,eigenvector:.0284},{id:136,oaid:"W2799915630",doi:"10.1038/s41578-018-0005-z",title:"Accelerating the discovery of materials for clean energy in the era of smart automation",authors:[{name:"Daniel P. Tabor",institutions:["Harvard University"]},{name:"Loı̈c M. Roch",institutions:["Harvard University"]},{name:"Semion K. Saikin",institutions:["Harvard University"]},{name:"Christoph Kreisbeck",institutions:["Harvard University"]},{name:"Dennis Sheberla",institutions:["Harvard University"]},{name:"Joseph H. Montoya",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Shyam Dwaraknath",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Muratahan Aykol",institutions:["Toyota Research Institute","Toyota Industries (United States)"]},{name:"C. Ortiz",institutions:["Secretaría de Energía"]},{name:"Hermann Tribukait",institutions:[]},{name:"Carlos Amador‐Bedolla",institutions:["Universidad Nacional Autónoma de México"]},{name:"Christoph J. Brabec",institutions:["Friedrich-Alexander-Universität Erlangen-Nürnberg","Bavarian Center for Applied Energy Research"]},{name:"Benji Maruyama",institutions:["Wright-Patterson Air Force Base"]},{name:"Kristin A. Persson",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"Alán Aspuru‐Guzik",institutions:["Harvard University"]}],authorString:"Daniel P. Tabor; Loı̈c M. Roch; Semion K. Saikin; Christoph Kreisbeck; Dennis Sheberla; Joseph H. Montoya; Shyam Dwaraknath; Muratahan Aykol; C. Ortiz; Hermann Tribukait; Carlos Amador‐Bedolla; Christoph J. Brabec et al.",institutions:["Bavarian Center for Applied Energy Research","Friedrich-Alexander-Universität Erlangen-Nürnberg","Harvard University","Lawrence Berkeley National Laboratory","Secretaría de Energía","Toyota Industries (United States)","Toyota Research Institute","Universidad Nacional Autónoma de México","University of California, Berkeley","Wright-Patterson Air Force Base"],countries:["DE","MX","US"],year:2018,journal:"Nature Reviews Materials",citations:782,abstract:"The discovery and development of novel materials in the field of energy are essential to accelerate the transition to a low-carbon economy. Bringing recent technological innovations in automation, robotics and computer science together with current approaches in chemistry, materials synthesis and characterization will act as a catalyst for revolutionizing traditional research and development in both industry and academia. This Perspective provides a vision for an integrated artificial intelligence approach towards autonomous materials discovery, which, in our opinion, will emerge within the next 5 to 10 years. The approach we discuss requires the integration of the following tools, which have already seen substantial development to date: high-throughput virtual screening, automated synthesis planning, automated laboratories and machine learning algorithms. In addition to reducing the time to deployment of new materials by an order of magnitude, this integrated approach is expected to lower the cost associated with the initial discovery. Thus, the price of the final products (for example, solar panels, batteries and electric vehicles) will also decrease. This in turn will enable industries and governments to meet more ambitious targets in terms of reducing greenhouse gas emissions at a faster pace. The discovery and development of advanced materials are imperative for the clean energy sector. We envision that a closed-loop approach, which combines high-throughput computation, artificial intelligence and advanced robotics, will sizeably reduce the time to deployment and the costs associated with materials development.",keywords:["Software deployment","Pace","Automation","Robotics","Throughput","Manufacturing engineering"],concepts:["Software deployment","Pace","Automation","Robotics","Throughput","Manufacturing engineering"],pdf_url:"https://www.nature.com/articles/s41578-018-0005-z.pdf",is_oa:!0,n_refs:291,n_refs_in_core:5,degree:22,community:2,deg_w:211.5,betweenness:.0022,pagerank:.00492,eigenvector:.0595},{id:137,oaid:"W4310273071",doi:"10.1038/s43246-022-00315-6",title:"Graph neural networks for materials science and chemistry",authors:[{name:"Patrick Reiser",institutions:["Karlsruhe Institute of Technology"]},{name:"Marlen Neubert",institutions:["Karlsruhe Institute of Technology"]},{name:"André Eberhard",institutions:["Karlsruhe Institute of Technology"]},{name:"Luca Torresi",institutions:["Karlsruhe Institute of Technology"]},{name:"Chen Zhou",institutions:["Karlsruhe Institute of Technology"]},{name:"Chen Shao",institutions:["Karlsruhe Institute of Technology"]},{name:"Houssam Metni",institutions:["Karlsruhe Institute of Technology","Université de Strasbourg"]},{name:"Clint van Hoesel",institutions:["Karlsruhe Institute of Technology","Eindhoven University of Technology"]},{name:"Henrik Schopmans",institutions:["Karlsruhe Institute of Technology"]},{name:"Timo Sommer",institutions:["Karlsruhe Institute of Technology","Trinity College Dublin"]},{name:"Pascal Friederich",institutions:["Karlsruhe Institute of Technology"]}],authorString:"Patrick Reiser; Marlen Neubert; André Eberhard; Luca Torresi; Chen Zhou; Chen Shao; Houssam Metni; Clint van Hoesel; Henrik Schopmans; Timo Sommer; Pascal Friederich",institutions:["Eindhoven University of Technology","Karlsruhe Institute of Technology","Trinity College Dublin","Université de Strasbourg"],countries:["DE","FR","IE","NL"],year:2022,journal:"Communications Materials",citations:767,abstract:"Machine learning plays an increasingly important role in many areas of chemistry and materials science, being used to predict materials properties, accelerate simulations, design new structures, and predict synthesis routes of new materials. Graph neural networks (GNNs) are one of the fastest growing classes of machine learning models. They are of particular relevance for chemistry and materials science, as they directly work on a graph or structural representation of molecules and materials and therefore have full access to all relevant information required to characterize materials. In this Review, we provide an overview of the basic principles of GNNs, widely used datasets, and state-of-the-art architectures, followed by a discussion of a wide range of recent applications of GNNs in chemistry and materials science, and concluding with a road-map for the further development and application of GNNs.",keywords:["Graph","Relevance","Representation","Data science","Cheminformatics","Theoretical computer science"],concepts:["Graph","Relevance","Representation","Data science","Cheminformatics","Theoretical computer science"],pdf_url:"https://www.nature.com/articles/s43246-022-00315-6.pdf",is_oa:!0,n_refs:255,n_refs_in_core:16,degree:30,community:2,deg_w:386,betweenness:.0083,pagerank:.00781,eigenvector:.1608},{id:138,oaid:"W2898197178",doi:"10.1002/mp.13264",title:"Deep learning in medical imaging and radiation therapy",authors:[{name:"Berkman Sahiner",institutions:["United States Food and Drug Administration"]},{name:"Aria Pezeshk",institutions:["United States Food and Drug Administration"]},{name:"Lubomir M. Hadjiiski",institutions:["University of Michigan"]},{name:"Xiaosong Wang",institutions:["National Institutes of Health Clinical Center"]},{name:"Karen Drukker",institutions:["University of Chicago"]},{name:"Kenny H. Cha",institutions:["United States Food and Drug Administration"]},{name:"Ronald M. Summers",institutions:["National Institutes of Health Clinical Center"]},{name:"Maryellen L. Giger",institutions:["University of Chicago"]}],authorString:"Berkman Sahiner; Aria Pezeshk; Lubomir M. Hadjiiski; Xiaosong Wang; Karen Drukker; Kenny H. Cha; Ronald M. Summers; Maryellen L. Giger",institutions:["National Institutes of Health Clinical Center","United States Food and Drug Administration","University of Chicago","University of Michigan"],countries:["US"],year:2018,journal:"Medical Physics",citations:748,abstract:"The goals of this review paper on deep learning (DL) in medical imaging and radiation therapy are to (a) summarize what has been achieved to date; (b) identify common and unique challenges, and strategies that researchers have taken to address these challenges; and (c) identify some of the promising avenues for the future both in terms of applications as well as technical innovations. We introduce the general principles of DL and convolutional neural networks, survey five major areas of application of DL in medical imaging and radiation therapy, identify common themes, discuss methods for dataset expansion, and conclude by summarizing lessons learned, remaining challenges, and future directions.",keywords:["Medical imaging","Medical radiation","Medical physicist","Deep learning","Medical physics","Radiation therapy","Convolutional neural network"],concepts:["Medical imaging","Medical radiation","Medical physicist","Deep learning","Medical physics","Radiation therapy","Convolutional neural network"],pdf_url:"https://aapm.onlinelibrary.wiley.com/doi/pdfdirect/10.1002/mp.13264",is_oa:!0,n_refs:413,n_refs_in_core:10,degree:25,community:1,deg_w:390,betweenness:.0049,pagerank:.00889,eigenvector:.0501},{id:139,oaid:"W2998957378",doi:"10.3390/app10020559",title:"A Novel Transfer Learning Based Approach for Pneumonia Detection in Chest X-ray Images",authors:[{name:"V. S. Chouhan",institutions:["Lovely Professional University"]},{name:"Sanjay Kumar Singh",institutions:["Lovely Professional University"]},{name:"Aditya Khamparia",institutions:["Lovely Professional University"]},{name:"Deepak Gupta",institutions:[]},{name:"Prayag Tiwari",institutions:["University of Padua"]},{name:"Catarina Moreira",institutions:["Queensland University of Technology"]},{name:"Robertas Damaševičius",institutions:["Silesian University of Technology"]},{name:"Victor Hugo C. de Albuquerque",institutions:["Universidade de Fortaleza"]}],authorString:"V. S. Chouhan; Sanjay Kumar Singh; Aditya Khamparia; Deepak Gupta; Prayag Tiwari; Catarina Moreira; Robertas Damaševičius; Victor Hugo C. de Albuquerque",institutions:["Lovely Professional University","Queensland University of Technology","Silesian University of Technology","Universidade de Fortaleza","University of Padua"],countries:["AU","BR","IN","IT","PL"],year:2020,journal:"Applied Sciences",citations:745,abstract:"Pneumonia is among the top diseases which cause most of the deaths all over the world. Virus, bacteria and fungi can all cause pneumonia. However, it is difficult to judge the pneumonia just by looking at chest X-rays. The aim of this study is to simplify the pneumonia detection process for experts as well as for novices. We suggest a novel deep learning framework for the detection of pneumonia using the concept of transfer learning. In this approach, features from images are extracted using different neural network models pretrained on ImageNet, which then are fed into a classifier for prediction. We prepared five different models and analyzed their performance. Thereafter, we proposed an ensemble model that combines outputs from all pretrained models, which outperformed individual models, reaching the state-of-the-art performance in pneumonia recognition. Our ensemble model reached an accuracy of 96.4% with a recall of 99.62% on unseen data from the Guangzhou Women and Children’s Medical Center dataset.",keywords:["Transfer of learning","Pneumonia","Deep learning","Classifier","Recall"],concepts:["Transfer of learning","Pneumonia","Deep learning","Classifier","Recall"],pdf_url:"https://www.mdpi.com/2076-3417/10/2/559/pdf?version=1578825619",is_oa:!0,n_refs:62,n_refs_in_core:4,degree:20,community:1,deg_w:138,betweenness:.0033,pagerank:.00374,eigenvector:.013},{id:140,oaid:"W2733343268",doi:"10.1155/2017/2917536",title:"Automatic Image-Based Plant Disease Severity Estimation Using Deep Learning",authors:[{name:"Guan Wang",institutions:["Beijing Forestry University"]},{name:"Yu Sun",institutions:["Beijing Forestry University"]},{name:"Jianxin Wang",institutions:["Beijing Forestry University"]}],authorString:"Guan Wang; Yu Sun; Jianxin Wang",institutions:["Beijing Forestry University"],countries:["CN"],year:2017,journal:"Computational Intelligence and Neuroscience",citations:739,abstract:"Automatic and accurate estimation of disease severity is essential for food security, disease management, and yield loss prediction. Deep learning, the latest breakthrough in computer vision, is promising for fine-grained disease severity classification, as the method avoids the labor-intensive feature engineering and threshold-based segmentation. Using the apple black rot images in the PlantVillage dataset, which are further annotated by botanists with four severity stages as ground truth, a series of deep convolutional neural networks are trained to diagnose the severity of the disease. The performances of shallow networks trained from scratch and deep models fine-tuned by transfer learning are evaluated systemically in this paper. The best model is the deep VGG16 model trained with transfer learning, which yields an overall accuracy of 90.4% on the hold-out test set. The proposed deep learning model may have great potential in disease control for modern agriculture.",keywords:["Deep learning","Transfer of learning","Convolutional neural network","Feature engineering","Feature"],concepts:["Deep learning","Transfer of learning","Convolutional neural network","Feature engineering","Feature"],pdf_url:"http://downloads.hindawi.com/journals/cin/2017/2917536.pdf",is_oa:!0,n_refs:22,n_refs_in_core:2,degree:9,community:3,deg_w:63,betweenness:0,pagerank:.00231,eigenvector:.0014},{id:141,oaid:"W2791006446",doi:"10.1109/tgrs.2018.2805286",title:"Generative Adversarial Networks for Hyperspectral Image Classification",authors:[{name:"Lin Zhu",institutions:["Harbin Institute of Technology"]},{name:"Yushi Chen",institutions:["Harbin Institute of Technology"]},{name:"Pedram Ghamisi",institutions:["Technical University of Munich"]},{name:"Jón Atli Benediktsson",institutions:["University of Iceland"]}],authorString:"Lin Zhu; Yushi Chen; Pedram Ghamisi; Jón Atli Benediktsson",institutions:["Harbin Institute of Technology","Technical University of Munich","University of Iceland"],countries:["CN","DE","IS"],year:2018,journal:"IEEE Transactions on Geoscience and Remote Sensing",citations:723,abstract:"A generative adversarial network (GAN) usually contains a generative network and a discriminative network in competition with each other. The GAN has shown its capability in a variety of applications. In this paper, the usefulness and effectiveness of GAN for classification of hyperspectral images (HSIs) are explored for the first time. In the proposed GAN, a convolutional neural network (CNN) is designed to discriminate the inputs and another CNN is used to generate so-called fake inputs. The aforementioned CNNs are trained together: the generative CNN tries to generate fake inputs that are as real as possible, and the discriminative CNN tries to classify the real and fake inputs. This kind of adversarial training improves the generalization capability of the discriminative CNN, which is really important when the training samples are limited. Specifically, we propose two schemes: 1) a well-designed 1D-GAN as a spectral classifier and 2) a robust 3D-GAN as a spectral-spatial classifier. Furthermore, the generated adversarial samples are used with real training samples to fine-tune the discriminative CNN, which improves the final classification performance. The proposed classifiers are carried out on three widely used hyperspectral data sets: Salinas, Indiana Pines, and Kennedy Space Center. The obtained results reveal that the proposed models provide competitive results compared to the state-of-the-art methods. In addition, the proposed GANs open new opportunities in the remote sensing community for the challenging task of HSI classification and also reveal the huge potential of GAN-based methods for the analysis of such complex and inherently nonlinear data.",keywords:["Discriminative model","Classifier","Hyperspectral imaging","Pattern recognition","Convolutional neural network","Generative grammar"],concepts:["Discriminative model","Classifier","Hyperspectral imaging","Pattern recognition","Convolutional neural network","Generative grammar"],pdf_url:null,is_oa:!1,n_refs:58,n_refs_in_core:6,degree:23,community:3,deg_w:209.5,betweenness:.0043,pagerank:.00534,eigenvector:.0125},{id:142,oaid:"W3135096391",doi:"10.1016/j.ejmp.2021.02.006",title:"AI applications to medical images: From machine learning to deep learning",authors:[{name:"Isabella Castiglioni",institutions:["National Research Council","University of Milano-Bicocca"]},{name:"Leonardo Rundo",institutions:["University of Cambridge","Cancer Research UK","Cancer Research UK Cambridge Center"]},{name:"Marina Codari",institutions:["Stanford University"]},{name:"Giovanni Di Leo",institutions:["IRCCS Policlinico San Donato"]},{name:"Christian Salvatore",institutions:["Istituto Universitario di Studi Superiori di Pavia"]},{name:"Matteo Interlenghi",institutions:["CE Technologies (United Kingdom)"]},{name:"Francesca Gallivanone",institutions:["Institute of Molecular Bioimaging and Physiology","National Research Council"]},{name:"Andrea Cozzi",institutions:["University of Milan"]},{name:"Natascha Claudia D’Amico",institutions:["Università Campus Bio-Medico","Centro Diagnostico Italiano"]},{name:"Francesco Sardanelli",institutions:["University of Milan","IRCCS Policlinico San Donato"]}],authorString:"Isabella Castiglioni; Leonardo Rundo; Marina Codari; Giovanni Di Leo; Christian Salvatore; Matteo Interlenghi; Francesca Gallivanone; Andrea Cozzi; Natascha Claudia D’Amico; Francesco Sardanelli",institutions:["CE Technologies (United Kingdom)","Cancer Research UK","Cancer Research UK Cambridge Center","Centro Diagnostico Italiano","IRCCS Policlinico San Donato","Institute of Molecular Bioimaging and Physiology","Istituto Universitario di Studi Superiori di Pavia","National Research Council","Stanford University","University of Cambridge","University of Milan","University of Milano-Bicocca","Università Campus Bio-Medico"],countries:["GB","IT","US"],year:2021,journal:"Physica Medica",citations:712,abstract:"PURPOSE: Artificial intelligence (AI) models are playing an increasing role in biomedical research and healthcare services. This review focuses on challenges points to be clarified about how to develop AI applications as clinical decision support systems in the real-world context. METHODS: A narrative review has been performed including a critical assessment of articles published between 1989 and 2021 that guided challenging sections. RESULTS: We first illustrate the architectural characteristics of machine learning (ML)/radiomics and deep learning (DL) approaches. For ML/radiomics, the phases of feature selection and of training, validation, and testing are described. DL models are presented as multi-layered artificial/convolutional neural networks, allowing us to directly process images. The data curation section includes technical steps such as image labelling, image annotation (with segmentation as a crucial step in radiomics), data harmonization (enabling compensation for differences in imaging protocols that typically generate noise in non-AI imaging studies) and federated learning. Thereafter, we dedicate specific sections to: sample size calculation, considering multiple testing in AI approaches; procedures for data augmentation to work with limited and unbalanced datasets; and the interpretability of AI models (the so-called black box issue). Pros and cons for choosing ML versus DL to implement AI applications to medical imaging are finally presented in a synoptic way. CONCLUSIONS: Biomedicine and healthcare systems are one of the most important fields for AI applications and medical imaging is probably the most suitable and promising domain. Clarification of specific challenging points facilitates the development of such systems and their translation to clinical practice.",keywords:["Interpretability","Deep learning","Convolutional neural network","Context","Medical imaging"],concepts:["Interpretability","Deep learning","Convolutional neural network","Context","Medical imaging"],pdf_url:"http://www.physicamedica.com/article/S1120179721000946/pdf",is_oa:!0,n_refs:208,n_refs_in_core:8,degree:22,community:4,deg_w:183,betweenness:.0066,pagerank:.00436,eigenvector:.0423},{id:143,oaid:"W3212512279",doi:"10.1038/s41524-021-00650-1",title:"Atomistic Line Graph Neural Network for improved materials property predictions",authors:[{name:"Kamal Choudhary",institutions:["National Institute of Standards and Technology","Theiss Research","National Labor College","Material Measurement Laboratory"]},{name:"Brian DeCost",institutions:["National Institute of Standards and Technology","Material Measurement Laboratory"]}],authorString:"Kamal Choudhary; Brian DeCost",institutions:["Material Measurement Laboratory","National Institute of Standards and Technology","National Labor College","Theiss Research"],countries:["US"],year:2021,journal:"npj Computational Materials",citations:708,abstract:"Abstract Graph neural networks (GNN) have been shown to provide substantial performance improvements for atomistic material representation and modeling compared with descriptor-based machine learning models. While most existing GNN models for atomistic predictions are based on atomic distance information, they do not explicitly incorporate bond angles, which are critical for distinguishing many atomic structures. Furthermore, many material properties are known to be sensitive to slight changes in bond angles. We present an Atomistic Line Graph Neural Network (ALIGNN), a GNN architecture that performs message passing on both the interatomic bond graph and its line graph corresponding to bond angles. We demonstrate that angle information can be explicitly and efficiently included, leading to improved performance on multiple atomistic prediction tasks. We ALIGNN models for predicting 52 solid-state and molecular properties available in the JARVIS-DFT, Materials project, and QM9 databases. ALIGNN can outperform some previously reported GNN models on atomistic prediction tasks with better or comparable model training speed.",keywords:["Artificial neural network","Graph","Bond graph","Representation","Line","Theoretical computer science","Property"],concepts:["Artificial neural network","Graph","Bond graph","Representation","Line","Theoretical computer science","Property"],pdf_url:"https://www.nature.com/articles/s41524-021-00650-1.pdf",is_oa:!0,n_refs:74,n_refs_in_core:8,degree:24,community:2,deg_w:237,betweenness:.0026,pagerank:.00498,eigenvector:.1048},{id:144,oaid:"W3046296398",doi:"10.1371/journal.pone.0254841",title:"An empirical survey of data augmentation for time series classification with neural networks",authors:[{name:"Brian Kenji Iwana",institutions:["Kyushu University"]},{name:"Seiichi Uchida",institutions:["Kyushu University"]}],authorString:"Brian Kenji Iwana; Seiichi Uchida",institutions:["Kyushu University"],countries:["JP"],year:2021,journal:"PLoS ONE",citations:680,abstract:"In recent times, deep artificial neural networks have achieved many successes in pattern recognition. Part of this success can be attributed to the reliance on big data to increase generalization. However, in the field of time series recognition, many datasets are often very small. One method of addressing this problem is through the use of data augmentation. In this paper, we survey data augmentation techniques for time series and their application to time series classification with neural networks. We propose a taxonomy and outline the four families in time series data augmentation, including transformation-based methods, pattern mixing, generative models, and decomposition methods. Furthermore, we empirically evaluate 12 time series data augmentation methods on 128 time series classification datasets with six different types of neural networks. Through the results, we are able to analyze the characteristics, advantages and disadvantages, and recommendations of each data augmentation method. This survey aims to help in the selection of time series data augmentation for neural network applications.",keywords:["Artificial neural network","Time series","Series","Data mining","Field"],concepts:["Artificial neural network","Time series","Series","Data mining","Field"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0254841&type=printable",is_oa:!0,n_refs:127,n_refs_in_core:6,degree:20,community:1,deg_w:139,betweenness:.0023,pagerank:.00381,eigenvector:.0104},{id:145,oaid:"W2952020389",doi:"10.1017/s0962492919000059",title:"Solving inverse problems using data-driven models",authors:[{name:"Simon Arridge",institutions:["University College London"]},{name:"Peter Maaß",institutions:["University of Bremen"]},{name:"Ozan Öktem",institutions:["KTH Royal Institute of Technology"]},{name:"Carola‐Bibiane Schönlieb",institutions:["University of Cambridge"]}],authorString:"Simon Arridge; Peter Maaß; Ozan Öktem; Carola‐Bibiane Schönlieb",institutions:["KTH Royal Institute of Technology","University College London","University of Bremen","University of Cambridge"],countries:["DE","GB","SE"],year:2019,journal:"Acta Numerica",citations:677,abstract:"Recent research in inverse problems seeks to develop a mathematically coherent foundation for combining data-driven models, and in particular those based on deep learning, with domain-specific knowledge contained in physical–analytical models. The focus is on solving ill-posed inverse problems that are at the core of many challenging applications in the natural sciences, medicine and life sciences, as well as in engineering and industrial applications. This survey paper aims to give an account of some of the main contributions in data-driven inverse problems.",keywords:["Inverse problem","Inverse","Focus","Domain","Data science","Natural science","Management science"],concepts:["Inverse problem","Inverse","Focus","Domain","Data science","Natural science","Management science"],pdf_url:"https://www.cambridge.org/core/services/aop-cambridge-core/content/view/CE5B3725869AEAF46E04874115B0AB15/S0962492919000059a.pdf/div-class-title-solving-inverse-problems-using-data-driven-models-div.pdf",is_oa:!0,n_refs:540,n_refs_in_core:6,degree:15,community:1,deg_w:96,betweenness:.01,pagerank:.00325,eigenvector:.0069},{id:146,oaid:"W3044960932",doi:"10.1007/s10462-021-10039-7",title:"Artificial intelligence in the creative industries: a review",authors:[{name:"Nantheera Anantrasirichai",institutions:["University of Bristol"]},{name:"David Bull",institutions:["University of Bristol"]}],authorString:"Nantheera Anantrasirichai; David Bull",institutions:["University of Bristol"],countries:["GB"],year:2021,journal:"Artificial Intelligence Review",citations:676,abstract:"Abstract This paper reviews the current state of the art in artificial intelligence (AI) technologies and applications in the context of the creative industries. A brief background of AI, and specifically machine learning (ML) algorithms, is provided including convolutional neural networks (CNNs), generative adversarial networks (GANs), recurrent neural networks (RNNs) and deep Reinforcement Learning (DRL). We categorize creative applications into five groups, related to how AI technologies are used: (i) content creation, (ii) information analysis, (iii) content enhancement and post production workflows, (iv) information extraction and enhancement, and (v) data compression. We critically examine the successes and limitations of this rapidly advancing technology in each of these areas. We further differentiate between the use of AI as a creative tool and its potential as a creator in its own right. We foresee that, in the near future, ML-based AI will be adopted widely as a tool or collaborative assistant for creativity. In contrast, we observe that the successes of ML in domains with fewer constraints, where AI is the ‘creator’, remain modest. The potential of AI (or its developers) to win awards for its original creations in competition with human creatives is also limited, based on contemporary technologies. We therefore conclude that, in the context of creative industries, maximum benefit from AI will be derived where its focus is human-centric—where it is designed to augment, rather than replace, human creativity.",keywords:["Context","Categorization","Generative grammar","Applications of artificial intelligence","Creativity","Deep learning","Focus","Reinforcement learning"],concepts:["Context","Categorization","Generative grammar","Applications of artificial intelligence","Creativity","Deep learning"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10462-021-10039-7.pdf",is_oa:!0,n_refs:331,n_refs_in_core:8,degree:22,community:1,deg_w:172,betweenness:.0047,pagerank:.00457,eigenvector:.0144},{id:147,oaid:"W3030790048",doi:"10.1109/jbhi.2020.2991043",title:"AI in Medical Imaging Informatics: Current Challenges and Future Directions",authors:[{name:"Andreas S. Panayides",institutions:["University of Cyprus"]},{name:"Amir A. Amini",institutions:["University of Louisville"]},{name:"Nenad Filipović",institutions:["University of Kragujevac"]},{name:"Ashish Sharma",institutions:["Emory University"]},{name:"Sotirios A. Tsaftaris",institutions:["The Alan Turing Institute","University of Edinburgh"]},{name:"Alistair A. Young",institutions:["University of Auckland"]},{name:"David J. Foran",institutions:["Rutgers, The State University of New Jersey"]},{name:"Nhan Do",institutions:["United States Department of Veterans Affairs","VA Boston Healthcare System"]},{name:"Spyretta Golemati",institutions:["National and Kapodistrian University of Athens"]},{name:"Tahsin Kurç",institutions:["Stony Brook University"]},{name:"Kun Huang",institutions:["Regenstrief Institute","Indiana University"]},{name:"Konstantina S. Nikita",institutions:["National Technical University of Athens"]},{name:"Ben P. Veasey",institutions:["University of Louisville"]},{name:"Michalis Zervakis",institutions:["Technical University of Crete"]},{name:"Joel Saltz",institutions:["Stony Brook University"]},{name:"Constantinos S. Pattichis",institutions:["University of Cyprus","Citard Services (Cyprus)"]}],authorString:"Andreas S. Panayides; Amir A. Amini; Nenad Filipović; Ashish Sharma; Sotirios A. Tsaftaris; Alistair A. Young; David J. Foran; Nhan Do; Spyretta Golemati; Tahsin Kurç; Kun Huang; Konstantina S. Nikita et al.",institutions:["Citard Services (Cyprus)","Emory University","Indiana University","National Technical University of Athens","National and Kapodistrian University of Athens","Regenstrief Institute","Rutgers, The State University of New Jersey","Stony Brook University","Technical University of Crete","The Alan Turing Institute","United States Department of Veterans Affairs","University of Auckland","University of Cyprus","University of Edinburgh","University of Kragujevac","University of Louisville","VA Boston Healthcare System"],countries:["CY","GB","GR","NZ","RS","US"],year:2020,journal:"IEEE Journal of Biomedical and Health Informatics",citations:675,abstract:"This paper reviews state-of-the-art research solutions across the spectrum of medical imaging informatics, discusses clinical translation, and provides future directions for advancing clinical practice. More specifically, it summarizes advances in medical imaging acquisition technologies for different modalities, highlighting the necessity for efficient medical data management strategies in the context of AI in big healthcare data analytics. It then provides a synopsis of contemporary and emerging algorithmic methods for disease classification and organ/ tissue segmentation, focusing on AI and deep learning architectures that have already become the de facto approach. The clinical benefits of in-silico modelling advances linked with evolving 3D reconstruction and visualization applications are further documented. Concluding, integrative analytics approaches driven by associate research branches highlighted in this study promise to revolutionize imaging informatics as known today across the healthcare continuum for both radiology and digital pathology applications. The latter, is projected to enable informed, more accurate diagnosis, timely prognosis, and effective treatment planning, underpinning precision medicine.",keywords:["Data science","Big data","Health informatics","Informatics","Medical imaging","Health care","Context"],concepts:["Data science","Big data","Health informatics","Informatics","Medical imaging","Health care","Context"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6221020/9130988/09103969.pdf",is_oa:!0,n_refs:295,n_refs_in_core:6,degree:21,community:1,deg_w:267,betweenness:.0032,pagerank:.00615,eigenvector:.0539},{id:148,oaid:"W2972219719",doi:"10.1002/advs.201900808",title:"Data‐Driven Materials Science: Status, Challenges, and Perspectives",authors:[{name:"Lauri Himanen",institutions:["Aalto University"]},{name:"Amber Geurts",institutions:["Netherlands Organisation for Applied Scientific Research","Aalto University"]},{name:"Adam Stuart Foster",institutions:["Kanazawa University","Life Science Institute","Aalto University"]},{name:"Patrick Rinke",institutions:["Technical University of Munich","Aalto University"]}],authorString:"Lauri Himanen; Amber Geurts; Adam Stuart Foster; Patrick Rinke",institutions:["Aalto University","Kanazawa University","Life Science Institute","Netherlands Organisation for Applied Scientific Research","Technical University of Munich"],countries:["DE","FI","JP","NL"],year:2019,journal:"Advanced Science",citations:673,abstract:"Data-driven science is heralded as a new paradigm in materials science. In this field, data is the new resource, and knowledge is extracted from materials datasets that are too big or complex for traditional human reasoning-typically with the intent to discover new or improved materials or materials phenomena. Multiple factors, including the open science movement, national funding, and progress in information technology, have fueled its development. Such related tools as materials databases, machine learning, and high-throughput methods are now established as parts of the materials research toolset. However, there are a variety of challenges that impede progress in data-driven materials science: data veracity, integration of experimental and computational data, data longevity, standardization, and the gap between industrial interests and academic efforts. In this perspective article, the historical development and current state of data-driven materials science, building from the early evolution of open science to the rapid expansion of materials data infrastructures are discussed. Key successes and challenges so far are also reviewed, providing a perspective on the future development of the field.",keywords:["Variety","Big data","Perspective","Key","State"],concepts:["Variety","Big data","Data science","Perspective","Key","State","Nanotechnology"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/advs.201900808",is_oa:!0,n_refs:193,n_refs_in_core:5,degree:21,community:2,deg_w:334.5,betweenness:.0013,pagerank:.00691,eigenvector:.1171},{id:149,oaid:"W2792724009",doi:"10.1109/tnnls.2018.2789927",title:"Learning Temporal Information for Brain-Computer Interface Using Convolutional Neural Networks",authors:[{name:"Siavash Sakhavi",institutions:["National University of Singapore"]},{name:"Cuntai Guan",institutions:["Agency for Science, Technology and Research"]},{name:"Shuicheng Yan",institutions:["National University of Singapore"]}],authorString:"Siavash Sakhavi; Cuntai Guan; Shuicheng Yan",institutions:["Agency for Science, Technology and Research","National University of Singapore"],countries:["SG"],year:2018,journal:"IEEE Transactions on Neural Networks and Learning Systems",citations:660,abstract:"Deep learning (DL) methods and architectures have been the state-of-the-art classification algorithms for computer vision and natural language processing problems. However, the successful application of these methods in motor imagery (MI) brain-computer interfaces (BCIs), in order to boost classification performance, is still limited. In this paper, we propose a classification framework for MI data by introducing a new temporal representation of the data and also utilizing a convolutional neural network (CNN) architecture for classification. The new representation is generated from modifying the filter-bank common spatial patterns method, and the CNN is designed and optimized accordingly for the representation. Our framework outperforms the best classification method in the literature on the BCI competition IV-2a 4-class MI data set by 7% increase in average subject accuracy. Furthermore, by studying the convolutional weights of the trained networks, we gain an insight into the temporal characteristics of EEG.",keywords:["Brain–computer interface","Convolutional neural network","Representation","Pattern recognition","Data set","Set"],concepts:["Brain–computer interface","Convolutional neural network","Representation","Pattern recognition","Data set","Set"],pdf_url:"https://dr.ntu.edu.sg/bitstream/10356/87699/1/Learning%20Temporal%20Information%20for%20Brain-Computer%20Interface%20Using%20Convolutional%20Neural%20Networks%20.pdf",is_oa:!0,n_refs:61,n_refs_in_core:6,degree:20,community:0,deg_w:125,betweenness:.0025,pagerank:.00351,eigenvector:.0126},{id:150,oaid:"W3158818505",doi:"10.1109/tnsre.2021.3076234",title:"An Attention-Based Deep Learning Approach for Sleep Stage Classification With Single-Channel EEG",authors:[{name:"Emadeldeen Eldele",institutions:["Nanyang Technological University"]},{name:"Zhenghua Chen",institutions:["Agency for Science, Technology and Research","Institute for Infocomm Research"]},{name:"Chengyu Liu",institutions:["Southeast University"]},{name:"Min Wu",institutions:["Agency for Science, Technology and Research","Institute for Infocomm Research"]},{name:"Chee Keong Kwoh",institutions:["Nanyang Technological University"]},{name:"Xiaoli Li",institutions:["Agency for Science, Technology and Research","Institute for Infocomm Research"]},{name:"Cuntai Guan",institutions:["Nanyang Technological University"]}],authorString:"Emadeldeen Eldele; Zhenghua Chen; Chengyu Liu; Min Wu; Chee Keong Kwoh; Xiaoli Li; Cuntai Guan",institutions:["Agency for Science, Technology and Research","Institute for Infocomm Research","Nanyang Technological University","Southeast University"],countries:["CN","SG"],year:2021,journal:"IEEE Transactions on Neural Systems and Rehabilitation Engineering",citations:651,abstract:"Automatic sleep stage mymargin classification is of great importance to measure sleep quality. In this paper, we propose a novel attention-based deep learning architecture called AttnSleep to classify sleep stages using single channel EEG signals. This architecture starts with the feature extraction module based on multi-resolution convolutional neural network (MRCNN) and adaptive feature recalibration (AFR). The MRCNN can extract low and high frequency features and the AFR is able to improve the quality of the extracted features by modeling the inter-dependencies between the features. The second module is the temporal context encoder (TCE) that leverages a multi-head attention mechanism to capture the temporal dependencies among the extracted features. Particularly, the multi-head attention deploys causal convolutions to model the temporal relations in the input features. We evaluate the performance of our proposed AttnSleep model using three public datasets. The results show that our AttnSleep outperforms state-of-the-art techniques in terms of different evaluation metrics. Our source codes, experimental data, and supplementary materials are available at https://github.com/emadeldeen24/AttnSleep.",keywords:["Electroencephalography","Sleep","Channel","Sleep Stages","Stage"],concepts:["Electroencephalography","Sleep","Channel","Sleep Stages","Stage"],pdf_url:"https://ieeexplore.ieee.org/ielx7/7333/9363468/09417097.pdf",is_oa:!0,n_refs:53,n_refs_in_core:6,degree:13,community:0,deg_w:74,betweenness:.001,pagerank:.00274,eigenvector:.0022},{id:151,oaid:"W4319162181",doi:"10.1038/s41467-023-36329-y",title:"Learning local equivariant representations for large-scale atomistic dynamics",authors:[{name:"Albert Musaelian",institutions:["Harvard University Press"]},{name:"Simon Batzner",institutions:["Harvard University Press"]},{name:"Anders Johansson",institutions:["Harvard University Press"]},{name:"Lixin Sun",institutions:["Harvard University Press"]},{name:"Cameron J. Owen",institutions:["Harvard University Press"]},{name:"Mordechai Kornbluth",institutions:["Robert Bosch (United States)"]},{name:"Boris Kozinsky",institutions:["Harvard University Press","Robert Bosch (United States)","Robert Bosch (Slovenia)"]}],authorString:"Albert Musaelian; Simon Batzner; Anders Johansson; Lixin Sun; Cameron J. Owen; Mordechai Kornbluth; Boris Kozinsky",institutions:["Harvard University Press","Robert Bosch (Slovenia)","Robert Bosch (United States)"],countries:["SI","US"],year:2023,journal:"Nature Communications",citations:642,abstract:"A simultaneously accurate and computationally efficient parametrization of the potential energy surface of molecules and materials is a long-standing goal in the natural sciences. While atom-centered message passing neural networks (MPNNs) have shown remarkable accuracy, their information propagation has limited the accessible length-scales. Local methods, conversely, scale to large simulations but have suffered from inferior accuracy. This work introduces Allegro, a strictly local equivariant deep neural network interatomic potential architecture that simultaneously exhibits excellent accuracy and scalability. Allegro represents a many-body potential using iterated tensor products of learned equivariant representations without atom-centered message passing. Allegro obtains improvements over state-of-the-art methods on QM9 and revMD17. A single tensor product layer outperforms existing deep MPNNs and transformers on QM9. Furthermore, Allegro displays remarkable generalization to out-of-distribution data. Molecular simulations using Allegro recover structural and kinetic properties of an amorphous electrolyte in excellent agreement with ab-initio simulations. Finally, we demonstrate parallelization with a simulation of 100 million atoms.",keywords:["Scalability","Iterated function","Parametrization","Equivariant map","Molecular dynamics","Statistical physics"],concepts:["Scalability","Iterated function","Parametrization","Equivariant map","Molecular dynamics","Statistical physics"],pdf_url:"https://www.nature.com/articles/s41467-023-36329-y.pdf",is_oa:!0,n_refs:63,n_refs_in_core:6,degree:16,community:2,deg_w:179.5,betweenness:6e-4,pagerank:.00412,eigenvector:.0453},{id:152,oaid:"W3176707157",doi:"10.1145/3448250",title:"Deep learning for AI",authors:[{name:"Yoshua Bengio",institutions:["Université de Montréal"]},{name:"Yann LeCun",institutions:["New York University"]},{name:"Geoffrey E. Hinton",institutions:["University of Toronto"]}],authorString:"Yoshua Bengio; Yann LeCun; Geoffrey E. Hinton",institutions:["New York University","University of Toronto","Université de Montréal"],countries:["CA","US"],year:2021,journal:"Communications of the ACM",citations:634,abstract:"How can neural networks learn the rich internal representations required for difficult tasks such as recognizing objects or understanding language?",keywords:["Deep learning","Artificial neural network","Natural language processing","Cognitive science"],concepts:["Deep learning","Artificial neural network","Natural language processing","Cognitive science"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3448250",is_oa:!0,n_refs:106,n_refs_in_core:5,degree:20,community:0,deg_w:153.5,betweenness:.0033,pagerank:.00421,eigenvector:.0134},{id:153,oaid:"W2736137960",doi:"10.1021/acs.molpharmaceut.7b00346",title:"druGAN: An Advanced Generative Adversarial Autoencoder Model for de Novo Generation of New Molecules with Desired Molecular Properties in Silico",authors:[{name:"Artur Kadurin",institutions:["Johns Hopkins University","Kazan Federal University","Steklov Mathematical Institute"]},{name:"Sergey Nikolenko",institutions:["National Research University Higher School of Economics","Kazan Federal University","Steklov Mathematical Institute"]},{name:"Kuzma Khrabrov",institutions:["Search"]},{name:"Alex Aliper",institutions:["Johns Hopkins University"]},{name:"Alex Zhavoronkov",institutions:["Johns Hopkins University","Moscow Institute of Physics and Technology","AULSS 2 Marca Trevigiana"]}],authorString:"Artur Kadurin; Sergey Nikolenko; Kuzma Khrabrov; Alex Aliper; Alex Zhavoronkov",institutions:["AULSS 2 Marca Trevigiana","Johns Hopkins University","Kazan Federal University","Moscow Institute of Physics and Technology","National Research University Higher School of Economics","Search","Steklov Mathematical Institute"],countries:["IT","RU","US"],year:2017,journal:"Molecular Pharmaceutics",citations:619,abstract:"Deep generative adversarial networks (GANs) are the emerging technology in drug discovery and biomarker development. In our recent work, we demonstrated a proof-of-concept of implementing deep generative adversarial autoencoder (AAE) to identify new molecular fingerprints with predefined anticancer properties. Another popular generative model is the variational autoencoder (VAE), which is based on deep neural architectures. In this work, we developed an advanced AAE model for molecular feature extraction problems, and demonstrated its advantages compared to VAE in terms of (a) adjustability in generating molecular fingerprints; (b) capacity of processing very large molecular data sets; and (c) efficiency in unsupervised pretraining for regression model. Our results suggest that the proposed AAE model significantly enhances the capacity and efficiency of development of the new molecules with specific anticancer properties using the deep generative models.",keywords:["Autoencoder","Generative grammar","Generative model","Artificial neural network","Deep learning","In silico"],concepts:["Autoencoder","Generative grammar","Generative model","Artificial neural network","Deep learning","In silico"],pdf_url:null,is_oa:!1,n_refs:19,n_refs_in_core:2,degree:8,community:2,deg_w:51,betweenness:5e-4,pagerank:.002,eigenvector:.0043},{id:154,oaid:"W2806547269",doi:"10.1039/c8sc00148k",title:"Large-scale comparison of machine learning methods for drug target prediction on ChEMBL",authors:[{name:"Andreas Mayr",institutions:["Johannes Kepler University of Linz","Bioinformatics Institute"]},{name:"Günter Klambauer",institutions:["Johannes Kepler University of Linz","Bioinformatics Institute"]},{name:"Thomas Unterthiner",institutions:["Johannes Kepler University of Linz","Bioinformatics Institute"]},{name:"Marvin Steijaert",institutions:[]},{name:"Jörg K. Wegner",institutions:["Janssen (Belgium)","Janssen (United States)"]},{name:"Hugo Ceulemans",institutions:["Janssen (Belgium)","Janssen (United States)"]},{name:"Djork-Arné Clevert",institutions:["Bayer (Germany)"]},{name:"Sepp Hochreiter",institutions:["Johannes Kepler University of Linz","Bioinformatics Institute"]}],authorString:"Andreas Mayr; Günter Klambauer; Thomas Unterthiner; Marvin Steijaert; Jörg K. Wegner; Hugo Ceulemans; Djork-Arné Clevert; Sepp Hochreiter",institutions:["Bayer (Germany)","Bioinformatics Institute","Janssen (Belgium)","Janssen (United States)","Johannes Kepler University of Linz"],countries:["AT","BE","DE","SG","US"],year:2018,journal:"Chemical Science",citations:611,abstract:"The to date largest comparative study of nine state-of-the-art drug target prediction methods finds that deep learning outperforms all other competitors. The results are based on a benchmark of 1300 assays and half a million compounds.",keywords:["chEMBL","Scale","Drug discovery","Computational biology","Bioinformatics"],concepts:["chEMBL","Scale","Drug discovery","Computational biology"],pdf_url:"https://pubs.rsc.org/en/content/articlepdf/2018/sc/c8sc00148k",is_oa:!0,n_refs:66,n_refs_in_core:7,degree:24,community:2,deg_w:214,betweenness:.0076,pagerank:.00518,eigenvector:.0457},{id:155,oaid:"W2751694392",doi:"10.1117/1.jrs.11.042609",title:"Comprehensive survey of deep learning in remote sensing: theories, tools, and challenges for the community",authors:[{name:"John E. Ball",institutions:["Mississippi State University"]},{name:"Derek T. Anderson",institutions:["Mississippi State University"]},{name:"Chee Seng Chan",institutions:["University of Malaya"]}],authorString:"John E. Ball; Derek T. Anderson; Chee Seng Chan",institutions:["Mississippi State University","University of Malaya"],countries:["MY","US"],year:2017,journal:"Journal of Applied Remote Sensing",citations:599,abstract:"In recent years, deep learning (DL), a rebranding of neural networks (NNs), has risen to the top in numerous areas, namely computer vision (CV), speech recognition, and natural language processing. Whereas remote sensing (RS) possesses a number of unique challenges, primarily related to sensors and applications, inevitably RS draws from many of the same theories as CV, e.g., statistics, fusion, and machine learning, to name a few. This means that the RS community should not only be aware of advancements such as DL, but also be leading researchers in this area. Herein, we provide the most comprehensive survey of state-of-the-art RS DL research. We also review recent new developments in the DL field that can be used in DL for RS. Namely, we focus on theories, tools, and challenges for the RS community. Specifically, we focus on unsolved challenges and opportunities as they relate to (i) inadequate data sets, (ii) human-understandable solutions for modeling physical phenomena, (iii) big data, (iv) nontraditional heterogeneous data sources, (v) DL architectures and learning algorithms for spectral, spatial, and temporal data, (vi) transfer learning, (vii) an improved theoretical understanding of DL systems, (viii) high barriers to entry, and (ix) training and optimizing the DL.",keywords:["Deep learning","Focus","Field","Big data","Transfer of learning","Deep neural networks","Artificial neural network"],concepts:["Deep learning","Data science","Focus","Field","Big data","Transfer of learning"],pdf_url:"https://www.spiedigitallibrary.org/journals/Journal-of-Applied-Remote-Sensing/volume-11/issue-4/042609/Comprehensive-survey-of-deep-learning-in-remote-sensing--theories/10.1117/1.JRS.11.042609.pdf",is_oa:!0,n_refs:395,n_refs_in_core:9,degree:25,community:3,deg_w:329,betweenness:.0045,pagerank:.00783,eigenvector:.0242},{id:156,oaid:"W2893892260",doi:"10.1109/tnsre.2019.2896659",title:"SeqSleepNet: End-to-End Hierarchical Recurrent Neural Network for Sequence-to-Sequence Automatic Sleep Staging",authors:[{name:"Huy Phan",institutions:["Kent State University","University of Kent"]},{name:"Fernando Andreotti",institutions:["University of Oxford"]},{name:"Navin Cooray",institutions:["University of Oxford"]},{name:"Oliver Y. Chén",institutions:["University of Oxford"]},{name:"Maarten De Vos",institutions:["University of Oxford"]}],authorString:"Huy Phan; Fernando Andreotti; Navin Cooray; Oliver Y. Chén; Maarten De Vos",institutions:["Kent State University","University of Kent","University of Oxford"],countries:["GB","US"],year:2019,journal:"IEEE Transactions on Neural Systems and Rehabilitation Engineering",citations:593,abstract:"Automatic sleep staging has been often treated as a simple classification problem that aims at determining the label of individual target polysomnography epochs one at a time. In this paper, we tackle the task as a sequence-to-sequence classification problem that receives a sequence of multiple epochs as input and classifies all of their labels at once. For this purpose, we propose a hierarchical recurrent neural network named SeqSleepNet (source code is available at http://github.com/pquochuy/SeqSleepNet). At the epoch processing level, the network consists of a filterbank layer tailored to learn frequency-domain filters for preprocessing and an attention-based recurrent layer designed for short-term sequential modeling. At the sequence processing level, a recurrent layer placed on top of the learned epoch-wise features for long-term modeling of sequential epochs. The classification is then carried out on the output vectors at every time step of the top recurrent layer to produce the sequence of output labels. Despite being hierarchical, we present a strategy to train the network in an end-to-end fashion. We show that the proposed network outperforms the state-of-the-art approaches, achieving an overall accuracy, macro F1-score, and Cohen's kappa of 87.1%, 83.3%, and 0.815 on a publicly available dataset with 200 subjects.",keywords:["Recurrent neural network","Sequence","Preprocessor","Artificial neural network","End-to-end principle","Macro"],concepts:["Recurrent neural network","Sequence","Preprocessor","Artificial neural network","End-to-end principle","Macro"],pdf_url:"https://kar.kent.ac.uk/72120/7/Phan2019a_TNSRE.pdf",is_oa:!0,n_refs:70,n_refs_in_core:8,degree:23,community:0,deg_w:168.5,betweenness:.0045,pagerank:.00504,eigenvector:.0114},{id:157,oaid:"W3006781240",doi:"10.3389/frai.2020.00004",title:"An Introductory Review of Deep Learning for Prediction Models With Big Data",authors:[{name:"Frank Emmert‐Streib",institutions:["Tampere University"]},{name:"Zhen Yang",institutions:["Tampere University"]},{name:"Feng Han",institutions:["Tampere University","University of Applied Sciences Upper Austria"]},{name:"Shailesh Tripathi",institutions:["Tampere University","University of Applied Sciences Upper Austria"]},{name:"Matthias Dehmer",institutions:["Nankai University","UMIT - Private Universität für Gesundheitswissenschaften, Medizinische Informatik und Technik","University of Applied Sciences Upper Austria"]}],authorString:"Frank Emmert‐Streib; Zhen Yang; Feng Han; Shailesh Tripathi; Matthias Dehmer",institutions:["Nankai University","Tampere University","UMIT - Private Universität für Gesundheitswissenschaften, Medizinische Informatik und Technik","University of Applied Sciences Upper Austria"],countries:["AT","CN","FI"],year:2020,journal:"Frontiers in Artificial Intelligence",citations:592,abstract:"Deep learning models stand for a new learning paradigm in artificial intelligence (AI) and machine learning. Recent breakthrough results in image analysis and speech recognition have generated a massive interest in this field because also applications in many other domains providing big data seem possible. On a downside, the mathematical and computational methodology underlying deep learning models is very challenging, especially for interdisciplinary scientists. For this reason, we present in this paper an introductory review of deep learning approaches including Deep Feedforward Neural Networks (D-FFNN), Convolutional Neural Networks (CNNs), Deep Belief Networks (DBNs), Autoencoders (AEs), and Long Short-Term Memory (LSTM) networks. These models form the major core architectures of deep learning models currently used and should belong in any data scientist's toolbox. Importantly, those core architectural building blocks can be composed flexibly-in an almost Lego-like manner-to build new application-specific network architectures. Hence, a basic understanding of these network architectures is important to be prepared for future developments in AI.",keywords:["Deep learning","Toolbox","Field","Convolutional neural network","Artificial neural network"],concepts:["Deep learning","Toolbox","Field","Convolutional neural network","Artificial neural network"],pdf_url:"https://www.frontiersin.org/articles/10.3389/frai.2020.00004/pdf",is_oa:!0,n_refs:170,n_refs_in_core:9,degree:23,community:0,deg_w:268,betweenness:.0082,pagerank:.00643,eigenvector:.0451},{id:158,oaid:"W4383995031",doi:"10.1063/5.0155600",title:"DeePMD-kit v2: A software package for deep potential models",authors:[{name:"Jinzhe Zeng",institutions:["Rutgers, The State University of New Jersey","Quantitative BioSciences"]},{name:"Duo Zhang",institutions:["Peking University"]},{name:"Denghui Lu",institutions:["Peking University"]},{name:"Pinghui Mo",institutions:["Hunan University"]},{name:"Zeyu Li",institutions:["Rutgers, The State University of New Jersey","Peking University","Quantitative BioSciences"]},{name:"Yixiao Chen",institutions:["Princeton University"]},{name:"Marián Rynik",institutions:["Comenius University Bratislava"]},{name:"Liang Huang",institutions:["Tsinghua University"]},{name:"Ziyao Li",institutions:["Rutgers, The State University of New Jersey","Peking University","Quantitative BioSciences"]},{name:"Shaochen Shi",institutions:[]},{name:"Yingze Wang",institutions:["Rutgers, The State University of New Jersey","Quantitative BioSciences"]},{name:"Haotian Ye",institutions:["Peking University"]},{name:"Ping Tuo",institutions:[]},{name:"Jiabin Yang",institutions:["Baidu (China)"]},{name:"Ye Ding",institutions:["Rutgers, The State University of New Jersey","Quantitative BioSciences"]},{name:"Yifan Li",institutions:["Princeton University"]},{name:"Davide Tisi",institutions:["Rutgers, The State University of New Jersey","Quantitative BioSciences"]},{name:"Qiyu Zeng",institutions:["National University of Defense Technology"]},{name:"Han Bao",institutions:[]},{name:"Yu Xia",institutions:[]},{name:"Jiameng Huang",institutions:[]},{name:"Koki Muraoka",institutions:["The University of Tokyo"]},{name:"Yibo Wang",institutions:["Rutgers, The State University of New Jersey","Quantitative BioSciences"]},{name:"Junhan Chang",institutions:["Rutgers, The State University of New Jersey","Quantitative BioSciences"]},{name:"Fengbo Yuan",institutions:[]},{name:"Sigbjørn Løland Bore",institutions:["University of Oslo"]},{name:"Chun Cai",institutions:[]},{name:"Yin‐Nian Lin",institutions:["Peking University"]},{name:"Bo Wang",institutions:["East China Normal University"]},{name:"Jiayan Xu",institutions:["Queen's University Belfast"]},{name:"Jiaxin Zhu",institutions:["Xiamen University","Collaborative Innovation Center of Chemistry for Energy Materials"]},{name:"Chenxing Luo",institutions:["Columbia University"]},{name:"Yuzhi Zhang",institutions:[]},{name:"Rhys E. A. Goodall",institutions:[]},{name:"Wenshuo Liang",institutions:[]},{name:"Anurag Kumar Singh",institutions:["Indian Institute of Technology Palakkad"]},{name:"Sikai Yao",institutions:[]},{name:"Jingchao Zhang",institutions:["Nvidia (United States)"]},{name:"Renata M. Wentzcovitch",institutions:[]},{name:"Jiequn Han",institutions:["Flatiron Health (United States)"]},{name:"Jie Liu",institutions:["Hunan University"]},{name:"Weile Jia",institutions:[]},{name:"Darrin M. York",institutions:["Rutgers, The State University of New Jersey","Quantitative BioSciences"]},{name:"E Weinan",institutions:[]},{name:"Roberto Car",institutions:["Princeton University"]},{name:"Linfeng Zhang",institutions:[]},{name:"Han Wang",institutions:["Peking University"]}],authorString:"Jinzhe Zeng; Duo Zhang; Denghui Lu; Pinghui Mo; Zeyu Li; Yixiao Chen; Marián Rynik; Liang Huang; Ziyao Li; Shaochen Shi; Yingze Wang; Haotian Ye et al.",institutions:["Baidu (China)","Collaborative Innovation Center of Chemistry for Energy Materials","Columbia University","Comenius University Bratislava","East China Normal University","Flatiron Health (United States)","Hunan University","Indian Institute of Technology Palakkad","National University of Defense Technology","Nvidia (United States)","Peking University","Princeton University","Quantitative BioSciences","Queen's University Belfast","Rutgers, The State University of New Jersey","The University of Tokyo","Tsinghua University","University of Oslo","Xiamen University"],countries:["CN","GB","IN","JP","NO","SK","US"],year:2023,journal:"The Journal of Chemical Physics",citations:555,abstract:"DeePMD-kit is a powerful open-source software package that facilitates molecular dynamics simulations using machine learning potentials known as Deep Potential (DP) models. This package, which was released in 2017, has been widely used in the fields of physics, chemistry, biology, and material science for studying atomistic systems. The current version of DeePMD-kit offers numerous advanced features, such as DeepPot-SE, attention-based and hybrid descriptors, the ability to fit tensile properties, type embedding, model deviation, DP-range correction, DP long range, graphics processing unit support for customized operators, model compression, non-von Neumann molecular dynamics, and improved usability, including documentation, compiled binary packages, graphical user interfaces, and application programming interfaces. This article presents an overview of the current major version of the DeePMD-kit package, highlighting its features and technical details. Additionally, this article presents a comprehensive procedure for conducting molecular dynamics as a representative application, benchmarks the accuracy and efficiency of different models, and discusses ongoing developments.",keywords:["Usability","Software","Computational science","Documentation","Graphics","Embedding","Range"],concepts:["Usability","Software","Computational science","Documentation","Graphics","Embedding","Range"],pdf_url:"https://pubs.aip.org/aip/jcp/article-pdf/doi/10.1063/5.0155600/18066973/054801_1_5.0155600.pdf",is_oa:!0,n_refs:166,n_refs_in_core:10,degree:18,community:2,deg_w:186,betweenness:.0049,pagerank:.00427,eigenvector:.0516},{id:159,oaid:"W3016488464",doi:"10.3390/sym12040651",title:"Within the Lack of Chest COVID-19 X-ray Dataset: A Novel Detection Model Based on GAN and Deep Transfer Learning",authors:[{name:"Mohamed Loey",institutions:["Benha University"]},{name:"Florentín Smarandache",institutions:["University of New Mexico"]},{name:"Nour Eldeen M. Khalifa",institutions:["Cairo University"]}],authorString:"Mohamed Loey; Florentín Smarandache; Nour Eldeen M. Khalifa",institutions:["Benha University","Cairo University","University of New Mexico"],countries:["EG","US"],year:2020,journal:"Symmetry",citations:554,abstract:"The coronavirus (COVID-19) pandemic is putting healthcare systems across the world under unprecedented and increasing pressure according to the World Health Organization (WHO). With the advances in computer algorithms and especially Artificial Intelligence, the detection of this type of virus in the early stages will help in fast recovery and help in releasing the pressure off healthcare systems. In this paper, a GAN with deep transfer learning for coronavirus detection in chest X-ray images is presented. The lack of datasets for COVID-19 especially in chest X-rays images is the main motivation of this scientific study. The main idea is to collect all the possible images for COVID-19 that exists until the writing of this research and use the GAN network to generate more images to help in the detection of this virus from the available X-rays images with the highest accuracy possible. The dataset used in this research was collected from different sources and it is available for researchers to download and use it. The number of images in the collected dataset is 307 images for four different types of classes. The classes are the COVID-19, normal, pneumonia bacterial, and pneumonia virus. Three deep transfer models are selected in this research for investigation. The models are the Alexnet, Googlenet, and Restnet18. Those models are selected for investigation through this research as it contains a small number of layers on their architectures, this will result in reducing the complexity, the consumed memory and the execution time for the proposed model. Three case scenarios are tested through the paper, the first scenario includes four classes from the dataset, while the second scenario includes 3 classes and the third scenario includes two classes. All the scenarios include the COVID-19 class as it is the main target of this research to be detected. In the first scenario, the Googlenet is selected to be the main deep transfer model as it achieves 80.6% in testing accuracy. In the second scenario, the Alexnet is selected to be the main deep transfer model as it achieves 85.2% in testing accuracy, while in the third scenario which includes two classes (COVID-19, and normal), Googlenet is selected to be the main deep transfer model as it achieves 100% in testing accuracy and 99.9% in the validation accuracy. All the performance measurement strengthens the obtained results through the research.",keywords:["Transfer of learning","Coronavirus disease 2019","Deep learning","Pneumonia","Severe acute respiratory syndrome coronavirus 2"],concepts:["Transfer of learning","Coronavirus disease 2019","Deep learning","Pneumonia","Severe acute respiratory syndrome coronavirus 2"],pdf_url:"https://www.mdpi.com/2073-8994/12/4/651/pdf?version=1587382932",is_oa:!0,n_refs:66,n_refs_in_core:7,degree:21,community:1,deg_w:142,betweenness:.003,pagerank:.0039,eigenvector:.0134},{id:160,oaid:"W2929803724",doi:"10.3390/info10040122",title:"A Survey of Deep Learning Methods for Cyber Security",authors:[{name:"Daniel S. Berman",institutions:["Johns Hopkins University Applied Physics Laboratory"]},{name:"Anna L. Buczak",institutions:["Johns Hopkins University Applied Physics Laboratory"]},{name:"Jeffrey S. Chavis",institutions:["Johns Hopkins University Applied Physics Laboratory"]},{name:"Cherita Corbett",institutions:["Johns Hopkins University Applied Physics Laboratory"]}],authorString:"Daniel S. Berman; Anna L. Buczak; Jeffrey S. Chavis; Cherita Corbett",institutions:["Johns Hopkins University Applied Physics Laboratory"],countries:["US"],year:2019,journal:"Information",citations:553,abstract:"This survey paper describes a literature review of deep learning (DL) methods for cyber security applications. A short tutorial-style description of each DL method is provided, including deep autoencoders, restricted Boltzmann machines, recurrent neural networks, generative adversarial networks, and several others. Then we discuss how each of the DL methods is used for security applications. We cover a broad array of attack types including malware, spam, insider threats, network intrusions, false data injection, and malicious domain names used by botnets.",keywords:["Deep learning","Malware","Insider","Computer security","Boltzmann machine","Botnet"],concepts:["Deep learning","Malware","Insider","Computer security","Boltzmann machine","Botnet"],pdf_url:"https://www.mdpi.com/2078-2489/10/4/122/pdf?version=1554207829",is_oa:!0,n_refs:169,n_refs_in_core:7,degree:22,community:0,deg_w:194,betweenness:.0039,pagerank:.00502,eigenvector:.0225},{id:161,oaid:"W2768213699",doi:"10.1039/c7sc04934j",title:"The TensorMol-0.1 model chemistry: a neural network augmented with long-range physics",authors:[{name:"Kun Yao",institutions:["University of Notre Dame"]},{name:"John E. Herr",institutions:["University of Notre Dame"]},{name:"David W. Toth",institutions:["University of Notre Dame"]},{name:"Ryker Mckintyre",institutions:["University of Notre Dame"]},{name:"John Parkhill",institutions:["University of Notre Dame"]}],authorString:"Kun Yao; John E. Herr; David W. Toth; Ryker Mckintyre; John Parkhill",institutions:["University of Notre Dame"],countries:["US"],year:2018,journal:"Chemical Science",citations:525,abstract:'accuracy at low cost. However a data-driven approach is naturally inefficient for long-range interatomic forces that have simple physical formulas. In this manuscript we construct a hybrid model chemistry consisting of a nearsighted neural network potential with screened long-range electrostatic and van der Waals physics. This trained potential, simply dubbed "TensorMol-0.1", is offered in an open-source Python package capable of many of the simulation types commonly used to study chemistry: geometry optimizations, harmonic spectra, open or periodic molecular dynamics, Monte Carlo, and nudged elastic band calculations. We describe the robustness and speed of the package, demonstrating its millihartree accuracy and scalability to tens-of-thousands of atoms on ordinary laptops. We demonstrate the performance of the model by reproducing vibrational spectra, and simulating the molecular dynamics of a protein. Our comparisons with electronic structure theory and experimental data demonstrate that neural network molecular dynamics is poised to become an important tool for molecular simulation, lowering the resource barrier to simulating chemistry.',keywords:["Python","Molecular dynamics","Statistical physics","Artificial neural network","Scalability","van der Waals force","Monte Carlo method"],concepts:["Python","Molecular dynamics","Statistical physics","Artificial neural network","Scalability","van der Waals force","Monte Carlo method"],pdf_url:"https://pubs.rsc.org/en/content/articlepdf/2018/sc/c7sc04934j",is_oa:!0,n_refs:100,n_refs_in_core:3,degree:20,community:2,deg_w:218,betweenness:.003,pagerank:.0047,eigenvector:.0735},{id:162,oaid:"W2946165673",doi:"10.1109/access.2019.2916887",title:"Deep Multimodal Representation Learning: A Survey",authors:[{name:"Wenzhong Guo",institutions:["Fuzhou University"]},{name:"Jianwen Wang",institutions:["Fujian Normal University"]},{name:"Shiping Wang",institutions:["Fuzhou University"]}],authorString:"Wenzhong Guo; Jianwen Wang; Shiping Wang",institutions:["Fujian Normal University","Fuzhou University"],countries:["CN"],year:2019,journal:"IEEE Access",citations:523,abstract:"Multimodal representation learning, which aims to narrow the heterogeneity gap among different modalities, plays an indispensable role in the utilization of ubiquitous multimodal data. Due to the powerful representation ability with multiple levels of abstraction, deep learning-based multimodal representation learning has attracted much attention in recent years. In this paper, we provided a comprehensive survey on deep multimodal representation learning which has never been concentrated entirely. To facilitate the discussion on how the heterogeneity gap is narrowed, according to the underlying structures in which different modalities are integrated, we category deep multimodal representation learning methods into three frameworks: joint representation, coordinated representation, and encoder-decoder. Additionally, we review some typical models in this area ranging from conventional models to newly developed technologies. This paper highlights on the key issues of newly developed technologies, such as encoder-decoder model, generative adversarial networks, and attention mechanism in a multimodal representation learning perspective, which, to the best of our knowledge, have never been reviewed previously, even though they have become the major focuses of much contemporary research. For each framework or model, we discuss its basic structure, learning objective, application scenes, key issues, advantages, and disadvantages, such that both novel and experienced researchers can benefit from this survey. Finally, we suggest some important directions for future work.",keywords:["Modalities","Representation","Multimodal learning","Feature learning","Deep learning","Key"],concepts:["Modalities","Representation","Multimodal learning","Feature learning","Deep learning","Key"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/8600701/08715409.pdf",is_oa:!0,n_refs:206,n_refs_in_core:6,degree:20,community:0,deg_w:188.5,betweenness:.0045,pagerank:.0048,eigenvector:.0397},{id:163,oaid:"W3185377372",doi:"10.3390/agriculture11080707",title:"Review on Convolutional Neural Network (CNN) Applied to Plant Leaf Disease Classification",authors:[{name:"Jinzhu Lu",institutions:["Xihua University"]},{name:"Lijuan Tan",institutions:["Xihua University"]},{name:"Huanyu Jiang",institutions:["Zhejiang University"]}],authorString:"Jinzhu Lu; Lijuan Tan; Huanyu Jiang",institutions:["Xihua University","Zhejiang University"],countries:["CN"],year:2021,journal:"Agriculture",citations:519,abstract:"Crop production can be greatly reduced due to various diseases, which seriously endangers food security. Thus, detecting plant diseases accurately is necessary and urgent. Traditional classification methods, such as naked-eye observation and laboratory tests, have many limitations, such as being time consuming and subjective. Currently, deep learning (DL) methods, especially those based on convolutional neural network (CNN), have gained widespread application in plant disease classification. They have solved or partially solved the problems of traditional classification methods and represent state-of-the-art technology in this field. In this work, we reviewed the latest CNN networks pertinent to plant leaf disease classification. We summarized DL principles involved in plant disease classification. Additionally, we summarized the main problems and corresponding solutions of CNN used for plant disease classification. Furthermore, we discussed the future development direction in plant disease classification.",keywords:["Convolutional neural network","Plant disease","Contextual image classification","Pattern recognition","Field"],concepts:["Convolutional neural network","Plant disease","Contextual image classification","Pattern recognition","Field"],pdf_url:"https://www.mdpi.com/2077-0472/11/8/707/pdf?version=1627382363",is_oa:!0,n_refs:114,n_refs_in_core:6,degree:21,community:3,deg_w:166.5,betweenness:.007,pagerank:.00477,eigenvector:.0053},{id:164,oaid:"W3154435685",doi:"10.1109/trpms.2021.3066428",title:"On Interpretability of Artificial Neural Networks: A Survey",authors:[{name:"Fenglei Fan",institutions:["Rensselaer Polytechnic Institute"]},{name:"Jinjun Xiong",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Mengzhou Li",institutions:["Rensselaer Polytechnic Institute"]},{name:"Ge Wang",institutions:["Rensselaer Polytechnic Institute"]}],authorString:"Fenglei Fan; Jinjun Xiong; Mengzhou Li; Ge Wang",institutions:["IBM Research - Thomas J. Watson Research Center","Rensselaer Polytechnic Institute"],countries:["US"],year:2021,journal:"IEEE Transactions on Radiation and Plasma Medical Sciences",citations:514,abstract:"Deep learning as represented by the artificial deep neural networks (DNNs) has achieved great success recently in many important areas that deal with text, images, videos, graphs, and so on. However, the black-box nature of DNNs has become one of the primary obstacles for their wide adoption in mission-critical applications such as medical diagnosis and therapy. Because of the huge potentials of deep learning, increasing the interpretability of deep neural networks has recently attracted much research attention. In this paper, we propose a simple but comprehensive taxonomy for interpretability, systematically review recent studies in improving interpretability of neural networks, describe applications of interpretability in medicine, and discuss possible future research directions of interpretability, such as in relation to fuzzy logic and brain science.",keywords:["Interpretability","Artificial neural network","Deep learning","Black box","Deep neural networks"],concepts:["Interpretability","Artificial neural network","Deep learning","Black box","Deep neural networks"],pdf_url:"https://ieeexplore.ieee.org/ielx7/7433213/9597881/09380482.pdf",is_oa:!0,n_refs:297,n_refs_in_core:6,degree:20,community:4,deg_w:396,betweenness:.0036,pagerank:.00781,eigenvector:.1841},{id:165,oaid:"W4391848979",doi:"10.1016/j.inffus.2024.102301",title:"Explainable Artificial Intelligence (XAI) 2.0: A manifesto of open challenges and interdisciplinary research directions",authors:[{name:"Luca Longo",institutions:["Intel (Ireland)","Technological University Dublin"]},{name:"Mario Brčić",institutions:["University of Zagreb"]},{name:"Federico Cabitza",institutions:["Istituto Clinico Sant'Ambrogio","University of Milano-Bicocca"]},{name:"Jaesik Choi",institutions:["Korea Advanced Institute of Science and Technology"]},{name:"Roberto Confalonieri",institutions:["University of Padua"]},{name:"Javier Del Ser",institutions:["University of the Basque Country","Universidad de Granada","Instituto Andaluz de Ciencias de la Tierra","Association of Electronic and Information Technologies"]},{name:"Riccardo Guidotti",institutions:["University of Pisa"]},{name:"Yoichi Hayashi",institutions:["Meiji University"]},{name:"Francisco Herrera",institutions:["Universidad de Granada","Instituto Andaluz de Ciencias de la Tierra"]},{name:"Andreas Holzinger",institutions:["BOKU University"]},{name:"Richard Jiang",institutions:["Lancaster University"]},{name:"Hassan Khosravi",institutions:["The University of Queensland"]},{name:"Freddy Lécué",institutions:["Institut national de recherche en sciences et technologies du numérique"]},{name:"Gianclaudio Malgieri",institutions:["Leiden University"]},{name:"Andrés Páez",institutions:["Universidad de Los Andes"]},{name:"Wojciech Samek",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Berlin Institute for the Foundations of Learning and Data","Technische Universität Berlin"]},{name:"Johannes Schneider",institutions:["University of Liechtenstein"]},{name:"Timo Speith",institutions:["University of Bayreuth","Saarland University"]},{name:"Simone Stumpf",institutions:["University of Glasgow"]}],authorString:"Luca Longo; Mario Brčić; Federico Cabitza; Jaesik Choi; Roberto Confalonieri; Javier Del Ser; Riccardo Guidotti; Yoichi Hayashi; Francisco Herrera; Andreas Holzinger; Richard Jiang; Hassan Khosravi et al.",institutions:["Association of Electronic and Information Technologies","BOKU University","Berlin Institute for the Foundations of Learning and Data","Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Institut national de recherche en sciences et technologies du numérique","Instituto Andaluz de Ciencias de la Tierra","Intel (Ireland)","Istituto Clinico Sant'Ambrogio","Korea Advanced Institute of Science and Technology","Lancaster University","Leiden University","Meiji University","Saarland University","Technische Universität Berlin","Technological University Dublin","The University of Queensland","Universidad de Granada","Universidad de Los Andes","University of Bayreuth","University of Glasgow","University of Liechtenstein","University of Milano-Bicocca","University of Padua","University of Pisa","University of Zagreb","University of the Basque Country"],countries:["AT","AU","CO","DE","ES","FR","GB","HR","IE","IT","JP","KR","LI","NL"],year:2024,journal:"Information Fusion",citations:498,abstract:"Understanding black box models has become paramount as systems based on opaque Artificial Intelligence (AI) continue to flourish in diverse real-world applications. In response, Explainable AI (XAI) has emerged as a field of research with practical and ethical benefits across various domains. This paper highlights the advancements in XAI and its application in real-world scenarios and addresses the ongoing challenges within XAI, emphasizing the need for broader perspectives and collaborative efforts. We bring together experts from diverse fields to identify open problems, striving to synchronize research agendas and accelerate XAI in practical applications. By fostering collaborative discussion and interdisciplinary cooperation, we aim to propel XAI forward, contributing to its continued success. We aim to develop a comprehensive proposal for advancing XAI. To achieve this goal, we present a manifesto of 28 open problems categorized into nine categories. These challenges encapsulate the complexities and nuances of XAI and offer a road map for future research. For each problem, we provide promising research directions in the hope of harnessing the collective intelligence of interested stakeholders.",keywords:["Manifesto","Open research","Data science","World Wide Web"],concepts:["Manifesto","Open research","Data science"],pdf_url:"https://doi.org/10.1016/j.inffus.2024.102301",is_oa:!0,n_refs:323,n_refs_in_core:8,degree:19,community:4,deg_w:207,betweenness:5e-4,pagerank:.00437,eigenvector:.1017},{id:166,oaid:"W3138815606",doi:"10.1145/3523273",title:"Membership Inference Attacks on Machine Learning: A Survey",authors:[{name:"Hongsheng Hu",institutions:["University of Auckland"]},{name:"Zoran Salčić",institutions:["University of Auckland"]},{name:"Lichao Sun",institutions:["Lehigh University"]},{name:"Gillian Dobbie",institutions:["University of Auckland"]},{name:"Philip S. Yu",institutions:["University of Illinois Chicago"]},{name:"Xuyun Zhang",institutions:["Macquarie University"]}],authorString:"Hongsheng Hu; Zoran Salčić; Lichao Sun; Gillian Dobbie; Philip S. Yu; Xuyun Zhang",institutions:["Lehigh University","Macquarie University","University of Auckland","University of Illinois Chicago"],countries:["AU","NZ","US"],year:2022,journal:"ACM Computing Surveys",citations:492,abstract:"Machine learning (ML) models have been widely applied to various applications, including image classification, text generation, audio recognition, and graph data analysis. However, recent studies have shown that ML models are vulnerable to membership inference attacks (MIAs), which aim to infer whether a data record was used to train a target model or not. MIAs on ML models can directly lead to a privacy breach. For example, via identifying the fact that a clinical record that has been used to train a model associated with a certain disease, an attacker can infer that the owner of the clinical record has the disease with a high chance. In recent years, MIAs have been shown to be effective on various ML models, e.g., classification models and generative models. Meanwhile, many defense methods have been proposed to mitigate MIAs. Although MIAs on ML models form a newly emerging and rapidly growing research area, there has been no systematic survey on this topic yet. In this article, we conduct the first comprehensive survey on membership inference attacks and defenses. We provide the taxonomies for both attacks and defenses, based on their characterizations, and discuss their pros and cons. Based on the limitations and gaps identified in this survey, we point out several promising future research directions to inspire the researchers who wish to follow this area. This survey not only serves as a reference for the research community but also provides a clear description for researchers outside this research domain. To further help the researchers, we have created an online resource repository, which we will keep updated with future relevant work. Interested readers can find the repository at https://github.com/HongshengHu/membership-inference-machine-learning-literature.",keywords:["Inference","Data science","Point","Generative grammar","Domain"],concepts:["Inference","Data science","Point","Generative grammar","Domain"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3523273",is_oa:!0,n_refs:299,n_refs_in_core:8,degree:22,community:1,deg_w:147,betweenness:.0075,pagerank:.00439,eigenvector:.0201},{id:167,oaid:"W2805033630",doi:"10.1109/tbme.2018.2872652",title:"Joint Classification and Prediction CNN Framework for Automatic Sleep Stage Classification",authors:[{name:"Huy Phan",institutions:["University of Oxford"]},{name:"Fernando Andreotti",institutions:["University of Oxford"]},{name:"Navin Cooray",institutions:["University of Oxford"]},{name:"Oliver Y. Chén",institutions:["University of Oxford"]},{name:"Maarten De Vos",institutions:["University of Oxford"]}],authorString:"Huy Phan; Fernando Andreotti; Navin Cooray; Oliver Y. Chén; Maarten De Vos",institutions:["University of Oxford"],countries:["GB"],year:2018,journal:"IEEE Transactions on Biomedical Engineering",citations:464,abstract:"Correctly identifying sleep stages is important in diagnosing and treating sleep disorders. This paper proposes a joint classification-and-prediction framework based on convolutional neural networks (CNNs) for automatic sleep staging, and, subsequently, introduces a simple yet efficient CNN architecture to power the framework. Given a single input epoch, the novel framework jointly determines its label (classification) and its neighboring epochs' labels (prediction) in the contextual output. While the proposed framework is orthogonal to the widely adopted classification schemes, which take one or multiple epochs as contextual inputs and produce a single classification decision on the target epoch, we demonstrate its advantages in several ways. First, it leverages the dependency among consecutive sleep epochs while surpassing the problems experienced with the common classification schemes. Second, even with a single model, the framework has the capacity to produce multiple decisions, which are essential in obtaining a good performance as in ensemble-of-models methods, with very little induced computational overhead. Probabilistic aggregation techniques are then proposed to leverage the availability of multiple decisions. To illustrate the efficacy of the proposed framework, we conducted experiments on two public datasets: Sleep-EDF Expanded (Sleep-EDF), which consists of 20 subjects, and Montreal Archive of Sleep Studies (MASS) dataset, which consists of 200 subjects. The proposed framework yields an overall classification accuracy of 82.3% and 83.6%, respectively. We also show that the proposed framework not only is superior to the baselines based on the common classification schemes but also outperforms existing deep-learning approaches. To our knowledge, this is the first work going beyond the standard single-output classification to consider multitask neural networks for automatic sleep staging. This framework provides avenues for further studies of different neural-network architectures for automatic sleep staging.",keywords:["Joint","Pattern recognition","Stage","Support vector machine","Feature extraction","Statistical classification"],concepts:["Joint","Pattern recognition","Stage","Support vector machine","Feature extraction","Statistical classification"],pdf_url:"https://doi.org/10.1109/tbme.2018.2872652",is_oa:!0,n_refs:82,n_refs_in_core:4,degree:16,community:0,deg_w:113.5,betweenness:.0038,pagerank:.00375,eigenvector:.0047},{id:168,oaid:"W4382516982",doi:"10.1021/acs.chemrev.3c00189",title:"Machine Learning Methods for Small Data Challenges in Molecular Science",authors:[{name:"Bozheng Dou",institutions:["Wuhan Textile University"]},{name:"Zailiang Zhu",institutions:["Wuhan Textile University"]},{name:"Ekaterina Merkurjev",institutions:["Michigan State University"]},{name:"Ke Lü",institutions:["Wuhan Textile University"]},{name:"Long Chen",institutions:["Wuhan Textile University"]},{name:"Jiang Jian",institutions:["Wuhan Textile University","Michigan State University"]},{name:"Yueying Zhu",institutions:["Wuhan Textile University"]},{name:"Jie Liu",institutions:["Wuhan Textile University"]},{name:"Bengong Zhang",institutions:["Wuhan Textile University"]},{name:"Guo‐Wei Wei",institutions:["Michigan State University"]}],authorString:"Bozheng Dou; Zailiang Zhu; Ekaterina Merkurjev; Ke Lü; Long Chen; Jiang Jian; Yueying Zhu; Jie Liu; Bengong Zhang; Guo‐Wei Wei",institutions:["Michigan State University","Wuhan Textile University"],countries:["CN","US"],year:2023,journal:"Chemical Reviews",citations:464,abstract:"Small data are often used in scientific and engineering research due to the presence of various constraints, such as time, cost, ethics, privacy, security, and technical limitations in data acquisition. However, big data have been the focus for the past decade, small data and their challenges have received little attention, even though they are technically more severe in machine learning (ML) and deep learning (DL) studies. Overall, the small data challenge is often compounded by issues, such as data diversity, imputation, noise, imbalance, and high-dimensionality. Fortunately, the current big data era is characterized by technological breakthroughs in ML, DL, and artificial intelligence (AI), which enable data-driven scientific discovery, and many advanced ML and DL technologies developed for big data have inadvertently provided solutions for small data problems. As a result, significant progress has been made in ML and DL for small data challenges in the past decade. In this review, we summarize and analyze several emerging potential solutions to small data challenges in molecular science, including chemical and biological sciences. We review both basic machine learning algorithms, such as linear regression, logistic regression (LR), k -nearest neighbor (KNN), support vector machine (SVM), kernel learning (KL), random forest (RF), and gradient boosting trees (GBT), and more advanced techniques, including artificial neural network (ANN), convolutional neural network (CNN), U-Net, graph neural network (GNN), Generative Adversarial Network (GAN), long short-term memory (LSTM), autoencoder, transformer, transfer learning, active learning, graph-based semi-supervised learning, combining deep learning with traditional machine learning, and physical model-based data augmentation. We also briefly discuss the latest advances in these methods. Finally, we conclude the survey with a discussion of promising trends in small data challenges in molecular science.",keywords:["Data science","Nanotechnology"],concepts:["Data science","Nanotechnology"],pdf_url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC10999174/pdf/nihms-1979743.pdf",is_oa:!0,n_refs:591,n_refs_in_core:16,degree:30,community:5,deg_w:275,betweenness:.0173,pagerank:.00652,eigenvector:.0718},{id:169,oaid:"W4328115538",doi:"10.3389/fpls.2023.1158933",title:"An advanced deep learning models-based plant disease detection: A review of recent research",authors:[{name:"Muhammad Shoaib",institutions:["Sarhad University of Science and Information Technology","CECOS University"]},{name:"Babar Shah",institutions:["Zayed University"]},{name:"Shaker El–Sappagh",institutions:["Suez University","Benha University","Galala University"]},{name:"Akhtar Ali",institutions:["Center of Plant Systems Biology and Biotechnology"]},{name:"Asad Ullah",institutions:["Sarhad University of Science and Information Technology"]},{name:"Fayadh Alenezi",institutions:["Jouf University"]},{name:"Tsanko Gechev",institutions:["Plovdiv University","Center of Plant Systems Biology and Biotechnology"]},{name:"Tariq Hussain",institutions:["Zhejiang Gongshang University"]},{name:"Farman Ali",institutions:["Sejong University","Sungkyunkwan University"]}],authorString:"Muhammad Shoaib; Babar Shah; Shaker El–Sappagh; Akhtar Ali; Asad Ullah; Fayadh Alenezi; Tsanko Gechev; Tariq Hussain; Farman Ali",institutions:["Benha University","CECOS University","Center of Plant Systems Biology and Biotechnology","Galala University","Jouf University","Plovdiv University","Sarhad University of Science and Information Technology","Sejong University","Suez University","Sungkyunkwan University","Zayed University","Zhejiang Gongshang University"],countries:["AE","BG","CN","EG","KR","PK","SA"],year:2023,journal:"Frontiers in Plant Science",citations:464,abstract:"Plants play a crucial role in supplying food globally. Various environmental factors lead to plant diseases which results in significant production losses. However, manual detection of plant diseases is a time-consuming and error-prone process. It can be an unreliable method of identifying and preventing the spread of plant diseases. Adopting advanced technologies such as Machine Learning (ML) and Deep Learning (DL) can help to overcome these challenges by enabling early identification of plant diseases. In this paper, the recent advancements in the use of ML and DL techniques for the identification of plant diseases are explored. The research focuses on publications between 2015 and 2022, and the experiments discussed in this study demonstrate the effectiveness of using these techniques in improving the accuracy and efficiency of plant disease detection. This study also addresses the challenges and limitations associated with using ML and DL for plant disease identification, such as issues with data availability, imaging quality, and the differentiation between healthy and diseased plants. The research provides valuable insights for plant disease detection researchers, practitioners, and industry professionals by offering solutions to these challenges and limitations, providing a comprehensive understanding of the current state of research in this field, highlighting the benefits and limitations of these methods, and proposing potential solutions to overcome the challenges of their implementation.",keywords:["Identification","Process","Plant disease","Risk analysis","Quality","Data science"],concepts:["Identification","Process","Plant disease","Risk analysis","Quality","Data science"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fpls.2023.1158933/pdf",is_oa:!0,n_refs:101,n_refs_in_core:6,degree:13,community:3,deg_w:134,betweenness:.0012,pagerank:.0039,eigenvector:.0045},{id:170,oaid:"W2804532080",doi:"10.1002/widm.1264",title:"Deep learning for remote sensing image classification: A survey",authors:[{name:"Ying Li",institutions:["Northwestern Polytechnical University"]},{name:"Haokui Zhang",institutions:["Northwestern Polytechnical University"]},{name:"Xizhe Xue",institutions:["Northwestern Polytechnical University"]},{name:"Yenan Jiang",institutions:["Northwestern Polytechnical University"]},{name:"Qiang Shen",institutions:["Aberystwyth University"]}],authorString:"Ying Li; Haokui Zhang; Xizhe Xue; Yenan Jiang; Qiang Shen",institutions:["Aberystwyth University","Northwestern Polytechnical University"],countries:["CN","GB"],year:2018,journal:"Wiley Interdisciplinary Reviews Data Mining and Knowledge Discovery",citations:458,abstract:"Remote sensing (RS) image classification plays an important role in the earth observation technology using RS data, having been widely exploited in both military and civil fields. However, due to the characteristics of RS data such as high dimensionality and relatively small amounts of labeled samples available, performing RS image classification faces great scientific and practical challenges. In recent years, as new deep learning (DL) techniques emerge, approaches to RS image classification with DL have achieved significant breakthroughs, offering novel opportunities for the research and development of RS image classification. In this paper, a brief overview of typical DL models is presented first. This is followed by a systematic review of pixel‐wise and scene‐wise RS image classification approaches that are based on the use of DL. A comparative analysis regarding the performances of typical DL‐based RS methods is also provided. Finally, the challenges and potential directions for further research are discussed. This article is categorized under: Application Areas &gt; Science and Technology Technologies &gt; Classification",keywords:["Contextual image classification","Image","Deep learning","Curse of dimensionality","Data science"],concepts:["Contextual image classification","Image","Deep learning","Curse of dimensionality","Data science"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/widm.1264",is_oa:!0,n_refs:113,n_refs_in_core:7,degree:21,community:3,deg_w:312,betweenness:.0016,pagerank:.00723,eigenvector:.0245},{id:171,oaid:"W2604262106",doi:"10.1109/access.2017.2696121",title:"Smart Augmentation Learning an Optimal Data Augmentation Strategy",authors:[{name:"Joseph Lemley",institutions:["Ollscoil na Gaillimhe – University of Galway"]},{name:"Shabab Bazrafkan",institutions:["Ollscoil na Gaillimhe – University of Galway"]},{name:"Peter Corcoran",institutions:["Ollscoil na Gaillimhe – University of Galway"]}],authorString:"Joseph Lemley; Shabab Bazrafkan; Peter Corcoran",institutions:["Ollscoil na Gaillimhe – University of Galway"],countries:["IE"],year:2017,journal:"IEEE Access",citations:438,abstract:"A recurring problem faced when training neural networks is that there is typically not enough data to maximize the generalization capability of deep neural networks. There are many techniques to address this, including data augmentation, dropout, and transfer learning. In this paper, we introduce an additional method, which we call smart augmentation and we show how to use it to increase the accuracy and reduce over fitting on a target network. Smart augmentation works, by creating a network that learns how to generate augmented data during the training process of a target network in a way that reduces that networks loss. This allows us to learn augmentations that minimize the error of that network. Smart augmentation has shown the potential to increase accuracy by demonstrably significant measures on all data sets tested. In addition, it has shown potential to achieve similar or improved performance levels with significantly smaller network sizes in a number of tested cases.",keywords:["Dropout","Artificial neural network","Generalization","Transfer of learning","Process"],concepts:["Dropout","Artificial neural network","Generalization","Transfer of learning","Process"],pdf_url:"https://doi.org/10.1109/access.2017.2696121",is_oa:!0,n_refs:31,n_refs_in_core:2,degree:13,community:1,deg_w:72.5,betweenness:.0011,pagerank:.00241,eigenvector:.005},{id:172,oaid:"W3161335554",doi:"10.1016/j.ejmp.2021.04.016",title:"Artificial intelligence and machine learning for medical imaging: A technology review",authors:[{name:"Ana María Barragán Montero",institutions:["UCLouvain"]},{name:"Umair Javaid",institutions:[]},{name:"Gilmer Valdés",institutions:["University of California, San Francisco"]},{name:"Dan Nguyen",institutions:["Southwestern Medical Center","Southwestern Medical Center","The University of Texas Southwestern Medical Center"]},{name:"Paul Desbordes",institutions:[]},{name:"Benoît Macq",institutions:[]},{name:"Siri Willems",institutions:["Universitair Ziekenhuis Leuven","KU Leuven"]},{name:"Liesbeth Vandewinckele",institutions:["KU Leuven"]},{name:"Mats Holmström",institutions:["RaySearch Laboratories (Sweden)"]},{name:"Fredrik Löfman",institutions:["RaySearch Laboratories (Sweden)"]},{name:"Steven Michiels",institutions:[]},{name:"Kevin Souris",institutions:[]},{name:"Edmond Sterpin",institutions:["European Society for Therapeutic Radiology and Oncology","KU Leuven"]},{name:"John A. Lee",institutions:[]}],authorString:"Ana María Barragán Montero; Umair Javaid; Gilmer Valdés; Dan Nguyen; Paul Desbordes; Benoît Macq; Siri Willems; Liesbeth Vandewinckele; Mats Holmström; Fredrik Löfman; Steven Michiels; Kevin Souris et al.",institutions:["European Society for Therapeutic Radiology and Oncology","KU Leuven","RaySearch Laboratories (Sweden)","Southwestern Medical Center","The University of Texas Southwestern Medical Center","UCLouvain","Universitair Ziekenhuis Leuven","University of California, San Francisco"],countries:["BE","SE","US"],year:2021,journal:"Physica Medica",citations:433,abstract:"Artificial intelligence (AI) has recently become a very popular buzzword, as a consequence of disruptive technical advances and impressive experimental results, notably in the field of image analysis and processing. In medicine, specialties where images are central, like radiology, pathology or oncology, have seized the opportunity and considerable efforts in research and development have been deployed to transfer the potential of AI to clinical applications. With AI becoming a more mainstream tool for typical medical imaging analysis tasks, such as diagnosis, segmentation, or classification, the key for a safe and efficient use of clinical AI applications relies, in part, on informed practitioners. The aim of this review is to present the basic technological pillars of AI, together with the state-of-the-art machine learning methods and their application to medical imaging. In addition, we discuss the new trends and future research directions. This will help the reader to understand how AI methods are now becoming an ubiquitous tool in any medical image analysis workflow and pave the way for the clinical implementation of AI-based solutions.",keywords:["Workflow","Applications of artificial intelligence","Mainstream","Medical imaging","Field","Data science"],concepts:["Workflow","Applications of artificial intelligence","Mainstream","Medical imaging","Field","Data science"],pdf_url:"http://www.physicamedica.com/article/S1120179721001733/pdf",is_oa:!0,n_refs:302,n_refs_in_core:7,degree:21,community:1,deg_w:144,betweenness:.005,pagerank:.0039,eigenvector:.0167},{id:173,oaid:"W3128776197",doi:"10.3390/rs13030498",title:"Spatial-Spectral Transformer for Hyperspectral Image Classification",authors:[{name:"Xin He",institutions:["Harbin Institute of Technology"]},{name:"Yushi Chen",institutions:["Harbin Institute of Technology"]},{name:"Zhouhan Lin",institutions:["Shanghai Jiao Tong University"]}],authorString:"Xin He; Yushi Chen; Zhouhan Lin",institutions:["Harbin Institute of Technology","Shanghai Jiao Tong University"],countries:["CN"],year:2021,journal:"Remote Sensing",citations:433,abstract:"Recently, a great many deep convolutional neural network (CNN)-based methods have been proposed for hyperspectral image (HSI) classification. Although the proposed CNN-based methods have the advantages of spatial feature extraction, they are difficult to handle the sequential data with and CNNs are not good at modeling the long-range dependencies. However, the spectra of HSI are a kind of sequential data, and HSI usually contains hundreds of bands. Therefore, it is difficult for CNNs to handle HSI processing well. On the other hand, the Transformer model, which is based on an attention mechanism, has proved its advantages in processing sequential data. To address the issue of capturing relationships of sequential spectra in HSI in a long distance, in this study, Transformer is investigated for HSI classification. Specifically, in this study, a new classification framework titled spatial-spectral Transformer (SST) is proposed for HSI classification. In the proposed SST, a well-designed CNN is used to extract the spatial features, and a modified Transformer (a Transformer with dense connection, i.e., DenseTransformer) is proposed to capture sequential spectra relationships, and multilayer perceptron is used to finish the final classification task. Furthermore, dynamic feature augmentation, which aims to alleviate the overfitting problem and therefore generalize the model well, is proposed and added to the SST (SST-FA). In addition, to address the issue of limited training samples in HSI classification, transfer learning is combined with SST, and another classification framework titled transferring-SST (T-SST) is proposed. At last, to mitigate the overfitting problem and improve the classification accuracy, label smoothing is introduced for the T-SST-based classification framework (T-SST-L). The proposed SST, SST-FA, T-SST, and T-SST-L are tested on three widely used hyperspectral datasets. The obtained results reveal that the proposed models provide competitive results compared to the state-of-the-art methods, which shows that the concept of Transformer opens a new window for HSI classification.",keywords:["Overfitting","Hyperspectral imaging","Pattern recognition","Convolutional neural network","Transformer","Feature extraction"],concepts:["Overfitting","Hyperspectral imaging","Pattern recognition","Convolutional neural network","Transformer","Feature extraction"],pdf_url:"https://www.mdpi.com/2072-4292/13/3/498/pdf?version=1612254960",is_oa:!0,n_refs:53,n_refs_in_core:6,degree:12,community:3,deg_w:107,betweenness:6e-4,pagerank:.00314,eigenvector:.0044},{id:174,oaid:"W2884821113",doi:"10.3390/rs10071119",title:"Very Deep Convolutional Neural Networks for Complex Land Cover Mapping Using Multispectral Remote Sensing Imagery",authors:[{name:"Masoud Mahdianpari",institutions:["Memorial University of Newfoundland","Centre For Cold Ocean Resources Engineering"]},{name:"Bahram Salehi",institutions:["Memorial University of Newfoundland","Centre For Cold Ocean Resources Engineering"]},{name:"Mohammad Rezaee",institutions:["University of New Brunswick"]},{name:"Fariba Mohammadimanesh",institutions:["Memorial University of Newfoundland","Centre For Cold Ocean Resources Engineering"]},{name:"Yun Zhang",institutions:["University of New Brunswick"]}],authorString:"Masoud Mahdianpari; Bahram Salehi; Mohammad Rezaee; Fariba Mohammadimanesh; Yun Zhang",institutions:["Centre For Cold Ocean Resources Engineering","Memorial University of Newfoundland","University of New Brunswick"],countries:["CA"],year:2018,journal:"Remote Sensing",citations:433,abstract:"Despite recent advances of deep Convolutional Neural Networks (CNNs) in various computer vision tasks, their potential for classification of multispectral remote sensing images has not been thoroughly explored. In particular, the applications of deep CNNs using optical remote sensing data have focused on the classification of very high-resolution aerial and satellite data, owing to the similarity of these data to the large datasets in computer vision. Accordingly, this study presents a detailed investigation of state-of-the-art deep learning tools for classification of complex wetland classes using multispectral RapidEye optical imagery. Specifically, we examine the capacity of seven well-known deep convnets, namely DenseNet121, InceptionV3, VGG16, VGG19, Xception, ResNet50, and InceptionResNetV2, for wetland mapping in Canada. In addition, the classification results obtained from deep CNNs are compared with those based on conventional machine learning tools, including Random Forest and Support Vector Machine, to further evaluate the efficiency of the former to classify wetlands. The results illustrate that the full-training of convnets using five spectral bands outperforms the other strategies for all convnets. InceptionResNetV2, ResNet50, and Xception are distinguished as the top three convnets, providing state-of-the-art classification accuracies of 96.17%, 94.81%, and 93.57%, respectively. The classification accuracies obtained using Support Vector Machine (SVM) and Random Forest (RF) are 74.89% and 76.08%, respectively, considerably inferior relative to CNNs. Importantly, InceptionResNetV2 is consistently found to be superior compared to all other convnets, suggesting the integration of Inception and ResNet modules is an efficient architecture for classifying complex remote sensing scenes such as wetlands.",keywords:["Multispectral image","Convolutional neural network","Random forest","Support vector machine","Remote sensing","Deep learning"],concepts:["Multispectral image","Convolutional neural network","Random forest","Support vector machine","Remote sensing","Deep learning"],pdf_url:"https://www.mdpi.com/2072-4292/10/7/1119/pdf?version=1531542172",is_oa:!0,n_refs:50,n_refs_in_core:6,degree:22,community:3,deg_w:175,betweenness:.0019,pagerank:.0044,eigenvector:.0116},{id:175,oaid:"W3007283957",doi:"10.3389/fnins.2020.00119",title:"Enabling Spike-Based Backpropagation for Training Deep Neural Network Architectures",authors:[{name:"Chankyu Lee",institutions:["Purdue University West Lafayette"]},{name:"Syed Shakib Sarwar",institutions:["Purdue University West Lafayette"]},{name:"Priyadarshini Panda",institutions:["Purdue University West Lafayette"]},{name:"Gopalakrishnan Srinivasan",institutions:["Purdue University West Lafayette"]},{name:"Kaushik Roy",institutions:["Purdue University West Lafayette"]}],authorString:"Chankyu Lee; Syed Shakib Sarwar; Priyadarshini Panda; Gopalakrishnan Srinivasan; Kaushik Roy",institutions:["Purdue University West Lafayette"],countries:["US"],year:2020,journal:"Frontiers in Neuroscience",citations:431,abstract:"Spiking Neural Networks (SNNs) have recently emerged as a prominent neural computing paradigm. However, the typical shallow SNN architectures have limited capacity for expressing complex representations while training deep SNNs using input spikes has not been successful so far. Diverse methods have been proposed to get around this issue such as converting off-the-shelf trained deep Artificial Neural Networks (ANNs) to SNNs. However, the ANN-SNN conversion scheme fails to capture the temporal dynamics of a spiking system. On the other hand, it is still a difficult problem to directly train deep SNNs using input spike events due to the discontinuous, non-differentiable nature of the spike generation function. To overcome this problem, we propose an approximate derivative method that accounts for the leaky behavior of LIF neurons. This method enables training deep convolutional SNNs directly (with input spike events) using spike-based backpropagation. Our experiments show the effectiveness of the proposed spike-based learning on deep networks (VGG and Residual architectures) by achieving the best classification accuracies in MNIST, SVHN, and CIFAR-10 datasets compared to other SNNs trained with a spike-based learning. Moreover, we analyze sparse event-based computations to demonstrate the efficacy of the proposed SNN training method for inference operation in the spiking domain.",keywords:["Spiking neural network","Spike","MNIST database","Backpropagation","Deep learning","Artificial neural network"],concepts:["Spiking neural network","Spike","MNIST database","Backpropagation","Deep learning","Artificial neural network"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnins.2020.00119/pdf",is_oa:!0,n_refs:94,n_refs_in_core:7,degree:23,community:0,deg_w:204.5,betweenness:.0021,pagerank:.00541,eigenvector:.0111},{id:176,oaid:"W4322627364",doi:"10.1155/2023/8342104",title:"Deep Learning with Graph Convolutional Networks: An Overview and Latest Applications in Computational Intelligence",authors:[{name:"Uzair Aslam Bhatti",institutions:["Hainan University"]},{name:"Hao Tang",institutions:["Hainan University"]},{name:"Guilu Wu",institutions:["Hainan University"]},{name:"Shah Marjan",institutions:["Balochistan University of Information Technology, Engineering and Management Sciences"]},{name:"Aamir Hussain",institutions:["Muhammad Nawaz Shareef University of Agriculture"]}],authorString:"Uzair Aslam Bhatti; Hao Tang; Guilu Wu; Shah Marjan; Aamir Hussain",institutions:["Balochistan University of Information Technology, Engineering and Management Sciences","Hainan University","Muhammad Nawaz Shareef University of Agriculture"],countries:["CN","PK"],year:2023,journal:"International Journal of Intelligent Systems",citations:427,abstract:"Convolutional neural networks (CNNs) have received widespread attention due to their powerful modeling capabilities and have been successfully applied in natural language processing, image recognition, and other fields. On the other hand, traditional CNN can only deal with Euclidean spatial data. In contrast, many real‐life scenarios, such as transportation networks, social networks, reference networks, and so on, exist in graph data. The creation of graph convolution operators and graph pooling is at the heart of migrating CNN to graph data analysis and processing. With the advancement of the Internet and technology, graph convolution network (GCN), as an innovative technology in artificial intelligence (AI), has received more and more attention. GCN has been widely used in different fields such as image processing, intelligent recommender system, knowledge‐based graph, and other areas due to their excellent characteristics in processing non‐European spatial data. At the same time, communication networks have also embraced AI technology in recent years, and AI serves as the brain of the future network and realizes the comprehensive intelligence of the future grid. Many complex communication network problems can be abstracted as graph‐based optimization problems and solved by GCN, thus overcoming the limitations of traditional methods. This survey briefly describes the definition of graph‐based machine learning, introduces different types of graph networks, summarizes the application of GCN in various research fields, analyzes the research status, and gives the future research direction.",keywords:["Graph","Pooling","Convolutional neural network","Graph database","Power graph analysis","Deep learning"],concepts:["Graph","Pooling","Convolutional neural network","Graph database","Power graph analysis","Deep learning"],pdf_url:"https://downloads.hindawi.com/journals/ijis/2023/8342104.pdf",is_oa:!0,n_refs:151,n_refs_in_core:6,degree:13,community:5,deg_w:138,betweenness:.0013,pagerank:.00335,eigenvector:.0798},{id:177,oaid:"W2998571806",doi:"10.1038/s41467-019-13807-w",title:"De novo generation of hit-like molecules from gene expression signatures using artificial intelligence",authors:[{name:"Oscar Méndez‐Lucio",institutions:["Bayer (France)"]},{name:"Benoît Baillif",institutions:["Bayer (France)"]},{name:"Djork-Arné Clevert",institutions:["Bayer (Germany)"]},{name:"David Rouquié",institutions:["Bayer (France)"]},{name:"Joerg Wichard",institutions:["Bayer (Germany)"]}],authorString:"Oscar Méndez‐Lucio; Benoît Baillif; Djork-Arné Clevert; David Rouquié; Joerg Wichard",institutions:["Bayer (France)","Bayer (Germany)"],countries:["DE","FR"],year:2020,journal:"Nature Communications",citations:421,abstract:"Finding new molecules with a desired biological activity is an extremely difficult task. In this context, artificial intelligence and generative models have been used for molecular de novo design and compound optimization. Herein, we report a generative model that bridges systems biology and molecular design, conditioning a generative adversarial network with transcriptomic data. By doing so, we can automatically design molecules that have a high probability to induce a desired transcriptomic profile. As long as the gene expression signature of the desired state is provided, this model is able to design active-like molecules for desired targets without any previous target annotation of the training compounds. Molecules designed by this model are more similar to active compounds than the ones identified by similarity of gene expression signatures. Overall, this method represents an alternative approach to bridge chemistry and biology in the long and difficult road of drug discovery.",keywords:["Context","Computational biology","Synthetic biology","Generative grammar","Drug discovery","Similarity","Generative model"],concepts:["Context","Computational biology","Synthetic biology","Generative grammar","Drug discovery","Similarity","Generative model"],pdf_url:"https://www.nature.com/articles/s41467-019-13807-w.pdf",is_oa:!0,n_refs:62,n_refs_in_core:5,degree:11,community:2,deg_w:74,betweenness:.0015,pagerank:.00245,eigenvector:.0089},{id:178,oaid:"W3112951420",doi:"10.1002/med.21764",title:"Artificial intelligence and machine learning‐aided drug discovery in central nervous system diseases: State‐of‐the‐arts and future directions",authors:[{name:"Sezen Vatansever",institutions:["Icahn School of Medicine at Mount Sinai"]},{name:"Avner Schlessinger",institutions:["Icahn School of Medicine at Mount Sinai"]},{name:"Daniel Wacker",institutions:["Icahn School of Medicine at Mount Sinai"]},{name:"H. Ümit Kanıskan",institutions:["Tisch Hospital","Icahn School of Medicine at Mount Sinai"]},{name:"Jian Jin",institutions:["Tisch Hospital","Icahn School of Medicine at Mount Sinai"]},{name:"Ming‐Ming Zhou",institutions:["Tisch Hospital","Icahn School of Medicine at Mount Sinai"]},{name:"Bin Zhang",institutions:["Icahn School of Medicine at Mount Sinai"]}],authorString:"Sezen Vatansever; Avner Schlessinger; Daniel Wacker; H. Ümit Kanıskan; Jian Jin; Ming‐Ming Zhou; Bin Zhang",institutions:["Icahn School of Medicine at Mount Sinai","Tisch Hospital"],countries:["US"],year:2020,journal:"Medicinal Research Reviews",citations:417,abstract:"Neurological disorders significantly outnumber diseases in other therapeutic areas. However, developing drugs for central nervous system (CNS) disorders remains the most challenging area in drug discovery, accompanied with the long timelines and high attrition rates. With the rapid growth of biomedical data enabled by advanced experimental technologies, artificial intelligence (AI) and machine learning (ML) have emerged as an indispensable tool to draw meaningful insights and improve decision making in drug discovery. Thanks to the advancements in AI and ML algorithms, now the AI/ML-driven solutions have an unprecedented potential to accelerate the process of CNS drug discovery with better success rate. In this review, we comprehensively summarize AI/ML-powered pharmaceutical discovery efforts and their implementations in the CNS area. After introducing the AI/ML models as well as the conceptualization and data preparation, we outline the applications of AI/ML technologies to several key procedures in drug discovery, including target identification, compound screening, hit/lead generation and optimization, drug response and synergy prediction, de novo drug design, and drug repurposing. We review the current state-of-the-art of AI/ML-guided CNS drug discovery, focusing on blood-brain barrier permeability prediction and implementation into therapeutic discovery for neurological diseases. Finally, we discuss the major challenges and limitations of current approaches and possible future directions that may provide resolutions to these difficulties.",keywords:["Drug discovery","Drug repositioning","Repurposing","Drug"],concepts:["Drug discovery","Drug repositioning","Repurposing","Drug"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/med.21764",is_oa:!0,n_refs:481,n_refs_in_core:9,degree:20,community:2,deg_w:174.5,betweenness:.0028,pagerank:.00467,eigenvector:.0223},{id:179,oaid:"W3037640242",doi:"10.1109/access.2020.3008036",title:"Deep Learning for Change Detection in Remote Sensing Images: Comprehensive Review and Meta-Analysis",authors:[{name:"Lazhar Khelifi",institutions:[]},{name:"Max Mignotte",institutions:[]}],authorString:"Lazhar Khelifi; Max Mignotte",institutions:[],countries:[],year:2020,journal:"IEEE Access",citations:414,abstract:"Deep learning (DL) algorithms are considered as a methodology of choice for remote-sensing image analysis over the past few years. Due to its effective applications, deep learning has also been introduced for automatic change detection and achieved great success. The present study attempts to provide a comprehensive review and a meta-analysis of the recent progress in this subfield. Specifically, we first introduce the fundamentals of deep learning methods which are frequently adopted for change detection. Secondly, we present the details of the meta-analysis conducted to examine the status of change detection DL studies. Then, we focus on deep learning-based change detection methodologies for remote sensing images by giving a general overview of the existing methods. Specifically, these deep learning-based methods were classified into three groups; fully supervised learning-based methods, fully unsupervised learning-based methods and transfer learning-based techniques. As a result of these investigations, promising new directions were identified for future research. This study will contribute in several ways to our understanding of deep learning for change detection and will provide a basis for further research. Some source codes of the methods discussed in this paper are available from: https://github.com/lazharkhelifi/deeplearning_changedetection_remotesensing_review.",keywords:["Deep learning","Change detection","Transfer of learning","Focus","Unsupervised learning"],concepts:["Deep learning","Change detection","Transfer of learning","Focus","Unsupervised learning"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/8948470/09136674.pdf",is_oa:!0,n_refs:145,n_refs_in_core:7,degree:21,community:3,deg_w:196.5,betweenness:.0035,pagerank:.00497,eigenvector:.0182},{id:180,oaid:"W3020975691",doi:"10.1613/jair.1.13200",title:"Explainable Deep Learning: A Field Guide for the Uninitiated",authors:[{name:"Gabriëlle Ras",institutions:["Radboud University Nijmegen"]},{name:"Ning Xie",institutions:["Seattle University"]},{name:"Marcel van Gerven",institutions:["Radboud University Nijmegen"]},{name:"Derek Doran",institutions:["Tenet 3 (United States)"]}],authorString:"Gabriëlle Ras; Ning Xie; Marcel van Gerven; Derek Doran",institutions:["Radboud University Nijmegen","Seattle University","Tenet 3 (United States)"],countries:["NL","US"],year:2022,journal:"Journal of Artificial Intelligence Research",citations:413,abstract:"Deep neural networks (DNNs) are an indispensable machine learning tool despite the difficulty of diagnosing what aspects of a model’s input drive its decisions. In countless real-world domains, from legislation and law enforcement to healthcare, such diagnosis is essential to ensure that DNN decisions are driven by aspects appropriate in the context of its use. The development of methods and studies enabling the explanation of a DNN’s decisions has thus blossomed into an active and broad area of research. The field’s complexity is exacerbated by competing definitions of what it means “to explain” the actions of a DNN and to evaluate an approach’s “ability to explain”. This article offers a field guide to explore the space of explainable deep learning for those in the AI/ML field who are uninitiated. The field guide: i) Introduces three simple dimensions defining the space of foundational methods that contribute to explainable deep learning, ii) discusses the evaluations for model explanations, iii) places explainability in the context of other related deep learning research areas, and iv) discusses user-oriented explanation design and future directions. We hope the guide is seen as a starting point for those embarking on this research field.",keywords:["Field","Deep learning","Context","Deep neural networks","Space","Legislation"],concepts:["Field","Deep learning","Context","Deep neural networks","Space","Legislation"],pdf_url:"https://www.jair.org/index.php/jair/article/download/13200/26763",is_oa:!0,n_refs:372,n_refs_in_core:7,degree:21,community:4,deg_w:451,betweenness:.0038,pagerank:.00876,eigenvector:.2085},{id:181,oaid:"W3159156584",doi:"10.1021/acs.chemrev.0c01195",title:"Unsupervised Learning Methods for Molecular Simulation Data",authors:[{name:"Aldo Glielmo",institutions:["Scuola Internazionale Superiore di Studi Avanzati"]},{name:"Brooke E. Husic",institutions:["Freie Universität Berlin"]},{name:"Álex Rodríguez",institutions:["The Abdus Salam International Centre for Theoretical Physics (ICTP)"]},{name:"Cecilia Clementi",institutions:["Rice University","Freie Universität Berlin"]},{name:"Frank Noé",institutions:["Rice University","Freie Universität Berlin"]},{name:"Alessandro Laio",institutions:["The Abdus Salam International Centre for Theoretical Physics (ICTP)","Scuola Internazionale Superiore di Studi Avanzati"]}],authorString:"Aldo Glielmo; Brooke E. Husic; Álex Rodríguez; Cecilia Clementi; Frank Noé; Alessandro Laio",institutions:["Freie Universität Berlin","Rice University","Scuola Internazionale Superiore di Studi Avanzati","The Abdus Salam International Centre for Theoretical Physics (ICTP)"],countries:["DE","IT","US"],year:2021,journal:"Chemical Reviews",citations:409,abstract:". We divide our discussion into self-contained sections, each discussing a specific method. In each section, we briefly touch upon the mathematical and algorithmic foundations of the method, highlight its strengths and limitations, and describe the specific ways in which it has been used-or can be used-to analyze molecular simulation data.",keywords:["Cluster analysis","Dimensionality reduction","Unsupervised learning","Representation","Field","Feature","Curse of dimensionality"],concepts:["Cluster analysis","Dimensionality reduction","Unsupervised learning","Representation","Field","Feature","Curse of dimensionality"],pdf_url:"https://doi.org/10.1021/acs.chemrev.0c01195",is_oa:!0,n_refs:436,n_refs_in_core:6,degree:21,community:2,deg_w:190,betweenness:.0095,pagerank:.00427,eigenvector:.0593},{id:182,oaid:"W3125860323",doi:"10.3390/rs12030582",title:"Classification of Hyperspectral Image Based on Double-Branch Dual-Attention Mechanism Network",authors:[{name:"Rui Li",institutions:["Wuhan University"]},{name:"Shunyi Zheng",institutions:["Wuhan University"]},{name:"Chenxi Duan",institutions:["Wuhan University","State Key Laboratory of Information Engineering in Surveying Mapping and Remote Sensing"]},{name:"Yang Yang",institutions:["Wuhan University"]},{name:"Xiqi Wang",institutions:["Wuhan University"]}],authorString:"Rui Li; Shunyi Zheng; Chenxi Duan; Yang Yang; Xiqi Wang",institutions:["State Key Laboratory of Information Engineering in Surveying Mapping and Remote Sensing","Wuhan University"],countries:["CN"],year:2020,journal:"Remote Sensing",citations:405,abstract:"In recent years, researchers have paid increasing attention on hyperspectral image (HSI) classification using deep learning methods. To improve the accuracy and reduce the training samples, we propose a double-branch dual-attention mechanism network (DBDA) for HSI classification in this paper. Two branches are designed in DBDA to capture plenty of spectral and spatial features contained in HSI. Furthermore, a channel attention block and a spatial attention block are applied to these two branches respectively, which enables DBDA to refine and optimize the extracted feature maps. A series of experiments on four hyperspectral datasets show that the proposed framework has superior performance to the state-of-the-art algorithm, especially when the training samples are signally lacking.",keywords:["Hyperspectral imaging","Block","Dual","Pattern recognition","Feature","Image"],concepts:["Hyperspectral imaging","Block","Dual","Pattern recognition","Feature","Image"],pdf_url:"https://www.mdpi.com/2072-4292/12/3/582/pdf?version=1581509105",is_oa:!0,n_refs:54,n_refs_in_core:6,degree:15,community:3,deg_w:103,betweenness:.0011,pagerank:.00302,eigenvector:.0057},{id:183,oaid:"W3122028341",doi:"10.1109/jstars.2021.3133021",title:"Hyperspectral Image Classification—Traditional to Deep Models: A Survey for Future Prospects",authors:[{name:"Muhammad Ahmad",institutions:["University of Messina","National University of Computer and Emerging Sciences"]},{name:"Sidrah Shabbir",institutions:["Khwaja Fareed University of Engineering and Information Technology"]},{name:"Swalpa Kumar Roy",institutions:[]},{name:"Danfeng Hong",institutions:["Chinese Academy of Sciences","Aerospace Information Research Institute"]},{name:"Xin Wu",institutions:["Beijing Institute of Technology"]},{name:"Jing Yao",institutions:["Chinese Academy of Sciences","Aerospace Information Research Institute"]},{name:"Adil Khan",institutions:["Innopolis University"]},{name:"Manuel Mazzara",institutions:["Innopolis University"]},{name:"Salvatore Distefano",institutions:["University of Messina"]},{name:"Jocelyn Chanussot",institutions:["Institut polytechnique de Grenoble","Centre National de la Recherche Scientifique","GIPSA-Lab","Université Grenoble Alpes"]}],authorString:"Muhammad Ahmad; Sidrah Shabbir; Swalpa Kumar Roy; Danfeng Hong; Xin Wu; Jing Yao; Adil Khan; Manuel Mazzara; Salvatore Distefano; Jocelyn Chanussot",institutions:["Aerospace Information Research Institute","Beijing Institute of Technology","Centre National de la Recherche Scientifique","Chinese Academy of Sciences","GIPSA-Lab","Innopolis University","Institut polytechnique de Grenoble","Khwaja Fareed University of Engineering and Information Technology","National University of Computer and Emerging Sciences","University of Messina","Université Grenoble Alpes"],countries:["CN","FR","IT","PK","RU"],year:2021,journal:"IEEE Journal of Selected Topics in Applied Earth Observations and Remote Sensing",citations:400,abstract:"Hyperspectral imaging (HSI) has been extensively utilized in many real-life applications because it benefits from the detailed spectral information contained in each pixel. Notably, the complex characteristics, i.e., the nonlinear relation among the captured spectral information and the corresponding object of HSI data, make accurate classification challenging for traditional methods. In the last few years, deep learning (DL) has been substantiated as a powerful feature extractor that effectively addresses the nonlinear problems that appeared in a number of computer vision tasks. This prompts the deployment of DL for HSI classification (HSIC) which revealed good performance. This survey enlists a systematic overview of DL for HSIC and compared state-of-the-art strategies of the said topic. Primarily, we will encapsulate the main challenges of TML for HSIC and then we will acquaint the superiority of DL to address these problems. This article breaks down the state-of-the-art DL frameworks into spectral-features, spatial-features, and together spatial–spectral features to systematically analyze the achievements (future research directions as well) of these frameworks for HSIC. Moreover, we will consider the fact that DL requires a large number of labeled training examples whereas acquiring such a number for HSIC is challenging in terms of time and cost. Therefore, this survey discusses some strategies to improve the generalization performance of DL strategies which can provide some future guidelines.",keywords:["Hyperspectral imaging","Contextual image classification","Remote sensing","Computer vision","Pattern recognition","Image"],concepts:["Hyperspectral imaging","Contextual image classification","Remote sensing","Computer vision","Pattern recognition","Image"],pdf_url:"https://ieeexplore.ieee.org/ielx7/4609443/9656571/09645266.pdf",is_oa:!0,n_refs:373,n_refs_in_core:14,degree:28,community:3,deg_w:339,betweenness:.0056,pagerank:.00824,eigenvector:.0198},{id:184,oaid:"W4225000412",doi:"10.1038/s41524-022-00765-z",title:"Accelerating materials discovery using artificial intelligence, high performance computing and robotics",authors:[{name:"Edward O. Pyzer‐Knapp",institutions:["Sci-Tech Daresbury"]},{name:"Jed W. Pitera",institutions:["IBM Research - Almaden"]},{name:"Peter Staar",institutions:["IBM Research - Zurich"]},{name:"Seiji Takeda",institutions:["IBM Research - Tokyo"]},{name:"Teodoro Laino",institutions:["IBM Research - Zurich"]},{name:"Daniel P. Sanders",institutions:["IBM Research - Almaden"]},{name:"James Sexton",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"John R. Smith",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Alessandro Curioni",institutions:["IBM Research - Zurich"]}],authorString:"Edward O. Pyzer‐Knapp; Jed W. Pitera; Peter Staar; Seiji Takeda; Teodoro Laino; Daniel P. Sanders; James Sexton; John R. Smith; Alessandro Curioni",institutions:["IBM Research - Almaden","IBM Research - Thomas J. Watson Research Center","IBM Research - Tokyo","IBM Research - Zurich","Sci-Tech Daresbury"],countries:["CH","GB","JP","US"],year:2022,journal:"npj Computational Materials",citations:395,abstract:"Abstract New tools enable new ways of working, and materials science is no exception. In materials discovery, traditional manual, serial, and human-intensive work is being augmented by automated, parallel, and iterative processes driven by Artificial Intelligence (AI), simulation and experimental automation. In this perspective, we describe how these new capabilities enable the acceleration and enrichment of each stage of the discovery cycle. We show, using the example of the development of a novel chemically amplified photoresist, how these technologies’ impacts are amplified when they are used in concert with each other as powerful, heterogeneous workflows.",keywords:["Workflow","Automation","Robotics","Robot","Database"],concepts:["Workflow","Automation","Robotics"],pdf_url:"https://www.nature.com/articles/s41524-022-00765-z.pdf",is_oa:!0,n_refs:81,n_refs_in_core:6,degree:10,community:2,deg_w:50,betweenness:2e-4,pagerank:.00172,eigenvector:.0133},{id:185,oaid:"W4206569030",doi:"10.1145/3510413",title:"Avoiding Overfitting: A Survey on Regularization Methods for Convolutional Neural Networks",authors:[{name:"Claudio Filipi Gonçalves dos Santos",institutions:["Universidade Federal de São Carlos"]},{name:"João Paulo Papa",institutions:["Universidade Estadual Paulista (Unesp)"]}],authorString:"Claudio Filipi Gonçalves dos Santos; João Paulo Papa",institutions:["Universidade Estadual Paulista (Unesp)","Universidade Federal de São Carlos"],countries:["BR"],year:2022,journal:"ACM Computing Surveys",citations:392,abstract:"Several image processing tasks, such as image classification and object detection, have been significantly improved using Convolutional Neural Networks (CNN). Like ResNet and EfficientNet, many architectures have achieved outstanding results in at least one dataset by the time of their creation. A critical factor in training concerns the network’s regularization, which prevents the structure from overfitting. This work analyzes several regularization methods developed in the past few years, showing significant improvements for different CNN models. The works are classified into three main areas: the first one is called “data augmentation,” where all the techniques focus on performing changes in the input data. The second, named “internal changes,” aims to describe procedures to modify the feature maps generated by the neural network or the kernels. The last one, called “label,” concerns transforming the labels of a given input. This work presents two main differences comparing to other available surveys about regularization: (i) the first concerns the papers gathered in the manuscript, which are not older than five years, and (ii) the second distinction is about reproducibility, i.e., all works referred here have their code available in public repositories or they have been directly implemented in some framework, such as TensorFlow or Torch.",keywords:["Overfitting","Convolutional neural network","Regularization","Pattern recognition","Artificial neural network"],concepts:["Overfitting","Convolutional neural network","Regularization","Pattern recognition","Artificial neural network"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3510413",is_oa:!0,n_refs:100,n_refs_in_core:7,degree:21,community:1,deg_w:208,betweenness:.0021,pagerank:.00526,eigenvector:.0183},{id:186,oaid:"W2955365692",doi:"10.3389/fpls.2019.00941",title:"Convolutional Neural Networks for the Automatic Identification of Plant Diseases",authors:[{name:"Justine Boulent",institutions:["Université de Sherbrooke","Computer Research Institute of Montréal"]},{name:"Samuel Foucher",institutions:["Computer Research Institute of Montréal"]},{name:"Jérôme Théau",institutions:["Université de Sherbrooke"]},{name:"Pierre-Luc St-Charles",institutions:["Computer Research Institute of Montréal"]}],authorString:"Justine Boulent; Samuel Foucher; Jérôme Théau; Pierre-Luc St-Charles",institutions:["Computer Research Institute of Montréal","Université de Sherbrooke"],countries:["CA"],year:2019,journal:"Frontiers in Plant Science",citations:388,abstract:"Deep learning techniques, and in particular Convolutional Neural Networks (CNNs), have led to significant progress in image processing. Since 2016, many applications for the automatic identification of crop diseases have been developed. These applications could serve as a basis for the development of expertise assistance or automatic screening tools. Such tools could contribute to more sustainable agricultural practices and greater food production security. To assess the potential of these networks for such applications, we survey 19 studies that relied on CNNs to automatically identify crop diseases. We describe their profiles, their main implementation aspects and their performance. Our survey allows us to identify the major issues and shortcomings of works in this research area. We also provide guidelines to improve the use of CNNs in operational contexts as well as some directions for future research.",keywords:["Convolutional neural network","Identification","Deep learning","Data science","Food security"],concepts:["Convolutional neural network","Identification","Deep learning","Data science","Food security"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fpls.2019.00941/pdf",is_oa:!0,n_refs:67,n_refs_in_core:6,degree:13,community:3,deg_w:131.5,betweenness:.0026,pagerank:.00392,eigenvector:.0036},{id:187,oaid:"W4296612997",doi:"10.1038/s41524-022-00884-7",title:"Explainable machine learning in materials science",authors:[{name:"Xiaoting Zhong",institutions:["Lawrence Livermore National Laboratory"]},{name:"Brian Gallagher",institutions:["Lawrence Livermore National Laboratory"]},{name:"Shusen Liu",institutions:["Lawrence Livermore National Laboratory"]},{name:"Bhavya Kailkhura",institutions:["Lawrence Livermore National Laboratory"]},{name:"Anna M. Hiszpanski",institutions:["Lawrence Livermore National Laboratory"]},{name:"T. Yong-Jin Han",institutions:["Lawrence Livermore National Laboratory"]}],authorString:"Xiaoting Zhong; Brian Gallagher; Shusen Liu; Bhavya Kailkhura; Anna M. Hiszpanski; T. Yong-Jin Han",institutions:["Lawrence Livermore National Laboratory"],countries:["US"],year:2022,journal:"npj Computational Materials",citations:386,abstract:"Abstract Machine learning models are increasingly used in materials studies because of their exceptional accuracy. However, the most accurate machine learning models are usually difficult to explain. Remedies to this problem lie in explainable artificial intelligence (XAI), an emerging research field that addresses the explainability of complicated machine learning models like deep neural networks (DNNs). This article attempts to provide an entry point to XAI for materials scientists. Concepts are defined to clarify what explain means in the context of materials science. Example works are reviewed to show how XAI helps materials science research. Challenges and opportunities are also discussed.",keywords:["Field","Context","Point","Artificial neural network","Data science"],concepts:["Field","Context","Point","Artificial neural network","Data science"],pdf_url:"https://www.nature.com/articles/s41524-022-00884-7.pdf",is_oa:!0,n_refs:132,n_refs_in_core:8,degree:22,community:4,deg_w:236,betweenness:.0049,pagerank:.0049,eigenvector:.1129},{id:188,oaid:"W4387409844",doi:"10.1126/sciadv.adi1480",title:"SpikingJelly: An open-source machine learning infrastructure platform for spike-based intelligence",authors:[{name:"Wei Fang",institutions:["Peking University","Peng Cheng Laboratory"]},{name:"Yanqi Chen",institutions:["Peking University","Peng Cheng Laboratory"]},{name:"Jianhao Ding",institutions:["Peking University"]},{name:"Zhaofei Yu",institutions:["Peking University","Beijing Academy of Artificial Intelligence"]},{name:"Timothée Masquelier",institutions:["Centre National de la Recherche Scientifique","Centre de recherche cerveau et cognition"]},{name:"Ding Chen",institutions:["Shanghai Jiao Tong University","Peng Cheng Laboratory"]},{name:"Liwei Huang",institutions:["Peking University","Peng Cheng Laboratory"]},{name:"Huihui Zhou",institutions:["Peng Cheng Laboratory"]},{name:"Guoqi Li",institutions:["Chinese Academy of Sciences","Institute of Automation","University of Chinese Academy of Sciences"]},{name:"Yonghong Tian",institutions:["Peking University","Peng Cheng Laboratory"]}],authorString:"Wei Fang; Yanqi Chen; Jianhao Ding; Zhaofei Yu; Timothée Masquelier; Ding Chen; Liwei Huang; Huihui Zhou; Guoqi Li; Yonghong Tian",institutions:["Beijing Academy of Artificial Intelligence","Centre National de la Recherche Scientifique","Centre de recherche cerveau et cognition","Chinese Academy of Sciences","Institute of Automation","Peking University","Peng Cheng Laboratory","Shanghai Jiao Tong University","University of Chinese Academy of Sciences"],countries:["CN","FR"],year:2023,journal:"Science Advances",citations:383,abstract:"Spiking neural networks (SNNs) aim to realize brain-inspired intelligence on neuromorphic chips with high energy efficiency by introducing neural dynamics and spike properties. As the emerging spiking deep learning paradigm attracts increasing interest, traditional programming frameworks cannot meet the demands of the automatic differentiation, parallel computation acceleration, and high integration of processing neuromorphic datasets and deployment. In this work, we present the SpikingJelly framework to address the aforementioned dilemma. We contribute a full-stack toolkit for preprocessing neuromorphic datasets, building deep SNNs, optimizing their parameters, and deploying SNNs on neuromorphic chips. Compared to existing methods, the training of deep SNNs can be accelerated 11×, and the superior extensibility and flexibility of SpikingJelly enable users to accelerate custom models at low costs through multilevel inheritance and semiautomatic code generation. SpikingJelly paves the way for synthesizing truly energy-efficient SNN-based machine intelligence systems, which will enrich the ecology of neuromorphic computing.",keywords:["Neuromorphic engineering","Spiking neural network","Spike","Computer architecture","Artificial neural network","Flexibility"],concepts:["Neuromorphic engineering","Spiking neural network","Spike","Computer architecture","Artificial neural network","Flexibility"],pdf_url:"https://www.science.org/doi/pdf/10.1126/sciadv.adi1480?download=true",is_oa:!0,n_refs:149,n_refs_in_core:6,degree:20,community:0,deg_w:135,betweenness:.0051,pagerank:.00382,eigenvector:.0077},{id:189,oaid:"W4309490745",doi:"10.1007/s10462-022-10306-1",title:"Deep learning in drug discovery: an integrative review and future challenges",authors:[{name:"Heba Askr",institutions:["University of Sadat City"]},{name:"Enas Elgeldawi",institutions:["Minia University"]},{name:"Heba Aboul Ella",institutions:[]},{name:"Yaseen A. M. M. Elshaier",institutions:["University of Sadat City"]},{name:"Mamdouh M. Gomaa",institutions:["Minia University"]},{name:"Aboul Ella Hassanien",institutions:["Cairo University"]}],authorString:"Heba Askr; Enas Elgeldawi; Heba Aboul Ella; Yaseen A. M. M. Elshaier; Mamdouh M. Gomaa; Aboul Ella Hassanien",institutions:["Cairo University","Minia University","University of Sadat City"],countries:["EG"],year:2022,journal:"Artificial Intelligence Review",citations:380,abstract:"Recently, using artificial intelligence (AI) in drug discovery has received much attention since it significantly shortens the time and cost of developing new drugs. Deep learning (DL)-based approaches are increasingly being used in all stages of drug development as DL technology advances, and drug-related data grows. Therefore, this paper presents a systematic Literature review (SLR) that integrates the recent DL technologies and applications in drug discovery Including, drug-target interactions (DTIs), drug-drug similarity interactions (DDIs), drug sensitivity and responsiveness, and drug-side effect predictions. We present a review of more than 300 articles between 2000 and 2022. The benchmark data sets, the databases, and the evaluation measures are also presented. In addition, this paper provides an overview of how explainable AI (XAI) supports drug discovery problems. The drug dosing optimization and success stories are discussed as well. Finally, digital twining (DT) and open issues are suggested as future research challenges for drug discovery problems. Challenges to be addressed, future research directions are identified, and an extensive bibliography is also included.",keywords:["Drug discovery","Drug","Data science","Benchmark","Drug repositioning"],concepts:["Drug discovery","Drug","Data science","Benchmark","Drug repositioning"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10462-022-10306-1.pdf",is_oa:!0,n_refs:265,n_refs_in_core:8,degree:22,community:2,deg_w:130,betweenness:.0088,pagerank:.0034,eigenvector:.0366},{id:190,oaid:"W2944248482",doi:"10.3390/jimaging5050052",title:"Deep Learning Meets Hyperspectral Image Analysis: A Multidisciplinary Review",authors:[{name:"Alberto Signoroni",institutions:["University of Brescia"]},{name:"Mattia Savardi",institutions:["University of Brescia"]},{name:"Annalisa Baronio",institutions:["University of Brescia"]},{name:"Sergio Benini",institutions:["University of Brescia"]}],authorString:"Alberto Signoroni; Mattia Savardi; Annalisa Baronio; Sergio Benini",institutions:["University of Brescia"],countries:["IT"],year:2019,journal:"Journal of Imaging",citations:378,abstract:"Modern hyperspectral imaging systems produce huge datasets potentially conveying a great abundance of information; such a resource, however, poses many challenges in the analysis and interpretation of these data. Deep learning approaches certainly offer a great variety of opportunities for solving classical imaging tasks and also for approaching new stimulating problems in the spatial-spectral domain. This is fundamental in the driving sector of Remote Sensing where hyperspectral technology was born and has mostly developed, but it is perhaps even more true in the multitude of current and evolving application sectors that involve these imaging technologies. The present review develops on two fronts: on the one hand, it is aimed at domain professionals who want to have an updated overview on how hyperspectral acquisition techniques can combine with deep learning architectures to solve specific tasks in different application fields. On the other hand, we want to target the machine learning and computer vision experts by giving them a picture of how deep learning technologies are applied to hyperspectral data from a multidisciplinary perspective. The presence of these two viewpoints and the inclusion of application fields other than Remote Sensing are the original contributions of this review, which also highlights some potentialities and critical issues related to the observed development trends.",keywords:["Hyperspectral imaging","Viewpoints","Data science","Multidisciplinary approach","Deep learning","Resource"],concepts:["Hyperspectral imaging","Viewpoints","Data science","Multidisciplinary approach","Deep learning","Resource"],pdf_url:"https://www.mdpi.com/2313-433X/5/5/52/pdf?version=1557308159",is_oa:!0,n_refs:241,n_refs_in_core:7,degree:24,community:3,deg_w:344,betweenness:.005,pagerank:.00819,eigenvector:.0188},{id:191,oaid:"W2895420596",doi:"10.3390/molecules23102520",title:"Artificial Intelligence in Drug Design",authors:[{name:"Gerhard Heßler",institutions:[]},{name:"Karl‐Heinz Baringhaus",institutions:[]}],authorString:"Gerhard Heßler; Karl‐Heinz Baringhaus",institutions:[],countries:[],year:2018,journal:"Molecules",citations:376,abstract:"Artificial Intelligence (AI) plays a pivotal role in drug discovery. In particular artificial neural networks such as deep neural networks or recurrent networks drive this area. Numerous applications in property or activity predictions like physicochemical and ADMET properties have recently appeared and underpin the strength of this technology in quantitative structure-property relationships (QSPR) or quantitative structure-activity relationships (QSAR). Artificial intelligence in de novo design drives the generation of meaningful new biologically active molecules towards desired properties. Several examples establish the strength of artificial intelligence in this field. Combination with synthesis planning and ease of synthesis is feasible and more and more automated drug discovery by computers is expected in the near future.",keywords:["Quantitative structure–activity relationship","Artificial neural network","Drug discovery","Field","Property"],concepts:["Quantitative structure–activity relationship","Artificial neural network","Drug discovery","Field","Property"],pdf_url:"https://www.mdpi.com/1420-3049/23/10/2520/pdf?version=1538461983",is_oa:!0,n_refs:81,n_refs_in_core:7,degree:18,community:2,deg_w:183.5,betweenness:.0037,pagerank:.00481,eigenvector:.0245},{id:192,oaid:"W2978707075",doi:"10.1038/s41467-020-19964-7",title:"Predicting materials properties without crystal structure: deep representation learning from stoichiometry",authors:[{name:"Rhys E. A. Goodall",institutions:["University of Cambridge"]},{name:"Alpha A. Lee",institutions:["University of Cambridge"]}],authorString:"Rhys E. A. Goodall; Alpha A. Lee",institutions:["University of Cambridge"],countries:["GB"],year:2020,journal:"Nature Communications",citations:372,abstract:"Machine learning has the potential to accelerate materials discovery by accurately predicting materials properties at a low computational cost. However, the model inputs remain a key stumbling block. Current methods typically use descriptors constructed from knowledge of either the full crystal structure - therefore only applicable to materials with already characterised structures - or structure-agnostic fixed-length representations hand-engineered from the stoichiometry. We develop a machine learning approach that takes only the stoichiometry as input and automatically learns appropriate and systematically improvable descriptors from data. Our key insight is to treat the stoichiometric formula as a dense weighted graph between elements. Compared to the state of the art for structure-agnostic methods, our approach achieves lower errors with less data.",keywords:["Stoichiometry","Representation","Block","Key","Graph"],concepts:["Stoichiometry","Representation","Block","Key","Graph"],pdf_url:"https://www.nature.com/articles/s41467-020-19964-7.pdf",is_oa:!0,n_refs:82,n_refs_in_core:5,degree:22,community:2,deg_w:227,betweenness:.0058,pagerank:.00489,eigenvector:.091},{id:193,oaid:"W2567534979",doi:"10.18632/oncotarget.14073",title:"The cornucopia of meaningful leads: Applying deep adversarial autoencoders for new molecule development in oncology",authors:[{name:"Artur Kadurin",institutions:["Russian Academy of Sciences","Johns Hopkins University","Kazan Federal University","St. Petersburg Department of Steklov Institute of Mathematics","Steklov Mathematical Institute"]},{name:"Alexander Aliper",institutions:["Johns Hopkins University"]},{name:"Andrey Kazennov",institutions:["Johns Hopkins University","Moscow Institute of Physics and Technology"]},{name:"Polina Mamoshina",institutions:["Johns Hopkins University","University of Oxford"]},{name:"Quentin Vanhaelen",institutions:["Johns Hopkins University"]},{name:"Kuzma Khrabrov",institutions:[]},{name:"Alex Zhavoronkov",institutions:["Johns Hopkins University","Moscow Institute of Physics and Technology","Urology Foundation"]}],authorString:"Artur Kadurin; Alexander Aliper; Andrey Kazennov; Polina Mamoshina; Quentin Vanhaelen; Kuzma Khrabrov; Alex Zhavoronkov",institutions:["Johns Hopkins University","Kazan Federal University","Moscow Institute of Physics and Technology","Russian Academy of Sciences","St. Petersburg Department of Steklov Institute of Mathematics","Steklov Mathematical Institute","University of Oxford","Urology Foundation"],countries:["GB","RU","US"],year:2016,journal:"Oncotarget",citations:368,abstract:"// Artur Kadurin 1, 2, 3, 4 , Alexander Aliper 2 , Andrey Kazennov 2, 7 , Polina Mamoshina 2, 5 , Quentin Vanhaelen 2 , Kuzma Khrabrov 1 , Alex Zhavoronkov 2, 6, 7 1 Search Department, Mail.Ru Group Ltd., Moscow, Russia 2 Pharmaceutical Artificial Intelligence Department, Insilico Medicine, Inc., Emerging Technology Centers, Johns Hopkins University at Eastern, Baltimore, Maryland, USA 3 Big Data and Text Analysis Laboratory, Kazan Federal University, Kazan, Republic of Tatarstan, Russia 4 St. Petersburg Department of V.A. Steklov Institute of Mathematics of the Russian Academy of Sciences, Petersburg, Russia 5 Department of Computer Science, University of Oxford, Oxford, UK 6 The Biogerontology Research Foundation, Trevissome Park, Truro TR4 8UN, UK 7 Moscow Institute of Physics and Technology, Dolgoprudny, Russia Correspondence to: Alex Zhavoronkov, email: alex@insilicomedicine.com Keywords: generative adversarian networks, adversarial autoencoder, deep learning, drug discovery, artificial intelligence Received: June 14, 2016&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Accepted: November 24, 2016&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Published: December 22, 2016 ABSTRACT Recent advances in deep learning and specifically in generative adversarial networks have demonstrated surprising results in generating new images and videos upon request even using natural language as input. In this paper we present the first application of generative adversarial autoencoders (AAE) for generating novel molecular fingerprints with a defined set of parameters. We developed a 7-layer AAE architecture with the latent middle layer serving as a discriminator. As an input and output the AAE uses a vector of binary fingerprints and concentration of the molecule. In the latent layer we also introduced a neuron responsible for growth inhibition percentage, which when negative indicates the reduction in the number of tumor cells after the treatment. To train the AAE we used the NCI-60 cell line assay data for 6252 compounds profiled on MCF-7 cell line. The output of the AAE was used to screen 72 million compounds in PubChem and select candidate molecules with potential anti-cancer properties. This approach is a proof of concept of an artificially-intelligent drug discovery engine, where AAEs are used to generate new molecular fingerprints with the desired molecular properties.",keywords:["PubChem","Discriminator","Deep learning","Set","Binary number","Layer"],concepts:["PubChem","Discriminator","Deep learning","Set","Binary number","Layer"],pdf_url:"http://www.oncotarget.com/index.php?journal=oncotarget&page=article&op=download&path%5B%5D=14073&path%5B%5D=44885",is_oa:!0,n_refs:35,n_refs_in_core:1,degree:10,community:2,deg_w:69.5,betweenness:.0014,pagerank:.00241,eigenvector:.0072},{id:194,oaid:"W4406488712",doi:"10.1007/s10462-024-11100-x",title:"Deep learning and computer vision in plant disease detection: a comprehensive review of techniques, models, and trends in precision agriculture",authors:[{name:"Abhishek Upadhyay",institutions:["Central Institute of Agricultural Engineering"]},{name:"Narendra Singh Chandel",institutions:["Central Institute of Agricultural Engineering"]},{name:"Krishna Pratap Singh",institutions:["Indian Council of Agricultural Research"]},{name:"Subir Kumar Chakraborty",institutions:["Central Institute of Agricultural Engineering"]},{name:"B. M. Nandede",institutions:[]},{name:"Mohit Kumar",institutions:["Sri Karan Narendra Agriculture University, Jobner"]},{name:"A. Subeesh",institutions:["Central Institute of Agricultural Engineering"]},{name:"Konga Upendar",institutions:[]},{name:"Ali Salem",institutions:["University of Pecs","Minia University"]},{name:"Ahmed Elbeltagi",institutions:["Mansoura University"]}],authorString:"Abhishek Upadhyay; Narendra Singh Chandel; Krishna Pratap Singh; Subir Kumar Chakraborty; B. M. Nandede; Mohit Kumar; A. Subeesh; Konga Upendar; Ali Salem; Ahmed Elbeltagi",institutions:["Central Institute of Agricultural Engineering","Indian Council of Agricultural Research","Mansoura University","Minia University","Sri Karan Narendra Agriculture University, Jobner","University of Pecs"],countries:["EG","HU","IN"],year:2025,journal:"Artificial Intelligence Review",citations:355,abstract:"Abstract Plant diseases cause significant damage to agriculture, leading to substantial yield losses and posing a major threat to food security. Detection, identification, quantification, and diagnosis of plant diseases are crucial parts of precision agriculture and crop protection. Modernizing agriculture and improving production efficiency are significantly affected by using computer vision technology for crop disease diagnosis. This technology is notable for its non-destructive nature, speed, real-time responsiveness, and precision. Deep learning (DL), a recent breakthrough in computer vision, has become a focal point in agricultural plant protection that can minimize the biases of manually selecting disease spot features. This study reviews the techniques and tools used for automatic disease identification, state-of-the-art DL models, and recent trends in DL-based image analysis. The techniques, performance, benefits, drawbacks, underlying frameworks, and reference datasets of more than 278 research articles were analyzed and subsequently highlighted in accordance with the architecture of computer vision and deep learning models. Key findings include the effectiveness of imaging techniques and sensors like RGB, multispectral, and hyperspectral cameras for early disease detection. Researchers also evaluated various DL architectures, such as convolutional neural networks, vision transformers, generative adversarial networks, vision language models, and foundation models. Moreover, the study connects academic research with practical agricultural applications, providing guidance on the suitability of these models for production environments. This comprehensive review offers valuable insights into the current state and future directions of deep learning in plant disease detection, making it a significant resource for researchers, academicians, and practitioners in precision agriculture.",keywords:["Deep learning","Precision agriculture","Convolutional neural network","Plant disease","Multispectral image"],concepts:["Deep learning","Precision agriculture","Convolutional neural network","Plant disease","Multispectral image"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10462-024-11100-x.pdf",is_oa:!0,n_refs:238,n_refs_in_core:8,degree:20,community:3,deg_w:225,betweenness:.0026,pagerank:.00599,eigenvector:.0066},{id:195,oaid:"W4312910656",doi:"10.1109/jproc.2022.3226481",title:"Efficient Acceleration of Deep Learning Inference on Resource-Constrained Edge Devices: A Review",authors:[{name:"Md Maruf Hossain Shuvo",institutions:["Analog Devices (United States)","University of Missouri"]},{name:"Syed K. Islam",institutions:["Analog Devices (United States)","University of Missouri"]},{name:"Jianlin Cheng",institutions:["University of Missouri"]},{name:"Bashir I. Morshed",institutions:["Texas Tech University"]}],authorString:"Md Maruf Hossain Shuvo; Syed K. Islam; Jianlin Cheng; Bashir I. Morshed",institutions:["Analog Devices (United States)","Texas Tech University","University of Missouri"],countries:["US"],year:2022,journal:"Proceedings of the IEEE",citations:353,abstract:"Successful integration of deep neural networks (DNNs) or deep learning (DL) has resulted in breakthroughs in many areas. However, deploying these highly accurate models for data-driven, learned, automatic, and practical machine learning (ML) solutions to end-user applications remains challenging. DL algorithms are often computationally expensive, power-hungry, and require large memory to process complex and iterative operations of millions of parameters. Hence, training and inference of DL models are typically performed on high-performance computing (HPC) clusters in the cloud. Data transmission to the cloud results in high latency, round-trip delay, security and privacy concerns, and the inability of real-time decisions. Thus, processing on edge devices can significantly reduce cloud transmission cost. Edge devices are end devices closest to the user, such as mobile phones, cyber–physical systems (CPSs), wearables, the Internet of Things (IoT), embedded and autonomous systems, and intelligent sensors. These devices have limited memory, computing resources, and power-handling capability. Therefore, optimization techniques at both the hardware and software levels have been developed to handle the DL deployment efficiently on the edge. Understanding the existing research, challenges, and opportunities is fundamental to leveraging the next generation of edge devices with artificial intelligence (AI) capability. Mainly, four research directions have been pursued for efficient DL inference on edge devices: 1) novel DL architecture and algorithm design; 2) optimization of existing DL methods; 3) development of algorithm–hardware codesign; and 4) efficient accelerator design for DL deployment. This article focuses on surveying each of the four research directions, providing a comprehensive review of the state-of-the-art tools and techniques for efficient edge inference.",keywords:["Edge device","Cloud computing","Edge computing","Software deployment","Deep learning","Inference"],concepts:["Edge device","Cloud computing","Edge computing","Software deployment","Deep learning","Inference"],pdf_url:"https://ieeexplore.ieee.org/ielx7/5/10015202/09985008.pdf",is_oa:!0,n_refs:475,n_refs_in_core:8,degree:22,community:0,deg_w:292,betweenness:.0043,pagerank:.00681,eigenvector:.0387},{id:196,oaid:"W3121263745",doi:"10.1186/s40537-020-00392-9",title:"Deep Learning applications for COVID-19",authors:[{name:"Connor Shorten",institutions:["Florida Atlantic University"]},{name:"Taghi M. Khoshgoftaar",institutions:["Florida Atlantic University"]},{name:"Borko Furht",institutions:["Florida Atlantic University"]}],authorString:"Connor Shorten; Taghi M. Khoshgoftaar; Borko Furht",institutions:["Florida Atlantic University"],countries:["US"],year:2021,journal:"Journal Of Big Data",citations:351,abstract:"This survey explores how Deep Learning has battled the COVID-19 pandemic and provides directions for future research on COVID-19. We cover Deep Learning applications in Natural Language Processing, Computer Vision, Life Sciences, and Epidemiology. We describe how each of these applications vary with the availability of big data and how learning tasks are constructed. We begin by evaluating the current state of Deep Learning and conclude with key limitations of Deep Learning for COVID-19 applications. These limitations include Interpretability, Generalization Metrics, Learning from Limited Labeled Data, and Data Privacy. Natural Language Processing applications include mining COVID-19 research for Information Retrieval and Question Answering, as well as Misinformation Detection, and Public Sentiment Analysis. Computer Vision applications cover Medical Image Analysis, Ambient Intelligence, and Vision-based Robotics. Within Life Sciences, our survey looks at how Deep Learning can be applied to Precision Diagnostics, Protein Structure Prediction, and Drug Repurposing. Deep Learning has additionally been utilized in Spread Forecasting for Epidemiology. Our literature review has found many examples of Deep Learning systems to fight COVID-19. We hope that this survey will help accelerate the use of Deep Learning for COVID-19 research.",keywords:["Deep learning","Interpretability","Repurposing","Data science","Misinformation"],concepts:["Deep learning","Interpretability","Repurposing","Data science","Misinformation"],pdf_url:"https://journalofbigdata.springeropen.com/counter/pdf/10.1186/s40537-020-00392-9",is_oa:!0,n_refs:186,n_refs_in_core:5,degree:22,community:1,deg_w:143,betweenness:.0083,pagerank:.0042,eigenvector:.0125},{id:197,oaid:"W3043424630",doi:"10.1109/access.2020.3009626",title:"Evaluation of Sentiment Analysis in Finance: From Lexicons to Transformers",authors:[{name:"Kostadin Mishev",institutions:["Ss. Cyril and Methodius University in Skopje"]},{name:"Ana Gjorgjevikj",institutions:["Ss. Cyril and Methodius University in Skopje"]},{name:"Irena Vodenska",institutions:["Boston University"]},{name:"Lubomir T. Chitkushev",institutions:["Boston University"]},{name:"Dimitar Trajanov",institutions:["Ss. Cyril and Methodius University in Skopje"]}],authorString:"Kostadin Mishev; Ana Gjorgjevikj; Irena Vodenska; Lubomir T. Chitkushev; Dimitar Trajanov",institutions:["Boston University","Ss. Cyril and Methodius University in Skopje"],countries:["MK","US"],year:2020,journal:"IEEE Access",citations:332,abstract:"Financial and economic news is continuously monitored by financial market participants. According to the efficient market hypothesis, all past information is reflected in stock prices and new information is instantaneously absorbed in determining future stock prices. Hence, prompt extraction of positive or negative sentiments from news is very important for investment decision-making by traders, portfolio managers and investors. Sentiment analysis models can provide an efficient method for extracting actionable signals from the news. However, financial sentiment analysis is challenging due to domain-specific language and unavailability of large labeled datasets. General sentiment analysis models are ineffective when applied to specific domains such as finance. To overcome these challenges, we design an evaluation platform which we use to assess the effectiveness and performance of various sentiment analysis approaches, based on combinations of text representation methods and machine-learning classifiers. We perform more than one hundred experiments using publicly available datasets, labeled by financial experts. We start the evaluation with specific lexicons for sentiment analysis in finance and gradually build the study to include word and sentence encoders, up to the latest available NLP transformers. The results show improved efficiency of contextual embeddings in sentiment analysis compared to lexicons and fixed word and sentence encoders, even when large datasets are not available. Furthermore, distilled versions of NLP transformers produce comparable results to their larger teacher models, which makes them suitable for use in production environments.",keywords:["Sentiment analysis","Unavailability","Sentence","Transformer","Encoder","Stock market"],concepts:["Sentiment analysis","Unavailability","Sentence","Transformer","Encoder","Stock market"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/8948470/09142175.pdf",is_oa:!0,n_refs:113,n_refs_in_core:7,degree:17,community:0,deg_w:93,betweenness:.0044,pagerank:.00329,eigenvector:.0095},{id:198,oaid:"W3126220825",doi:"10.1186/s40537-021-00419-9",title:"A survey on data‐efficient algorithms in big data era",authors:[{name:"Amina Adadi",institutions:[]}],authorString:"Amina Adadi",institutions:[],countries:[],year:2021,journal:"Journal Of Big Data",citations:322,abstract:"Abstract The leading approaches in Machine Learning are notoriously data-hungry. Unfortunately, many application domains do not have access to big data because acquiring data involves a process that is expensive or time-consuming. This has triggered a serious debate in both the industrial and academic communities calling for more data-efficient models that harness the power of artificial learners while achieving good results with less training data and in particular less human supervision. In light of this debate, this work investigates the issue of algorithms’ data hungriness. First, it surveys the issue from different perspectives. Then, it presents a comprehensive review of existing data-efficient methods and systematizes them into four categories. Specifically, the survey covers solution strategies that handle data-efficiency by (i) using non-supervised algorithms that are, by nature, more data-efficient, by (ii) creating artificially more data, by (iii) transferring knowledge from rich-data domains into poor-data domains, or by (iv) altering data-hungry algorithms to reduce their dependency upon the amount of samples, in a way they can perform well in small samples regime. Each strategy is extensively reviewed and discussed. In addition, the emphasis is put on how the four strategies interplay with each other in order to motivate exploration of more robust and data-efficient algorithms. Finally, the survey delineates the limitations, discusses research challenges, and suggests future opportunities to advance the research on data-efficiency in machine learning.",keywords:["Big data","Data science","Process","Algorithm","Data mining"],concepts:["Big data","Data science","Process","Algorithm","Data mining"],pdf_url:"https://journalofbigdata.springeropen.com/track/pdf/10.1186/s40537-021-00419-9",is_oa:!0,n_refs:330,n_refs_in_core:6,degree:20,community:1,deg_w:172,betweenness:.0032,pagerank:.00467,eigenvector:.0142},{id:199,oaid:"W4317625850",doi:"10.3390/ijms24032026",title:"Artificial Intelligence and Machine Learning Technology Driven Modern Drug Discovery and Development",authors:[{name:"Chayna Sarkar",institutions:["North Eastern Indira Gandhi Regional Institute of Health and Medical Sciences"]},{name:"Biswadeep Das",institutions:["All India Institute of Medical Sciences Rishikesh"]},{name:"Vikram Singh Rawat",institutions:["All India Institute of Medical Sciences Rishikesh"]},{name:"Julie Birdie Wahlang",institutions:["North Eastern Indira Gandhi Regional Institute of Health and Medical Sciences"]},{name:"Arvind Nongpiur",institutions:["North Eastern Indira Gandhi Regional Institute of Health and Medical Sciences"]},{name:"Iadarilang Tiewsoh",institutions:["North Eastern Indira Gandhi Regional Institute of Health and Medical Sciences"]},{name:"Nari M Lyngdoh",institutions:["North Eastern Indira Gandhi Regional Institute of Health and Medical Sciences"]},{name:"Debasmita Das",institutions:["Vellore Institute of Technology University"]},{name:"Manjunath Bidarolli",institutions:["All India Institute of Medical Sciences Rishikesh"]},{name:"Hannah Theresa Sony",institutions:["All India Institute of Medical Sciences Rishikesh"]}],authorString:"Chayna Sarkar; Biswadeep Das; Vikram Singh Rawat; Julie Birdie Wahlang; Arvind Nongpiur; Iadarilang Tiewsoh; Nari M Lyngdoh; Debasmita Das; Manjunath Bidarolli; Hannah Theresa Sony",institutions:["All India Institute of Medical Sciences Rishikesh","North Eastern Indira Gandhi Regional Institute of Health and Medical Sciences","Vellore Institute of Technology University"],countries:["IN"],year:2023,journal:"International Journal of Molecular Sciences",citations:313,abstract:'The discovery and advances of medicines may be considered as the ultimate relevant translational science effort that adds to human invulnerability and happiness. But advancing a fresh medication is a quite convoluted, costly, and protracted operation, normally costing USD ~2.6 billion and consuming a mean time span of 12 years. Methods to cut back expenditure and hasten new drug discovery have prompted an arduous and compelling brainstorming exercise in the pharmaceutical industry. The engagement of Artificial Intelligence (AI), including the deep-learning (DL) component in particular, has been facilitated by the employment of classified big data, in concert with strikingly reinforced computing prowess and cloud storage, across all fields. AI has energized computer-facilitated drug discovery. An unrestricted espousing of machine learning (ML), especially DL, in many scientific specialties, and the technological refinements in computing hardware and software, in concert with various aspects of the problem, sustain this progress. ML algorithms have been extensively engaged for computer-facilitated drug discovery. DL methods, such as artificial neural networks (ANNs) comprising multiple buried processing layers, have of late seen a resurgence due to their capability to power automatic attribute elicitations from the input data, coupled with their ability to obtain nonlinear input-output pertinencies. Such features of DL methods augment classical ML techniques which bank on human-contrived molecular descriptors. A major part of the early reluctance concerning utility of AI in pharmaceutical discovery has begun to melt, thereby advancing medicinal chemistry. AI, along with modern experimental technical knowledge, is anticipated to invigorate the quest for new and improved pharmaceuticals in an expeditious, economical, and increasingly compelling manner. DL-facilitated methods have just initiated kickstarting for some integral issues in drug discovery. Many technological advances, such as "message-passing paradigms", "spatial-symmetry-preserving networks", "hybrid de novo design", and other ingenious ML exemplars, will definitely come to be pervasively widespread and help dissect many of the biggest, and most intriguing inquiries. Open data allocation and model augmentation will exert a decisive hold during the progress of drug discovery employing AI. This review will address the impending utilizations of AI to refine and bolster the drug discovery operation.',keywords:["Drug discovery","Big data","Data science","Deep learning","Artificial neural network"],concepts:["Drug discovery","Big data","Data science","Deep learning","Artificial neural network"],pdf_url:"https://www.mdpi.com/1422-0067/24/3/2026/pdf?version=1675066963",is_oa:!0,n_refs:252,n_refs_in_core:8,degree:21,community:2,deg_w:227,betweenness:.0042,pagerank:.00572,eigenvector:.0354}],i={n_papers:200,papers_with_refs:198,mean_refs:149.9,direct_citation_edges:979,coupling_edges_kept:1046,total_edges_kept:2066,data_mode:"co-citation",reference_source:"OpenAlex referenced_works"},n={papers:e,completeness:i};export{i as completeness,n as default,e as papers};
